		this.attenuationType = AttenuationType.LINEAR;
		this.entity = entity;
		this.isPlaying = isPlaying;
		this.xPosF = (float) this.entity.posX;
		this.yPosF = (float) this.entity.posY;
		this.zPosF = (float) this.entity.posZ;
