    	if (this.isSoundStreamed(false) && donePlaying && !isDone) {
            if (pauseTicks == 0) {
                SoundManager manager = Minecraft.getMinecraft().getSoundHandler().sndManager;
                SoundSystem sys = manager.sndSystem;
