public void update() {
		this.updateCounter++;

		this.prevPosX = this.posX;
		this.prevPosY = this.posY;

		this.posX -= 0.4F;

		this.posY += this.motionY;
		this.posX += this.motionX;

		if (this.motionY > 0) {
			this.motionY -= 0.001F;
		} else {
			this.motionY += 0.001F;
		}
	}

