private float getShakeStrength(Entity renderViewEntity) {
		float screenShake = 0.0F;
		World world = renderViewEntity.world;

		if(renderViewEntity != null) {
			for(Entity entity : (List<Entity>) world.loadedEntityList) {
				if(entity instanceof IEntityScreenShake) {
					IEntityScreenShake shake = (IEntityScreenShake) entity;
					screenShake += shake.getShakeIntensity(renderViewEntity);
				}
			}

			for(TileEntity tile : (List<TileEntity>) world.loadedTileEntityList) {
				if(tile instanceof IEntityScreenShake) {
					IEntityScreenShake shake = (IEntityScreenShake) tile;
					screenShake += shake.getShakeIntensity(renderViewEntity);
				}
			}

			//Crumbling cragrock tower
			BetweenlandsWorldStorage worldData = BetweenlandsWorldStorage.forWorld(world);
			List<LocationCragrockTower> towers = worldData.getLocalStorageHandler().getLocalStorages(LocationCragrockTower.class, renderViewEntity.posX, renderViewEntity.posZ, location -> location.getInnerBoundingBox().grow(4, 4, 4).contains(renderViewEntity.getPositionVector()));
			for(LocationCragrockTower tower : towers) {
				if(tower.isCrumbling()) {
					screenShake += Math.min(Math.pow(tower.getCrumblingTicks() / 400.0f, 4) * 0.08f, 0.08f);
				}
			}

			//Ring of Summoning
			List<EntityPlayer> nearbyPlayers = renderViewEntity.world.getEntitiesWithinAABB(EntityPlayer.class, renderViewEntity.getEntityBoundingBox().grow(32, 32, 32), entity -> entity.getDistance(renderViewEntity) <= 32.0D);

			for(EntityPlayer player : nearbyPlayers) {
				ISummoningCapability cap = player.getCapability(CapabilityRegistry.CAPABILITY_SUMMON, null);
				if (cap != null) {
					if(cap.isActive()) {
						screenShake += (ItemRingOfSummoning.MAX_USE_TIME - cap.getActiveTicks()) / (float)ItemRingOfSummoning.MAX_USE_TIME * 0.1F + 0.01F;
					}
				}
			}

			//Shock
			if(renderViewEntity instanceof EntityLivingBase) {
				PotionEffect effect = ((EntityLivingBase) renderViewEntity).getActivePotionEffect(ElixirEffectRegistry.EFFECT_SHOCKED.getPotionEffect());
				if(effect != null) {
					screenShake += Math.min(0.1f, effect.getDuration() / 30.0f * 0.1f);
				}
			}
		}

		return MathHelper.clamp(screenShake, 0.0F, 0.15F);
	}

@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public void onClientTick(ClientTickEvent event) {
		Entity renderViewEntity = Minecraft.getMinecraft().getRenderViewEntity();

		if(renderViewEntity != null) {
			this.shakeStrength = this.getShakeStrength(renderViewEntity);

			this.offsetEntities.clear();

			List<IEntityCameraOffset> offsetEntities = new ArrayList<IEntityCameraOffset>();
			for(Entity entity : (List<Entity>) renderViewEntity.world.loadedEntityList) {
				if(entity instanceof IEntityCameraOffset)
					offsetEntities.add((IEntityCameraOffset)entity);
			}
		} else {
			this.shakeStrength = 0.0f;
			this.offsetEntities.clear();
		}
	}

@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public void onRenderTickStart(RenderTickEvent event) {
		Entity renderViewEntity = Minecraft.getMinecraft().getRenderViewEntity();

		if(renderViewEntity != null) {
			boolean shouldChange = this.shakeStrength > 0.0F || !this.offsetEntities.isEmpty();

			if((shouldChange && !Minecraft.getMinecraft().isGamePaused()) || this.didChange) {
				if(event.phase == Phase.START) {
					this.prevPosX = renderViewEntity.posX;
					this.prevPosY = renderViewEntity.posY;
					this.prevPosZ = renderViewEntity.posZ;

					Random rnd = renderViewEntity.world.rand;

					renderViewEntity.posX += rnd.nextFloat() * this.shakeStrength;
					renderViewEntity.posY += rnd.nextFloat() * this.shakeStrength;
					renderViewEntity.posZ += rnd.nextFloat() * this.shakeStrength;

					if(!this.offsetEntities.isEmpty()) {
						for(IEntityCameraOffset offset : offsetEntities)
							if(((Entity) offset).isEntityAlive() && offset.applyOffset(renderViewEntity, event.renderTickTime))
								break;
					}

					this.didChange = true;
				} else {
					renderViewEntity.posX = this.prevPosX;
					renderViewEntity.posY = this.prevPosY;
					renderViewEntity.posZ = this.prevPosZ;

					this.didChange = false;
				}
			}
		}
	}

@SubscribeEvent
	public static void renderWorld(RenderWorldLastEvent event) {
		if (StreamSupport.stream(Minecraft.getMinecraft().player.getHeldEquipment().spliterator(), false)
				.anyMatch(stack -> !stack.isEmpty() && (stack.getItem() == ItemRegistry.LOCATION_DEBUG || stack.getItem() == ItemRegistry.TEST_ITEM_CHIMP_RULER))) {
			World world = Minecraft.getMinecraft().world;
			BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);

			for (ILocalStorage sharedStorage : worldStorage.getLocalStorageHandler().getLoadedStorages()) {
				if (sharedStorage instanceof LocationStorage) {
					LocationStorage location = (LocationStorage) sharedStorage;

					GlStateManager.pushMatrix();
					if (GuiScreen.isCtrlKeyDown()) {
						GlStateManager.disableDepth();
					}
					GlStateManager.disableTexture2D();
					GlStateManager.enableBlend();
					GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
					GlStateManager.alphaFunc(GL11.GL_GREATER, 0.0f);
					GlStateManager.color(1, 1, 1, 1);
					GlStateManager.glLineWidth(1F);
					GlStateManager.depthMask(false);
					GL11.glEnable(GL11.GL_LINE_SMOOTH);

					Random rnd = new Random(location.getSeed());

					float red = (0.25F + rnd.nextFloat() / 2.0F * 0.75F) * (location.getLayer() + 2) / 2.0F;
					float green = (0.25F + rnd.nextFloat() / 2.0F * 0.75F) * (location.getLayer() + 2) / 2.0F;
					float blue = (0.25F + rnd.nextFloat() * 0.75F) * (location.getLayer() + 2) / 2.0F;
					float alpha = 0.25F;

					GlStateManager.color(red, green, blue, alpha);
					for (AxisAlignedBB bb : location.getBounds()) {
						drawBoundingBox(bb.offset(-Minecraft.getMinecraft().getRenderManager().viewerPosX,
								-Minecraft.getMinecraft().getRenderManager().viewerPosY,
								-Minecraft.getMinecraft().getRenderManager().viewerPosZ));
					}

					GlStateManager.color(red / 1.5F, green / 1.5F, blue / 1.5F, 1.0F);
					for (AxisAlignedBB bb : location.getBounds()) {
						drawBoundingBoxOutline(bb.offset(-Minecraft.getMinecraft().getRenderManager().viewerPosX,
								-Minecraft.getMinecraft().getRenderManager().viewerPosY,
								-Minecraft.getMinecraft().getRenderManager().viewerPosZ));
					}

					if (location.getEnclosingBounds() != null) {
						GlStateManager.color(red, green, blue, 1.0F);
						drawBoundingBoxOutline(location.getEnclosingBounds().offset(
								-Minecraft.getMinecraft().getRenderManager().viewerPosX,
								-Minecraft.getMinecraft().getRenderManager().viewerPosY,
								-Minecraft.getMinecraft().getRenderManager().viewerPosZ));

						AxisAlignedBB aabb = location.getEnclosingBounds();
						Vec3d center = new Vec3d((aabb.maxX + aabb.minX) / 2.0D, (aabb.maxY + aabb.minY) / 2.0D,
								(aabb.maxZ + aabb.minZ) / 2.0D).add(
										-Minecraft.getMinecraft().getRenderManager().viewerPosX,
										-Minecraft.getMinecraft().getRenderManager().viewerPosY,
										-Minecraft.getMinecraft().getRenderManager().viewerPosZ);

						GlStateManager.pushMatrix();
						GlStateManager.translate(center.x, center.y, center.z);

						float scale = Math.max(2.0F, (float) center.length() / 10.0F);

						GlStateManager.scale(scale, scale, scale);

						renderTag(Minecraft.getMinecraft().fontRenderer, location.hasLocalizedName() ? location.getLocalizedName() : location.getName(), 0, 0, 0, 0,
								Minecraft.getMinecraft().getRenderManager().playerViewY,
								Minecraft.getMinecraft().getRenderManager().playerViewX,
								Minecraft.getMinecraft().getRenderManager().options.thirdPersonView == 2);

						GlStateManager.enableBlend();

						GlStateManager.popMatrix();
					}

					GlStateManager.disableTexture2D();
					GlStateManager.color(1, 1, 1, 1);

					GlStateManager.enableDepth();
					GlStateManager.glLineWidth(2F);

					ILocationGuard guard = location.getGuard();
					if (guard != null) {
						GlStateManager.doPolygonOffset(-0.1F, -10.0F);
						GlStateManager.enablePolygonOffset();
						for (int xo = -8; xo <= 8; xo++) {
							for (int yo = -8; yo <= 8; yo++) {
								for (int zo = -8; zo <= 8; zo++) {
									BlockPos pos = Minecraft.getMinecraft().player.getPosition().add(xo, yo, zo);
									if (pos.getY() >= 0) {
										IBlockState state = world.getBlockState(pos);
										boolean guarded = guard.isGuarded(world, Minecraft.getMinecraft().player, pos);
										if (guarded) {
											if (state.getBlock() != Blocks.AIR) {
												GlStateManager.color(1, 0, 0, 0.25F);
												drawBoundingBox(state.getBoundingBox(world, pos).offset(pos).offset(
														-Minecraft.getMinecraft().getRenderManager().viewerPosX,
														-Minecraft.getMinecraft().getRenderManager().viewerPosY,
														-Minecraft.getMinecraft().getRenderManager().viewerPosZ));
											} else {
												GlStateManager.color(1, 0, 0, 0.8F);
												drawBoundingBoxOutline(new AxisAlignedBB(pos).offset(
														-Minecraft.getMinecraft().getRenderManager().viewerPosX,
														-Minecraft.getMinecraft().getRenderManager().viewerPosY,
														-Minecraft.getMinecraft().getRenderManager().viewerPosZ));
											}
										}
									}
								}
							}
						}
						GlStateManager.disablePolygonOffset();
					}

					GL11.glDisable(GL11.GL_LINE_SMOOTH);
					GlStateManager.color(1, 1, 1, 1);
					GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1f);
					GlStateManager.depthMask(true);
					GlStateManager.enableTexture2D();
					GlStateManager.enableDepth();
					GlStateManager.disableBlend();
					GlStateManager.popMatrix();
				}
			}
		}
	}

public static void renderTag(FontRenderer fontRenderer, String str, float x, float y, float z, int yOffset,
			float playerViewY, float playerViewX, boolean thirdPerson) {
		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y, z);
		GlStateManager.glNormal3f(0.0F, 1.0F, 0.0F);
		GlStateManager.rotate(-playerViewY, 0.0F, 1.0F, 0.0F);
		GlStateManager.rotate((float) (thirdPerson ? -1 : 1) * playerViewX, 1.0F, 0.0F, 0.0F);
		GlStateManager.scale(-0.025F, -0.025F, 0.025F);

		GlStateManager.enableBlend();
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA,
				GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE,
				GlStateManager.DestFactor.ZERO);
		int i = fontRenderer.getStringWidth(str) / 2;
		GlStateManager.disableTexture2D();
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder vertexbuffer = tessellator.getBuffer();
		vertexbuffer.begin(7, DefaultVertexFormats.POSITION_COLOR);
		vertexbuffer.pos((double) (-i - 1), (double) (-1 + yOffset), 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		vertexbuffer.pos((double) (-i - 1), (double) (8 + yOffset), 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		vertexbuffer.pos((double) (i + 1), (double) (8 + yOffset), 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		vertexbuffer.pos((double) (i + 1), (double) (-1 + yOffset), 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		tessellator.draw();
		GlStateManager.enableTexture2D();

		fontRenderer.drawString(str, -fontRenderer.getStringWidth(str) / 2, yOffset, 0xFFFFFFFF);
		GlStateManager.disableBlend();
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.popMatrix();
	}

