public RingOfDispersionWorldRenderer(int rangeXZ, int rangeY) {
		this.rangeXZ = rangeXZ;
		this.rangeY = rangeY;
		this.fogColor.put(new float[4]);
	}

public void setPos(BlockPos pos) {
		this.pos = pos;
	}

public void setWorld(World world) {
		this.world = world;
	}

protected BufferBuilder getBufferBuilder(BlockRenderLayer layer) {
		BufferBuilder builder = this.bufferBuilders.get(layer);
		if(builder == null) {
			this.bufferBuilders.put(layer, builder = new BufferBuilder(4000 /*TODO find good default value*/));
		}
		return builder;
	}

protected VertexBatchRenderer getBatchRenderer(BlockRenderLayer layer) {
		VertexBatchRenderer renderer = this.batchRenderers.get(layer);
		if(renderer == null) {
			this.batchRenderers.put(layer, renderer = new VertexBatchRenderer(DefaultVertexFormats.BLOCK, OpenGlHelper.useVbo()));
		}
		return renderer;
	}

public void render() {
		if(this.world == null) {
			return;
		}

		if(this.currentlyUsingVbos != OpenGlHelper.useVbo()) {
			this.deleteBuffers();
		}
		this.currentlyUsingVbos = OpenGlHelper.useVbo();

		if(!this.pos.equals(this.renderedPos)) {
			this.renderedPos = this.pos;
			this.rebuildVertexBuffer();
		}

		Minecraft mc = Minecraft.getMinecraft();

		GlStateManager.pushMatrix();

		GlStateManager.translate(this.renderedPos.getX() - mc.getRenderManager().renderPosX, this.renderedPos.getY() - mc.getRenderManager().renderPosY, this.renderedPos.getZ() - mc.getRenderManager().renderPosZ);


		GlStateManager.enableTexture2D();
		GlStateManager.enableBlend();
		mc.getTextureManager().bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);

		GlStateManager.enableFog();

		this.fogColor.rewind();
		GlStateManager.glFog(GL11.GL_FOG_COLOR, this.fogColor);

		GlStateManager.setFog(FogMode.LINEAR);
		GlStateManager.setFogStart(this.rangeXZ - 1);
		GlStateManager.setFogEnd(this.rangeXZ);

		this.renderBuffers(mc);

		GlStateManager.disableFog();


		GlStateManager.popMatrix();
	}

protected void renderBuffers(Minecraft mc) {
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0.5F);
		GlStateManager.disableAlpha();

		this.renderLayerBuffer(mc, BlockRenderLayer.SOLID);

		GlStateManager.enableAlpha();

		mc.getTextureManager().getTexture(TextureMap.LOCATION_BLOCKS_TEXTURE).setBlurMipmap(false, mc.gameSettings.mipmapLevels > 0); // FORGE: fix flickering leaves when mods mess up the blurMipmap settings
		this.renderLayerBuffer(mc, BlockRenderLayer.CUTOUT_MIPPED);
		mc.getTextureManager().getTexture(TextureMap.LOCATION_BLOCKS_TEXTURE).restoreLastBlurMipmap();

		mc.getTextureManager().getTexture(TextureMap.LOCATION_BLOCKS_TEXTURE).setBlurMipmap(false, false);
		this.renderLayerBuffer(mc, BlockRenderLayer.CUTOUT);
		mc.getTextureManager().getTexture(TextureMap.LOCATION_BLOCKS_TEXTURE).restoreLastBlurMipmap();

		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
		GlStateManager.alphaFunc(GL11.GL_GREATER, 0.1F);
		this.renderLayerBuffer(mc, BlockRenderLayer.TRANSLUCENT);

		GlStateManager.disableAlpha();
		this.renderLayerBuffer(mc, BlockRenderLayer.TRANSLUCENT);

		GlStateManager.enableAlpha();
	}

protected void renderLayerBuffer(Minecraft mc, BlockRenderLayer layer) {
		//VertexBuffer buffer = this.getVertexBuffer(layer);
		VertexBatchRenderer batchRenderer = this.getBatchRenderer(layer);

		GlStateManager.shadeModel(GL11.GL_SMOOTH);
		RenderHelper.disableStandardItemLighting();

		//mc.entityRenderer.enableLightmap();
		mc.entityRenderer.disableLightmap();

		batchRenderer.render();

		mc.entityRenderer.disableLightmap();
	}

protected void rebuildVertexBuffer() {
		BlockRendererDispatcher blockRenderer = Minecraft.getMinecraft().getBlockRendererDispatcher();

		for(BlockRenderLayer layer : BlockRenderLayer.values()) {
			this.getBufferBuilder(layer).begin(GL11.GL_QUADS, DefaultVertexFormats.BLOCK);
		}

		for(int xo = -this.rangeXZ; xo <= this.rangeXZ; xo++) {
			for(int yo = -this.rangeY; yo <= 0; yo++) {
				for(int zo = -this.rangeXZ; zo <= this.rangeXZ; zo++) {
					BlockPos pos = new BlockPos(this.renderedPos.add(xo, yo, zo));
					IBlockState state = this.world.getBlockState(pos);

					EnumBlockRenderType renderType = state.getRenderType();

					if(!state.getBlock().isAir(state, this.world, pos) && (renderType == EnumBlockRenderType.MODEL || renderType == EnumBlockRenderType.LIQUID)) {
						state = state.getActualState(this.world, pos);

						IBakedModel blockModel = Minecraft.getMinecraft().getBlockRendererDispatcher().getModelForState(state);

						state = state.getBlock().getExtendedState(state, this.world, pos);

						if(blockModel != null) {
							for(BlockRenderLayer layer : BlockRenderLayer.values()) {
								if(state.getBlock().canRenderInLayer(state, layer)) {
									int prevPass = MinecraftForgeClient.getRenderPass();
									BlockRenderLayer prevLayer = MinecraftForgeClient.getRenderLayer();

									ForgeHooksClient.setRenderPass(0);
									ForgeHooksClient.setRenderLayer(layer);

									BufferBuilder bufferBuilder = this.getBufferBuilder(layer);

									bufferBuilder.setTranslation(-this.renderedPos.getX(), -this.renderedPos.getY(), -this.renderedPos.getZ());

									switch(renderType) {
									case MODEL:
										blockRenderer.getBlockModelRenderer().renderModel(this.world, blockModel, state, pos, bufferBuilder, layer == BlockRenderLayer.TRANSLUCENT);
										break;
									case LIQUID:
										blockRenderer.renderBlock(state, pos, this.world, bufferBuilder);
										break;
									}

									bufferBuilder.setTranslation(0, 0, 0);

									ForgeHooksClient.setRenderPass(prevPass);
									ForgeHooksClient.setRenderLayer(prevLayer);
								}
							}
						}
					}
				}
			}
		}

		for(BlockRenderLayer layer : BlockRenderLayer.values()) {
			BufferBuilder bufferBuilder = this.getBufferBuilder(layer);

			if(layer == BlockRenderLayer.TRANSLUCENT) {
				//Sort only on build, resorting is likely not necessary since the buffers
				//are rebuilt after moving a block
				bufferBuilder.sortVertexData(0, 2, 0);
			}

			VertexBatchRenderer batchRenderer = this.getBatchRenderer(layer);
			batchRenderer.compile(bufferBuilder);
		}
	}

public void deleteBuffers() {
		this.bufferBuilders.clear();

		for(VertexBatchRenderer batchRenderer : this.batchRenderers.values()) {
			batchRenderer.deleteBuffers();
		}
		this.batchRenderers.clear();
	}

public VertexBatchRenderer(VertexFormat format, boolean useVbo) {
		this(format, useVbo, null, -1);
	}

public VertexBatchRenderer(VertexFormat format, boolean useVbo, @Nullable VertexBuffer vertexBuffer, int displayList) {
		this.format = format;
		this.useVbo = useVbo;
		this.vertexBuffer = vertexBuffer;
		this.displayList = displayList;
	}

public void compile(BufferBuilder bufferBuilder) {
		bufferBuilder.finishDrawing();

		if(this.useVbo) {
			if(this.vertexBuffer == null) {
				this.vertexBuffer = new VertexBuffer(this.format);
			}
			this.vertexBufferUploader.setVertexBuffer(this.vertexBuffer);
			this.vertexBufferUploader.draw(bufferBuilder);
		} else {
			if(this.displayList < 0) {
				this.displayList = GL11.glGenLists(1);
			}
			GL11.glNewList(this.displayList, GL11.GL_COMPILE);
			this.worldVertexUploader.draw(bufferBuilder);
			GL11.glEndList();
		}
	}

public void render() {
		if(this.useVbo) {
			if(this.vertexBuffer != null) {
				this.vertexBuffer.bindBuffer();

				int stride = this.format.getSize();

				int elementIndex = 0;
				for(VertexFormatElement element : this.format.getElements()) {
					int count = element.getElementCount();
					int constant = element.getType().getGlConstant();
					int offset = this.format.getOffset(elementIndex);

					switch(element.getUsage()) {
					case POSITION:
						GlStateManager.glVertexPointer(count, constant, stride, offset);
						GlStateManager.glEnableClientState(GL11.GL_VERTEX_ARRAY);
						break;
					case NORMAL:
						if(count != 3) {
							throw new IllegalArgumentException("Normal attribute should have the size 3: " + element);
						}
						//GlStateManager.glNormalPointer(constant, stride, offset);
						GL11.glNormalPointer(constant, stride, offset);
						GlStateManager.glEnableClientState(GL11.GL_NORMAL_ARRAY);
						break;
					case COLOR:
						GlStateManager.glColorPointer(count, constant, stride, offset);
						GlStateManager.glEnableClientState(GL11.GL_COLOR_ARRAY);
						break;
					case UV:
						OpenGlHelper.setClientActiveTexture(OpenGlHelper.defaultTexUnit + element.getIndex());
						GlStateManager.glTexCoordPointer(count, constant, stride, offset);
						GlStateManager.glEnableClientState(GL11.GL_TEXTURE_COORD_ARRAY);
						OpenGlHelper.setClientActiveTexture(OpenGlHelper.defaultTexUnit);
						break;
					case PADDING:
						break;
					case GENERIC:
						GL20.glEnableVertexAttribArray(element.getIndex());
						GL20.glVertexAttribPointer(element.getIndex(), count, constant, false, stride, offset);
						break;
					}

					elementIndex++;
				}

				this.vertexBuffer.drawArrays(GL11.GL_QUADS);

				this.vertexBuffer.unbindBuffer();

				for(VertexFormatElement element : this.format.getElements()) {
					switch(element.getUsage()) {
					case POSITION:
						GlStateManager.glDisableClientState(GL11.GL_VERTEX_ARRAY);
						break;
					case NORMAL:
						GlStateManager.glDisableClientState(GL11.GL_NORMAL_ARRAY);
						break;
					case COLOR:
						GlStateManager.glDisableClientState(GL11.GL_COLOR_ARRAY);
						GlStateManager.resetColor();
						break;
					case UV:
						OpenGlHelper.setClientActiveTexture(OpenGlHelper.defaultTexUnit + element.getIndex());
						GlStateManager.glDisableClientState(GL11.GL_TEXTURE_COORD_ARRAY);
						OpenGlHelper.setClientActiveTexture(OpenGlHelper.defaultTexUnit);
						break;
					case PADDING:
						break;
					case GENERIC:
						GL20.glDisableVertexAttribArray(element.getIndex());
						break;
					}
				}
			}
		} else {
			if(this.displayList >= 0) {
				GL11.glCallList(this.displayList);
			}
		}
	}

public void deleteBuffers() {
		if(this.vertexBuffer != null) {
			this.vertexBuffer.deleteGlBuffers();
			this.vertexBuffer = null;
		}

		if(this.displayList >= 0) {
			GL11.glDeleteLists(this.displayList, 1);
			this.displayList = -1;
		}
	}

public RenderAnadia(RenderManager manager) {
		super(manager, ANADIA_MODEL, 0.5F);
	}

@Override
	protected ResourceLocation getEntityTexture(EntityAnadia entity) {
		return TEXTURE_1[2];
	}

@Override
	protected void applyRotations(EntityAnadia entity, float ageInTicks, float rotationYaw, float partialTicks) {
		float smoothedPitch = entity.prevRotationPitch + (entity.rotationPitch - entity.prevRotationPitch) * partialTicks;
		float smoothedYaw = entity.prevRotationYaw + (entity.rotationYaw - entity.prevRotationYaw) * partialTicks;

		GlStateManager.rotate(180 - smoothedYaw, 0F, 1F, 0F);

		float scale = entity.getFishSize();
		GlStateManager.translate(0, 0.4f * scale, 0);
		GlStateManager.rotate(-smoothedPitch, 1F, 0F, 0F);
		GlStateManager.translate(0, -0.4f * scale, 0);

		if(entity.deathTime > 0) {
            float f = ((float)entity.deathTime + partialTicks - 1.0F) / 20.0F * 1.6F;
            f = MathHelper.sqrt(f);

            if(f > 1.0F) {
                f = 1.0F;
            }

            GlStateManager.rotate(f * this.getDeathMaxRotation(entity), 0.0F, 0.0F, 1.0F);
        }
	}

@Override
	protected void preRenderCallback(EntityAnadia entity, float partialTickTime) {
		float scale = entity.getFishSize();
		GlStateManager.scale(scale, scale, scale);
	}

@Override
	protected void renderModel(EntityAnadia entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch, float scaleFactor) {
		boolean isVisible = this.isVisible(entity);
		boolean isTransparent = !isVisible && !entity.isInvisibleToPlayer(Minecraft.getMinecraft().player);

		if(isVisible || isTransparent) {
			if(!this.bindEntityTexture(entity)) {
				return;
			}

			if(isTransparent) {
				GlStateManager.enableBlendProfile(GlStateManager.Profile.TRANSPARENT_MODEL);
			}

			GlStateManager.enableCull();

			switch (entity.getHeadType()) {
			default:
			case HEAD_1:
				bindTexture(getTextureForColor(TEXTURE_1, entity.getFishColour()));
				ANADIA_MODEL.renderHead(entity.getHeadType(), 0.0625F);
				break;
			case HEAD_2:
				bindTexture(getTextureForColor(TEXTURE_2, entity.getFishColour()));
				ANADIA_MODEL.renderHead(entity.getHeadType(), 0.0625F);
				break;
			case HEAD_3:
				bindTexture(getTextureForColor(TEXTURE_3, entity.getFishColour()));
				ANADIA_MODEL.renderHead(entity.getHeadType(), 0.0625F);
				break;
			}

			switch (entity.getBodyType()) {
			default:
			case BODY_1:
				bindTexture(getTextureForColor(TEXTURE_1, entity.getFishColour()));
				ANADIA_MODEL.renderBody(entity.getBodyType(), 0.0625F);
				break;
			case BODY_2:
				bindTexture(getTextureForColor(TEXTURE_2, entity.getFishColour()));
				ANADIA_MODEL.renderBody(entity.getBodyType(), 0.0625F);
				break;
			case BODY_3:
				bindTexture(getTextureForColor(TEXTURE_3, entity.getFishColour()));
				ANADIA_MODEL.renderBody(entity.getBodyType(), 0.0625F);
				break;
			}

			switch (entity.getTailType()) {
			default:
			case TAIL_1:
				bindTexture(getTextureForColor(TEXTURE_1, entity.getFishColour()));
				ANADIA_MODEL.renderTail(entity.getTailType(), 0.0625F);
				break;
			case TAIL_2:
				bindTexture(getTextureForColor(TEXTURE_2, entity.getFishColour()));
				ANADIA_MODEL.renderTail(entity.getTailType(), 0.0625F);
				break;
			case TAIL_3:
				bindTexture(getTextureForColor(TEXTURE_3, entity.getFishColour()));
				ANADIA_MODEL.renderTail(entity.getTailType(), 0.0625F);
				break;
			} 

			GlStateManager.disableCull();

			if(isTransparent) {
				GlStateManager.disableBlendProfile(GlStateManager.Profile.TRANSPARENT_MODEL);
			}
		}
	}

