		if(this.renderWall) {
			if(this.getWallSprite(entity) != null) {
				return TextureMap.LOCATION_BLOCKS_TEXTURE;
			} else {
				return WALL_TEXTURE;
			}
		} else {
			return this.modelTexture;
		}
