private State(Consumer<T> animator, Supplier<Float> weight) {
			this.animator = animator;
			this.weight = weight;
		}

private void update(AnimationBlender<T> blender, T model, boolean reset) {
			if(reset) {
				for(int i = 0; i < model.boxList.size(); i++) {
					ModelRenderer part = model.boxList.get(i);
					part.rotateAngleX = Float.NaN;
					part.rotateAngleY = Float.NaN;
					part.rotateAngleZ = Float.NaN;
				}
			}

			this.animator.accept(model);

			for(int i = 0; i < model.boxList.size(); i++) {
				ModelRenderer part = model.boxList.get(i);

				if(Float.isFinite(part.rotateAngleX)) {
					blender.rotX[i] += this.currentWeight * part.rotateAngleX;
				}

				if(Float.isFinite(part.rotateAngleY)) {
					blender.rotY[i] += this.currentWeight * part.rotateAngleY;
				}

				if(Float.isFinite(part.rotateAngleZ)) {
					blender.rotZ[i] += this.currentWeight * part.rotateAngleZ;
				}
			}
		}

public AnimationBlender(T model) {
		this.model = model;
		this.states.add(this.baseState = new State(m -> {}, () -> 1.0f));
		this.rotX = new float[this.model.boxList.size()];
		this.rotY = new float[this.model.boxList.size()];
		this.rotZ = new float[this.model.boxList.size()];
	}

public void addState(Consumer<T> animator, Supplier<Float> weight) {
		this.states.add(new State(animator, weight));
	}

public void setAngles(boolean useExistingAngles) {
		for(int i = 0; i < this.model.boxList.size(); i++) {
			this.rotX[i] = this.rotY[i] = this.rotZ[i] = 0;
		}

		for(State state : this.states) {
			if(useExistingAngles || state != this.baseState) {
				state.currentWeight = state.weight.get();
				state.update(this, this.model, state != this.baseState);
			}
		}

		for(int i = 0; i < this.model.boxList.size(); i++) {
			ModelRenderer part = model.boxList.get(i);

			part.rotateAngleX = this.rotX[i];
			part.rotateAngleY = this.rotY[i];
			part.rotateAngleZ = this.rotZ[i];
		}
	}

public ControlledAnimation(int d) {
        prevTimer = 0;
        timer = 0;
        duration = d;
    }

public void setDuration(int duration) {
        prevTimer = 0;
        timer = 0;
        this.duration = duration;
    }

public int getTimer() {
        return timer;
    }

public void setTimer(int time) {
        timer = time;

        if (timer > duration) {
            timer = duration;
        } else if (timer < 0) {
            timer = 0;
        }
    }

public void resetTimer() {
        timer = 0;
    }

public void updateTimer() {
        prevTimer = timer;
    }

public void increaseTimer() {
        if (timer < duration) {
            timer++;
            timerChange = 1;
        }
    }

public boolean canIncreaseTimer() {
        return timer < duration;
    }

public void increaseTimer(int time) {
        int newTime = timer + time;
        if (newTime <= duration && newTime >= 0) {
            timer = newTime;
        } else {
            timer = newTime < 0 ? 0 : duration;
        }
    }

public void decreaseTimer() {
        if (timer > 0) {
            timer--;
            timerChange = -1;
        }
    }

public boolean canDecreaseTimer() {
        return timer > 0;
    }

public void decreaseTimer(int time) {
        if (timer - time > 0) {
            timer -= time;
        } else {
            timer = 0;
        }
    }

public float getAnimationFraction(float partialRenderTicks) {
        return (prevTimer + (timer - prevTimer) * partialRenderTicks) / duration;
    }

public float getAnimationProgressSmooth(float partialRenderTicks) {
        if (timer > 0) {
            if (timer < duration) {
                return (float) (1.0D / (1.0D + Math.exp(4.0D - 8.0D * getAnimationFraction(partialRenderTicks))));
            } else {
                return 1.0F;
            }
        }
        return 0.0F;
    }

public float getAnimationProgressSteep(float partialRenderTicks) {
        return (float) (1.0D / (1.0D + Math.exp(6.0D - 12.0D * getAnimationFraction(partialRenderTicks))));
    }

public float getAnimationProgressSin(float partialRenderTicks) {
        return MathHelper.sin(1.57079632679F * getAnimationFraction(partialRenderTicks));
    }

public float getAnimationProgressSinSqrt(float partialRenderTicks) {
        float result = MathHelper.sin(1.57079632679F * getAnimationFraction(partialRenderTicks));
        return result * result;
    }

public float getAnimationProgressSinToTen(float partialRenderTicks) {
        return (float) Math.pow(MathHelper.sin(1.57079632679F * getAnimationFraction(partialRenderTicks)), 10);
    }

public float getAnimationProgressSinToTenWithoutReturn(float partialRenderTicks) {
        float t = getAnimationFraction(partialRenderTicks);
        if (timerChange == -1) {
            return MathHelper.sin(1.57079632679F * t) * MathHelper.sin(1.57079632679F * t);
        }
        return (float) Math.pow(MathHelper.sin(1.57079632679F * t), 10);
    }

public float getAnimationProgressSinPowerOf(float partialRenderTicks, int i) {
        return (float) Math.pow(MathHelper.sin(1.57079632679F * getAnimationFraction(partialRenderTicks)), i);
    }

public float getAnimationProgressPoly2(float partialRenderTicks) {
        float x = getAnimationFraction(partialRenderTicks);
        float x2 = x * x;
        return x2 / (x2 + (1 - x) * (1 - x));
    }

public float getAnimationProgressPoly3(float partialRenderTicks) {
        float x = getAnimationFraction(partialRenderTicks);
        float x3 = x * x * x;
        return x3 / (x3 + (1 - x) * (1 - x) * (1 - x));
    }

public float getAnimationProgressPolyN(float partialRenderTicks, int n) {
        double x = getAnimationFraction(partialRenderTicks);
        double xi = Math.pow(x, n);
        return (float) (xi / (xi + Math.pow(1.0D - x, n)));
    }

public float getAnimationProgressArcTan(float partialRenderTicks) {
        return (float) (0.5F + 0.49806510671F * Math.atan(3.14159265359D * (getAnimationFraction(partialRenderTicks) - 0.5D)));
    }

public float getAnimationProgressTemporary(float partialRenderTicks) {
        float x = 6.28318530718F * getAnimationFraction(partialRenderTicks);
        return 0.5F - 0.5F * MathHelper.cos(x + MathHelper.sin(x));
    }

public float getAnimationProgressTemporaryFS(float partialRenderTicks) {
        float x = 3.14159265359F * getAnimationFraction(partialRenderTicks);
        return MathHelper.sin(x + MathHelper.sin(x));
    }

public float getAnimationProgressTemporaryInvesed(float partialRenderTicks) {
        float x = 6.28318530718F * getAnimationFraction(partialRenderTicks);
        return 0.5F + 0.5F * MathHelper.cos(x + MathHelper.sin(x));
    }

public Model3DTexture(ModelRenderer model, int textureOffsetX, int textureOffsetY, float posX, float posY, float posZ, int width, int height) {
		super(model, 0, 0, posX, posY, posZ, 0, 0, 0, 0);
		this.textureOffsetX = textureOffsetX;
		this.textureOffsetY = textureOffsetY;
		this.width = width;
		this.height = height;
		u1 = textureOffsetX / model.textureWidth;
		v1 = textureOffsetY / model.textureHeight;
		u2 = (textureOffsetX + width) / model.textureWidth;
		v2 = (textureOffsetY + height) / model.textureHeight;
	}

public Model3DTexture(ModelRenderer model, int textureOffsetX, int textureOffsetY, int width, int height) {
		this(model, textureOffsetX, textureOffsetY, 0, 0, 0, width, height);
	}

@Override
	public void render(BufferBuilder renderer, float scale) {
		GlStateManager.pushMatrix();
		GlStateManager.translate(posX1, posY1, posZ1);
		GlStateManager.scale(width / 16F, height / 16F, 1);
		float depth = 0.0625F;
		Tessellator tessellator = Tessellator.getInstance();

		renderer.begin(7, DefaultVertexFormats.POSITION_TEX_NORMAL);
		renderer.pos(0.0D, 0.0D, 0.0D).tex(u1, v2).normal(0.0F, 0.0F, 1.0F).endVertex();
		renderer.pos(1.0D, 0.0D, 0.0D).tex(u2, v2).normal(0.0F, 0.0F, 1.0F).endVertex();
		renderer.pos(1.0D, 1.0D, 0.0D).tex(u2, v1).normal(0.0F, 0.0F, 1.0F).endVertex();
		renderer.pos(0.0D, 1.0D, 0.0D).tex(u1, v1).normal(0.0F, 0.0F, 1.0F).endVertex();
		tessellator.draw();

		renderer.begin(7, DefaultVertexFormats.POSITION_TEX_NORMAL);
		renderer.pos(0.0D, 1.0D, (0.0F - depth)).tex(u1, v1).normal(0.0F, 0.0F, -1.0F).endVertex();
		renderer.pos(1.0D, 1.0D, (0.0F - depth)).tex(u2, v1).normal(0.0F, 0.0F, -1.0F).endVertex();
		renderer.pos(1.0D, 0.0D, (0.0F - depth)).tex(u2, v2).normal(0.0F, 0.0F, -1.0F).endVertex();
		renderer.pos(0.0D, 0.0D, (0.0F - depth)).tex(u1, v2).normal(0.0F, 0.0F, -1.0F).endVertex();
		tessellator.draw();

		float halfU = 0.5F * (u1 - u2) / width;
		float halfV = 0.5F * (v2 - v1) / height;

		int pixel;
		float pixelPos;
		float mirroredPixelPos;
		float pixelUV;

		renderer.begin(7, DefaultVertexFormats.POSITION_TEX_NORMAL);
		for (pixel = 0; pixel < width; pixel++) {
			pixelPos = (float) pixel / (float) width;
			pixelUV = u1 + (u2 - u1) * pixelPos - halfU;
			renderer.pos(pixelPos, 0.0D, (0.0F - depth)).tex(pixelUV, v2).normal(-1.0F, 0.0F, 0.0F).endVertex();
			renderer.pos(pixelPos, 0.0D, 0.0D).tex(pixelUV, v2).normal(-1.0F, 0.0F, 0.0F).endVertex();
			renderer.pos(pixelPos, 1.0D, 0.0D).tex(pixelUV, v1).normal(-1.0F, 0.0F, 0.0F).endVertex();
			renderer.pos(pixelPos, 1.0D, (0.0F - depth)).tex(pixelUV, v1).normal(-1.0F, 0.0F, 0.0F).endVertex();
		}
		tessellator.draw();

		renderer.begin(7, DefaultVertexFormats.POSITION_TEX_NORMAL);
		for (pixel = 0; pixel < width; pixel++) {
			pixelPos = (float) pixel / (float) width;
			pixelUV = u1 + (u2 - u1) * pixelPos - halfU;
			mirroredPixelPos = pixelPos + 1.0F / width;
			renderer.pos(mirroredPixelPos, 1.0D, (0.0F - depth)).tex(pixelUV, v1).normal(1.0F, 0.0F, 0.0F).endVertex();
			renderer.pos(mirroredPixelPos, 1.0D, 0.0D).tex(pixelUV, v1).normal(1.0F, 0.0F, 0.0F).endVertex();
			renderer.pos(mirroredPixelPos, 0.0D, 0.0D).tex(pixelUV, v2).normal(1.0F, 0.0F, 0.0F).endVertex();
			renderer.pos(mirroredPixelPos, 0.0D, (0.0F - depth)).tex(pixelUV, v2).normal(1.0F, 0.0F, 0.0F).endVertex();
		}
		tessellator.draw();

		renderer.begin(7, DefaultVertexFormats.POSITION_TEX_NORMAL);
		for (pixel = 0; pixel < height; pixel++) {
			pixelPos = (float) pixel / (float) height;
			pixelUV = v2 + (v1 - v2) * pixelPos - halfV;
			renderer.pos(1.0D, pixelPos, 0.0D).tex(u2, pixelUV).normal(0.0F, -1.0F, 0.0F).endVertex();
			renderer.pos(0.0D, pixelPos, 0.0D).tex(u1, pixelUV).normal(0.0F, -1.0F, 0.0F).endVertex();
			renderer.pos(0.0D, pixelPos, (0.0F - depth)).tex(u1, pixelUV).normal(0.0F, -1.0F, 0.0F).endVertex();
			renderer.pos(1.0D, pixelPos, (0.0F - depth)).tex(u2, pixelUV).normal(0.0F, -1.0F, 0.0F).endVertex();
		}
		tessellator.draw();

		renderer.begin(7, DefaultVertexFormats.POSITION_TEX_NORMAL);
		for (pixel = 0; pixel < height; pixel++) {
			pixelPos = (float) pixel / (float) height;
			pixelUV = v2 + (v1 - v2) * pixelPos - halfV;
			mirroredPixelPos = pixelPos + 1.0F / height;
			renderer.pos(0.0D, mirroredPixelPos, 0.0D).tex(u1, pixelUV).normal(0.0F, 1.0F, 0.0F).endVertex();
			renderer.pos(1.0D, mirroredPixelPos, 0.0D).tex(u2, pixelUV).normal(0.0F, 1.0F, 0.0F).endVertex();
			renderer.pos(1.0D, mirroredPixelPos, (0.0F - depth)).tex(u2, pixelUV).normal(0.0F, 1.0F, 0.0F).endVertex();
			renderer.pos(0.0D, mirroredPixelPos, (0.0F - depth)).tex(u1, pixelUV).normal(0.0F, 1.0F, 0.0F).endVertex();
		}
		tessellator.draw();

		GlStateManager.popMatrix();
	}

