@Override
		public int hashCode() {
			final int prime = 31;
			int result = 1;
			result = prime * result + ((model == null) ? 0 : model.hashCode());
			result = prime * result + ((texture == null) ? 0 : texture.hashCode());
			result = prime * result + ((vertexProcessor == null) ? 0 : vertexProcessor.hashCode());
			return result;
		}

@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (getClass() != obj.getClass())
				return false;
			ModelCacheKey other = (ModelCacheKey) obj;
			if (model == null) {
				if (other.model != null)
					return false;
			} else if (!model.equals(other.model))
				return false;
			if (texture == null) {
				if (other.texture != null)
					return false;
			} else if (!texture.equals(other.texture))
				return false;
			if (vertexProcessor == null) {
				if (other.vertexProcessor != null)
					return false;
			} else if (!vertexProcessor.equals(other.vertexProcessor))
				return false;
			return true;
		}

