protected ImmutableMap<String, String> parseMetadata(JsonParser parser, ResourceLocation location) {
		return parseJsonElementList(parser, this.readMetadata(location), location.toString() + " model metadata");
	}

protected String readMetadata(String metadata) {
		if(metadata.startsWith("mlmeta:")) {
			//Load metadata from external file
			metadata = this.readMetadata(new ResourceLocation(metadata.substring("mlmeta:".length())));
		}
		return metadata;
	}

protected String readMetadata(ResourceLocation location) {
		location = new ResourceLocation(location.getNamespace(), location.getPath() + ".mlmeta");
		IResourceManager manager = Minecraft.getMinecraft().getResourceManager();
		try {
			IResource metadataResource = manager.getResource(location);
			return IOUtils.toString(metadataResource.getInputStream());
		} catch (IOException ex) {
			this.throwLoaderException("Failed to load file " + location, ex);
		}
		return "";
	}

public static ImmutableMap<String, String> parseJsonElementList(JsonParser parser, String json, String member) {
		return parseJsonElementList(JsonUtils.getJsonObject(parser.parse(json), member));
	}

public static ImmutableMap<String, String> parseJsonElementList(JsonObject jsonObj) {
		Builder<String, String> parsedElements = ImmutableMap.<String, String>builder();
		for(Entry<String, JsonElement> elementEntry : jsonObj.entrySet()) {
			parsedElements.put(elementEntry.getKey(), elementEntry.getValue().toString());
		}
		return parsedElements.build();
	}

public LoaderExtensionException(String reason, Throwable cause) {
		super(reason, cause);
	}

@Override
	public String getName() {
		return "process_model";
	}

@Override
	public IModel loadModel(IModel original, ResourceLocation location, String arg) {
		IModel processedModel = original;
		String metadata = this.readMetadata(arg);
		JsonParser parser = new JsonParser();
		JsonObject json = JsonUtils.getJsonObject(parser.parse(metadata), location.toString() + " model metadata");

		if(json.has("custom")) {
			if(original == null) {
				this.throwLoaderException("Specified model " + location + " does not support custom data");
			}
			ImmutableMap<String, String> dataMap = parseJsonElementList(JsonUtils.getJsonObject(json.get("custom"), "custom"));
			processedModel = processedModel.process(dataMap);
		}

		if(json.has("smooth_lighting")) {
			if(original == null) {
				this.throwLoaderException("Specified model " + location + " does not support smooth lighting");
			}
			processedModel = processedModel.smoothLighting(JsonUtils.getBoolean(json.get("smooth_lighting"), "smooth_lighting"));
		}

		if(json.has("gui3d")) {
			if(original == null) {
				this.throwLoaderException("Specified model " + location + " does not support gui3d");
			}
			processedModel = processedModel.gui3d(JsonUtils.getBoolean(json.get("gui3d"), "gui3d"));
		}

		if(json.has("uvlock")) {
			if(original == null) {
				this.throwLoaderException("Specified model " + location + " does not support uvlock");
			}
			processedModel = processedModel.uvlock(JsonUtils.getBoolean(json.get("uvlock"), "uvlock"));
		}

		if(json.has("textures")) {
			if(original == null) {
				this.throwLoaderException("Specified model " + location + " does not support retexturing");
			}
			ImmutableMap<String, String> dataMap = parseJsonElementList(JsonUtils.getJsonObject(json.get("textures"), "textures"));
			processedModel = processedModel.retexture(dataMap);
		}
		return processedModel;
	}

