@Override
	public int getBrightnessForRender(float partTicks) {
		int i = super.getBrightnessForRender(partTicks);
		float f1 = (float) this.particleAge / (float) this.particleMaxAge;
		f1 *= f1;
		f1 *= f1;
		int j = i & 255;
		int k = i >> 16 & 255;
		k += (int) (f1 * 15.0F * 16.0F);

		if( k > 240 ) {
			k = 240;
		}

		return j | k << 16;
	}

