@Override
	public void render(TileEntityAnimator te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		int meta = 0;

		if(te != null) {
			meta = te.getBlockMetadata();
		}
		RenderItem renderItem = Minecraft.getMinecraft().getRenderItem();

		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		bindTexture(TEXTURE);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x + 0.5F, y + 1.5F, z + 0.5F);
		GlStateManager.scale(1F, -1F, -1F);
		GlStateManager.rotate(meta * 90.0F - 180.0F, 0.0F, 1F, 0F);
		GlStateManager.disableCull();
		model.render(null, 0, 0, 0, 0, 0, 0.0625F);
		GlStateManager.enableCull();
		GlStateManager.popMatrix();

		if(te != null) {
			SplittableRandom rand = new SplittableRandom((long) (te.getPos().getX() + te.getPos().getY() + te.getPos().getZ()));
			double viewRot = 180D + Math.toDegrees(Math.atan2(x + 0.5D, z + 0.5D));

			// Sulfur rendering
			if (!te.getStackInSlot(2).isEmpty()) {
				GlStateManager.pushMatrix();
				GlStateManager.translate(x + 0.5D, y + 0.27D, z + 0.5D);
				GlStateManager.rotate(180, 1, 0, 0);
				int items = te.getStackInSlot(2).getCount() / 4 + 1;
				for (int i = 0; i < items; i++) {
					GlStateManager.pushMatrix();
					GlStateManager.translate(rand.nextDouble() / 3.0D - 1.0D / 6.0D, 0.0D, rand.nextDouble() / 3.0D - 1.0D / 6.0D);
					GlStateManager.rotate((float)rand.nextDouble() * 30.0f - 15.0f, 1, 0, 0);
					GlStateManager.rotate((float)rand.nextDouble() * 30.0f - 15.0f, 0, 0, 1);
					GlStateManager.scale(0.125D, 0.125D, 0.125D);
					GlStateManager.rotate(90, 1, 0, 0);
					GlStateManager.rotate((float)rand.nextDouble() * 360.0F, 0, 0, 1);
					ItemStack stack = ItemMisc.EnumItemMisc.SULFUR.create(1);
					renderItem.renderItem(stack, TransformType.FIXED);
					GlStateManager.popMatrix();
				}
				GlStateManager.popMatrix();
			}

			// Life crystal
			ItemStack crystal = te.getStackInSlot(1);
			if (!crystal.isEmpty()) {
				GlStateManager.pushMatrix();
				GlStateManager.translate(x + 0.5D, y + 0.43D, z + 0.5D);
				GlStateManager.scale(0.18D, 0.18D, 0.18D);
				GlStateManager.rotate((float) viewRot + 180, 0, 1, 0);
				renderItem.renderItem(crystal, TransformType.FIXED);
				GlStateManager.popMatrix();
			}

			// Item
			ItemStack input = te.getStackInSlot(0);
			if (!input.isEmpty()) {
				GlStateManager.pushMatrix();
				GlStateManager.translate(x + 0.5D, y + 1.43D, z + 0.5D);

				IAnimatorRecipe recipe = AnimatorRecipe.getRecipe(input);

				if(recipe != null) {
					if (!(input.getItem() instanceof ItemMonsterPlacer) && (recipe == null || recipe.getRenderEntity(input) == null)) {
						GlStateManager.scale(0.3D, 0.3D, 0.3D);
						GlStateManager.rotate((float) viewRot + 180, 0, 1, 0);
						ItemStack stack = te.getStackInSlot(0);
						renderItem.renderItem(stack, TransformType.FIXED);
					} else {
						GlStateManager.enableBlend();
						GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
						GlStateManager.color(1.0F, 1.0F, 1.0F, 0.65F);
						Entity entity = null;
						if (recipe.getRenderEntity(input) != null) {
							entity = recipe.getRenderEntity(input);
						} else if (input.getItem() instanceof ItemMonsterPlacer) {
							entity = EntityList.createEntityByID(input.getItemDamage(), te.getWorld());
						}
						if (entity != null) {
							GlStateManager.translate(0.0D, -entity.height / 4.0D, 0.0D);
							GlStateManager.rotate((float) viewRot, 0, 1, 0);
							GlStateManager.scale(0.75D, 0.75D, 0.75D);
							entity.setWorld(te.getWorld());
							entity.setRotationYawHead(0F);
							entity.rotationPitch = 0F;
							entity.ticksExisted = (int) this.getWorld().getTotalWorldTime();
							Minecraft.getMinecraft().getRenderManager().renderEntity(entity, 0D, 0D, 0D, 0F, 0F, true);
						}
						GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
					}
				}

				GlStateManager.popMatrix();
			}
		}
	}

@Override
	public void render(TileEntityAspectVial te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		BlockDentrothyst.EnumDentrothyst type = StatePropertyHelper.getStatePropertySafely(te, BlockAspectVial.class, BlockAspectVial.TYPE, EnumDentrothyst.GREEN);
		switch(type) {
		default:
		case GREEN:
			bindTexture(TEXTURE1);
			break;
		case ORANGE:
			bindTexture(TEXTURE2);
			break;
		}

		float randX = 0;
		float randZ = 0;

		if(StatePropertyHelper.getStatePropertySafely(te, BlockAspectVial.class, BlockAspectVial.RANDOM_POSITION, true)) {
			long posRand = (long)(te.getPos().getY() * 224856) ^ (te.getPos().getX() * 3129871) ^ (long)te.getPos().getZ() * 116129781L;
			posRand = posRand * posRand * 42317861L + posRand * 11L;
			randX = (((float)(posRand >> 16 & 15L) / 15.0F) - 0.5F) * 0.45F;
			randZ = (((float)(posRand >> 24 & 15L) / 15.0F) - 0.5F) * 0.45F;
		}

		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
		GlStateManager.scale(1F, -1F, -1F);
		GlStateManager.translate(-0.3F + randX, -0.001F, 0.25F + randZ);

		GlStateManager.depthMask(false);
		MODEL.davids_jar.render(0.0625F);
		GlStateManager.depthMask(true);

		if(te.getAspect() != null) {
			GlStateManager.blendFunc(SourceFactor.ONE, DestFactor.ONE);

			GlStateManager.disableTexture2D();
			float[] aspectRGBA = ColorUtils.getRGBA(te.getAspect().type.getColor());
			GlStateManager.color(aspectRGBA[0], aspectRGBA[1], aspectRGBA[2], 0.98F);

			float filled = te.getAspect().amount / TileEntityAspectVial.MAX_AMOUNT;

			if(filled != 0.0F) {
				LightingUtil.INSTANCE.setLighting(255);
				GlStateManager.enableNormalize();
				GlStateManager.pushMatrix();
				GlStateManager.translate(0, -(23.5F * 0.0625F) * filled + (23.5F * 0.0625F), 0);
				GlStateManager.scale(1, filled, 1);
				MODEL.jar_liquid.render(0.0625F);
				GlStateManager.popMatrix();
				GlStateManager.disableNormalize();
				LightingUtil.INSTANCE.revert();
			}

			GlStateManager.enableTexture2D();
			GlStateManager.color(1, 1, 1, 1.0F);

			GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		}

		GlStateManager.colorMask(false, false, false, false);
		MODEL.davids_jar.render(0.0625F);
		GlStateManager.colorMask(true, true, true, true);

		GlStateManager.cullFace(CullFace.FRONT);
		MODEL.davids_jar.render(0.0625F);
		GlStateManager.cullFace(CullFace.BACK);

		GlStateManager.popMatrix();
	}

@Override
	public void render(TileEntityAspectrusCrop tile, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		Random rnd = new Random();
		long seed = tile.getPos().getX() * 0x2FC20FL ^ tile.getPos().getY() * 0x6EBFFF5L ^ tile.getPos().getZ();
		rnd.setSeed(seed * seed * 0x285B825L + seed * 11L);
		int rndRot = rnd.nextInt(4);

		Aspect aspect = tile.getAspect();

		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
		GlStateManager.scale(1F, -1F, -1F);
		GlStateManager.rotate(rndRot * 90.0F, 0, 1, 0);
		GlStateManager.disableCull();

		int index = StatePropertyHelper.getStatePropertySafely(tile, BlockAspectrusCrop.class, BlockRegistry.ASPECTRUS_CROP.getStageProperty(), 0, true, false) / 2;
		if(index <= 4) {
			index = index / 2;
		} else {
			index = index - 2;
		}
		if(index >= 5 && StatePropertyHelper.getStatePropertySafely(tile, BlockAspectrusCrop.class, BlockGenericCrop.DECAYED, false, true, false)) {
			index = 6;
		}

		if(index >= 4 && ShaderHelper.INSTANCE.isWorldShaderActive() && aspect != null) {
			float[] rgba = ColorUtils.getRGBA(aspect.type.getColor());
			ShaderHelper.INSTANCE.require();
			float brightness = ((float)Math.sin((tile.glowTicks + partialTicks) / 15.0F) * (float)Math.cos((tile.glowTicks + partialTicks + 4) / 80.0F) + 1.0F) / 2.0F;
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(tile.getPos().getX() + 0.5D, tile.getPos().getY() + 0.5D, tile.getPos().getZ() + 0.5D, 
					brightness * brightness * 4.0F,
					rgba[0] * brightness * brightness * 2.5F,
					rgba[1] * brightness * brightness * 2.5F,
					rgba[2] * brightness * brightness * 2.5F));
		}

		switch(index) {
		case 0:
			this.bindTexture(TEXTURE_0);
			break;
		case 1:
			this.bindTexture(TEXTURE_1);
			break;
		case 2:
			this.bindTexture(TEXTURE_2);
			break;
		case 3:
			this.bindTexture(TEXTURE_3);
			break;
		case 4:
			this.bindTexture(TEXTURE_4);
			break;
		case 5:
			this.bindTexture(TEXTURE_5);
			break;
		case 6:
			this.bindTexture(TEXTURE_6);
			break;
		}

		switch(index) {
		case 0:
		case 1:
			MODEL1.render();
			break;
		case 2:
		case 3:
			MODEL2.render();
			break;
		case 4:
			if(aspect != null) {
				float[] rgba = ColorUtils.getRGBA(aspect.type.getColor());
				GlStateManager.color(rgba[0], rgba[1], rgba[2], 0.85F);
				LightingUtil.INSTANCE.setLighting(255);
			}
			MODEL3.renderFruitAspects();
			if(aspect != null) {
				LightingUtil.INSTANCE.revert();
			}
			GlStateManager.color(1, 1, 1, 1);
			MODEL3.renderPlant();
			break;
		case 5:
		default:
			if(aspect != null) {
				float[] rgba = ColorUtils.getRGBA(aspect.type.getColor());
				GlStateManager.color(rgba[0], rgba[1], rgba[2], 0.85F);
				LightingUtil.INSTANCE.setLighting(255);
			}
			MODEL4.renderFruitAspects();
			if(aspect != null) {
				LightingUtil.INSTANCE.revert();
			}
			GlStateManager.color(1, 1, 1, 1);
			MODEL4.renderPlant();
			break;
		case 6:
			//Decay
			MODEL4.renderPlant();
			break;
		}

		GlStateManager.enableCull();
		GlStateManager.popMatrix();
	}

@Override
	public void renderTileEntityFast(TileEntityBarrel te, double x, double y, double z, float partialTicks, int destroyStage, float partial, BufferBuilder buffer) {
		IFluidTankProperties props = te.getTankProperties()[0];
		FluidStack fluid = props.getContents();

		if(fluid != null && fluid.amount > 0) {
			ResourceLocation texture = fluid.getFluid().getStill();

			if(texture == null) {
				texture = WHITE_SPRITE_PATH;
			}

			TextureAtlasSprite sprite = Minecraft.getMinecraft().getTextureMapBlocks().getAtlasSprite(texture.toString());

			int maxAmount = props.getCapacity();

			World world = te.getWorld();
			BlockPos pos = te.getPos();

			IBlockState state = world.getBlockState(pos);

			int packedLightmap = state.getPackedLightmapCoords(world, pos);
			int skyLight = packedLightmap >> 16 & 65535;
			int blockLight = packedLightmap & 65535;

			float height = fluid.amount / (float)maxAmount * 0.8f + 0.13f;

			int color = fluid.getFluid().getColor(fluid);

			float r = ((color >> 16) & 0xFF) / 255f;
			float g = ((color >> 8) & 0xFF) / 255f;
			float b = ((color >> 0) & 0xFF) / 255f;
			float a = ((color >> 24) & 0xFF) / 255f;

			float minU = sprite.getMinU();
			float minV = sprite.getMinV();
			float maxU = sprite.getMaxU();
			float maxV = sprite.getMaxV();

			float width = 0.5F;
			float depth = 0.5F;

			float offX = (1 - width) / 2.0f;
			float offZ = (1 - depth) / 2.0f;

			buffer.setTranslation(x, y, z);

			buffer.pos(offX, height, offZ).color(r, g, b, a).tex(minU, maxV).lightmap(skyLight, blockLight).endVertex();
			buffer.pos(offX, height, 1 - offZ).color(r, g, b, a).tex(minU, minV).lightmap(skyLight, blockLight).endVertex();
			buffer.pos(1 - offX, height, 1 - offZ).color(r, g, b, a).tex(maxU, minV).lightmap(skyLight, blockLight).endVertex();
			buffer.pos(1 - offX, height, offZ).color(r, g, b, a).tex(maxU, maxV).lightmap(skyLight, blockLight).endVertex();

			buffer.setTranslation(0, 0, 0);
		}
	}

@Override
	public void render(TileEntityBeamOrigin te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		GlStateManager.pushMatrix();
		GlStateManager.enableRescaleNormal();
		GlStateManager.translate(x + 0.5F, y - 1.5F, z + 0.5F);
		GlStateManager.enableBlend();
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);

		LightingUtil.INSTANCE.setLighting(255);

		GlStateManager.disableLighting();

		float visibility = te.prevVisibility + (te.visibility - te.prevVisibility) * partialTicks;

		RotationMatrix m = new RotationMatrix();
		m.setRotations(0, te.prevRotation + (te.rotation - te.prevRotation) * partialTicks, 0);

		double h = 1.65D;
		double w = 0.45D;

		Vec3d v0 = new Vec3d(-w, 0, 0).add(w, 1, 0);
		Vec3d v1 = new Vec3d(0, h, w).add(w, 1, 0);
		Vec3d v2 = new Vec3d(0, h, -w).add(w, 1, 0);

		Vec3d mid = Vec3d.ZERO;

		this.renderMirrorTri(te, m.transformVec(v0, mid), m.transformVec(v1, mid), m.transformVec(v2, mid), visibility, partialTicks);
		this.renderMirrorTri(te, m.transformVec(v0, mid), m.transformVec(v1.add(-w*2, 0, 0), mid), m.transformVec(v2.add(0, 0, w*2), mid), visibility, partialTicks);
		this.renderMirrorTri(te, m.transformVec(v0, mid), m.transformVec(v1.add(-w*2, 0, -w*2), mid), m.transformVec(v2.add(-w*2, 0, w*2), mid), visibility, partialTicks);
		this.renderMirrorTri(te, m.transformVec(v0, mid), m.transformVec(v1.add(0, 0, -w*2), mid), m.transformVec(v2.add(-w*2, 0, 0), mid), visibility, partialTicks);

		Vec3d p0 = m.transformVec(v1, mid);
		Vec3d p1 = m.transformVec(v1.add(-w*2, 0, 0), mid);
		Vec3d p2 = m.transformVec(v1.add(-w*2, 0, -w*2), mid);
		Vec3d p3 = m.transformVec(v1.add(0, 0, -w*2), mid);

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder bufferBuilder = tessellator.getBuffer();

		GlStateManager.disableTexture2D();
		GlStateManager.color(visibility, visibility, visibility, 0.75f + 0.25f * (1 - visibility));

		bufferBuilder.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION);

		bufferBuilder.pos(p3.x, p3.y, p3.z).endVertex();
		bufferBuilder.pos(p2.x, p2.y, p2.z).endVertex();
		bufferBuilder.pos(p1.x, p1.y, p1.z).endVertex();
		bufferBuilder.pos(p0.x, p0.y, p0.z).endVertex();

		tessellator.draw();

		GlStateManager.color(0, 0, 0, 0.9f * (1 - visibility));

		bufferBuilder.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION);

		bufferBuilder.pos(p3.x, p3.y, p3.z).endVertex();
		bufferBuilder.pos(p2.x, p2.y, p2.z).endVertex();
		bufferBuilder.pos(p1.x, p1.y, p1.z).endVertex();
		bufferBuilder.pos(p0.x, p0.y, p0.z).endVertex();

		tessellator.draw();

		this.bindTexture(new ResourceLocation(ModInfo.ID, "textures/tiles/prism_mirror.png"));

		GlStateManager.enableTexture2D();
		GlStateManager.color(visibility, visibility, visibility, visibility);

		bufferBuilder.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX);

		bufferBuilder.pos(p3.x, p3.y, p3.z).tex(0.25, 0.25).endVertex();
		bufferBuilder.pos(p2.x, p2.y, p2.z).tex(0.25, 0.75).endVertex();
		bufferBuilder.pos(p1.x, p1.y, p1.z).tex(0.75, 0.75).endVertex();
		bufferBuilder.pos(p0.x, p0.y, p0.z).tex(0.25, 0.75).endVertex();

		tessellator.draw();

		RenderHelper.enableStandardItemLighting();

		GlStateManager.shadeModel(GL11.GL_FLAT);

		GlStateManager.enableLighting();

		LightingUtil.INSTANCE.revert();

		GlStateManager.disableRescaleNormal();
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.popMatrix();
	}

