public boolean isSafeMobItem(TileEntityCrabPot te) {
		return te.getStackInSlot(0).getItem() instanceof ItemMob && (te.getEntity() instanceof EntitySiltCrab || te.getEntity() instanceof EntityBubblerCrab);
	}

public void renderMobInSlot(Entity entity, float x, float y, float z, float rotation) {
		if (entity != null) {
			float scale = 0.95F;
			float tumble = rotation * 11.25F;
			float offsetRotation = 90F;
			float offsetY = 0.0625F;
			GlStateManager.pushMatrix();
			GlStateManager.translate(x, y + offsetY, z);
			GlStateManager.scale(scale, scale, scale);
			if(tumble > 0F)
				GlStateManager.rotate(tumble, 1.0F, 0.0F, 0.0F);
			else
				GlStateManager.rotate(0F, 1.0F, 0.0F, 0.0F);
			GlStateManager.rotate(offsetRotation - Minecraft.getMinecraft().getRenderManager().playerViewY, 0.0F, 1.0F, 0.0F);
			Render<Entity> renderer = Minecraft.getMinecraft().getRenderManager().getEntityRenderObject(entity);
			renderer.doRender(entity, 0, 0, 0, 0, 0);
			GlStateManager.popMatrix();
		}
	}

public void renderItemInSlot(ItemStack stack, float x, float y, float z, float scale) {
		if (!stack.isEmpty()) {
			GlStateManager.pushMatrix();
			GlStateManager.translate(x, y, z);
			GlStateManager.scale(scale, scale, scale);
			GlStateManager.rotate(-Minecraft.getMinecraft().getRenderManager().playerViewY, 0.0F, 1.0F, 0.0F);
			Minecraft.getMinecraft().getRenderItem().renderItem(stack, TransformType.FIXED);
			GlStateManager.popMatrix();
		}
	}

@Override
	public void render(TileEntityCrabPotFilter te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		int index = te != null ? te.getRotation() : 0;
		GlStateManager.pushMatrix();
		GlStateManager.translate((float) x + 0.5f, (float) y, (float) z + 0.5f);
		GlStateManager.pushMatrix();
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1, 1, 1, 1);
		GlStateManager.translate(0, 1.5f, 0);
		GlStateManager.rotate(getRotation(index), 0.0F, 1F, 0F);
		GlStateManager.scale(1.005F, -1F, -1.005F);
		bindTexture(TEXTURE);
		MODEL.render();
		GlStateManager.popMatrix();
		GlStateManager.popMatrix();

		if(te != null) {
			RenderItem renderItem = Minecraft.getMinecraft().getRenderItem();
			SplittableRandom rand = new SplittableRandom((long) (te.getPos().getX() + te.getPos().getY() + te.getPos().getZ()));

			// input rendering
			if (!te.getStackInSlot(1).isEmpty() && te.isActive() && te.hasBait() && te.getSlotProgress() > 0) {
				GlStateManager.pushMatrix();
				GlStateManager.translate(x + 0.5D + getItemOffsetX(index), y + 1.25D - (double) (te.getFilteringAnimationScaled(200, partialTicks) * 0.000625D), z + 0.5D + getItemOffsetZ(index));
				GlStateManager.pushMatrix();
				GlStateManager.scale(0.5D - (float) (te.getFilteringAnimationScaled(200, partialTicks) * 0.0025F), 0.5D - (float) (te.getFilteringAnimationScaled(200, partialTicks) * 0.0025F), 0.5D - (float) (te.getFilteringAnimationScaled(200, partialTicks) * 0.0025F));
				GlStateManager.rotate(-90F - index * 90F, 0, 1, 0);
				GlStateManager.rotate((float) (te.getFilteringAnimationScaled(200, partialTicks) * 2F), 1, 0, 1);
				ItemStack stack = te.getStackInSlot(1);
				renderItem.renderItem(stack, TransformType.FIXED);
				GlStateManager.popMatrix();
				GlStateManager.popMatrix();
			}

			// result rendering
			if (!te.getStackInSlot(2).isEmpty()) {
				GlStateManager.pushMatrix();
				double yUp = 0.25D;
				if (te.getStackInSlot(2).getItem() instanceof ItemBlock)
					yUp = 0.29D;
				GlStateManager.translate(x + 0.5D, y + yUp, z + 0.5D);
				GlStateManager.rotate(180, 1, 0, 0);
				int items = te.getStackInSlot(2).getCount() / 2 + 1;
				for (int i = 0; i < items; i++) {
					GlStateManager.pushMatrix();
					GlStateManager.translate(rand.nextDouble() / 2.0D - 1.0D / 4.0D, 0.0D, rand.nextDouble() / 2.0D - 1.0D / 4.0D);
					GlStateManager.rotate((float) rand.nextDouble() * 30.0f - 15.0f, 1, 0, 0);
					GlStateManager.rotate((float) rand.nextDouble() * 30.0f - 15.0f, 0, 0, 1);
					GlStateManager.scale(0.25D, 0.25D, 0.25D);
					GlStateManager.rotate(90, 1, 0, 0);
					GlStateManager.rotate((float) rand.nextDouble() * 360.0F, 0, 0, 1);
					ItemStack stack = te.getStackInSlot(2);
					renderItem.renderItem(stack, TransformType.FIXED);
					GlStateManager.popMatrix();
				}
				GlStateManager.popMatrix();
			}
		}
	}

