private void setGLColorFromInt(int color, float alpha) {
		float red = (color >> 16 & 0xFF) / 255.0F;
		float green = (color >> 8 & 0xFF) / 255.0F;
		float blue = (color & 0xFF) / 255.0F;
		GlStateManager.color(red, green, blue, alpha);
	}

private void renderCuboid(BufferBuilder buffer, float xMax, float xMin, float yMin, float height, float zMin, float zMax, TextureAtlasSprite textureAtlasSprite) {

		double uMin = (double) textureAtlasSprite.getMinU();
		double uMax = (double) textureAtlasSprite.getMaxU();
		double vMin = (double) textureAtlasSprite.getMinV();
		double vMax = (double) textureAtlasSprite.getMaxV();

		final double vHeight = vMax - vMin;

		// top
		addVertexWithUV(buffer, xMax, height, zMax, uMax, vMin);
		addVertexWithUV(buffer, xMax, height, zMin, uMin, vMin);
		addVertexWithUV(buffer, xMin, height, zMin, uMin, vMax);
		addVertexWithUV(buffer, xMin, height, zMax, uMax, vMax);

		// north
		addVertexWithUV(buffer, xMax, yMin, zMin, uMax, vMin);
		addVertexWithUV(buffer, xMin, yMin, zMin, uMin, vMin);
		addVertexWithUV(buffer, xMin, height, zMin, uMin, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMax, height, zMin, uMax, vMin + (vHeight * height));

		// south
		addVertexWithUV(buffer, xMax, yMin, zMax, uMin, vMin);
		addVertexWithUV(buffer, xMax, height, zMax, uMin, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMin, height, zMax, uMax, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMin, yMin, zMax, uMax, vMin);

		// east
		addVertexWithUV(buffer, xMax, yMin, zMin, uMin, vMin);
		addVertexWithUV(buffer, xMax, height, zMin, uMin, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMax, height, zMax, uMax, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMax, yMin, zMax, uMax, vMin);

		// west
		addVertexWithUV(buffer, xMin, yMin, zMax, uMin, vMin);
		addVertexWithUV(buffer, xMin, height, zMax, uMin, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMin, height, zMin, uMax, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMin, yMin, zMin, uMax, vMin);

		// down
		addVertexWithUV(buffer, xMax, yMin, zMin, uMax, vMin);
		addVertexWithUV(buffer, xMax, yMin, zMax, uMin, vMin);
		addVertexWithUV(buffer, xMin, yMin, zMax, uMin, vMax);
		addVertexWithUV(buffer, xMin, yMin, zMin, uMax, vMax);
	}

private void addVertexWithUV(BufferBuilder buffer, float x, float y, float z, double u, double v) {
		buffer.pos(x / 2f, y, z / 2f).tex(u, v).endVertex();
	}

@Override
	public void render(TileEntityInfuser infuser, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		bindTexture(TEXTURE);

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		if(infuser == null || !infuser.hasWorld()) {
			GlStateManager.pushMatrix();
			GlStateManager.translate((float) 0.5F, (float) 1.5F, (float) 0.5F);
			GlStateManager.scale(1F, -1F, -1F);
			model.render();
			GlStateManager.popMatrix();
			return;
		}

		BlockPos pos = infuser.getPos();
		EnumFacing facing = StatePropertyHelper.getStatePropertySafely(infuser, BlockInfuser.class, BlockInfuser.FACING, EnumFacing.NORTH);
		GlStateManager.pushMatrix();
		GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
		GlStateManager.scale(1F, -1F, -1F);
		switch (facing) {
		default:
		case NORTH:
			GlStateManager.rotate(180F, 0.0F, 1F, 0F);
			break;
		case WEST:
			GlStateManager.rotate(0F, 0.0F, 1F, 0F);
			break;
		case EAST:
			GlStateManager.rotate(90F, 0.0F, 1F, 0F);
			break;
		case SOUTH:
			GlStateManager.rotate(-90F, 0.0F, 1F, 0F);
			break;
		}
		model.render();
		GlStateManager.pushMatrix();
		GlStateManager.rotate(infuser.getStirProgress() * 4, 0.0F, 1F, 0F);
		model.renderSpoon();
		GlStateManager.popMatrix();
		GlStateManager.popMatrix();

		ElixirRecipe recipe = infuser.getInfusingRecipe();

		if(BetweenlandsConfig.DEBUG.debug) {
			String elixirName = recipe != null ? recipe.name : " N/A";
			renderStirCount("Evap: " + infuser.getEvaporation() + " Temp: "+ infuser.getTemperature() + " Time: " + infuser.getInfusionTime() + " Recipe: " + elixirName, x, y, z);
		}

		int amount = infuser.waterTank.getFluidAmount();
		int capacity = infuser.waterTank.getCapacity();
		float size = 1F / capacity * amount;

		int itemBob = infuser.getItemBob();
		int stirProgress = infuser.getStirProgress();
		float crystalRotation = infuser.getCrystalRotation();
		double itemY = y + 0.3D + size * 0.5D;
		Random rand = new Random();
		rand.setSeed((long) (pos.getX() + pos.getY() + pos.getZ()));
		for(int i = 0; i <= TileEntityInfuser.MAX_INGREDIENTS; i++) {
			float randRot = rand.nextFloat() * 360.0F;
			double xo = -0.2D + rand.nextFloat() * 0.4D;
			double zo = -0.2D + rand.nextFloat() * 0.4D;
			double rot = (stirProgress < 90 && amount >= 100 ? stirProgress * 4D + 45D : 45D) + randRot;
			GlStateManager.pushMatrix();
			GlStateManager.translate(x + 0.5D, 0, z + 0.5D);
			GlStateManager.rotate((float)-rot, 0, 1, 0);
			GlStateManager.translate(xo, 0, zo);
			renderItemInSlot(infuser, i, 0, itemY, 0, amount >= 100 ? (i % 2 == 0 ? (itemBob * 0.01D) : ((-itemBob + 20) * 0.01D)) : 0.0D, -rot);
			GlStateManager.popMatrix();
		}

		renderItemInSlot(infuser, TileEntityInfuser.MAX_INGREDIENTS + 1, x + 0.5, y + 1.43D, z + 0.5D, itemBob * 0.01D, crystalRotation);

		if (amount >= 100) {
			Tessellator tess = Tessellator.getInstance();
			BufferBuilder vb = tess.getBuffer();
			TextureAtlasSprite waterSprite = Minecraft.getMinecraft().getTextureMapBlocks().getAtlasSprite(FluidRegistry.SWAMP_WATER.getStill().toString());
			GlStateManager.pushMatrix();
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(770, 771);
			bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
			float tx = (float) x + 0.0F;
			float ty = (float) (y + 0.35F + size * 0.5F);
			float tz = (float) z + 0.0F;
			vb.setTranslation(tx, ty, tz);
			vb.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);
			float[] targetColor;
			if(infuser.getInfusionColorGradientTicks() > 0) {
				targetColor = new float[] {
						infuser.prevInfusionColor[0] + (infuser.currentInfusionColor[0] - infuser.prevInfusionColor[0]) / 30.0F * infuser.getInfusionColorGradientTicks(),
						infuser.prevInfusionColor[1] + (infuser.currentInfusionColor[1] - infuser.prevInfusionColor[1]) / 30.0F * infuser.getInfusionColorGradientTicks(),
						infuser.prevInfusionColor[2] + (infuser.currentInfusionColor[2] - infuser.prevInfusionColor[2]) / 30.0F * infuser.getInfusionColorGradientTicks(),
						infuser.prevInfusionColor[3] + (infuser.currentInfusionColor[3] - infuser.prevInfusionColor[3]) / 30.0F * infuser.getInfusionColorGradientTicks()
				};
			} else {
				targetColor = infuser.currentInfusionColor;
			}
			vb.pos(0.1875, 0, 0.1875).tex(waterSprite.getMinU(), waterSprite.getMinV()).color(targetColor[0], targetColor[1], targetColor[2], targetColor[3]).endVertex();
			vb.pos(0.1875, 0, 0.8125).tex(waterSprite.getMinU(), waterSprite.getMaxV()).color(targetColor[0], targetColor[1], targetColor[2], targetColor[3]).endVertex();
			vb.pos(0.8125, 0, 0.8125).tex(waterSprite.getMaxU(), waterSprite.getMaxV()).color(targetColor[0], targetColor[1], targetColor[2], targetColor[3]).endVertex();
			vb.pos(0.8125, 0, 0.1875).tex(waterSprite.getMaxU(), waterSprite.getMinV()).color(targetColor[0], targetColor[1], targetColor[2], targetColor[3]).endVertex();
			vb.setTranslation(0, 0, 0);
			tess.draw();
			GlStateManager.disableBlend();
			GlStateManager.popMatrix();
		}
	}

private void renderItemInSlot(TileEntityInfuser infuser, int slotIndex, double x, double y, double z, double itemBob, double rotation) {
		if (!infuser.getStackInSlot(slotIndex).isEmpty()) {
			GlStateManager.pushMatrix();
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
			GlStateManager.translate(x, y, z);
			GlStateManager.scale(0.25D, 0.25D, 0.25D);
			GlStateManager.translate(0D, itemBob, 0D);
			GlStateManager.rotate((float) rotation, 0, 1, 0);
			Minecraft.getMinecraft().getRenderItem().renderItem(infuser.getStackInSlot(slotIndex), TransformType.FIXED);
			GlStateManager.popMatrix();
		}
	}

private void renderStirCount(String count, double x, double y, double z) {
		float scale = 0.02666667F;
		float height = 0.8F;

		GlStateManager.pushMatrix();
		GlStateManager.translate(x + 0.5F, y + height + 0.75F, z + 0.5F);
		GlStateManager.glNormal3f(0.0F, 1.0F, 0.0F);
		GlStateManager.rotate(-Minecraft.getMinecraft().getRenderManager().playerViewY, 0.0F, 1.0F, 0.0F);
		GlStateManager.rotate(Minecraft.getMinecraft().getRenderManager().playerViewX, 1.0F, 0.0F, 0.0F);
		GlStateManager.scale(-scale, -scale, scale);
		GlStateManager.disableLighting();
		GlStateManager.depthMask(false);
		GlStateManager.disableDepth();
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.disableTexture2D();

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder vb = tessellator.getBuffer();

		vb.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_COLOR);
		FontRenderer fontrenderer = Minecraft.getMinecraft().fontRenderer;
		int width = fontrenderer.getStringWidth(count) / 2;
		vb.pos(-width - 1, -1, 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		vb.pos(-width - 1, 8, 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		vb.pos(width + 1, 8, 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		vb.pos(width + 1, -1, 0.0D).color(0.0F, 0.0F, 0.0F, 0.25F).endVertex();
		tessellator.draw();

		GlStateManager.enableTexture2D();
		fontrenderer.drawString(count, -fontrenderer.getStringWidth(count) / 2, 0, 553648127);
		GlStateManager.enableDepth();
		GlStateManager.depthMask(true);
		fontrenderer.drawString(count, -fontrenderer.getStringWidth(count) / 2, 0, -1);
		GlStateManager.enableLighting();
		GlStateManager.disableBlend();
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.popMatrix();
	}

@Override
	public void render(TileEntityItemCage tile, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		float ticks = (float) (720.0 * (System.currentTimeMillis() & 0x3FFFL) / 0x3FFFL);

		if(ShaderHelper.INSTANCE.isWorldShaderActive() && tile != null) {
			ShaderHelper.INSTANCE.require();
			ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(tile.getPos().getX() + 0.5D, tile.getPos().getY() + 0.5D, tile.getPos().getZ() + 0.5D, 
					3.5f,
					5.0f / 255.0f * 16.0F, 
					40.0f / 255.0f * 16.0F, 
					60.0f / 255.0f * 16.0F));
		}

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		GlStateManager.pushMatrix();
		GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
		GlStateManager.scale(1, -1, -1);
		float f1 = ticks;
		bindTexture(FORCE_TEXTURE);
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		float f2 = f1 * 0.0015F;
		float f3 = f1 * 0.0015F;
		GlStateManager.translate(f2, f3, f2);
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableBlend();
		float f4 = 0.5F;
		GlStateManager.color(f4, f4, f4, 1.0F);
		GlStateManager.disableLighting();
		GlStateManager.blendFunc(GL11.GL_ONE, GL11.GL_ONE);
		model.renderBars();
		GlStateManager.matrixMode(GL11.GL_TEXTURE);
		GlStateManager.loadIdentity();
		GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		GlStateManager.enableLighting();
		GlStateManager.disableBlend();
		GlStateManager.popMatrix();

		GlStateManager.pushMatrix();
		GlStateManager.enableBlend();
		GlStateManager.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE_MINUS_SRC_ALPHA);
		GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
		GlStateManager.scale(1, -1, -1);
		bindTexture(CAGE_TEXTURE);
		model.renderSolid();
		GlStateManager.disableBlend();
		GlStateManager.popMatrix();
	}

@Override
	public void render(TileEntityItemShelf te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		if(te != null) {
			double unitPixel = 0.0625D;
			double offSetX = 0;
			double offSetZ = 0;
			double offSetXX = 0;
			double offSetZZ = 0;
			float rotation = 0;

			switch (StatePropertyHelper.getStatePropertySafely(te, BlockItemShelf.class, BlockItemShelf.FACING, EnumFacing.NORTH)) {
			default:
			case NORTH:
				rotation = 0F;
				offSetX = unitPixel * 3.75;
				offSetZ = unitPixel * 3.75;
				offSetXX = unitPixel * 12;
				offSetZZ = unitPixel * 3.75;
				break;
			case SOUTH:
				rotation = 180F;
				offSetX = unitPixel * 12;
				offSetZ = unitPixel * 12;
				offSetXX = unitPixel * 3.75;
				offSetZZ = unitPixel * 12;
				break;
			case EAST:
				rotation = -90F;
				offSetX = unitPixel * 12;
				offSetZ = unitPixel * 3.75;
				offSetXX = unitPixel * 12;
				offSetZZ = unitPixel * 12;
				break;
			case WEST:
				rotation = 90F;
				offSetX = unitPixel * 3.75;
				offSetZ = unitPixel * 12;
				offSetXX = unitPixel * 3.75;
				offSetZZ = unitPixel * 3.75;
				break;
			}

			this.renderItemInSlot(te, 0, x + offSetX, y + unitPixel * 11, z + offSetZ, rotation);
			this.renderItemInSlot(te, 1, x + offSetXX, y + unitPixel * 11, z + offSetZZ, rotation);
			this.renderItemInSlot(te, 2, x + offSetX, y + unitPixel * 3, z + offSetZ, rotation);
			this.renderItemInSlot(te, 3, x + offSetXX, y + unitPixel * 3, z + offSetZZ, rotation);
		}
	}

protected void renderItemInSlot(TileEntityItemShelf te, int slot, double x, double y, double z, float rotation) {
		ItemStack stack = te.getStackInSlot(slot);

		if (!stack.isEmpty()) {
			RenderItem renderItem = Minecraft.getMinecraft().getRenderItem();
			GlStateManager.pushMatrix();
			GlStateManager.pushAttrib();
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
			GlStateManager.translate(x, y, z);
			GlStateManager.rotate(rotation, 0.0F, 1F, 0F);
			GlStateManager.scale(0.4F, 0.4F, 0.4F);
			RenderHelper.enableStandardItemLighting();

			if (!renderItem.shouldRenderItemIn3D(stack) || stack.getItem() instanceof ItemSkull) {
				GlStateManager.rotate(180.0F, 0.0F, 1.0F, 0.0F);
			}

			renderItem.renderItem(stack, ItemCameraTransforms.TransformType.FIXED);

			RenderHelper.disableStandardItemLighting();
			GlStateManager.popAttrib();
			GlStateManager.popMatrix();
		}
	}

public RenderItemStackAsTileEntity(Class<? extends TileEntity> te) {
		this.renderer = TileEntityRendererDispatcher.instance.getRenderer(te);
		this.map = null;
		Preconditions.checkNotNull(this.renderer, "TileEntity %s for ItemStack renderer does not have a renderer!", te.getName());
	}

public RenderItemStackAsTileEntity(Map<Integer, Class<? extends TileEntity>> map) {
		this.renderer = null;
		for(Entry<Integer, Class<? extends TileEntity>> entry : map.entrySet()) {
			this.add(entry.getKey(), entry.getValue());
		}
	}

public RenderItemStackAsTileEntity() {
		this.renderer = null;
		this.map = null;
	}

public RenderItemStackAsTileEntity(Consumer<RenderItemStackAsTileEntity> constructor) {
		constructor.accept(this);
	}

public RenderItemStackAsTileEntity add(int meta, Class<? extends TileEntity> te) {
		if(this.map == null) {
			this.map = new Int2ObjectOpenHashMap<>();
		}
		TileEntitySpecialRenderer<?> renderer = TileEntityRendererDispatcher.instance.getRenderer(te);
		Preconditions.checkNotNull(renderer, "TileEntity %s for ItemStack renderer does not have a renderer!", te.getName());
		this.map.put(meta, renderer);
		return this;
	}

@Override
	public void renderByItem(ItemStack stack, float partialTicks) {
		if(this.renderer != null) {
			this.renderer.render(null, 0, 0, 0, partialTicks, -1, 1);
		} else if(this.map != null) {
			TileEntitySpecialRenderer<?> renderer = this.map.get(stack.getMetadata());
			if(renderer != null) {
				renderer.render(null, 0, 0, 0, partialTicks, -1, 1);
			}
		}

		//Reset GL state to what GUI item rendering expects
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
        GlStateManager.enableRescaleNormal();
        GlStateManager.alphaFunc(516, 0.1F);
        GlStateManager.enableBlend();
        GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
	}

