protected void copy(ItemStack stack) {
		((ItemWeedwoodShield)this.normalShield.getItem()).setBurningTicks(this.normalShield, ((ItemWeedwoodShield)stack.getItem()).getBurningTicks(stack));
	}

@Override
	public void renderByItem(ItemStack stack, float partialTicks) {
		this.copy(stack);

		Minecraft mc = Minecraft.getMinecraft();
		TextureManager textureManager = mc.getTextureManager();

		GlStateManager.pushMatrix();

		GlStateManager.translate(0.5D, 0.5D, 0.5D);


		ITextureObject atlas = textureManager.getTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);

		//Need to restore before rendering item because item renderer restores too
		textureManager.bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
		atlas.restoreLastBlurMipmap();

		mc.getRenderItem().renderItem(this.normalShield, TransformType.NONE);

		textureManager.bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
		atlas.setBlurMipmap(false, false);

		textureManager.bindTexture(TEXTURE);

		GlStateManager.scale(-1, -1, 1);
		GlStateManager.rotate(180, 0, 1, 0);
		GlStateManager.translate(-0.5D, -0.65D, 0.02D);
		GlStateManager.scale(0.75D, 0.75D, 0.75D);
		GlStateManager.rotate(-5, 1, 0, 0);

		this.faceModel.renderOnShield();

		int spitTicks = ((ItemLivingWeedwoodShield) stack.getItem()).getSpitTicks(stack);

		if(spitTicks > 0) {
			float overlayAlpha = (spitTicks - partialTicks) / 15.0F;

			textureManager.bindTexture(TEXTURE_GLOW);

			GlStateManager.doPolygonOffset(0, -3.0F);
			GlStateManager.enablePolygonOffset();
			GlStateManager.enableBlend();
			GlStateManager.enableAlpha();
			GlStateManager.depthMask(false);
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1, 1, 1, overlayAlpha);

			this.faceModel.renderOnShield();

			LightingUtil.INSTANCE.setLighting(255);
			GlStateManager.blendFunc(GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ONE);
			GlStateManager.color(overlayAlpha,overlayAlpha, overlayAlpha, overlayAlpha);

			this.faceModel.renderOnShield();

			LightingUtil.INSTANCE.revert();

			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.depthMask(true);
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
			GlStateManager.doPolygonOffset(0.0F, 0.0F);
			GlStateManager.disablePolygonOffset();
		}

		GlStateManager.popMatrix();

		//Reset GL state to what GUI item rendering expects
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
        GlStateManager.enableRescaleNormal();
        GlStateManager.alphaFunc(516, 0.1F);
        GlStateManager.enableBlend();
        GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
	}

@Override
    public void render(TileEntityMothHouse te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
        EnumFacing rotation = StatePropertyHelper.getStatePropertySafely(te, BlockMothHouse.class, BlockMothHouse.FACING, EnumFacing.NORTH);

        int silkRenderStage = 0;

        if(te != null) {
            silkRenderStage = te.getSilkRenderStage();
        }

        silkRenderStage = Math.max(0, Math.min(silkRenderStage, 3));

        switch(silkRenderStage) {
            case 0:
                bindTexture(TEXTURE_STAGE_0);
                break;

            case 1:
                bindTexture(TEXTURE_STAGE_1);
                break;

            case 2:
                bindTexture(TEXTURE_STAGE_2);
                break;

            case 3:
                bindTexture(TEXTURE_STAGE_3);
                break;
        }

        GlStateManager.pushMatrix();
        GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
        GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
        GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
        GlStateManager.scale(1F, -1F, -1F);

        switch (rotation) {
            case SOUTH:
                GlStateManager.rotate(180F, 0.0F, 1F, 0F);
                break;
            case NORTH:
                GlStateManager.rotate(0F, 0.0F, 1F, 0F);
                break;
            case EAST:
                GlStateManager.rotate(90F, 0.0F, 1F, 0F);
                break;
            case WEST:
                GlStateManager.rotate(-90F, 0.0F, 1F, 0F);
                break;
        }


        boolean onWall = StatePropertyHelper.getStatePropertySafely(te, BlockMothHouse.class, BlockMothHouse.ON_WALL, false);

        if(onWall) {
        	GlStateManager.translate(0, 0, 0.38f);
        }

        MODEL.render();

        if(te != null && !te.isSilkProductionFinished() && x * x + y * y + z * z < 256) {
        	ItemStack grubs = te.getStackInSlot(TileEntityMothHouse.SLOT_GRUBS);

        	if(!grubs.isEmpty()) {
            	renderGrubs(grubs);
            }
        }

        GlStateManager.popMatrix();
    }

