@Override
	public void render(TileEntityMortar te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		int meta = 0;
		if(te != null) {
			meta = te.getBlockMetadata();
		}

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		bindTexture(TEXTURE);
		GlStateManager.pushMatrix();
		GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
		GlStateManager.scale(1F, -1F, -1F);

		switch (meta) {
		case 2:
			GlStateManager.rotate(180F, 0.0F, 1F, 0F);
			break;
		case 3:
			GlStateManager.rotate(0F, 0.0F, 1F, 0F);
			break;
		case 4:
			GlStateManager.rotate(90F, 0.0F, 1F, 0F);
			break;
		case 5:
			GlStateManager.rotate(-90F, 0.0F, 1F, 0F);
			break;
		}

		model.render();

		if(te != null && te.hasPestle) {
			GlStateManager.pushMatrix();
			if(te.progress > 0 && te.progress < 84) {
				float interpProgress = te.progress - 1 + partialTicks;
				float rise = (float)(interpProgress - 42F) * -0.03F;
				//GlStateManager.rotate(Math.min(interpProgress * 8.6747f, 360.0f), 0.0F, 1F, 0F);
				GlStateManager.rotate(Math.min((float)Math.pow(((float)Math.tanh(interpProgress * 1.5f / 8.3f - 5.0f) + 1) * 0.5f, 0.5f) * 360.0f, 360.0f), 0.0F, 1F, 0F);
				if(interpProgress > 42 && interpProgress < 53)
					GlStateManager.translate(0F, rise, 0F);
				if(interpProgress >= 53 && interpProgress < 63)
					GlStateManager.translate(0F, -0.33F + Math.pow((-0.332f - rise) / 0.2975f, 3) * 0.33f, 0F);
				if(interpProgress >= 63 && interpProgress < 73)
					GlStateManager.translate(0F, 0.63f + rise, 0F);
				if(interpProgress >= 73 && interpProgress < 83)
					GlStateManager.translate(0F, -0.31F + Math.pow((-0.9323952 - rise) / 0.2975f, 3) * 0.31f, 0F);
			}
			model.renderPestle();
			GlStateManager.popMatrix();
		}

		GlStateManager.popMatrix();

		if (te != null && !te.getStackInSlot(3).isEmpty()) {
			GlStateManager.pushMatrix();
			GlStateManager.translate(x + 0.5D, y + 1.43D, z + 0.5D);
			GlStateManager.scale(0.15D, 0.15D, 0.15D);
			GlStateManager.translate(0D, te.itemBob * 0.01F, 0D);
			GlStateManager.rotate(te.crystalRotation, 0, 1, 0);
			Minecraft.getMinecraft().getRenderItem().renderItem(te.getStackInSlot(3), ItemCameraTransforms.TransformType.GROUND);
			GlStateManager.popMatrix();
		}
	}

@Override
    public void render(TileEntityPossessedBlock te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {

        EnumFacing facing = StatePropertyHelper.getStatePropertySafely(te, BlockPossessedBlock.class, BlockPossessedBlock.FACING, EnumFacing.NORTH);

        GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

        bindTexture(TEXTURE);
        GlStateManager.pushMatrix();
        GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
        GlStateManager.scale(-1, -1, 1);

        switch (facing) {
            case NORTH:
                GlStateManager.rotate(0F, 0.0F, 1F, 0F);
                break;
            case SOUTH:
                GlStateManager.rotate(180F, 0.0F, 1F, 0F);
                break;
            case WEST:
                GlStateManager.rotate(-90F, 0.0F, 1F, 0F);
                break;
            case EAST:
                GlStateManager.rotate(90F, 0.0F, 1F, 0F);
                break;
        }

        model.render(te);
        GlStateManager.popMatrix();
    }

@Override
	public void render(TileEntityPurifier tile, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		this.bindTexture(TEXTURE);

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		if (tile == null || !tile.hasWorld()) {
			GlStateManager.pushMatrix();
			GlStateManager.translate(x + 0.5F, y + 1.5F, z + 0.5F);
			GlStateManager.rotate(180F, 0.0F, 0.0F, 1.0F);
			MODEL.renderAll();
			GlStateManager.popMatrix();
			return;
		}

		GlStateManager.pushMatrix();
		GlStateManager.translate((float) x + 0.5F, (float) y + 1.5F, (float) z + 0.5F);
		GlStateManager.scale(1F, -1F, -1F);
		int rotation = StatePropertyHelper.getStatePropertySafely(tile, BlockPurifier.class, BlockPurifier.FACING, EnumFacing.NORTH).getHorizontalIndex() * 90;
		GlStateManager.rotate(rotation - 180, 0, 1, 0);
		MODEL.renderAll();
		if (tile.isPurifying() && tile.lightOn)
			MODEL.renderFirePlate();
		GlStateManager.popMatrix();
		int amount = tile.waterTank.getFluidAmount();
		int capacity = tile.waterTank.getCapacity();
		float size = 1F / capacity * amount;


		if (!tile.getStackInSlot(2).isEmpty()) {
			GlStateManager.pushMatrix();
			GlStateManager.translate(x + 0.5D, y + 0.27D, z + 0.5D);
			GlStateManager.rotate(180, 1, 0, 0);
			int items = tile.getStackInSlot(2).getCount() / 4 + 1;
			Random rand = new Random(tile.getPos().toLong());
			for (int i = 0; i < items; i++) {
				GlStateManager.pushMatrix();
				GlStateManager.translate(rand.nextFloat() / 3.0D - 1.0D / 6.0D, -0.25D, rand.nextFloat() / 3.0D - 1.0D / 6.0D);
				GlStateManager.rotate(rand.nextFloat() * 30.0F - 15.0F, 1, 0, 0);
				GlStateManager.rotate(rand.nextFloat() * 30.0F - 15.0F, 0, 0, 1);
				GlStateManager.scale(0.15F, 0.15F, 0.15F);
				GlStateManager.rotate(-90, 1, 0, 0);
				GlStateManager.rotate(rand.nextFloat() * 360.0F, 0, 0, 1);
				ItemStack stack = tile.getStackInSlot(2);
				Minecraft.getMinecraft().getRenderItem().renderItem(stack, TransformType.FIXED);
				GlStateManager.popMatrix();
			}
			GlStateManager.popMatrix();
		}

		if (amount >= 100) {
			Tessellator tesselator = Tessellator.getInstance();
			BufferBuilder buffer = tesselator.getBuffer();
			TextureAtlasSprite waterIcon = Minecraft.getMinecraft().getTextureMapBlocks().getAtlasSprite("thebetweenlands:fluids/swamp_water_still");
			GlStateManager.pushMatrix();
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
			bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
			float translationX = (float) x + 0.0F;
			float translationY = (float) (y + 0.35F + size * 0.5F);
			float translationZ = (float) z + 0.0F;
			buffer.setTranslation(translationX, translationY, translationZ);
			buffer.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_COLOR);
			buffer.pos(0.1F, 0.0F, 0.1F).tex(waterIcon.getMinU(), waterIcon.getMinV()).color(0.2F, 0.6F, 0.4F, 1.0F).endVertex();
			buffer.pos(0.1F, 0.0F, 0.9F).tex(waterIcon.getMinU(), waterIcon.getMaxV()).color(0.2F, 0.6F, 0.4F, 1.0F).endVertex();
			buffer.pos(0.9F, 0.0F, 0.9F).tex(waterIcon.getMaxU(), waterIcon.getMaxV()).color(0.2F, 0.6F, 0.4F, 1.0F).endVertex();
			buffer.pos(0.9F, 0.0F, 0.1F).tex(waterIcon.getMaxU(), waterIcon.getMinV()).color(0.2F, 0.6F, 0.4F, 1.0F).endVertex();
			tesselator.draw();
			buffer.setTranslation(0.0F, 0.0F, 0.0F);
			GlStateManager.disableBlend();
			GlStateManager.popMatrix();
		}
	}

