private void setGLColorFromInt(int color, float alpha) {
		float red = (color >> 16 & 0xFF) / 255.0F;
		float green = (color >> 8 & 0xFF) / 255.0F;
		float blue = (color & 0xFF) / 255.0F;
		GlStateManager.color(red, green, blue, alpha);
	}

private void renderCuboid(BufferBuilder buffer, float xMax, float xMin, float yMin, float height, float zMin, float zMax, TextureAtlasSprite textureAtlasSprite) {

		double uMin = (double) textureAtlasSprite.getMinU();
		double uMax = (double) textureAtlasSprite.getMaxU();
		double vMin = (double) textureAtlasSprite.getMinV();
		double vMax = (double) textureAtlasSprite.getMaxV();

		final double vHeight = vMax - vMin;

		// top
		addVertexWithUV(buffer, xMax, height, zMax, uMax, vMin);
		addVertexWithUV(buffer, xMax, height, zMin, uMin, vMin);
		addVertexWithUV(buffer, xMin, height, zMin, uMin, vMax);
		addVertexWithUV(buffer, xMin, height, zMax, uMax, vMax);

		// north
		addVertexWithUV(buffer, xMax, yMin, zMin, uMax, vMin);
		addVertexWithUV(buffer, xMin, yMin, zMin, uMin, vMin);
		addVertexWithUV(buffer, xMin, height, zMin, uMin, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMax, height, zMin, uMax, vMin + (vHeight * height));

		// south
		addVertexWithUV(buffer, xMax, yMin, zMax, uMin, vMin);
		addVertexWithUV(buffer, xMax, height, zMax, uMin, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMin, height, zMax, uMax, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMin, yMin, zMax, uMax, vMin);

		// east
		addVertexWithUV(buffer, xMax, yMin, zMin, uMin, vMin);
		addVertexWithUV(buffer, xMax, height, zMin, uMin, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMax, height, zMax, uMax, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMax, yMin, zMax, uMax, vMin);

		// west
		addVertexWithUV(buffer, xMin, yMin, zMax, uMin, vMin);
		addVertexWithUV(buffer, xMin, height, zMax, uMin, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMin, height, zMin, uMax, vMin + (vHeight * height));
		addVertexWithUV(buffer, xMin, yMin, zMin, uMax, vMin);

	}

private void addVertexWithUV(BufferBuilder buffer, float x, float y, float z, double u, double v) {
		buffer.pos(x / 2f, y, z / 2f).tex(u, v).endVertex();
	}

@Override
	public void render(TileEntityWaystone te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		BlockWaystone.Part part = StatePropertyHelper.getStatePropertySafely(te, BlockWaystone.class, BlockWaystone.PART, BlockWaystone.Part.BOTTOM);
		boolean active = StatePropertyHelper.getStatePropertySafely(te, BlockWaystone.class, BlockWaystone.ACTIVE, false);

		if(destroyStage < 0 || te == null) {
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		} else {
			GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.DST_COLOR, GlStateManager.DestFactor.SRC_COLOR, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
			GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		}

		GlStateManager.pushMatrix();
		GlStateManager.enableTexture2D();
		GlStateManager.enableRescaleNormal();
		GlStateManager.translate(x + 0.5F, y + 1.5F, z + 0.5F);
		GlStateManager.scale(1F, -1F, -1F);

		boolean isBreakingAnimation = te != null && destroyStage >= 0;

		if(part == BlockWaystone.Part.BOTTOM || isBreakingAnimation) {
			float rotation = 0.0F;;

			if(isBreakingAnimation) {
				this.bindTexture(DESTROY_STAGES[destroyStage]);
				GlStateManager.matrixMode(GL11.GL_TEXTURE);
				GlStateManager.pushMatrix();
				GlStateManager.scale(8.0F, 8.0F, 1.0F);
				GlStateManager.translate(0.0625F, 0.0625F, 0.0625F);
				GlStateManager.matrixMode(GL11.GL_MODELVIEW);

				TileEntity master = null;

				switch(part) {
				case TOP:
					GlStateManager.translate(0, 2, 0);
					if(te.getWorld() != null) master = te.getWorld().getTileEntity(te.getPos().down(2));
					break;
				case MIDDLE:
					GlStateManager.translate(0, 1, 0);
					if(te.getWorld() != null) master = te.getWorld().getTileEntity(te.getPos().down(1));
					break;
				case BOTTOM:
					master = te;
					break;
				}

				if(master instanceof TileEntityWaystone) {
					rotation = ((TileEntityWaystone) master).getRotation();
				}
			} else {
				if(active) {
					this.bindTexture(TEXTURE_ACTIVE);
				} else {
					this.bindTexture(TEXTURE_INACTIVE);
				}

				rotation = te != null ? te.getRotation() : 0;

				if(active && te != null && ShaderHelper.INSTANCE.isWorldShaderActive()) {
					BlockPos pos = te.getPos();
					double px = pos.getX() + 0.5D;
					double py = pos.getY();
					double pz = pos.getZ() + 0.5D;

					EntityPlayer closestPlayer = te.getWorld().getClosestPlayer(px, py, pz, 4.0D, false);

					if(closestPlayer != null) {
						ShaderHelper.INSTANCE.require();

						float brightness = 3.0F * (float)(1.0D - closestPlayer.getDistance(px, py, pz) / 4.0D);

						ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(px, py, pz, 8F, 0.44f * brightness, 0.8f * brightness, 1.0f * brightness));
					}
				}
			}

			GlStateManager.rotate(rotation, 0, 1, 0);

			MODEL.render(null, 0, 0, 0, 0, 0, 0.0625F);

			if(isBreakingAnimation) {
				GlStateManager.matrixMode(GL11.GL_TEXTURE);
				GlStateManager.popMatrix();
				GlStateManager.matrixMode(GL11.GL_MODELVIEW);
			} else {
				this.bindTexture(TEXTURE_GRASS);

				int grassColor = te != null ? BiomeColorHelper.getGrassColorAtPos(te.getWorld(), te.getPos()) : ColorizerGrass.getGrassColor(0.5D, 1.0D);

				GlStateManager.color((float)(grassColor >> 16 & 0xff) / 255F, (float)(grassColor >> 8 & 0xff) / 255F, (float)(grassColor & 0xff) / 255F);

				GlStateManager.enablePolygonOffset();
				GlStateManager.doPolygonOffset(-3, -3);

				MODEL.render(null, 0, 0, 0, 0, 0, 0.0625F);

				GlStateManager.disablePolygonOffset();
			}
		}

		GlStateManager.disableRescaleNormal();
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.popMatrix();
	}

