@Override
	public void render(TileEntityWeedwoodSign te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {

		Block block = te.getBlockType();
		GlStateManager.pushMatrix();

		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		if (block == BlockRegistry.STANDING_WEEDWOOD_SIGN) {
			GlStateManager.translate((float)x + 0.5F, (float)y + 0.5F, (float)z + 0.5F);
			float f1 = (float)(te.getBlockMetadata() * 360) / 16.0F;
			GlStateManager.rotate(-f1, 0.0F, 1.0F, 0.0F);
			this.model.signStick.showModel = true;
		} else {
			int meta = te.getBlockMetadata();
			float rotation = 0.0F;

			if (meta == 2) {
				rotation = 180.0F;
			}

			if (meta == 4) {
				rotation = 90.0F;
			}

			if (meta == 5) {
				rotation = -90.0F;
			}

			GlStateManager.translate((float)x + 0.5F, (float)y + 0.5F, (float)z + 0.5F);
			GlStateManager.rotate(-rotation, 0.0F, 1.0F, 0.0F);
			GlStateManager.translate(0.0F, -0.3125F, -0.4375F);
			this.model.signStick.showModel = false;
		}

		if (destroyStage >= 0) {
			this.bindTexture(DESTROY_STAGES[destroyStage]);
			GlStateManager.matrixMode(5890);
			GlStateManager.pushMatrix();
			GlStateManager.scale(4.0F, 2.0F, 1.0F);
			GlStateManager.translate(0.0625F, 0.0625F, 0.0625F);
			GlStateManager.matrixMode(5888);
		} else {
			this.bindTexture(SIGN_TEXTURE);
		}

		GlStateManager.enableRescaleNormal();
		GlStateManager.pushMatrix();
		GlStateManager.scale(0.6666667F, -0.6666667F, -0.6666667F);
		this.model.renderSign();
		GlStateManager.popMatrix();
		FontRenderer fontrenderer = this.getFontRenderer();
		GlStateManager.translate(0.0F, 0.33333334F, 0.046666667F);
		GlStateManager.scale(0.010416667F, -0.010416667F, 0.010416667F);
		GlStateManager.glNormal3f(0.0F, 0.0F, -0.010416667F);
		GlStateManager.depthMask(false);

		if (destroyStage < 0) {
			for (int i = 0; i < te.signText.length; ++i) {
				if (te.signText[i] != null) {
					ITextComponent itextcomponent = te.signText[i];
					List<ITextComponent> list = GuiUtilRenderComponents.splitText(itextcomponent, 90, fontrenderer, false, true);
					String s = list != null && !list.isEmpty() ? ((ITextComponent)list.get(0)).getFormattedText() : "";

					if (i == te.lineBeingEdited) {
						s = "> " + s + " <";
						fontrenderer.drawString(s, -fontrenderer.getStringWidth(s) / 2, i * 10 - te.signText.length * 5, 0);
					} else {
						fontrenderer.drawString(s, -fontrenderer.getStringWidth(s) / 2, i * 10 - te.signText.length * 5, 0);
					}
				}
			}
		}

		GlStateManager.depthMask(true);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.popMatrix();

		if (destroyStage >= 0) {
			GlStateManager.matrixMode(5890);
			GlStateManager.popMatrix();
			GlStateManager.matrixMode(5888);
		}
	}

@Override
	public void render(TileEntityWeedwoodWorkbench table, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		GlStateManager.pushMatrix();
		GlStateManager.translate(x + 0.5D, y + 0.875D, z + 0.5D);
		GlStateManager.scale(0.25F, 0.25F, 0.25F);
		GlStateManager.rotate(90.0F * (-table.rotation + 3), 0.0F, 1.0F, 0.0F);
		GlStateManager.translate(-1.5F, -0.0F, -1.0F);
		GlStateManager.blendFunc(SourceFactor.SRC_ALPHA, DestFactor.ONE_MINUS_SRC_ALPHA);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);

		Minecraft.getMinecraft().getTextureManager().bindTexture(TextureMap.LOCATION_BLOCKS_TEXTURE);
		float prevLGTX = OpenGlHelper.lastBrightnessX;
		float prevLGTY = OpenGlHelper.lastBrightnessY;
		BlockPos pos = table.getPos();
		int bright = table.getWorld().getCombinedLight(pos.up(), 0);
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, bright % 65536, bright / 65536);

		for (int row = 0; row < 3; row++) {
			for (int column = 0; column < 3; column++) {
				ItemStack stack = table.craftingSlots.get(column * 3 + row);
				if (!stack.isEmpty()) {
					GlStateManager.pushMatrix();
					GlStateManager.translate(row * 0.75F, 0.0D, column * 0.75F);
					GlStateManager.translate(0.75F, 0.52F, 0.25F);
					GlStateManager.scale(0.5F, 0.5F, 0.5F);
					GlStateManager.rotate(-90.0F, 1.0F, 0.0F, 0.0F);
					RenderHelper.disableStandardItemLighting();
					RenderItem renderItem = Minecraft.getMinecraft().getRenderItem();
					renderItem.renderItem(stack, renderItem.getItemModelWithOverrides(stack, null, null));
					GlStateManager.popMatrix();
				}
			}
		}
		OpenGlHelper.setLightmapTextureCoords(OpenGlHelper.lightmapTexUnit, prevLGTX, prevLGTY);

		GlStateManager.popMatrix();
	}

@Override
	public void render(TileEntityWindChime te, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		GlStateManager.pushMatrix();
		GlStateManager.enableTexture2D();
		GlStateManager.enableRescaleNormal();
		GlStateManager.translate(x + 0.5F, y + 1.5F, z + 0.5F);
		GlStateManager.scale(1F, -1F, -1F);

		boolean isBreakingAnimation = te != null && destroyStage >= 0;

		if(isBreakingAnimation) {
			this.bindTexture(DESTROY_STAGES[destroyStage]);
			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.pushMatrix();
			GlStateManager.scale(8.0F, 8.0F, 1.0F);
			GlStateManager.translate(0.0625F, 0.0625F, 0.0625F);
			GlStateManager.matrixMode(GL11.GL_MODELVIEW);

		} else {
			this.bindTexture(TEXTURE);
		}

		if(te != null) {
			MODEL.render(te.renderTicks + partialTicks, Math.min((te.prevChimeTicks + (te.chimeTicks - te.prevChimeTicks) * partialTicks) / 100.0f, 1.25f));
		} else {
			MODEL.render(0, 0);
		}

		if(isBreakingAnimation) {
			GlStateManager.matrixMode(GL11.GL_TEXTURE);
			GlStateManager.popMatrix();
			GlStateManager.matrixMode(GL11.GL_MODELVIEW);
		}

		GlStateManager.disableRescaleNormal();
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);
		GlStateManager.color(1.0F, 1.0F, 1.0F, 1.0F);
		GlStateManager.popMatrix();

		if(!isBreakingAnimation && te != null) {
			ParticleBatch batch = te.getParticleBatch();

			if(batch != null) {
				RenderHelper.disableStandardItemLighting();
				Minecraft.getMinecraft().entityRenderer.enableLightmap();

				BatchedParticleRenderer.INSTANCE.renderBatch(batch, Minecraft.getMinecraft().getRenderViewEntity(), partialTicks);

				RenderHelper.enableStandardItemLighting();
				Minecraft.getMinecraft().entityRenderer.enableLightmap();
			}
		}
	}

@Override
	public void render(TileEntityWisp tileEntity, double x, double y, double z, float partialTicks, int destroyStage, float alpha) {
		double renderViewX = Minecraft.getMinecraft().getRenderManager().viewerPosX;
		double renderViewY = Minecraft.getMinecraft().getRenderManager().viewerPosY;
		double renderViewZ = Minecraft.getMinecraft().getRenderManager().viewerPosZ;

		Entity renderView = Minecraft.getMinecraft().getRenderViewEntity();

		if(!StatePropertyHelper.getStatePropertySafely(tileEntity, BlockWisp.class, BlockWisp.VISIBLE, false)) {
			double dist = renderView != null ? renderView.getDistance(x + renderViewX, y + renderViewY, z + renderViewZ) : 0.0D;
			if(dist > 50 || dist < 10) {
				return;
			}
		}

		int colorIndex = StatePropertyHelper.getStatePropertySafely(tileEntity, BlockWisp.class, BlockWisp.COLOR, 0);

		if(!Minecraft.getMinecraft().isGamePaused()) {
			if(System.nanoTime() - ((TileEntityWisp)tileEntity).lastSpawn >= (500f - 500.0f * BetweenlandsConfig.RENDERING.wispQuality / 150.0f) * 1000000L) {
				((TileEntityWisp)tileEntity).lastSpawn = System.nanoTime();

				int color = BlockWisp.COLORS[colorIndex * 2];
				float r = (color >> 16 & 0xFF) / 255F;
				float g = (color >> 8 & 0xFF) / 255F;
				float b = (color & 0xFF) / 255F;

				BatchedParticleRenderer.INSTANCE.addParticle(DefaultParticleBatches.WISPS, BLParticles.WISP.create(tileEntity.getWorld(), 
						x + 0.5 + renderViewX, 
						y + 0.5 + renderViewY, 
						z + 0.5 + renderViewZ, 
						ParticleArgs.get().withColor(r, g, b, 1.0F).withScale(3.0F)));

				color = BlockWisp.COLORS[colorIndex * 2 + 1];
				r = (color >> 16 & 0xFF) / 255F;
				g = (color >> 8 & 0xFF) / 255F;
				b = (color & 0xFF) / 255F;

				BatchedParticleRenderer.INSTANCE.addParticle(DefaultParticleBatches.WISPS, BLParticles.WISP.create(tileEntity.getWorld(), 
						x + 0.5 + renderViewX, 
						y + 0.5 + renderViewY, 
						z + 0.5 + renderViewZ, 
						ParticleArgs.get().withColor(r, g, b, 1.0F).withScale(2.0F)));
			}
		}

		if(ShaderHelper.INSTANCE.isWorldShaderActive()) {
			ShaderHelper.INSTANCE.require();

			for(int i = 0; i < 2; i++) {
				int color = BlockWisp.COLORS[colorIndex * 2 + i];
				float r = (color >> 16 & 0xFF) / 255F;
				float g = (color >> 8 & 0xFF) / 255F;
				float b = (color & 0xFF) / 255F;

				float size = 1.5f;

				ShaderHelper.INSTANCE.getWorldShader().addLight(new LightSource(tileEntity.getPos().getX() + 0.5f, tileEntity.getPos().getY(), tileEntity.getPos().getZ() + 0.5f,
						i == 0 ? size : size * 0.5F,
								r * (i == 0 ? 6 : 3),
								g * (i == 0 ? 6 : 3),
								b * (i == 0 ? 6 : 3)));
			}
		}
	}

