		boolean isUpper = (meta & 1) == 1;
		return this.getDefaultState().withProperty(HALF, isUpper ? EnumBlockHalf.TOP : EnumBlockHalf.BOTTOM).withProperty(FACING, EnumFacing.byHorizontalIndex(facing));
