@Override
	public int getMetaFromState(IBlockState state) {
		int facing = ((EnumFacing)state.getValue(FACING)).getHorizontalIndex();
		boolean isUpper = state.getValue(HALF) == EnumBlockHalf.TOP;
		int meta = facing << 1;
		meta |= isUpper ? 1 : 0;
		return meta;
	}

