		IBlockState blockState = world.getBlockState(pos);
		boolean removed = blockState.getBlock().removedByPlayer(blockState, world, pos, player, canHarvest);
		if (removed) {
			blockState.getBlock().onPlayerDestroy(world, pos, blockState);
		}
		return removed;
	}

