					}

					worldIn.setBlockState(pos, state.withProperty(AGE, this.resetAge ? 0 : 15));
				} else {
					worldIn.setBlockState(pos, state.withProperty(AGE, currentAge + 1));
				}

				ForgeHooks.onCropsGrowPost(worldIn, pos, state, worldIn.getBlockState(pos));
			}
		}
	}

