		if (world.isAirBlock(pos.down())) {
			world.setBlockToAir(pos);
			if (state.getValue(HALF) == EnumBrazierHalf.LOWER)
				dropBlockAsItem(world, pos, state, 0);
			return false;
		}
		return true;
	}

