		if (!entity.isImmuneToFire() && entity instanceof EntityLivingBase && !EnchantmentHelper.hasFrostWalkerEnchantment((EntityLivingBase) entity))
			entity.attackEntityFrom(DamageSource.HOT_FLOOR, 1.0F);
	}

