	public void onUpdate() {
		super.onUpdate();

		if(!getEntityWorld().isRemote)
			if(ticksExisted >= getBaitDissolveTime() && cannotPickup())
				setDead();

		if(isInWater()) {
			motionX *= 0.9D;
			motionY = -(float) getBaitSinkSPeed() * 0.02D;
			motionZ *= 0.9D;
			if(!getEntityWorld().isRemote) {
				if(!hasNoGravity())
					setNoGravity(true);
			if(getBaitRange() >= 1)
				lureCloseFish();
			}
		} else {
			if(!getEntityWorld().isRemote)
				if(hasNoGravity())
					setNoGravity(false);
		}
