		mat.rotate(Math.toRadians(this.getUpgradeRotY(i)), 0, 1, 0);

		offsetVec = mat.transform(offsetVec);

		switch(i) {
		default:
		case 0:
			return new Vec3d(10 / 16.0f, 14 / 16.0f, 8 / 16.0f).add(offsetVec);
		case 1:
			return new Vec3d(-10 / 16.0f, 14 / 16.0f, 8 / 16.0f).add(offsetVec);
		case 2:
			return new Vec3d(10 / 16.0f, 14 / 16.0f, -8 / 16.0f).add(offsetVec);
		case 3:
			return new Vec3d(-10 / 16.0f, 14 / 16.0f, -8 / 16.0f).add(offsetVec);
		case 4:
