protected void dropFurnaceContent(int index) {
		Vec3d dropPos = this.getRotatedCarriagePoint(this.getUpgradePoint(index, 0.25f), 1).add(this.posX, this.posY, this.posZ);

		IInventory furnaceInv = this.getFurnace(index);
