		float head = getHeadType().getStaminaModifier();
		float body = getBodyType().getStaminaModifier();
		float tail = getTailType().getStaminaModifier();
		return Math.max(Math.round(getFishSize() * head + body + tail * 2F) / 2F, 3.5F);
	}

