				} else if(this.rollDir != null && target != null) {
					double overshoot = this.rollDir.dotProduct(new Vec3d(this.entity.posX - target.posX, 0, this.entity.posZ - target.posZ));
					if(overshoot >= 2) {
						this.entity.stopRolling();
