@Override
    public void onLivingUpdate() {
        super.onLivingUpdate();
		if (isLeader()) {
			if (getEntityWorld().isRemote && getEntityWorld().getTotalWorldTime() % 5 + getEntityWorld().rand.nextInt(5) == 0) {
				if (isInWater()) {
					for (int i = 0; i < 2; ++i) {
						double a = Math.toRadians(rotationYaw);
						double offSetX = -Math.sin(a) * width * 0.5D;
						double offSetZ = Math.cos(a) * width * 0.5D;
						getEntityWorld().spawnParticle(EnumParticleTypes.WATER_BUBBLE, posX + offSetX, posY + height * 0.5D + rand.nextDouble() * 0.5D, posZ + offSetZ, 0.0D, 0.4D, 0.0D, new int[0]);
					}
				}
			}
		}
		if (!world.isRemote) {
			if(world.getTotalWorldTime()%200 == 0)
				checkIfCanBeLeader(); // just in case there is no leader
		}

		if(!spawnedChildren && this.ticksExisted % 20 == 0 && isLeader() && this.world.getClosestPlayer(this.posX, this.posY, this.posZ, 16, false) != null) {
			checkSpawnChildren();
		}

		if (inWater) {
			setAir(300);
		} else if (onGround) {
			motionY += 0.25D;
			motionX += (double) ((rand.nextFloat() * 2.0F - 1.0F) * 0.075F);
			motionZ += (double) ((rand.nextFloat() * 2.0F - 1.0F) * 0.075F);
			rotationYaw = rand.nextFloat() * 360.0F;
			onGround = false;
			isAirBorne = true;
			if (world.getTotalWorldTime() % 5 == 0)
				world.playSound((EntityPlayer) null, posX, posY, posZ, SoundRegistry.FISH_FLOP, SoundCategory.HOSTILE, 1F, 1F);
			this.damageEntity(DamageSource.DROWN, 0.5F);
		}
    }

private void checkIfCanBeLeader() {
		AxisAlignedBB aoe = new AxisAlignedBB(getPosition()).grow(10D);
		if (!getEntityWorld().isRemote) {
			List<EntityCaveFish> list = getEntityWorld().getEntitiesWithinAABB(EntityCaveFish.class, aoe);
			for (Iterator<EntityCaveFish> iterator = list.iterator(); iterator.hasNext();) {
				EntityLivingBase entity  = iterator.next();
				if (entity != null && entity instanceof EntityCaveFish && !((EntityCaveFish) entity).isLeader())
					iterator.remove();
			}
			if (list.isEmpty())
				promoteThisFish();

			if (!list.isEmpty()) {
				return;
			}
		}

	}

private void promoteThisFish() {
		setIsLeader(true);
	}

