					double distance = taskOwner.getDistanceSq(targetEntity);
					if (distance <= 256.0D)
						taskOwner.getEntityWorld().playSound(null, taskOwner.getPosition(), SoundRegistry.CHIROMAW_MATRIARCH_ROAR, SoundCategory.HOSTILE, 2F, 1.5F);
