			if (entitylivingbase != null)
				return false;
			if (largeChiromaw.homeisOccupied())
				return false;
			if (largeChiromaw.getReturnToNest() && !largeChiromaw.getIsNesting()) {
				Vec3d nestLocation = getNestPosition();

				if (nestLocation == null) {
					return false;
				} else {
					x = nestLocation.x;
					y = nestLocation.y;
					z = nestLocation.z;
					return true;
				}
			}
			return false;
		}

