				setSize(0.98F, 1.9F);
				experienceValue = 20;
				getEntityAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).setBaseValue(0.28D);
				getEntityAttribute(SharedMonsterAttributes.MAX_HEALTH).setBaseValue(100D);
