		this.anchor = new BlockPos(nbt.getDouble("anchorX"), nbt.getDouble("anchorY"), nbt.getDouble("anchorZ"));
		this.anchorRadius = nbt.getDouble("anchorRadius");
		this.setFloating(nbt.getBoolean("floating"));
