	public float getShakeIntensity(Entity viewer, float partialTicks) {
		if(this.isScreaming()) {
			double dist = this.getDistance(viewer);
			float screamMult = (float) (1.0F - dist / 30.0F);
			if(dist >= 30.0F) {
