@SubscribeEvent(priority = EventPriority.LOW)
	public static void onUseItemTick(LivingEntityUseItemEvent.Tick event) {
		//Check if item will be consumed this tick
		if(!event.getEntityLiving().getEntityWorld().isRemote && event.getDuration() <= 1) {
			if (!event.getItem().isEmpty() && event.getEntityLiving() instanceof EntityPlayer) {
				DecayFoodStats decayFoodStats = OverworldItemHandler.getDecayFoodStats(event.getItem());
				if(decayFoodStats != null) {
					EntityPlayer player = (EntityPlayer) event.getEntityLiving();
					IDecayCapability cap = player.getCapability(CapabilityRegistry.CAPABILITY_DECAY, null);
					if(cap != null) {
						cap.getDecayStats().addStats(-decayFoodStats.decay, decayFoodStats.saturation);
					}
				}
			}
		}
	}

@SubscribeEvent
	public static void onStartUsingItem(LivingEntityUseItemEvent.Start event) {
		if(!event.getItem().isEmpty() && event.getEntityLiving() instanceof EntityPlayer) {
			EntityPlayer player = (EntityPlayer) event.getEntityLiving();
			boolean isDecayFood = OverworldItemHandler.getDecayFoodStats(event.getItem()) != null;
			if(isDecayFood) {
				boolean canEatFood = player.getFoodStats().needFood() && event.getItem().getItem() instanceof ItemFood && ((ItemFood)event.getItem().getItem()).getHealAmount(event.getItem()) > 0;
				boolean canEatDecayFood = false;
				IDecayCapability cap = player.getCapability(CapabilityRegistry.CAPABILITY_DECAY, null);
				if(cap != null) {
					canEatDecayFood = cap.getDecayStats().getDecayLevel() > 0;
				}
				if (!canEatFood && !canEatDecayFood) {
					event.setDuration(-1);
					event.setCanceled(true);
				}
			}
		}
	}

private static boolean isTargetSmelly(EntityLivingBase entity) {
		IRotSmellCapability cap = entity.getCapability(CapabilityRegistry.CAPABILITY_ROT_SMELL, null);
		if(cap != null)
			if(cap.isSmellingBad())
				return true;
		return false;
	}

private static int getArmorDecayReduction(EntityLivingBase entity) {
		int armorCount = 0;

		for (ItemStack armor : entity.getArmorInventoryList()) {
			if (armor.getItem() instanceof ItemAmphibiousArmor) {
				if (((ItemAmphibiousArmor) armor.getItem()).getUpgradeCount(armor, AmphibiousArmorUpgrades.DECAY_DECREASE) >= 1) {
					armorCount++;
				}
			}
		}

		return armorCount;
	}

@SubscribeEvent
	public static void onEntityJoin(EntityJoinWorldEvent event) {
		if(!event.getWorld().isRemote && event.getEntity() instanceof EntityPlayer && BetweenlandsConfig.WORLD_AND_DIMENSION.activateRiftOnFirstJoin && event.getWorld().provider.getDimension() == BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId) {
			EntityPlayer player = (EntityPlayer) event.getEntity();

			NBTTagCompound dataNbt = player.getEntityData();
			NBTTagCompound persistentNbt = dataNbt.getCompoundTag(EntityPlayer.PERSISTED_NBT_TAG);

			boolean isFirstTimeInDimension = !(persistentNbt.hasKey(NOT_FIRST_JOIN_NBT, Constants.NBT.TAG_BYTE) && persistentNbt.getBoolean(NOT_FIRST_JOIN_NBT));

			if(isFirstTimeInDimension) {
				int minActiveTicks = BetweenlandsConfig.WORLD_AND_DIMENSION.minRiftOnFirstJoinDuration * 20;

				EventRift rift = BetweenlandsWorldStorage.forWorld(event.getWorld()).getEnvironmentEventRegistry().rift;
				if(!rift.isActive()) {
					rift.setActive(true);
				}
				if(rift.getTicks() < minActiveTicks) {
					rift.setTicks(minActiveTicks);
				}

				persistentNbt.setBoolean(NOT_FIRST_JOIN_NBT, true);
				dataNbt.setTag(EntityPlayer.PERSISTED_NBT_TAG, persistentNbt);
			}
		}
	}

@SubscribeEvent
	public static void onPlayerLogin(PlayerLoggedInEvent event) {
		if(!event.player.world.isRemote && BetweenlandsConfig.WORLD_AND_DIMENSION.startInBetweenlands && event.player.world.provider.getDimension() != BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId && event.player.world instanceof WorldServer) {
			NBTTagCompound dataNbt = event.player.getEntityData();
			NBTTagCompound persistentNbt = dataNbt.getCompoundTag(EntityPlayer.PERSISTED_NBT_TAG);

			boolean isFirstTimeSpawning = !(persistentNbt.hasKey(NOT_FIRST_SPAWN_NBT, Constants.NBT.TAG_BYTE) && persistentNbt.getBoolean(NOT_FIRST_SPAWN_NBT));

			if(isFirstTimeSpawning) {
				//Set before teleporting because recursion
				persistentNbt.setBoolean(NOT_FIRST_SPAWN_NBT, true);
				dataNbt.setTag(EntityPlayer.PERSISTED_NBT_TAG, persistentNbt);

				WorldServer blWorld = ((WorldServer) event.player.world).getMinecraftServer().getWorld(BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId);

				TeleporterHandler.transferToDim(event.player, blWorld, BetweenlandsConfig.WORLD_AND_DIMENSION.startInPortal, true);
			}
		}
	}

@SubscribeEvent
	public static void teleportCheck(PlayerTickEvent event) {
		if(event.phase == TickEvent.Phase.END) {
			EntityPlayer player = event.player;

			IPortalCapability cap = player.getCapability(CapabilityRegistry.CAPABILITY_PORTAL, null);
			if (cap != null) {
				if(cap.isInPortal()){
					BlockPos pos = new BlockPos(player.posX, player.posY + 0.5D, player.posZ);
					IBlockState state = player.world.getBlockState(pos);

					boolean inPortalBlock = false;
					if(state.getBlock() instanceof BlockTreePortal) {
						AxisAlignedBB aabb = state.getBoundingBox(player.world, pos);
						if(aabb != null && aabb.offset(pos).intersects(player.getEntityBoundingBox())) {
							inPortalBlock = true;
						}
					}

					if(inPortalBlock) {
						if(!cap.wasTeleported()) {
							if (cap.getTicksUntilTeleport() <= 0 || player.capabilities.isCreativeMode) {
								if(player.world instanceof WorldServer) {
									BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(player.world);
									AxisAlignedBB entityAabb = player.getEntityBoundingBox();
									List<LocationPortal> portals = worldStorage.getLocalStorageHandler().getLocalStorages(LocationPortal.class, entityAabb, loc -> loc.intersects(entityAabb));
									LocationPortal portal = null;
									if(!portals.isEmpty()) {
										portal = portals.get(0);
									}
									int targetDim = BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId;
									if(portal != null && (portal.getOtherPortalPosition() != null || portal.hasTargetDimension())) {
										//Portal already linked, teleport to linked dimension
										targetDim = portal.getOtherPortalDimension();
									} else if (player.dimension == BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId) {
										targetDim = BetweenlandsConfig.WORLD_AND_DIMENSION.portalDefaultReturnDimension;
									}
									if(targetDim != player.dimension) {
										WorldServer otherDim = ((WorldServer) player.world).getMinecraftServer().getWorld(targetDim);
										if(otherDim != null) {
											TeleporterHandler.transferToDim(player, otherDim);
										}
									}
								}
								player.timeUntilPortal = 10;
								cap.setInPortal(false);
								cap.setTicksUntilTeleport(MAX_PORTAL_TIME);
							} else {
								cap.setTicksUntilTeleport(cap.getTicksUntilTeleport() - 1);
							}
						}
					} else {
						cap.setTicksUntilTeleport(MAX_PORTAL_TIME);
						cap.setInPortal(false);
						cap.setWasTeleported(false);
					}
				} else {
					cap.setTicksUntilTeleport(MAX_PORTAL_TIME);
					if(!cap.isInPortal()) {
						cap.setWasTeleported(false);
					}
				}
			}
		}
	}

@SideOnly(Side.CLIENT)
	@SubscribeEvent
	public static void onClientTick(ClientTickEvent event) {
		if(event.phase == Phase.END) {
			EntityPlayerSP player = Minecraft.getMinecraft().player;

			if (player != null) {
				IPortalCapability cap = player.getCapability(CapabilityRegistry.CAPABILITY_PORTAL, null);
				if (cap != null) {

					boolean renderPortalEffect = cap.isInPortal() && !cap.wasTeleported();

					if (renderPortalEffect) {
						int timer = cap.getTicksUntilTeleport();
						if (timer < MAX_PORTAL_TIME) {
							player.closeScreen();

							if (timer == MAX_PORTAL_TIME - 1) {
								Minecraft.getMinecraft().getSoundHandler().playSound(new PortalSound(SoundRegistry.PORTAL_TRIGGER, SoundCategory.BLOCKS, player));
							}

							if (timer == 2) {
								player.playSound(SoundRegistry.PORTAL_TRAVEL, 1.0F, 0.8F);
							}
						}
					}

					if (ShaderHelper.INSTANCE.isWorldShaderActive()) {
						WorldShader shader = ShaderHelper.INSTANCE.getWorldShader();

						if (!renderPortalEffect) {
							shader.setSwirlAngle(0.0F);
						} else {
							float swirl = shader.getSwirlAngle(1);
							if (swirl < 2) {
								shader.setSwirlAngle(swirl + (swirl * 0.055F) + 0.0005F);
							} else {
								shader.setSwirlAngle(swirl + ((swirl * 0.055F) / (swirl - 1)) + 0.0005F);
							}
						}
					}
				}
			}
		}
	}

@SubscribeEvent
	public static void onPlayerDeath(LivingDeathEvent event) {
		if(event.getEntityLiving() instanceof EntityPlayer) {
			EntityPlayer player = (EntityPlayer) event.getEntityLiving();

			NBTTagCompound dataNbt = player.getEntityData();
			NBTTagCompound persistentNbt = dataNbt.getCompoundTag(EntityPlayer.PERSISTED_NBT_TAG);

			BlockPos spawnPos = player.getBedLocation(player.dimension);

			BlockPos adjustedSpawnPos = spawnPos == null ? null : EntityPlayer.getBedSpawnLocation(player.world, spawnPos, player.isSpawnForced(player.dimension));

			boolean respawnInBL = BetweenlandsConfig.WORLD_AND_DIMENSION.startInBetweenlands && (!player.world.provider.canRespawnHere() || adjustedSpawnPos == null);

			persistentNbt.setBoolean(RESPAWN_IN_BL_NBT, respawnInBL);

			dataNbt.setTag(EntityPlayer.PERSISTED_NBT_TAG, persistentNbt);
		}
	}

@SubscribeEvent
	public static void onRespawn(PlayerRespawnEvent event) {
		if(!event.player.world.isRemote) {
			BlockPos spawnPos = event.player.getBedLocation(event.player.dimension);

			BlockPos adjustedSpawnPos = spawnPos == null ? null : EntityPlayer.getBedSpawnLocation(event.player.world, spawnPos, event.player.isSpawnForced(event.player.dimension));

			NBTTagCompound dataNbt = event.player.getEntityData();
			NBTTagCompound persistentNbt = dataNbt.getCompoundTag(EntityPlayer.PERSISTED_NBT_TAG);

			boolean shouldTeleportToBL = (BetweenlandsConfig.WORLD_AND_DIMENSION.startInBetweenlands && event.isEndConquered()) || persistentNbt.getBoolean(RESPAWN_IN_BL_NBT);

			if(shouldTeleportToBL && event.player.world instanceof WorldServer) {
				WorldServer blWorld = ((WorldServer) event.player.world).getMinecraftServer().getWorld(BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId);

				TeleporterHandler.transferToDim(event.player, blWorld, false, false);

				spawnPos = event.player.getBedLocation(event.player.dimension);

				adjustedSpawnPos = spawnPos == null ? null : EntityPlayer.getBedSpawnLocation(event.player.world, spawnPos, event.player.isSpawnForced(event.player.dimension));

				if(adjustedSpawnPos != null) {
					event.player.setPosition(adjustedSpawnPos.getX() + 0.5D, adjustedSpawnPos.getY(), adjustedSpawnPos.getZ() + 0.5D);

					if(event.player instanceof EntityPlayerMP) {
						EntityPlayerMP playerMP = (EntityPlayerMP) event.player;

						playerMP.connection.setPlayerLocation(playerMP.posX, playerMP.posY, playerMP.posZ, playerMP.rotationYaw, playerMP.rotationPitch);
						playerMP.connection.sendPacket(new SPacketSpawnPosition(adjustedSpawnPos));
					}
				}
			}

			if(shouldTeleportToBL || event.player.dimension == BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId) {
				boolean newRespawn = false;
				if(adjustedSpawnPos == null) {
					newRespawn = true;
				} else {
					IBlockState stateDown = event.player.world.getBlockState(adjustedSpawnPos.down());
					boolean isValidSpawnBlock = stateDown.getMaterial().blocksMovement() && !stateDown.getBlock().isLeaves(stateDown, event.player.world, adjustedSpawnPos.down()) && !stateDown.getBlock().isFoliage(event.player.world, adjustedSpawnPos.down());
					if(!isValidSpawnBlock) {
						newRespawn = true;
					}
				}

				if(newRespawn) {
					if(persistentNbt.hasKey(TeleporterBetweenlands.LAST_PORTAL_POS_NBT, Constants.NBT.TAG_LONG)) {
						BlockPos lastPortal = BlockPos.fromLong(persistentNbt.getLong(TeleporterBetweenlands.LAST_PORTAL_POS_NBT));

						respawnNearPos(event.player, lastPortal);
					}
				}
			}
		}
	}

public static void respawnNearPos(Entity entity, BlockPos pos) {
		BlockPos newSpawn = getRespawnPointNearPos(entity.world, pos, 64);

		entity.setLocationAndAngles(newSpawn.getX() + 0.5D, newSpawn.getY(), newSpawn.getZ() + 0.5D, entity.rotationYaw, entity.rotationPitch);

		while (!entity.world.getCollisionBoxes(entity, entity.getEntityBoundingBox()).isEmpty() && entity.posY < 256.0D) {
			entity.setPosition(entity.posX, entity.posY + 1.0D, entity.posZ);
		}

		newSpawn = new BlockPos(entity);

		if(entity instanceof EntityPlayer) {
			((EntityPlayer)entity).setSpawnPoint(newSpawn, true);
		}

		if(entity instanceof EntityPlayerMP) {
			EntityPlayerMP playerMP = (EntityPlayerMP) entity;

			playerMP.connection.setPlayerLocation(playerMP.posX, playerMP.posY, playerMP.posZ, playerMP.rotationYaw, playerMP.rotationPitch);
			playerMP.connection.sendPacket(new SPacketSpawnPosition(newSpawn));
		}
	}

public static BlockPos getRespawnPointNearPos(World world, BlockPos pos, int fuzz) {
		BlockPos result = getSpawnPointNearPos(world, pos, fuzz, true, 16, 3);
		if(result == null) {
			int spawnFuzz = fuzz;
			int spawnFuzzHalf = spawnFuzz / 2;
			result = world.getTopSolidOrLiquidBlock(pos.add(world.rand.nextInt(spawnFuzz) - spawnFuzzHalf, 0, world.rand.nextInt(spawnFuzz) - spawnFuzzHalf));
		}
		return result;
	}

@Nullable
	public static BlockPos getSpawnPointNearPos(World world, BlockPos pos, int fuzz, boolean surface, int yRange, int xzSkip) {
		xzSkip = Math.max(xzSkip, 1);

		int spawnFuzz = fuzz;
		int spawnFuzzHalf = spawnFuzz / 2;

		class WeightedPos implements IWeightProvider {
			final BlockPos pos;
			short weight;

			WeightedPos(BlockPos pos) {
				this.pos = pos;
			}

			@Override
			public short getWeight() {
				return this.weight;
			}
		}

		short maxWeight = 0;

		WeightedList<WeightedPos> spawnCandidates = new WeightedList<>();

		MutableBlockPos checkPos = new MutableBlockPos();

		for(int xo = -spawnFuzzHalf; xo <= spawnFuzzHalf; xo += 1 + world.rand.nextInt(xzSkip)) {
			for(int zo = -spawnFuzzHalf; zo <= spawnFuzzHalf; zo += 1 + world.rand.nextInt(xzSkip)) {
				checkPos.setPos(pos.getX() + xo, 0, pos.getZ() + zo);

				Chunk chunk = world.getChunk(checkPos);

				for(int yo = yRange; surface || yo >= -yRange; yo--) {
					if(surface) {
						checkPos.setPos(checkPos.getX(), chunk.getHeight(checkPos), checkPos.getZ());
					} else {
						checkPos.setPos(checkPos.getX(), pos.getY() + yo, checkPos.getZ());
					}

					if(Math.abs(checkPos.getY() - pos.getY()) <= yRange && EntityPlayer.getBedSpawnLocation(world, checkPos, true) != null) {
						checkPos.setY(checkPos.getY() - 1);

						IBlockState stateDown = chunk.getBlockState(checkPos);
						if(stateDown.getMaterial().blocksMovement() && !stateDown.getBlock().isLeaves(stateDown, world, checkPos) && !stateDown.getBlock().isFoliage(world, checkPos)) {
							BlockPos newPos = checkPos.up();
							WeightedPos p = new WeightedPos(newPos);
							p.weight = (short)Math.abs(newPos.getY() - pos.getY());
							maxWeight = (short)Math.max(maxWeight, p.weight);
							spawnCandidates.add(p);
						}
					}

					if(surface) {
						break;
					}
				}
			}
		}

		if(!spawnCandidates.isEmpty()) {
			Collections.shuffle(spawnCandidates, world.rand);

			for(WeightedPos p : spawnCandidates) {
				p.weight = (short) (maxWeight - p.weight);
				p.weight = (short) Math.pow(p.weight, 1.5D);
			}

			spawnCandidates.recalculateWeight();

			return spawnCandidates.getRandomItem(world.rand).pos;
		}

		return null;
	}

