                            } else if (((Character) characters[i]).compareTo(charactersFirst[i]) < 0) {
                                currentFirst = page;
                                break;
                            }
                        }
                    }
                }
            }
            infusionPages.remove(currentFirst);
            temp.add(currentFirst);
        }
        infusionPages.clear();
        infusionPages.addAll(temp);
