        FurnaceData data = tileFurnace.getFurnaceData(index);
        if (newId == 0)
            data.setFurnaceCookTime(value);
        else if (newId == 1)
            data.setFurnaceBurnTime(value);
        else if (newId == 2)
            data.setCurrentItemBurnTime(value);
    }

