		if (facing != EnumFacing.DOWN && facing != EnumFacing.UP && player.canPlayerEdit(offsetPos, facing, itemstack)) {
			EntityHanging entity = this.factory.create(world, offsetPos, facing);

			if (entity != null && entity.onValidSurface()) {
