			if (!getUpgradeList(chest, EntityEquipmentSlot.CHEST).isEmpty())
				for (IAmphibiousArmorUpgrade upgrade : getUpgradeList(chest, EntityEquipmentSlot.CHEST))
					if (isValidUpgrade(upgrade))
