				IAttributeInstance speedAttrib = ((EntityLivingBase) entity).getEntityAttribute(SharedMonsterAttributes.MOVEMENT_SPEED);

				if(speedAttrib != null) {
					speedAttrib.removeModifier(POWER_SPEED_MODIFIER_ATTRIBUTE_UUID);
				}
			}
		}
