@Override
	public boolean itemInteractionForEntity(ItemStack stack, EntityPlayer player, EntityLivingBase target, EnumHand hand) {
		if (target instanceof EntityEmberlingWild && EnumItemMisc.UNDYING_EMBER.isItemOf(stack)) {
			EntityEmberlingWild oldEmberling = (EntityEmberlingWild) target;
			EntityEmberling newEmberling = new EntityEmberling(player.getEntityWorld());
			if (!player.getEntityWorld().isRemote) {

				newEmberling.copyLocationAndAnglesFrom(oldEmberling);
				newEmberling.setTamedBy(player);
				player.getEntityWorld().removeEntity(oldEmberling);
				player.getEntityWorld().spawnEntity(newEmberling);

				if (!player.capabilities.isCreativeMode) {
					stack.shrink(1);
					if (stack.getCount() <= 0)
						player.setHeldItem(hand, ItemStack.EMPTY);
				}
				return true;
			} else {
				oldEmberling.playTameEffect(true);
				return true;
			}
		} else {
			return false;
		}
	}

@Override
	public EnumActionResult onItemUse(EntityPlayer player, World world, BlockPos pos, EnumHand hand, EnumFacing facing, float hitX, float hitY, float hitZ) {
		ItemStack heldItem = player.getHeldItem(hand);

		if (!heldItem.isEmpty() && heldItem.getItem() == EnumItemMisc.BETWEENSTONE_PEBBLE.getItem() && heldItem.getItemDamage() == EnumItemMisc.BETWEENSTONE_PEBBLE.getID()) {
			IBlockState iblockstate = world.getBlockState(pos);
			Block block = iblockstate.getBlock();
			Block blockType;

			if (!block.isReplaceable(world, pos) && !(block instanceof BlockBetweenstonePebblePileWater))
				pos = pos.offset(facing);

			if(world.getBlockState(pos).getMaterial() == Material.WATER)
				blockType = BlockRegistry.BETWEENSTONE_PEBBLE_PILE_WATER;
			else
				blockType = BlockRegistry.BETWEENSTONE_PEBBLE_PILE;

			ItemStack itemstack = player.getHeldItem(hand);

			if (!itemstack.isEmpty() && player.canPlayerEdit(pos, facing, itemstack) && world.mayPlace(blockType, pos, false, facing, (Entity) null)) {
				int i = this.getMetadata(itemstack.getMetadata());
				IBlockState iblockstate1 = blockType.getStateForPlacement(world, pos, facing, hitX, hitY, hitZ, i, player, hand);

				if (placeBlockAt(itemstack, player, world, pos, facing, hitX, hitY, hitZ, iblockstate1)) {
					iblockstate1 = world.getBlockState(pos);
					SoundType soundtype = iblockstate1.getBlock().getSoundType(iblockstate1, world, pos, player);
					world.playSound(player, pos, soundtype.getPlaceSound(), SoundCategory.BLOCKS, (soundtype.getVolume() + 1.0F) / 2.0F, soundtype.getPitch() * 0.8F);
					itemstack.shrink(1);
				}
				return EnumActionResult.SUCCESS;
			}

			return EnumActionResult.FAIL;
		} else if (!heldItem.isEmpty() && EnumItemMisc.WEEDWOOD_BOWL.isItemOf(heldItem)) {
			IFluidHandler handler = FluidUtil.getFluidHandler(world, pos, facing);
			if (handler != null) {
				FluidStack tankContents = handler.drain(250, false);
				if (tankContents != null) { 
					if(tankContents.getFluid() == FluidRegistry.DYE_FLUID || tankContents.getFluid() == FluidRegistry.DRINKABLE_BREW) {
						if(!world.isRemote) {
							IBlockState state = world.getBlockState(pos);

							ItemStack filledBowl = EnumItemMisc.WEEDWOOD_BOWL.create(1);

							if(tankContents.tag != null && tankContents.tag.hasKey("type")) {
								if(tankContents.getFluid() == FluidRegistry.DYE_FLUID)
									filledBowl = new ItemStack(ItemRegistry.DYE, 1, tankContents.tag.getInteger("type"));
								if(tankContents.getFluid() == FluidRegistry.DRINKABLE_BREW)
									filledBowl = EnumBLDrinkableBrew.byMetadata(tankContents.tag.getInteger("type")).getBrewItemStack();
							}

							if (!player.capabilities.isCreativeMode) {
								heldItem.shrink(1);
							}

							if (!player.inventory.addItemStackToInventory(filledBowl))
								ForgeHooks.onPlayerTossEvent(player, filledBowl, false);

							handler.drain(250, true);
							world.notifyBlockUpdate(pos, state, state, 3);
						}

						world.playSound((EntityPlayer) null, pos, SoundEvents.ENTITY_PLAYER_SPLASH, SoundCategory.BLOCKS, 0.75F, 2F);

						return EnumActionResult.SUCCESS;
					}
				}
			}

			return EnumActionResult.FAIL;
		}
		else if (!heldItem.isEmpty() && EnumItemMisc.PHEROMONE_THORAX_CLUTCH.isItemOf(heldItem)) {
			IBlockState iblockstate = world.getBlockState(pos);
			Block block = iblockstate.getBlock();
			if (!world.isRemote && block instanceof BlockWeedwoodBush) {
				world.playEvent(null, 2001, pos, Block.getIdFromBlock(BlockRegistry.WEEDWOOD_BUSH));
				world.setBlockState(pos, BlockRegistry.DEAD_WEEDWOOD_BUSH.getDefaultState());
				EntitySwarm swarm = new EntitySwarm(world);
				swarm.setPosition(pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D);
				world.spawnEntity(swarm);
				heldItem.shrink(1);
				return EnumActionResult.SUCCESS;
			}
			return EnumActionResult.FAIL;
		}
		return EnumActionResult.PASS;
	}

public boolean placeBlockAt(ItemStack stack, EntityPlayer player, World world, BlockPos pos, EnumFacing side, float hitX, float hitY, float hitZ, IBlockState newState) {
        if ((world.getBlockState(pos.down()).getBlock() instanceof BlockBetweenstonePebblePileWater || world.getBlockState(pos.down()).getBlock() instanceof BlockBetweenstonePebblePile) && side == EnumFacing.UP)
        	return false;

        if (!world.setBlockState(pos, newState, 11))
    		return false;

        IBlockState state = world.getBlockState(pos);
        if (state.getBlock() == BlockRegistry.BETWEENSTONE_PEBBLE_PILE) {
        	BlockRegistry.BETWEENSTONE_PEBBLE_PILE.onBlockPlacedBy(world, pos, state, player, stack);
            if (player instanceof EntityPlayerMP)
                CriteriaTriggers.PLACED_BLOCK.trigger((EntityPlayerMP)player, pos, stack);
        }
        if (state.getBlock() == BlockRegistry.BETWEENSTONE_PEBBLE_PILE_WATER) {
        	BlockRegistry.BETWEENSTONE_PEBBLE_PILE_WATER.onBlockPlacedBy(world, pos, state, player, stack);
            if (player instanceof EntityPlayerMP)
                CriteriaTriggers.PLACED_BLOCK.trigger((EntityPlayerMP)player, pos, stack);
        }
        return true;
    }

