	}

public static float getAmmoVelocity(int charge) {
		float strength = (float) charge / 20.0F;
		strength = (strength * strength + strength * 2.0F) / 3.0F * 1.15F;
		if (strength > 1.0F)
			strength = 1.0F;
		return strength;
	}

