private float getFloatOrDefault(float x, float def) {
		if(Float.isFinite(x)) {
			return x;
		}
		return def;
	}

@Override
	public void deserialize(PacketBuffer buf) {
		super.deserialize(buf);

		this.action = Action.values()[buf.readVarInt()];

		this.position = new Position(
				buf.readVarInt(), buf.readVarInt(),
				DraetonPhysicsPart.Type.values()[buf.readVarInt()],
				this.getFloatOrDefault(buf.readFloat(), 0), this.getFloatOrDefault(buf.readFloat(), 0), this.getFloatOrDefault(buf.readFloat(), 0),
				this.getFloatOrDefault(buf.readFloat(), 0), this.getFloatOrDefault(buf.readFloat(), 0), this.getFloatOrDefault(buf.readFloat(), 0)
				);
	}

@Override
	public IMessage process(MessageContext ctx) {
		super.process(ctx);

		//Check for invalid ID
		if(this.position.id < 0) {
			return null;
		}

		if(ctx.side == Side.SERVER) {
			if(this.action == Action.UPDATE) {
				EntityPlayer player = ctx.getServerHandler().player;

				Entity entity = this.getEntity(0);
				if(entity instanceof EntityDraeton) {
					EntityDraeton carriage = (EntityDraeton) entity;

					if(carriage.getControllingPassenger() == player) {
						DraetonPhysicsPart part = carriage.getPhysicsPartById(this.position.id);

						if(part != null) {
							//Make sure position is in valid range since it is client controlled
							float dist = (float) Math.sqrt(this.position.x * this.position.x + this.position.y * this.position.y + this.position.z * this.position.z);
							float maxDist = carriage.getMaxTetherLength(part);
							if(dist > maxDist) {
								this.position.x *= 1.0f / dist * maxDist;
								this.position.y *= 1.0f / dist * maxDist;
								this.position.z *= 1.0f / dist * maxDist;
							}

							//Make sure motion is in valid range
							float speed = (float) Math.sqrt(this.position.mx * this.position.mx + this.position.my * this.position.my + this.position.mz * this.position.mz);
							float maxSpeed = carriage.getMaxPullerSpeed();
							if(speed > maxSpeed) {
								this.position.mx *= 1.0f / speed * maxSpeed;
								this.position.my *= 1.0f / speed * maxSpeed;
								this.position.mz *= 1.0f / speed * maxSpeed;
							}

							carriage.setPacketRelativePartPosition(part, this.position.x, this.position.y, this.position.z, this.position.mx, this.position.my, this.position.mz);
						}
					}
				}
			}
		} else {
			Entity entity = this.getEntity(0);
			if(entity instanceof EntityDraeton) {
				this.processClient((EntityDraeton) entity);
			}
		}

		return null;
	}

public void processClient(EntityDraeton carriage) {
		if(this.action == Action.ADD) {
			carriage.addPhysicsPart(this.position);
		} else if(this.action == Action.REMOVE) {
			carriage.removePhysicsPartById(this.position.id);
		} else {
			DraetonPhysicsPart part = carriage.getPhysicsPartById(this.position.id);

			//fallback if adding failed somehow
			if(part == null) {
				part = carriage.addPhysicsPart(this.position);
			} else {
				carriage.setPacketRelativePartPosition(part, this.position.x, this.position.y, this.position.z, this.position.mx, this.position.my, this.position.mz);
			}
		}
	}

public MessageAddLocalStorage(ILocalStorage localStorage) {
		this.type = StorageRegistry.getStorageId(localStorage.getClass());

		localStorage.getID().writeToNBT(this.idNbt = new NBTTagCompound());

		IGenericDataManagerAccess dataManager = localStorage.getDataManager();
		if(dataManager != null) {
			this.dataManagerEntries = dataManager.getAll();
		}

		localStorage.writeInitialPacket(this.nbt = new NBTTagCompound());
	}

@Override
	public void serialize(PacketBuffer buf) throws IOException {
		buf.writeString(this.type.toString());

		buf.writeCompoundTag(this.idNbt);

		buf.writeCompoundTag(this.nbt);

		buf.writeBoolean(this.dataManagerEntries != null);
		if(this.dataManagerEntries != null) {
			GenericDataManager.writeEntries(this.dataManagerEntries, buf);
		}
	}

@Override
	public void deserialize(PacketBuffer buf) throws IOException {
		this.type = new ResourceLocation(buf.readString(128));

		this.idNbt = buf.readCompoundTag();

		this.nbt = buf.readCompoundTag();

		if(buf.readBoolean()) {
			this.dataManagerEntries = GenericDataManager.readEntries(buf);
		}
	}

@Override
	public IMessage process(MessageContext ctx) {
		if(ctx.side == Side.CLIENT) {
			this.handle();
		}
		return null;
	}

@SideOnly(Side.CLIENT)
	private void handle() {
		World world = Minecraft.getMinecraft().world;
		if(world != null) {
			StorageID id = StorageID.readFromNBT(this.idNbt);

			IWorldStorage worldStorage = WorldStorageImpl.getCapability(world);
			ILocalStorageHandler storageHandler = worldStorage.getLocalStorageHandler();

			ILocalStorage loadedStorage = storageHandler.getLocalStorage(id);
			if(loadedStorage != null) {
				storageHandler.removeLocalStorage(loadedStorage);
			}

			ILocalStorage newStorage = storageHandler.createLocalStorage(this.type, id, null);

			newStorage.readInitialPacket(this.nbt);

			if(this.dataManagerEntries != null) {
				IGenericDataManagerAccess dataManager = newStorage.getDataManager();
				if(dataManager != null) {
					dataManager.setValuesFromPacket(this.dataManagerEntries);
				}
			}

			storageHandler.addLocalStorage(newStorage);
		}
	}

