			this.entry.setDirty(true);
			return this;
		}

public EntryAccess<T> syncImmediately() {
			if(this.entry.queuedDirty) {
				this.entry.dirty = true;
				this.entry.dataManager.dirty = true;
				this.entry.queuedDirty = false;
			}
			return this;
		}

