					teeth++;
				}
			}
		}

		int nodesPerUpgrade = 3;

		int newDamage = Math.min(hook.getItemDamage() + Math.min(tongues, teeth / 2) * nodesPerUpgrade, hook.getMaxDamage());

		hook = hook.copy();
