public int addAmount(int amount) {
        int canAdd = (int) (MAX_AMOUNT - this.aspect.amount);
        int added = 0;
        if(canAdd > 0) {
            added = Math.min(canAdd, amount);
            this.aspect = new Aspect(this.aspect.type, this.aspect.amount + added);
        }
        markDirty();
        return added;
