public int removeAmount(int amount) {
        int removed = Math.min(this.aspect.amount, amount);
        if(removed < this.aspect.amount) {
            this.aspect = new Aspect(this.aspect.type, this.aspect.amount - removed);
        } else {
            this.aspect = null;
        }
        markDirty();
        return removed;
    }

