public void shake(int shakeTimerMax) {
		shakingTimerMax = shakeTimerMax;
		prevShakeTimer = shakeTimer;
		if(shakeTimer == 0) {
			shaking = true;
			shakeTimer = 1;
		}
		if(shakeTimer > 0)
			shakeTimer++;

		if(shakeTimer >= shakingTimerMax)
			shaking = false;
		else
			shaking = true;
	}

@Override
	public float getShakeIntensity(Entity viewer, float partialTicks) {
		if(isShaking()) {
			double dist = getShakeDistance(viewer);
			float shakeMult = (float) (1.0F - dist / 10.0F);
			if(dist >= 10.0F) {
				return 0.0F;
			}
			return (float) ((Math.sin(getShakingProgress(partialTicks) * Math.PI) + 0.1F) * 2F * shakeMult);
		} else {
			return 0.0F;
		}
	}

public float getShakeDistance(Entity entity) {
        float distX = (float)(getPos().getX() - entity.getPosition().getX());
        float distY = (float)(getPos().getY() - entity.getPosition().getY());
        float distZ = (float)(getPos().getZ() - entity.getPosition().getZ());
        return MathHelper.sqrt(distX  * distX  + distY * distY + distZ * distZ);
    }

public boolean isShaking() {
		return shaking;
	}

public float getShakingProgress(float delta) {
		return 1.0F / shakingTimerMax * (prevShakeTimer + (shakeTimer - prevShakeTimer) * delta);
	}

@Override
	public void update() {
		animationTicksChainPrev = animationTicksChain;
		if (isMoving()) {
			if (isSlow())
				animationTicksChain++;
			else
				if(isBroken())
					animationTicksChain += 32;
				else
					animationTicksChain += 8;
		}

		if (getEntityCollidedWithChains(getHangingLengthCollision(0.625F, 5F, 0.625F)) != null)
			checkCollisions(getEntityCollidedWithChains(getHangingLengthCollision(0.625F, 5F, 0.625F)));

		if (animationTicksChainPrev >= 128) {
			animationTicksChain = animationTicksChainPrev = 0;
			if(!isBroken())
				setMoving(false);
		}

		if (!getWorld().isRemote && isBroken()) {
			breakTimer++;
			if (breakTimer > 32) {
				if (breakTimer % 4 == 0) {
					setLength(getLength() - 1);
					updateBlock();
				}
				if (getLength() <= 0) {
					getWorld().setBlockToAir(getPos());
				}
			}
		}	
	}

