@Override
	public void onDataPacket(NetworkManager net, SPacketUpdateTileEntity pkt) {
		NBTTagCompound nbt = pkt.getNbtCompound();
		this.readInventoryNBT(nbt);
		waterTank.readFromNBT(nbt.getCompoundTag("waterTank"));
