public void cycleRadiusState() {
		this.radiusState = (this.radiusState + 1) % 4;
		if(this.running)
			this.deployTicks = 0;
		this.markDirty();
		IBlockState blockState = this.world.getBlockState(this.pos);
		this.world.notifyBlockUpdate(this.pos, blockState, blockState, 2);
	}

