			for(int y = lowestBlock; y < lerp(layerHeight - (layerHeight - lowestBlock) / 2.5f + noise * (layerHeight - lowestBlock) - 2, lowestBlock, biomeWeight); y++) {
				chunkPrimer.setBlockState(x, y, z, chunkGenerator.baseBlockState);
