@Override
	public void initializeGenerators(long seed, Biome biome) {
		Random rng = new Random(seed);
		this.landNoiseGen = new NoiseGeneratorPerlin(rng, 4);
		this.riverNoiseGen = new NoiseGeneratorPerlin(rng, 2);
