public WorldGenBarnacleCluster(IBlockState blockState) {
		this(blockState, 8, 256);
	}

@Override
	public boolean generate(World worldIn, Random rand, BlockPos position) {
		boolean generated = false;

		for (IBlockState iblockstate = worldIn.getBlockState(position);
				(iblockstate.getBlock().isAir(iblockstate, worldIn, position) || iblockstate.getBlock().isLeaves(iblockstate, worldIn, position)) && position.getY() > 0; iblockstate = worldIn.getBlockState(position)) {
			position = position.down();
		}

		PooledMutableBlockPos mutablePos = PooledMutableBlockPos.retain();
		for (int i = 0; i < this.attempts; ++i) {
			mutablePos.setPos(position.getX() + rand.nextInt(this.offset) - rand.nextInt(this.offset), position.getY() + rand.nextInt(this.offset/2+1) - rand.nextInt(this.offset/2+1), position.getZ() + rand.nextInt(this.offset) - rand.nextInt(this.offset));

			if (worldIn.isAreaLoaded(mutablePos, 1) && worldIn.getBlockState(mutablePos).getMaterial() == Material.WATER && this.block.canPlaceBlockAt(worldIn, mutablePos)) {
				EnumFacing facing = EnumFacing.byIndex(rand.nextInt(EnumFacing.VALUES.length));
				EnumFacing.Axis axis = facing.getAxis();
				EnumFacing oppositeFacing = facing.getOpposite();
				boolean isInvalid = false;
				if (axis.isHorizontal() && !worldIn.isSideSolid(mutablePos.offset(oppositeFacing), facing, true)) {
					isInvalid = true;
				} else if (axis.isVertical() && !this.canPlaceOn(worldIn, mutablePos.offset(oppositeFacing))) {
					isInvalid = true;
				}
				if (!isInvalid) {
					IBlockState state = this.blockState.withProperty(BlockBarnacle_1_2.BARNACLE_TYPE_EARLY, BlockBarnacle_1_2.getTypeFromFacing(oppositeFacing));
					this.setBlockAndNotifyAdequately(worldIn, mutablePos.toImmutable(), state);
					generated = true;
				}
			}
		}
		mutablePos.release();

		return generated;
	}

private boolean canPlaceOn(World worldIn, BlockPos pos) {
		IBlockState state = worldIn.getBlockState(pos);
		if (state.isSideSolid(worldIn, pos, EnumFacing.UP)) {
			return true;
		} else {
			return false;
		}
	}

public void generateHead(World world, BlockPos pos){
		world.setBlockState(pos, head, 2);
		world.setBlockState(pos.add(0, -1, 0), head, 2);
		int startY = pos.getY();
		for(int yy = startY; yy >= startY - 4; yy--){
			pos = new BlockPos(pos.getX(), yy, pos.getZ());
			world.setBlockState(pos.add(1, 0, 0), head, 2);
			world.setBlockState(pos.add(-1, 0, 0), head, 2);
			world.setBlockState(pos.add(0, 0, 1), head, 2);
			world.setBlockState(pos.add(0, 0, -1), head, 2);
			world.setBlockState(pos.add(1, 0, -1), head, 2);
			world.setBlockState(pos.add(-1, 0, -1), head, 2);
			world.setBlockState(pos.add(1, 0, 1), head, 2);
			world.setBlockState(pos.add(-1, 0, 1), head, 2);
			if(yy >= startY - 3 && yy <= startY - 1){
				world.setBlockState(pos.add(-2, 0, 0), head, 2);
				world.setBlockState(pos.add(2, 0, 0), head, 2);
				world.setBlockState(pos.add(0, 0, -2), head, 2);
				world.setBlockState(pos.add(0, 0, 2), head, 2);
				world.setBlockState(pos.add(-2, 0, -1), head, 2);
				world.setBlockState(pos.add(-2, 0, 1), head, 2);
				world.setBlockState(pos.add(2, 0, -1), head, 2);
				world.setBlockState(pos.add(2, 0, 1), head, 2);
				world.setBlockState(pos.add(-1, 0, 2), head, 2);
				world.setBlockState(pos.add(1, 0, 2), head, 2);
				world.setBlockState(pos.add(-1, 0, -2), head, 2);
				world.setBlockState(pos.add(1, 0, -2), head, 2);
			}
		}
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		this.head = BlockRegistry.BULB_CAPPED_MUSHROOM_CAP.getDefaultState();
		this.stalk = BlockRegistry.BULB_CAPPED_MUSHROOM_STALK.getDefaultState().withProperty(BlockLog.LOG_AXIS, EnumAxis.Y);

		int height = rand.nextInt(2) + 8;
		int maxRadius = 2;

		MutableBlockPos checkPos = new MutableBlockPos();

		int x = position.getX();
		int y = position.getY();
		int z = position.getZ();

		for (int xx = x - maxRadius; xx <= x + maxRadius; xx++)
			for (int zz = z - maxRadius; zz <= z + maxRadius; zz++)
				for (int yy = y + 2; yy < y + height; yy++)
					if (!world.isAirBlock(checkPos.setPos(xx, yy, zz)))
						return false;


		for (int yy = y; yy < y + height; ++yy) {
			if (yy == y) {
				world.setBlockState(new BlockPos(x, yy, z), stalk, 2);
			}
			else
				world.setBlockState(new BlockPos(x, yy, z), stalk, 2);

			if(yy == y + height -1)
				generateHead(world, new BlockPos(x, yy, z));

		}
		DecorationHelper.GEN_BULB_CAPPED_MUSHROOMS.generate(world, rand, position);
		return true;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		boolean generated = false;

		for (IBlockState iblockstate = world.getBlockState(position); (iblockstate.getBlock().isAir(iblockstate, world, position) || iblockstate.getBlock().isLeaves(iblockstate, world, position)) && position.getY() > 0; iblockstate = world.getBlockState(position)) {
			position = position.down();
		}

		for (int i = 0; i < 128; ++i) {
			BlockPos pos = position.add(rand.nextInt(10) - rand.nextInt(10), rand.nextInt(8) - rand.nextInt(8), rand.nextInt(10) - rand.nextInt(10));

			if(world.isBlockLoaded(pos) && SurfaceType.WATER.matches(world, pos.up()) && SurfaceType.DIRT.matches(world, pos)) {
				if(this.generateBladderwortStack(world, rand, pos.up()))
					generated = true;
			}
		}

		return generated;
	}

private boolean generateBladderwortStack(World world, Random rand, BlockPos pos) {
		int height = 0;
		MutableBlockPos checkPos = new MutableBlockPos();
		for(int yo = 0; yo < 128; yo++) {
			checkPos.setPos(pos.getX(), pos.getY() + yo, pos.getZ());
			if(!world.isAirBlock(checkPos) && !SurfaceType.WATER.matches(world, checkPos))
				return false;
			if(world.isAirBlock(checkPos) && world.isAirBlock(checkPos.setPos(pos.getX(), pos.getY() + yo + 1, pos.getZ()))) {
				height = yo;
				break;
			}
		}
		if(height < 4)
			return false;
		for(int yo = 0; yo <= height; yo++) {
			BlockPos offsetPos = pos.add(0, yo, 0);
			IBlockState state = world.getBlockState(offsetPos);
			if(!SurfaceType.WATER.matches(state)) {
				world.setBlockState(offsetPos, BlockRegistry.BLADDERWORT_FLOWER.getDefaultState(), 2 | 16);
				break;
			} else {
				world.setBlockState(offsetPos, BlockRegistry.BLADDERWORT_STALK.getDefaultState(), 2 | 16);
			}
		}
		return true;
	}

