			}
		}
		if(height < 2)
			return false;
		height = rand.nextInt(height) + 1 + rand.nextInt(4);
		for(int yo = 0; yo < height; yo++) {
			BlockPos offsetPos = pos.add(0, yo, 0);
			world.setBlockState(offsetPos, BlockRegistry.ROOT.getDefaultState(), 2 | 16);
