@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		this.log = BlockRegistry.LOG_ROTTEN_BARK.getDefaultState().withProperty(BlockLogBetweenlands.LOG_AXIS, EnumAxis.NONE);

		int x = pos.getX();
		int y = pos.getY();
		int z = pos.getZ();

		// Trunk N/S
		if (direction == 1) {
			for (int xx = x - baseRadius; baseRadius + x >= xx; xx++) {
				for (int zz = z - length; length + z - 1 >= zz; zz++) {
					for (int yy = y + 1; yy <= y + baseRadius * 2; yy++) {
						BlockPos offsetPos = new BlockPos(xx, yy, zz);
						if (!world.isBlockLoaded(offsetPos) || !world.getBlockState(offsetPos).getBlock().isReplaceable(world, offsetPos)) {
							return false;
						}
					}
				}
			}

			for (int zz = z - length; length + z - 1 >= zz; zz++)
				for (int i = baseRadius * -1; i <= baseRadius; ++i)
					for (int j = baseRadius * -1; j <= baseRadius; ++j) {
						double dSq = i * i + j * j;
						BlockPos offsetPos = new BlockPos(x + i, y + j + baseRadius, zz);
						if (Math.round(Math.sqrt(dSq)) == baseRadius) {
							world.setBlockState(offsetPos, log, 2 | 16);
							if (rand.nextInt(12) == 0)
								world.setBlockState(offsetPos, Blocks.AIR.getDefaultState(), 2 | 16);
							if (zz == z - length && rand.nextInt(2) == 0 || zz == z + length - 1 && rand.nextInt(2) == 0)
								world.setBlockState(offsetPos, Blocks.AIR.getDefaultState(), 2 | 16);
						} else
							world.setBlockState(offsetPos, Blocks.AIR.getDefaultState(), 2 | 16);
					}

		} else {

			// Trunk E/W
			for (int xx = x - length; length + x - 1 >= xx; xx++) {
				for (int zz = z - baseRadius; baseRadius + z >= zz; zz++) {
					for (int yy = y + 1; yy <= y + baseRadius * 2; yy++) {
						BlockPos offsetPos = new BlockPos(xx, yy, zz);
						if (!world.isBlockLoaded(offsetPos) || !world.getBlockState(offsetPos).getBlock().isReplaceable(world, offsetPos)) {
							return false;
						}
					}
				}
			}

			for (int xx = x - length; length + x - 1 >= xx; xx++)
				for (int i = baseRadius * -1; i <= baseRadius; ++i)
					for (int j = baseRadius * -1; j <= baseRadius; ++j) {
						double dSq = i * i + j * j;
						BlockPos offsetPos = new BlockPos(xx, y + j + baseRadius, z + i);
						if (Math.round(Math.sqrt(dSq)) == baseRadius) {
							world.setBlockState(offsetPos, log, 2 | 16);
							if (rand.nextInt(12) == 0)
								world.setBlockState(offsetPos, Blocks.AIR.getDefaultState(), 2 | 16);
							if (xx == x - length && rand.nextInt(2) == 0 || xx == x + length - 1 && rand.nextInt(2) == 0)
								world.setBlockState(offsetPos, Blocks.AIR.getDefaultState(), 2 | 16);
						} else
							world.setBlockState(offsetPos, Blocks.AIR.getDefaultState(), 2 | 16);
					}
		}
		return true;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		int radius = rand.nextInt(2) + 3;
		int height = rand.nextInt(2) + 15;
		int maxRadius = 9;

		this.log = BlockRegistry.LOG_ROTTEN_BARK.getDefaultState();
		this.bark = BlockRegistry.LOG_ROTTEN_BARK.getDefaultState();
		this.wood = BlockRegistry.WEEDWOOD.getDefaultState();
		this.ivy = BlockRegistry.POISON_IVY.getDefaultState();

		if (!world.isAreaLoaded(pos, maxRadius))
			return false;

		int x = pos.getX();
		int y = pos.getY();
		int z = pos.getZ();

		boolean hasPoisonIvy = rand.nextInt(2) == 0;

		for (int xx = x - maxRadius; xx <= x + maxRadius; xx++)
			for (int zz = z - maxRadius; zz <= z + maxRadius; zz++)
				for (int yy = y + 2; yy < y + height; yy++)
					if (!world.isAirBlock(new BlockPos(xx, yy, zz)) && !world.getBlockState(new BlockPos(xx, yy, zz)).getBlock().isReplaceable(world, new BlockPos(xx, yy, zz)))
						return false;


		for (int yy = y; yy < y + height; ++yy) {
			if (yy % 5 == 0 && radius > 1)
				--radius;

			for (int i = radius * -1; i <= radius; ++i)
				for (int j = radius * -1; j <= radius; ++j) {
					double dSq = i * i + j * j;
					if (Math.round(Math.sqrt(dSq)) < radius && yy <= y + height - 2)
						this.setBlockAndNotifyAdequately(world, new BlockPos(x + i, yy, z + j), wood);
					if (Math.round(Math.sqrt(dSq)) == radius && yy == y || Math.round(Math.sqrt(dSq)) == radius && yy <= y + height - 1)
						this.setBlockAndNotifyAdequately(world, new BlockPos(x + i, yy, z + j), bark);
				}

			if (yy == y + height/2 + 2) {
				createBranch(world, rand, x + radius + 1, yy - rand.nextInt(1), z, 1, false, rand.nextInt(2) + 4, hasPoisonIvy);
				createBranch(world, rand, x - radius - 1, yy - rand.nextInt(1), z, 2, false, rand.nextInt(2) + 4, hasPoisonIvy);
				createBranch(world, rand, x, yy - rand.nextInt(1), z + radius + 1, 3, false, rand.nextInt(2) + 4, hasPoisonIvy);
				createBranch(world, rand, x, yy - rand.nextInt(1), z - radius - 1, 4, false, rand.nextInt(2) + 4, hasPoisonIvy);

				createBranch(world, rand, x + radius + 1, yy - rand.nextInt(1), z + radius + 1, 5, false, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x - radius - 1, yy - rand.nextInt(1), z - radius - 1, 6, false, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x - radius - 1, yy - rand.nextInt(1), z + radius + 1, 7, false, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x + radius + 1, yy - rand.nextInt(1), z - radius - 1, 8, false, rand.nextInt(2) + 3, hasPoisonIvy);
			}

			if (yy == y + height/2 + 4) {
				createSmallBranch(world, rand, x + radius + 1, yy - rand.nextInt(1), z, 1, 4);
				createSmallBranch(world, rand, x - radius - 1, yy - rand.nextInt(1), z, 2, 4);
				createSmallBranch(world, rand, x, yy - rand.nextInt(1), z + radius + 1, 3, 4);
				createSmallBranch(world, rand, x, yy - rand.nextInt(1), z - radius - 1, 4, 4);

				createSmallBranch(world, rand, x + radius + 1, yy - rand.nextInt(1), z + radius + 1, 5, 3);
				createSmallBranch(world, rand, x - radius - 1, yy - rand.nextInt(1), z - radius - 1, 6, 3);
				createSmallBranch(world, rand, x - radius - 1, yy - rand.nextInt(1), z + radius + 1, 7, 3);
				createSmallBranch(world, rand, x + radius + 1, yy - rand.nextInt(1), z - radius - 1, 8, 3);
			}

			if (yy == y + height/2 + 7) {
				createSmallBranch(world, rand, x + radius + 1, yy - rand.nextInt(2), z, 1, 2);
				createSmallBranch(world, rand, x - radius - 1, yy - rand.nextInt(2), z, 2, 2);
				createSmallBranch(world, rand, x, yy - rand.nextInt(3), z + radius + 1, 3, 2);
				createSmallBranch(world, rand, x, yy - rand.nextInt(3), z - radius - 1, 4, 2);

				createSmallBranch(world, rand, x + radius + 1, yy - rand.nextInt(1), z + radius + 1, 5, 2);
				createSmallBranch(world, rand, x - radius - 1, yy - rand.nextInt(1), z - radius - 1, 6, 2);
				createSmallBranch(world, rand, x - radius - 1, yy - rand.nextInt(1), z + radius + 1, 7, 2);
				createSmallBranch(world, rand, x + radius + 1, yy - rand.nextInt(1), z - radius - 1, 8, 2);
			}

			if (yy == y + 1) {
				createBranch(world, rand, x + radius + 1, yy - rand.nextInt(3), z, 1, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x - radius - 1, yy - rand.nextInt(3), z, 2, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x, yy - rand.nextInt(3), z + radius + 1, 3, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x, yy - rand.nextInt(3), z - radius - 1, 4, true, rand.nextInt(2) + 3, hasPoisonIvy);

				createBranch(world, rand, x + radius + 1, yy - rand.nextInt(2), z + radius + 1, 5, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x - radius - 1, yy - rand.nextInt(2), z - radius - 1, 6, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x - radius - 1, yy - rand.nextInt(2), z + radius + 1, 7, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, x + radius + 1, yy - rand.nextInt(2), z - radius - 1, 8, true, rand.nextInt(2) + 3, hasPoisonIvy);
			}
		}
		return true;
	}

private void createSmallBranch(World world, Random rand, int x, int y, int z, int dir, int branchLength) {
		for (int i = 0; i <= branchLength; ++i) {
			if (dir == 1)
				this.setBlockAndNotifyAdequately(world, new BlockPos(x + i, y, z), log);

			if (dir == 2)
				this.setBlockAndNotifyAdequately(world, new BlockPos(x - i, y, z), log);

			if (dir == 3)
				this.setBlockAndNotifyAdequately(world, new BlockPos(x, y, z + i), log);

			if (dir == 4)
				this.setBlockAndNotifyAdequately(world, new BlockPos(x, y, z - i), log);

			if (dir == 5)
				this.setBlockAndNotifyAdequately(world, new BlockPos(x + i - 1, y, z + i - 1), log);

			if (dir == 6)
				this.setBlockAndNotifyAdequately(world, new BlockPos(x - i + 1, y, z - i + 1), log);

			if (dir == 7)
				this.setBlockAndNotifyAdequately(world, new BlockPos(x - i + 1, y, z + i - 1), log);

			if (dir == 8)
				this.setBlockAndNotifyAdequately(world, new BlockPos(x + i - 1, y, z - i + 1), log);
		}
	}

private void createBranch(World world, Random rand, int x, int y, int z, int dir, boolean root, int branchLength, boolean ivy) {
		for (int i = 0; i <= branchLength; ++i) {

			if (i >= 3) {
				if(!root)
					y++;
				else
					y--;
			}

			if (dir == 1)
				if (!root) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i, y, z), log);
					if (i <= branchLength && ivy)
						addVines(world, rand, x + i, y - 1, z, EnumFacing.WEST);
				} else {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i, y, z), log);
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i, y - 1, z), log);
				}

			if (dir == 2)
				if (!root) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i, y, z), log);
					if (i <= branchLength && ivy)
						addVines(world, rand, x - i, y - 1, z, EnumFacing.EAST);
				} else {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i, y, z), log);
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i, y - 1, z), log);
				}

			if (dir == 3)
				if (!root) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x, y, z + i), log);
					if (i <= branchLength && ivy)
						addVines(world, rand, x, y - 1, z + i, EnumFacing.NORTH);
				} else {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x, y, z + i), log);
					this.setBlockAndNotifyAdequately(world, new BlockPos(x, y - 1, z + i), log);
				}

			if (dir == 4)
				if (!root) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x, y, z - i), log);
					if (i <= branchLength && ivy)
						addVines(world, rand, x, y - 1, z - i, EnumFacing.SOUTH);
				} else {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x, y, z - i), log);
					this.setBlockAndNotifyAdequately(world, new BlockPos(x, y - 1, z - i), log);
				}

			if (dir == 5)
				if (!root) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i - 1, y, z + i - 1), log);
					if (i <= branchLength && ivy)
						addVines(world, rand, x + i - 1, y - 1, z + i - 1, EnumFacing.WEST);
				} else {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i - 1, y, z + i - 1), log);
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i - 1, y - 1, z + i - 1), log);
				}

			if (dir == 6)
				if (!root) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i + 1, y, z - i + 1), log);
					if (i <= branchLength && ivy)
						addVines(world, rand, x - i + 1, y - 1, z - i + 1, EnumFacing.SOUTH);
				} else {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i + 1, y, z - i + 1), log);
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i + 1, y - 1, z - i + 1), log);
				}

			if (dir == 7)
				if (!root) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i + 1, y, z + i - 1), log);
					if (i <= branchLength && ivy)
						addVines(world, rand, x - i + 1, y - 1, z + i - 1, EnumFacing.EAST);
				} else {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i + 1, y, z + i - 1), log);
					this.setBlockAndNotifyAdequately(world, new BlockPos(x - i + 1, y - 1, z + i - 1), log);
				}

			if (dir == 8)
				if (!root) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i - 1, y, z - i + 1), log);
					if (i <= branchLength && ivy)
						addVines(world, rand, x + i - 1, y - 1, z - i + 1, EnumFacing.NORTH);
				} else {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i - 1, y, z - i + 1), log);
					this.setBlockAndNotifyAdequately(world, new BlockPos(x + i - 1, y - 1, z - i + 1), log);
				}
		}
	}

private void addVines(World world, Random rand, int x, int y, int z, EnumFacing... dirs) {
		IBlockState state = this.ivy;
		for(EnumFacing dir : dirs) {
			switch(dir) {
			default:
			case NORTH:
				state = state.withProperty(BlockPoisonIvy.NORTH, true);
				break;
			case SOUTH:
				state = state.withProperty(BlockPoisonIvy.SOUTH, true);
				break;
			case EAST:
				state = state.withProperty(BlockPoisonIvy.EAST, true);
				break;
			case WEST:
				state = state.withProperty(BlockPoisonIvy.WEST, true);
				break;
			case UP:
				state = state.withProperty(BlockPoisonIvy.UP, true);
				break;
			}
		}
		if (BlockRegistry.POISON_IVY.canPlaceBlockOnSide(world, new BlockPos(x, y, z), dirs[0].getOpposite()) && rand.nextInt(4) != 0) {
			int length = rand.nextInt(4) + 4;
			for (int yy = y; yy > y - length; --yy)
				if (world.isAirBlock(new BlockPos(x, yy, z))) {
					this.setBlockAndNotifyAdequately(world, new BlockPos(x, yy, z), state);
				} else {
					break;
				}
		}
	}

public WorldGenSimulacrum(List<BlockSimulacrum> variants, ResourceLocation lootTable) {
		this.variants = variants;
		this.lootTableLocation = lootTable;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		if(!world.isRemote && world.isAirBlock(position)) {
			for(int i = 0; i < 8 && world.isAirBlock(position); i++) {
				position = position.down();
			}

			position = position.up();

			if(world.isAirBlock(position) && world.isSideSolid(position.down(), EnumFacing.UP) && this.canGenerateHere(world, rand, position)) {
				BlockSimulacrum block = this.variants.get(rand.nextInt(this.variants.size()));

				EnumFacing facing = null;

				if(world instanceof WorldServer && this.shouldGenerateOfferingTable(rand)) {
					List<EnumFacing> offsets = new ArrayList<>(Arrays.asList(EnumFacing.HORIZONTALS));
					Collections.shuffle(offsets, rand);

					for(EnumFacing dir : offsets) {
						BlockPos offset = position.offset(dir);

						if(world.isAirBlock(offset) && world.isSideSolid(offset.down(), EnumFacing.UP)) {
							this.setBlockAndNotifyAdequately(world, offset, BlockRegistry.OFFERING_TABLE.getDefaultState().withProperty(BlockOfferingTable.FACING, dir.getOpposite()));

							facing = dir;

							TileEntity tile = world.getTileEntity(offset);
							if(tile instanceof TileEntityGroundItem) {
								LootTable lootTable = ((WorldServer) world).getLootTableManager().getLootTableFromLocation(this.lootTableLocation);

								if(lootTable != null) {
									LootContext.Builder lootBuilder = new LootContext.Builder((WorldServer) world);

									List<ItemStack> loot = lootTable.generateLootForPools(rand, lootBuilder.build());

									if(!loot.isEmpty()) {
										((TileEntityGroundItem) tile).setStack(loot.get(0));
									}
								}
							}

							break;
						}
					}
				}

				IBlockState state = block.getDefaultState()
						.withProperty(BlockSimulacrum.VARIANT, BlockSimulacrum.Variant.values()[rand.nextInt(BlockSimulacrum.Variant.values().length)])
						.withProperty(BlockSimulacrum.FACING, facing == null ? EnumFacing.HORIZONTALS[rand.nextInt(EnumFacing.HORIZONTALS.length)] : facing);

				this.setBlockAndNotifyAdequately(world, position, state);

				TileEntity tile = world.getTileEntity(position);
				if(tile instanceof TileEntitySimulacrum) {
					((TileEntitySimulacrum) tile).setEffect(TileEntitySimulacrum.Effect.values()[rand.nextInt(TileEntitySimulacrum.Effect.values().length)]);
				}

				int torches = rand.nextInt(3);

				for(int i = 0; i < 32 && torches > 0; i++) {
					int rx = rand.nextInt(5) - 2;
					int rz = rand.nextInt(5) - 2;

					if((rx != 0 || rz != 0) && Math.abs(rx) + Math.abs(rz) <= 2) {
						BlockPos offset = position.add(rx, rand.nextInt(3) - 2, rz);

						if(world.isAirBlock(offset) && world.isSideSolid(offset.down(), EnumFacing.UP)) {
							this.setBlockAndNotifyAdequately(world, offset, BlockRegistry.MUD_FLOWER_POT_CANDLE.getDefaultState());
							torches--;
						}
					}
				}

				return true;
			}
		}

		return false;
	}

protected boolean shouldGenerateOfferingTable(Random rand) {
		return rand.nextInt(3) != 0;
	}

protected boolean canGenerateHere(World world, Random rand, BlockPos pos) {
		return true;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		int len = rand.nextInt(3) + 3;
		int offsetX = rand.nextInt(2), offsetZ = 1 - offsetX;

		for (int a = 0; a < len; a++)
			if (!world.isAirBlock(pos.add(offsetX * a, 0, offsetZ * a)) || world.isAirBlock(pos.add(offsetX * a, -1, offsetZ * a)))
				return false;

		boolean wasLastBranch = false;
		for (int a = 0; a < len; a++) {
			IBlockState state = BlockRegistry.HOLLOW_LOG.getDefaultState();
			if(offsetX != 0)
				state = state.withProperty(BlockHollowLog.FACING, EnumFacing.EAST);
			else if(offsetZ != 0)
				state = state.withProperty(BlockHollowLog.FACING, EnumFacing.SOUTH);
			this.setBlockAndNotifyAdequately(world, pos.add(offsetX * a, 0, offsetZ * a), state);
			if(wasLastBranch) {
				wasLastBranch = false;
			} else if(rand.nextInt(6) == 0) {
				wasLastBranch = true;
				IBlockState state2 = BlockRegistry.HOLLOW_LOG.getDefaultState();
				if(offsetX != 0)
					state2 = state.withProperty(BlockHollowLog.FACING, EnumFacing.SOUTH);
				else if(offsetZ != 0)
					state2 = state.withProperty(BlockHollowLog.FACING, EnumFacing.EAST);
				BlockPos newPos = pos.add(offsetX * a, 0, offsetZ * a);
				if(rand.nextInt(2) == 0)
					newPos = newPos.add(offsetZ != 0 ? 1 : 0, 0, offsetX != 0 ? 1 : 0);
				else
					newPos = newPos.add(offsetZ != 0 ? -1 : 0, 0, offsetX != 0 ? -1 : 0);
				if(world.isAirBlock(newPos)) {
					this.setBlockAndNotifyAdequately(world, newPos, state2);
				}
			}
		}
		return true;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		int checkRadius = 4;

		for (int xx = -checkRadius; xx <= checkRadius; xx++) {
			for (int zz = -checkRadius; zz <= checkRadius; zz++) {
				for (int yy = 2; yy < 10; yy++) {
					if (!world.isAirBlock(position.add(xx, yy, zz)) && world.getBlockState(position.add(xx, yy, zz)).isNormalCube()) {
						return false;
					}
				}
			}
		}

		this.log = BlockRegistry.LOG_SPIRIT_TREE.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.NONE);
		this.leavesTop = BlockRegistry.LEAVES_SPIRIT_TREE_TOP.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
		this.leavesMiddle = BlockRegistry.LEAVES_SPIRIT_TREE_MIDDLE.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
		this.leavesBottom = BlockRegistry.LEAVES_SPIRIT_TREE_BOTTOM.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
		this.roots = BlockRegistry.ROOT.getDefaultState();

		int trunkX = position.getX();
		int trunkY = position.getY();
		int trunkZ = position.getZ();

		int height = 5 + rand.nextInt(3);

		List<BlockPos> facePositions = new ArrayList<>();

		for(int yo = 0; yo < height; yo++) {
			BlockPos pos = new BlockPos(trunkX, trunkY + yo, trunkZ);
			this.setBlock(world, pos, this.log, false, trunkX, trunkY, trunkZ);
			facePositions.add(pos);
		}

		Map<List<BlockPos>, BlockPos> branches = new HashMap<>();

		BlockPos sideBranch;

		//Generate 4 main branches in the cardinal directions

		if(rand.nextInt(2) == 0) {
			sideBranch = new BlockPos(trunkX, trunkY + height - 2, trunkZ);
			branches.put(this.generateSideBranch(world, rand, sideBranch, 0, trunkX, trunkY, trunkZ), sideBranch);

			sideBranch = new BlockPos(trunkX + 1, trunkY + height - 2, trunkZ);
			branches.put(this.generateSideBranch(world, rand, sideBranch, 6, trunkX, trunkY, trunkZ), sideBranch);
		} else {
			sideBranch = new BlockPos(trunkX, trunkY + height - 2, trunkZ);
			branches.put(this.generateSideBranch(world, rand, sideBranch, 2, trunkX, trunkY, trunkZ), sideBranch);

			sideBranch = new BlockPos(trunkX, trunkY + height - 2, trunkZ + 1);
			branches.put(this.generateSideBranch(world, rand, sideBranch, 4, trunkX, trunkY, trunkZ), sideBranch);
		}

		//Generate 1-2 diagonal branches
		List<Integer> diagonals = new ArrayList<>(Arrays.asList(1, 3, 5, 7));
		int numDiagonals = 1 + rand.nextInt(2);
		for(int i = 0; i < numDiagonals; i++) {
			int dir = diagonals.remove(rand.nextInt(diagonals.size()));
			int[] offset = this.getDirOffset(dir);
			int bx = trunkX + offset[0];
			int bz = trunkZ + offset[1];
			sideBranch = new BlockPos(bx, trunkY + height, bz);
			branches.put(this.generateSideBranch(world, rand, sideBranch, dir, trunkX, trunkY, trunkZ), sideBranch);
		}

		//Generate two tall branches at top of trunk
		sideBranch = new BlockPos(trunkX, trunkY + height, trunkZ);
		branches.put(this.generateTopBranch(world, rand, sideBranch, 1, trunkX, trunkY, trunkZ), sideBranch);

		sideBranch = new BlockPos(trunkX + 1, trunkY + height, trunkZ + 1);
		branches.put(this.generateTopBranch(world, rand, sideBranch, 5, trunkX, trunkY, trunkZ), sideBranch);

		sideBranch = new BlockPos(trunkX, trunkY + height, trunkZ + 1);
		branches.put(this.generateTopBranch(world, rand, sideBranch, 3, trunkX, trunkY, trunkZ), sideBranch);

		sideBranch = new BlockPos(trunkX + 1, trunkY + height, trunkZ);
		branches.put(this.generateTopBranch(world, rand, sideBranch, 7, trunkX, trunkY, trunkZ), sideBranch);

		for(Entry<List<BlockPos>, BlockPos> branch : branches.entrySet()) {
			this.generateBranchLeaves(world, rand, branch.getValue(), branch.getKey(), trunkX, trunkY, trunkZ);
		}

		//Generate roots

		List<BlockPos> rootBlocks = new ArrayList<>();

		sideBranch = new BlockPos(trunkX + rand.nextInt(2), trunkY - 1, trunkZ);
		rootBlocks.addAll(this.generateRoot(world, rand, sideBranch, 0, trunkX, trunkY, trunkZ));

		sideBranch = new BlockPos(trunkX, trunkY - 1, trunkZ + rand.nextInt(2));
		rootBlocks.addAll(this.generateRoot(world, rand, sideBranch, 2, trunkX, trunkY, trunkZ));

		sideBranch = new BlockPos(trunkX + rand.nextInt(2), trunkY - 1, trunkZ + 1);
		rootBlocks.addAll(this.generateRoot(world, rand, sideBranch, 4, trunkX, trunkY, trunkZ));

		sideBranch = new BlockPos(trunkX + 1, trunkY - 1, trunkZ + rand.nextInt(2));
		rootBlocks.addAll(this.generateRoot(world, rand, sideBranch, 6, trunkX, trunkY, trunkZ));

		for(BlockPos rootBlock : rootBlocks) {
			if(rand.nextInt(4) == 0 && new Vec3d(rootBlock.getX() + 0.5D, 0, rootBlock.getZ() + 0.5D).squareDistanceTo(trunkX + 1.0D, 0, trunkZ + 1.0D) >= 9 && world.isAirBlock(rootBlock.up())) {
				int rootHeight = 1 + rand.nextInt(3);
				for(int yo = 0; yo < rootHeight; yo++) {
					BlockPos pos = rootBlock.up(1 + yo);
					if(world.isAirBlock(pos)) {
						this.setBlock(world, pos, this.roots, true, trunkX, trunkY, trunkZ);
					} else {
						break;
					}
				}
			}
		}

		EntityTamedSpiritTreeFace face = new EntityTamedSpiritTreeFace(world);
		this.trySpawnFace(world, rand, face, facePositions);

		return true;
	}

private void trySpawnFace(World world, Random rand, EntitySpiritTreeFace face, List<BlockPos> locations) {
		BlockPos faceAnchor = null;
		EnumFacing faceFacing = null;

		List<BlockPos> randFacePositions = new ArrayList<>();
		randFacePositions.addAll(locations);
		Collections.shuffle(randFacePositions, rand);
		largeFaceLoop: for(BlockPos anchor : randFacePositions) {
			List<EnumFacing> facings = new ArrayList<>();
			facings.addAll(Arrays.asList(EnumFacing.HORIZONTALS));
			Collections.shuffle(facings, rand);
			for(EnumFacing facing : facings) {
				if(face.checkAnchorAt(anchor, facing, EnumFacing.UP, AnchorChecks.ALL) == 0) {
					faceAnchor = anchor;
					faceFacing = facing;
					break largeFaceLoop;
				}
			}
		}

		if(faceAnchor != null && faceFacing != null) {
			face.onInitialSpawn(world.getDifficultyForLocation(faceAnchor), null);
			face.setPositionToAnchor(faceAnchor, faceFacing, EnumFacing.UP);
			world.spawnEntity(face);
		}
	}

private int[] getDirOffset(int dir) {
		int[] offset = new int[2];
		switch(dir) {
		case 0: //N
			offset[1] = -1;
			break;
		case 1: //NW
			offset[0] = -1;
			offset[1] = -1;
			break;
		case 2: //W
			offset[0] = -1;
			break;
		case 3: //SW
			offset[0] = -1;
			offset[1] = 1;
			break;
		case 4: //S
			offset[1] = 1;
			break;
		case 5: //SE
			offset[0] = 1;
			offset[1] = 1;
			break;
		case 6: //E
			offset[0] = 1;
			break;
		case 7: //NE
			offset[0] = 1;
			offset[1] = -1;
			break;
		}
		return offset;
	}

private List<BlockPos> generateRoot(World world, Random rand, BlockPos start, int dir, int trunkX, int trunkY, int trunkZ) {
		List<BlockPos> root = this.generateBranchPositions(rand, start, dir, 1 + rand.nextInt(2), 0.9D, 0.8D, (i, remainingBlocks) -> i < 2 ? 0 : rand.nextInt((i - 2) * 2 + 2) == 0 ? 0 : -1, (i, length) -> true);
		for(BlockPos pos : root) {
			BlockPos rel = pos.subtract(new BlockPos(trunkX, trunkY, trunkZ));
			if(Math.abs(rel.getX()) + Math.abs(rel.getZ()) == 1) {
				root.add(root.indexOf(pos), pos.up());
				break;
			}
		}
		for(BlockPos pos : root) {
			this.setBlock(world, pos, this.log, true, trunkX, trunkY, trunkZ);
		}
		return root;
	}

private List<BlockPos> generateSideBranch(World world, Random rand, BlockPos start, int dir, int trunkX, int trunkY, int trunkZ) {
		List<BlockPos> branch = this.generateSideBranchPositions(rand, start, dir);
		for(BlockPos pos : branch) {
			this.setBlock(world, pos, this.log, true, trunkX, trunkY, trunkZ);
		}
		return branch;
	}

private List<BlockPos> generateSideBranchPositions(Random rand, BlockPos start, int dir) {
		return this.generateBranchPositions(rand, start, dir, 1 + rand.nextInt(2), 0.3D, 0.6D, (i, remainingBlocks) -> i < remainingBlocks / 2 ? 1 : (i >= remainingBlocks - 1 && rand.nextInt(2) == 0 ? -1  : 0), (i, length) -> true);
	}

private List<BlockPos> generateTopBranch(World world, Random rand, BlockPos start, int dir, int trunkX, int trunkY, int trunkZ) {
		List<BlockPos> branch = this.generateBranchPositions(rand, start, dir, 1 + rand.nextInt(3), 0.1D, 0.2D, (i, remainingBlocks) -> i < remainingBlocks - 1 ? 1 : 0, (i, length) -> i >= length - 1);
		for(BlockPos pos : branch) {
			this.setBlock(world, pos, this.log, true, trunkX, trunkY, trunkZ);
		}
		return branch;
	}

public List<BlockPos> generateBranchPositions(Random rand, BlockPos start, int dir, int length, double defaultCurveWeight, double directedCurveWeight,
			BiFunction<Integer, Double, Integer> heightFunction, BiFunction<Integer, Double, Boolean> forceMoveFunction) {
		double remainingBlocks = length;

		List<BlockPos> branchBlocks = new ArrayList<>(length);

		BlockPos branch = start;

		double rx = rand.nextDouble() * defaultCurveWeight * 2 - defaultCurveWeight;
		double rz = rand.nextDouble() * defaultCurveWeight * 2 - defaultCurveWeight;

		int[] offset = this.getDirOffset(dir);

		if(offset[0] != 0) {
			rx = offset[0] * directedCurveWeight;
		}

		if(offset[1] != 0) {
			rz = offset[1] * directedCurveWeight;
		}

		branchBlocks.add(branch);

		for(int i = 0; i < remainingBlocks; i++) {
			int xo = rand.nextDouble() < Math.abs(rx) ? (int)Math.signum(rx) : 0;
			int zo = rand.nextDouble() < Math.abs(rz) ? (int)Math.signum(rz) : 0;
			if(zo == 0 && xo == 0 && forceMoveFunction.apply(i, remainingBlocks)) {
				if(rand.nextDouble() * Math.abs(rx) > rand.nextDouble() * Math.abs(rz)) {
					xo = (int)Math.signum(rx);
				} else {
					zo = (int)Math.signum(rz);
				}
			}
			if(Math.abs(xo) == Math.abs(zo) && xo != 0) {
				remainingBlocks -= 0.414D; //sqrt(2)-1
			}
			branch = branch.add(xo, heightFunction.apply(i, remainingBlocks), zo);

			branchBlocks.add(branch);
		}

		return branchBlocks;
	}

private void generateBranchLeaves(World world, Random rand, BlockPos start, List<BlockPos> branchBlocks, int trunkX, int trunkY, int trunkZ) {
		for(BlockPos branchBlock : branchBlocks) {
			int dist = (int) branchBlock.getDistance(start.getX(), start.getY(), start.getZ());
			if(dist >= 1) {
				for(EnumFacing side : LEAVES_OFFSETS) {
					int leavesLength = 3 + (rand.nextInt(5) == 0 ? rand.nextInt(dist + 1) : rand.nextInt(dist / 2 + 1));
					for(int yo = 0; yo > -leavesLength; yo--) {
						BlockPos leafPos = branchBlock.offset(side).add(0, yo, 0);
						IBlockState state;
						if(yo == 0) {
							state = this.leavesTop;
						} else {
							state = this.leavesMiddle;
						}
						if(world.isAirBlock(leafPos)) {
							if(yo == -leavesLength + 1 || (yo < -1 && !world.isAirBlock(leafPos.down()))) {
								state = this.leavesBottom;
								this.setBlock(world, leafPos, state, true, trunkX, trunkY, trunkZ);
								break;
							} else {
								this.setBlock(world, leafPos, state, true, trunkX, trunkY, trunkZ);
							}
						} else {
							break;
						}
					}
				}
			}
		}
	}

