private boolean isBlockSupported(Block block) {
		return block == BlockRegistry.BETWEENSTONE;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		if (world.isAirBlock(pos) && isBlockSupported(world.getBlockState(pos.up()).getBlock())) {
			int height = 1;
			while (world.isAirBlock(pos.add(0, -height, 0))) {
				height++;
			}
			if (height < 3) {
				return false;
			}
			boolean hasStalagmite = isBlockSupported(world.getBlockState(pos.add(0, -height, 0)).getBlock());
			int length = rand.nextInt(height < 11 ? height / 2 : 5) + 1;
			boolean isColumn = length == height / 2;
			for (int dy = 0; dy < length; dy++) {
				this.setBlockAndNotifyAdequately(world, pos.add(0, -dy, 0), speleothem);
				if (hasStalagmite && (isColumn || dy < length - 1)) {
					this.setBlockAndNotifyAdequately(world, pos.add(0, -height + dy + 1, 0), speleothem);
				}
			}
			return true;
		}
		return false;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		boolean generated = false;

		for (IBlockState iblockstate = world.getBlockState(position); (iblockstate.getBlock().isAir(iblockstate, world, position) || iblockstate.getBlock().isLeaves(iblockstate, world, position)) && position.getY() > 0; iblockstate = world.getBlockState(position)) {
			position = position.down();
		}

		for (int i = 0; i < 128; ++i) {
			BlockPos pos = position.add(rand.nextInt(10) - rand.nextInt(10), rand.nextInt(8) - rand.nextInt(8), rand.nextInt(10) - rand.nextInt(10));

			if(SurfaceType.WATER.matches(world, pos.up()) && SurfaceType.DIRT.matches(world, pos)) {
				if(this.generateSwampKelpStack(world, rand, pos.up()))
					generated = true;
			}
		}

		return generated;
	}

private boolean generateSwampKelpStack(World world, Random rand, BlockPos pos) {
		int height = 0;
		MutableBlockPos checkPos = new MutableBlockPos();
		for(int yo = 0; yo < 128; yo++) {
			checkPos.setPos(pos.getX(), pos.getY() + yo, pos.getZ());
			if(!SurfaceType.WATER.matches(world, checkPos)) {
				height = yo;
				break;
			}
		}
		if(height < 2)
			return false;
		height = Math.min(height, 7);
		height = rand.nextInt(height) + 1;
		for(int yo = 0; yo < height; yo++) {
			BlockPos offsetPos = pos.add(0, yo, 0);
			IBlockState state = world.getBlockState(offsetPos);
			if(SurfaceType.WATER.matches(state)) {
				world.setBlockState(offsetPos, BlockRegistry.SWAMP_KELP.getDefaultState(), 2 | 16);
				//this.setBlockAndNotifyAdequately(world, offsetPos, BlockRegistry.SWAMP_KELP.getDefaultState());
			}
		}
		return true;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		boolean generated = false;

		for (IBlockState iblockstate = world.getBlockState(position); (iblockstate.getBlock().isAir(iblockstate, world, position) || iblockstate.getBlock().isLeaves(iblockstate, world, position)) && position.getY() > 0; iblockstate = world.getBlockState(position)) {
			position = position.down();
		}

		for (int i = 0; i < 128; ++i) {
			BlockPos pos = position.add(rand.nextInt(10) - rand.nextInt(10), rand.nextInt(8) - rand.nextInt(8), rand.nextInt(10) - rand.nextInt(10));

			if (world.isBlockLoaded(pos)) {
				if (SurfaceType.WATER.matches(world, pos.up()) && world.getBlockState(pos).getBlock() == BlockRegistry.MUD && world.isAirBlock(pos.up(2))) {
					this.generateReedStack(world, rand, pos.up());
					generated = true;
				} else if (SurfaceType.MIXED_GROUND.matches(world, pos) && BlockRegistry.SWAMP_REED.canPlaceBlockAt(world, pos.up())) {
					this.generateReedStack(world, rand, pos.up());
					generated = true;
				}
			}
		}

		return generated;
	}

private void generateReedStack(World world, Random rand, BlockPos pos) {
		int height = world.rand.nextInt(4) + 2;
		for(int yo = 0; yo < height; yo++) {
			BlockPos offsetPos = pos.add(0, yo, 0);
			IBlockState state = world.getBlockState(offsetPos);
			if(state.getBlock() != Blocks.AIR && !SurfaceType.WATER.matches(state)) {
				break;
			}
			if(SurfaceType.WATER.matches(state)) {
				world.setBlockState(offsetPos, BlockRegistry.SWAMP_REED_UNDERWATER.getDefaultState(), 2 | 16);
			} else {
				world.setBlockState(offsetPos, BlockRegistry.SWAMP_REED.getDefaultState(), 2 | 16);
			}
		}
	}

