			if(SurfaceType.WATER.matches(world, pos.up()) && SurfaceType.MIXED_GROUND.matches(world, pos)) {
				if(this.generateWaterRootsStack(world, rand, pos.up()))
					generated = true;
			}
		}

		return generated;
