			if (level == 7)
				buildRoof(world, pos.add(0, yy - 3, 0).up(8), rand, 7, 7, level);

			if (level < 7 && level >= 0)
				generateMaze(world, rand, pos.add(0, yy, 0), level);

			if (level <= 7) {
				// create STAIRS
				if (level == 1 || level == 3 || level == 5|| level == 7) {
