		this.size = 1.0D;
	}

public WorldGenSpawner setMinY(int minY) {
		this.minY = minY;
		return this;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		BlockPos center = position;

		position = position.add(-8, 0, -8);

		if (position.getY() <= 4 + this.minY) {
			return false;
		} else {
			position = position.down(4);

			for (int xx = 0; xx < 16; ++xx)
				for (int zz = 0; zz < 16; ++zz)
					for (int yy = 0; yy < 8; ++yy) {
						BlockPos pos = position.add(xx, yy, zz);
						if (!world.isBlockLoaded(pos) || this.blackListedBlocks.contains(world.getBlockState(pos).getBlock()))
							return false;
					}

			boolean canGenerateNearCave = rand.nextInt(8) == 0;

			boolean[] isInBlob = new boolean[4096];
			int blobs = rand.nextInt(32) + 16;

			for (int blob = 0; blob < blobs; ++blob) {
				double sx = (rand.nextDouble() * 6.0D + 3.0D) * this.size;
				double sy = (rand.nextDouble() * 6.0D + 3.0D + (rand.nextInt(12) == 0 ? 8 : 0)) * this.size;
				double sz = (rand.nextDouble() * 6.0D + 3.0D) * this.size;
				double bx = rand.nextDouble() * (16.0D - sx - 2.0D) + 1.0D + sx / 2.0D;
				double by = rand.nextDouble() * (8.0D - sy - 4.0D) + 2.0D + sy / 2.0D;
				double bz = rand.nextDouble() * (16.0D - sz - 2.0D) + 1.0D + sz / 2.0D;

				for (int ox = 1; ox < 15; ++ox) {
					for (int oz = 1; oz < 15; ++oz) {
						for (int oy = 1; oy < 15; ++oy) {
							double dx = ((double)ox - bx) / (sx / 2.0D);
							double dy = ((double)oy - by) / (sy / 2.0D);
							double dz = ((double)oz - bz) / (sz / 2.0D);
							double dst = dx * dx + dy * dy + dz * dz;

							if (dst < 1.0D) {
								isInBlob[(ox * 16 + oz) * 16 + oy] = true;
							}
						}
					}
				}
			}

			for (int ox = 0; ox < 16; ++ox) {
				for (int oz = 0; oz < 16; ++oz) {
					for (int oy = 0; oy < 16; ++oy) {
						boolean isOuterBlock = !isInBlob[(ox * 16 + oz) * 16 + oy] && (ox < 15 && isInBlob[((ox + 1) * 16 + oz) * 16 + oy] || ox > 0 && isInBlob[((ox - 1) * 16 + oz) * 16 + oy] || oz < 15 && isInBlob[(ox * 16 + oz + 1) * 16 + oy] || oz > 0 && isInBlob[(ox * 16 + (oz - 1)) * 16 + oy] || oy < 15 && isInBlob[(ox * 16 + oz) * 16 + oy + 1] || oy > 0 && isInBlob[(ox * 16 + oz) * 16 + (oy - 1)]);

						if (isOuterBlock) {
							Material material = world.getBlockState(position.add(ox, oy, oz)).getMaterial();

							if((oy < 4 || !canGenerateNearCave) && material == Material.AIR) {
								return false;
							} else if(material.isLiquid()) {
								return false;
							}
						}
					}
				}
			}

			for (int ox = 0; ox < 16; ++ox) {
				for (int oz = 0; oz < 16; ++oz) {
					for (int oy = 15; oy >= 0; --oy) {
						if(isInBlob[(ox * 16 + oz) * 16 + oy]) {
							this.setBlockAndNotifyAdequately(world, position.add(ox, oy, oz), Blocks.AIR.getDefaultState());
						}
					}
				}
			}

			for (int ox = 0; ox < 16; ++ox) {
				for (int oz = 0; oz < 16; ++oz) {
					for (int oy = 15; oy >= 0; --oy) {
						boolean isOuterBlock = !isInBlob[(ox * 16 + oz) * 16 + oy] && (ox < 15 && isInBlob[((ox + 1) * 16 + oz) * 16 + oy] || ox > 0 && isInBlob[((ox - 1) * 16 + oz) * 16 + oy] || oz < 15 && isInBlob[(ox * 16 + oz + 1) * 16 + oy] || oz > 0 && isInBlob[(ox * 16 + (oz - 1)) * 16 + oy] || oy < 15 && isInBlob[(ox * 16 + oz) * 16 + oy + 1] || oy > 0 && isInBlob[(ox * 16 + oz) * 16 + (oy - 1)]);

						BlockPos pos = position.add(ox, oy, oz);

						if(isOuterBlock) {
							if(oy < 2) {
								if(world.getBlockState(pos.up()).isFullCube()) {
									this.setBlockAndNotifyAdequately(world, pos, BlockRegistry.SWAMP_DIRT.getDefaultState());	
								} else {
									this.setBlockAndNotifyAdequately(world, pos, BlockRegistry.SWAMP_GRASS.getDefaultState());	
								}
							} else {
								if(world.getBlockState(pos).isFullCube()) {
									world.setBlockState(pos, BlockRegistry.BETWEENSTONE.getDefaultState());
								}
							}
						}
					}
				}
			}

			BlockPos spawnerPos = center.add(0, -1, 0);
			this.setBlockAndNotifyAdequately(world, spawnerPos, BlockRegistry.MOB_SPAWNER.getDefaultState());
			BlockMobSpawnerBetweenlands.setRandomMob(world, spawnerPos, rand);
			MobSpawnerLogicBetweenlands logic = BlockMobSpawnerBetweenlands.getLogic(world, spawnerPos);
			if(logic != null) {
				logic.setSpawnRange(6);
				logic.setCheckRange(16);
				logic.setSpawnInAir(false);
			}

			boolean bigMushroom = false;
			for(int i = 0; i < 40; i++) {
				BlockPos pos = center.add(rand.nextInt(8) - 4, rand.nextInt(8) - 4, rand.nextInt(8) - 4);
				if(world.getBlockState(pos.down()).getBlock() == BlockRegistry.SWAMP_GRASS) {
					bigMushroom |= DecorationHelper.GEN_BIG_BULB_CAPPED_MUSHROOM.generate(world, rand, pos);
				}
			}

			if(!bigMushroom) {
				for(int i = 0; i < 8; i++) {
					BlockPos pos = center.add(rand.nextInt(8) - 4, rand.nextInt(8) - 4, rand.nextInt(8) - 4);
					if(BlockRegistry.BULB_CAPPED_MUSHROOM.canPlaceBlockAt(world, pos)) {
						this.setBlockAndNotifyAdequately(world, pos, BlockRegistry.BULB_CAPPED_MUSHROOM.getDefaultState());
					}
				}
			}

			this.positionProvider.init(world, world.getBiomeForCoordsBody(center), null, rand, center.getX(), center.getY(), center.getZ());

			this.positionProvider.setOffsetY(-6, 3);
			this.positionProvider.setOffsetXZ(-8, 8);

			for(int i = 0; i < 80; i++) {
				DecorationHelper.generateWeepingBlue(this.positionProvider);
			}

			for(int i = 0; i < 260; i++) {
				DecorationHelper.generateSwampDoubleTallgrass(this.positionProvider);
			}

			for(int i = 0; i < 16; i++) {
				DecorationHelper.GEN_SWAMP_TALLGRASS.generate(world, rand, center.add(rand.nextInt(8) - 4, rand.nextInt(8) - 4, rand.nextInt(8) - 4));
			}

			this.positionProvider.setOffsetY(0, 8);
			this.positionProvider.setOffsetXZ(-3, 3);

			for(int i = 0; i < 80; i++) {
				DecorationHelper.generateSpeleothemCluster(this.positionProvider);
			}

			BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);
			LocationStorage location = new LocationStorage(worldStorage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(position), "underground_dungeon", EnumLocationType.DUNGEON);
			location.addBounds(new AxisAlignedBB(center).grow(6, 4, 6));
			location.setLayer(0);
			location.setSeed(rand.nextLong());
			location.setVisible(false);
			location.setDirty(true);
			worldStorage.getLocalStorageHandler().addLocalStorage(location);

			return true;
		}
	}

@Override
	public boolean generate(World world, Random random, BlockPos position) {
		return generateStructure1(world, random, position);
	}

public boolean generateStructure1(World world, Random random, BlockPos pos) {
		MutableBlockPos checkPos = new MutableBlockPos();

		int x = pos.getX();
		int y = pos.getY();
		int z = pos.getZ();

		int surfaceBlocks = 0;
		for (int xx = x; xx < x + 5; xx++) {
			for (int zz = z; zz < z + 5; zz++) {
				for (int yy = y; yy < y + 5; yy++) {
					if(yy == y && SurfaceType.MIXED_GROUND.matches(world.getBlockState(checkPos.setPos(xx, y - 1, zz))))
						surfaceBlocks++;
					if (!world.isAirBlock(checkPos.setPos(xx, yy, zz)) && !world.getBlockState(checkPos.setPos(xx, yy, zz)).getBlock().isReplaceable(world, checkPos.setPos(xx, yy, zz)))
						return false;
				}
				for (int yy = y; yy >= y - 5; yy--) {
					if(!world.isAirBlock(checkPos.setPos(xx, yy, zz)) && !world.getBlockState(checkPos.setPos(xx, yy, zz)).getBlock().isReplaceable(world, checkPos.setPos(xx, yy, zz)))
						break;
					if(yy <= y - 5)
						return false;
				}
			}
		}
		if(surfaceBlocks < 8)
			return false;

		for (int xx = x; xx < x + 5; xx++) {
			for (int zz = z; zz < z + 5; zz++) {
				for (int yy = y; yy >= y - 5; yy--) {
					if(!world.isAirBlock(checkPos.setPos(xx, yy, zz)) && !world.getBlockState(checkPos.setPos(xx, yy, zz)).getBlock().isReplaceable(world, checkPos.setPos(xx, yy, zz)))
						break;
					world.setBlockState(new BlockPos(xx, yy, zz), BlockRegistry.BETWEENSTONE_BRICKS.getDefaultState(), 2);
				}
			}
		}

		for (int yy = y; yy < y + 5; yy++) {
			if (yy == y) {
				world.setBlockState(new BlockPos(x, yy, z), BlockRegistry.BETWEENSTONE_BRICKS.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x + 4, yy, z), BlockRegistry.BETWEENSTONE_BRICKS.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x + 4, yy, z + 4), BlockRegistry.BETWEENSTONE_BRICKS.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x, yy, z + 4), BlockRegistry.BETWEENSTONE_BRICKS.getDefaultState(), 2);
				for (int xx = x + 1; xx < x + 4; xx++) {
					world.setBlockState(new BlockPos(xx, yy, z), BlockRegistry.BETWEENSTONE_BRICK_STAIRS.getDefaultState().withProperty(BlockStairsBetweenlands.FACING, EnumFacing.SOUTH), 2);
					world.setBlockState(new BlockPos(xx, yy, z + 4), BlockRegistry.BETWEENSTONE_BRICK_STAIRS.getDefaultState().withProperty(BlockStairsBetweenlands.FACING, EnumFacing.NORTH), 2);
				}
				for (int zz = z + 1; zz < z + 4; zz++) {
					world.setBlockState(new BlockPos(x, yy, zz), BlockRegistry.BETWEENSTONE_BRICK_STAIRS.getDefaultState().withProperty(BlockStairsBetweenlands.FACING, EnumFacing.EAST), 2);
					world.setBlockState(new BlockPos(x + 1, yy, zz), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
					if (zz != z + 2)
						world.setBlockState(new BlockPos(x + 2, yy, zz), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
					else {
						world.setBlockState(new BlockPos(x + 2, yy, zz), BlockRegistry.BETWEENSTONE_CHISELED.getDefaultState(), 2);
						world.setBlockState(new BlockPos(x + 2, yy + 2, zz), BlockRegistry.MOB_SPAWNER.getDefaultState(), 2);
						MobSpawnerLogicBetweenlands logic = BlockMobSpawnerBetweenlands.setRandomMob(world, new BlockPos(x + 2, yy + 2, zz), random);
						if(logic != null) {
							logic.setSpawnInAir(false);
						}
					}
					world.setBlockState(new BlockPos(x + 3, yy, zz), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
					world.setBlockState(new BlockPos(x + 4, yy, zz), BlockRegistry.BETWEENSTONE_BRICK_STAIRS.getDefaultState().withProperty(BlockStairsBetweenlands.FACING, EnumFacing.WEST), 2);
				}
				int randomInt = random.nextInt(4);
				TileEntity tile;
				switch (randomInt) {
				case 0:
					world.setBlockState(new BlockPos(x + 1, yy + 1, z + 1), BlockRegistry.WEEDWOOD_CHEST.getDefaultState(), 2);
					tile = world.getTileEntity(new BlockPos(x + 1, yy + 1, z + 1));
					if (tile instanceof TileEntityChest) {
						((TileEntityChest) tile).setLootTable(LootTableRegistry.SPAWNER_CHEST, random.nextLong());
					}
					break;
				case 1:
					world.setBlockState(new BlockPos(x + 1, yy + 1, z + 3), BlockRegistry.WEEDWOOD_CHEST.getDefaultState(), 2);
					tile = world.getTileEntity(new BlockPos(x + 1, yy + 1, z + 3));
					if (tile instanceof TileEntityChest) {
						((TileEntityChest) tile).setLootTable(LootTableRegistry.SPAWNER_CHEST, random.nextLong());
					}
					break;
				case 2:
					world.setBlockState(new BlockPos(x + 3, yy + 1, z + 1), BlockRegistry.WEEDWOOD_CHEST.getDefaultState(), 2);
					tile = world.getTileEntity(new BlockPos(x + 3, yy + 1, z + 1));
					if (tile instanceof TileEntityChest) {
						((TileEntityChest) tile).setLootTable(LootTableRegistry.SPAWNER_CHEST, random.nextLong());
					}
					break;
				case 3:
					world.setBlockState(new BlockPos(x + 3, yy + 1, z + 3), BlockRegistry.WEEDWOOD_CHEST.getDefaultState(), 2);
					tile = world.getTileEntity(new BlockPos(x + 3, yy + 1, z + 3));
					if (tile instanceof TileEntityChest) {
						((TileEntityChest) tile).setLootTable(LootTableRegistry.SPAWNER_CHEST, random.nextLong());
					}
					break;
				}
			} else if (yy < y + 4) {
				world.setBlockState(new BlockPos(x, yy, z), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x + 4, yy, z), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x + 4, yy, z + 4), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x, yy, z + 4), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
			} else {
				world.setBlockState(new BlockPos(x, yy, z), BlockRegistry.BETWEENSTONE_BRICK_SLAB.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x + 4, yy, z), BlockRegistry.BETWEENSTONE_BRICK_SLAB.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x + 4, yy, z + 4), BlockRegistry.BETWEENSTONE_BRICK_SLAB.getDefaultState(), 2);
				world.setBlockState(new BlockPos(x, yy, z + 4), BlockRegistry.BETWEENSTONE_BRICK_SLAB.getDefaultState(), 2);
				for (int xx = x + 1; xx < x + 4; xx++) {
					world.setBlockState(new BlockPos(xx, yy, z), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
					world.setBlockState(new BlockPos(xx, yy, z + 4), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
				}
				for (int zz = z + 1; zz < z + 4; zz++) {
					world.setBlockState(new BlockPos(x, yy, zz), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
					world.setBlockState(new BlockPos(x + 4, yy, zz), BlockRegistry.BETWEENSTONE_TILES.getDefaultState(), 2);
				}
			}
		}

		BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);
		LocationStorage location = new LocationStorage(worldStorage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(x, z), "small_dungeon", EnumLocationType.DUNGEON);
		location.setVisible(true);
		location.addBounds(new AxisAlignedBB(x, y, z, x + 5, y + 5, z + 5).grow(2, 2, 2));
		location.setLayer(0);
		location.setSeed(random.nextLong());
		location.setDirty(true);
		worldStorage.getLocalStorageHandler().addLocalStorage(location);

		return true;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		byte height = 10;
		int halfSize = 7;

		int x = pos.getX();
		int y = pos.getY();
		int z = pos.getZ();

		if (!world.isAreaLoaded(pos, halfSize + 1))
			return false;

		if (y + height + 1 >= WorldProviderBetweenlands.LAYER_HEIGHT - height || y - 1 <= WorldProviderBetweenlands.CAVE_WATER_HEIGHT + height)
			return false;

		for (int xx = x - halfSize - 1; xx <= x + halfSize + 1; ++xx)
			for (int yy = y - 1; yy <= y + height + 1; ++yy)
				for (int zz = z - halfSize - 1; zz <= z + halfSize + 1; ++zz) {
					Material mat = world.getBlockState(this.getCheckPos(xx, yy, zz)).getMaterial();
					if ((yy == y - 1 || yy == y + height + 1) && !mat.isSolid())
						return false;
				}

		for (int x1 = x - halfSize; x1 <= x + halfSize; x1++)
			for (int z1 = z - halfSize; z1 <= z + halfSize; z1++)
				for (int y1 = y; y1 < y + height; y1++) {
					double dSq = Math.pow(x1 - x, 2.0D) + Math.pow(z1 - z, 2.0D) + Math.pow(y1 - y, 2.0D);
					if (Math.round(Math.sqrt(dSq)) <= halfSize && y1 >= y + 3)
						world.setBlockToAir(new BlockPos(x1, y1, z1));
				}

		for (int yy = y + 2; yy >= y; --yy) {
			for (int xx = halfSize * -1; xx <= halfSize; ++xx) {
				for (int zz = halfSize * -1; zz <= halfSize; ++zz) {
					double dSq = xx * xx + zz * zz;
					if (Math.round(Math.sqrt(dSq)) == halfSize - 2 && yy >= y + 1) {
						world.setBlockState(new BlockPos(x + xx, yy, z + zz), BlockRegistry.BETWEENSTONE_TILES.getDefaultState());
						if (rand.nextBoolean() && yy == y + 2)
							if ((xx % 4 == 0 || zz % 4 == 0 || xx % 3 == 0 || zz % 3 == 0 ) && world.getBlockState(this.getCheckPos(x + xx,  y + 6, z + zz)).getBlock() == BlockRegistry.BETWEENSTONE)
								placePillar(world, x + xx, y + 3, z + zz, rand);
					}
					if (Math.round(Math.sqrt(dSq)) <= halfSize && Math.round(Math.sqrt(dSq)) >= halfSize -1 && yy <= y + 2)
						world.setBlockState(new BlockPos(x + xx, yy, z + zz), BlockRegistry.BETWEENSTONE.getDefaultState());
					if (Math.round(Math.sqrt(dSq)) < halfSize - 2 && yy >= y + 1)
						world.setBlockState(new BlockPos(x + xx, yy, z + zz), BlockRegistry.TAR.getDefaultState());
					if (Math.round(Math.sqrt(dSq)) < halfSize - 2 && yy == y) {
						if (rand.nextBoolean() && rand.nextBoolean())
							world.setBlockState(new BlockPos(x + xx, yy, z + zz), BlockRegistry.TAR_SOLID.getDefaultState());
						else
							world.setBlockState(new BlockPos(x + xx, yy, z + zz), BlockRegistry.BETWEENSTONE.getDefaultState());
						if (rand.nextInt(18) == 0) {
							world.setBlockState(new BlockPos(x + xx, yy, z + zz), getRandomTarLootPot(rand).withProperty(BlockLootPot.FACING, EnumFacing.HORIZONTALS[rand.nextInt(4)]));
							TileEntity te = world.getTileEntity(this.getCheckPos(x + xx, yy, z + zz));
							if(te instanceof TileEntityLootPot) {
								((TileEntityLootPot)te).setLootTable(LootTableRegistry.TAR_POOL_POT, rand.nextLong());
							}
						}
					}
				}
			}
		}

		world.setBlockState(new BlockPos(x + rand.nextInt(halfSize - 2) - rand.nextInt(halfSize - 2), y, z + rand.nextInt(halfSize - 2) - rand.nextInt(halfSize - 2)), BlockRegistry.TAR_BEAST_SPAWNER.getDefaultState());

		BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);
		LocationStorage location = new LocationStorage(worldStorage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(pos), "tar_pool_dungeon", EnumLocationType.DUNGEON);
		location.setVisible(true);
		location.addBounds(new AxisAlignedBB(x - halfSize, y - 1, z - halfSize, x + halfSize, y + height, z + halfSize).grow(1, 1, 1));
		location.setLayer(0);
		location.setSeed(rand.nextLong());
		location.setVisible(true);
		location.setDirty(true);
		worldStorage.getLocalStorageHandler().addLocalStorage(location);

		return true;
	}

private void placePillar(World world, int x, int y, int z, Random rand) {
		int randHeight = rand.nextInt(3);
		for (int yy = y; randHeight + y >= yy; ++yy)
			world.setBlockState(new BlockPos(x, yy, z), BlockRegistry.BETWEENSTONE_BRICK_WALL.getDefaultState());
	}

private IBlockState getRandomTarLootPot(Random rand) {
		switch(rand.nextInt(3)) {
		default:
		case 0: return BlockRegistry.TAR_LOOT_POT.getDefaultState().withProperty(BlockLootPot.VARIANT, EnumLootPot.POT_1);
		case 1: return BlockRegistry.TAR_LOOT_POT.getDefaultState().withProperty(BlockLootPot.VARIANT, EnumLootPot.POT_2);
		case 2: return BlockRegistry.TAR_LOOT_POT.getDefaultState().withProperty(BlockLootPot.VARIANT, EnumLootPot.POT_3);
		}
	}

