private boolean structure6(World world, Random random, int x, int y, int z, LocationStorage location) {
		width = 7;
		depth = 7;
		int direction = random.nextInt(4);
		if (rotatedCubeCantReplace(world, x, y, z, 0, 0, 0, 3, 2, 1, direction)
				|| rotatedCubeCantReplace(world, x, y, z, 1, 0, 0, 1, 1, 1, direction)
				|| rotatedCubeCantReplace(world, x, y, z, 6, 0, 3, 1, 2, 3, direction)
				|| rotatedCubeCantReplace(world, x, y, z, 2, 0, 6, 4, 3, 1, direction))
			return false;
		if (!makePitstoneSupport(world, x, y, z, 0, -1, 0, width, depth, direction, true))
			return false;

		location.addBounds(this.rotatedAABB(world, x, y, z, 0, 0, 0, 3, 2, 1, direction).grow(3, 2, 3));
		location.addBounds(this.rotatedAABB(world, x, y, z, 1, 0, 0, 1, 1, 1, direction).grow(3, 2, 3));
		location.addBounds(this.rotatedAABB(world, x, y, z, 6, 0, 3, 1, 2, 3, direction).grow(3, 2, 3));
		location.addBounds(this.rotatedAABB(world, x, y, z, 2, 0, 6, 4, 3, 1, direction).grow(3, 2, 3));

		makePitstoneSupport(world, x, y, z, 0, -1, 0, width, depth, direction, false);

		rotatedCubeVolume(world, x, y, z, 0, 0, 0, PITSTONE_BRICKS, 1, 1, 3, direction);
		rotatedCubeVolume(world, x, y, z, 1, 0, 0, PITSTONE_BRICKS, 1, 1, 1, direction);
		rotatedCubeVolume(world, x, y, z, 6, 0, 3, PITSTONE_BRICKS, 1, 1, 4, direction);
		rotatedCubeVolume(world, x, y, z, 2, 0, 6, PITSTONE_BRICKS, 4, 1, 1, direction);

		rotatedCubeVolume(world, x, y, z, 0, 1, 0, PITSTONE_BRICKS, 1, 1, 2, direction);
		rotatedCubeVolume(world, x, y, z, 6, 1, 4, PITSTONE_BRICKS, 1, 1, 4, direction);
		rotatedCubeVolume(world, x, y, z, 3, 1, 6, PITSTONE_BRICKS, 3, 1, 1, direction);

		rotatedCubeVolume(world, x, y, z, 5, 2, 6, PITSTONE_BRICKS, 2, 1, 1, direction);

		rotatedLootPot(world, random, x, y, z, 5, 0, 5, direction, 1, 2, 3, LootTableRegistry.UNDERGROUND_RUINS_POT);
		rotatedLootPot(world, random, x, y, z, 1, 0, 1, direction, 1, 2, 3, LootTableRegistry.UNDERGROUND_RUINS_POT);
		return true;
	}

private boolean makePitstoneSupport(World world, int x, int y, int z, int offsetX, int offsetY, int offsetZ, int sizeWidth, int sizeDepth, int direction, boolean simulate) {
		x -= width / 2;
		z -= depth / 2;
		switch (direction) {
		case 0:
			if (world.isAreaLoaded(new BlockPos(x + offsetX, y, z + offsetZ), new BlockPos(x + offsetX + sizeWidth, y + offsetZ, z + offsetZ + sizeWidth))) {
				for (int xx = x + offsetX; xx < x + offsetX + sizeWidth; xx++)
					for (int zz = z + offsetZ; zz < z + offsetZ + sizeDepth; zz++) {
						int yy = y + offsetY;
						int times = 0;
						while (world.getBlockState(this.getCheckPos(xx, yy, zz)).getBlock().isReplaceable(world, this.getCheckPos(xx, yy, zz))) {
							if (!simulate)
								world.setBlockState(new BlockPos(xx, yy, zz), BlockRegistry.PITSTONE.getDefaultState(), 2 | 16);
							yy--;
							times++;
							if (times > 4) {
								if (simulate) {
									return false;
								} else {
									break;
								}
							}
						}
					}
			} else
				return false;
			break;
		case 1:
			if (world.isAreaLoaded(new BlockPos(x + offsetZ, y, z + depth - offsetX - sizeWidth - 1), new BlockPos(x + offsetZ + sizeDepth, y + offsetZ, z + depth - offsetX - 1))) {
				for (int zz = z + depth - offsetX - 1; zz > z + depth - offsetX - sizeWidth - 1; zz--)
					for (int xx = x + offsetZ; xx < x + offsetZ + sizeDepth; xx++) {
						int yy = y + offsetY;
						int times = 0;
						while (world.getBlockState(this.getCheckPos(xx, yy, zz)).getBlock().isReplaceable(world, this.getCheckPos(xx, yy, zz))) {
							if (!simulate)
								world.setBlockState(new BlockPos(xx, yy, zz), BlockRegistry.PITSTONE.getDefaultState(), 2 | 16);
							yy--;
							times++;
							if (times > 4) {
								if (simulate) {
									return false;
								} else {
									break;
								}
							}
						}
					}
			} else
				return false;
			break;
		case 2:
			if (world.isAreaLoaded(new BlockPos(x - offsetX - sizeWidth - 1, y, z + depth - offsetZ - sizeDepth - 1), new BlockPos(x + width - offsetX - 1, y + offsetZ, z + depth - offsetZ - 1))) {
				for (int xx = x + width - offsetX - 1; xx > x + width - offsetX - sizeWidth - 1; xx--)
					for (int zz = z + depth - offsetZ - 1; zz > z + depth - offsetZ - sizeDepth - 1; zz--) {
						int yy = y + offsetY;
						int times = 0;
						while (world.getBlockState(this.getCheckPos(xx, yy, zz)).getBlock().isReplaceable(world, this.getCheckPos(xx, yy, zz))) {
							if (!simulate)
								world.setBlockState(new BlockPos(xx, yy, zz), BlockRegistry.PITSTONE.getDefaultState(), 2 | 16);
							yy--;
							times++;
							if (times > 4) {
								if (simulate) {
									return false;
								} else {
									break;
								}
							}
						}
					}
			} else
				return false;
			break;
		case 3:
			if (world.isAreaLoaded(new BlockPos(x + width - offsetZ - sizeDepth - 1, y, z + offsetX), new BlockPos(x + width - offsetZ - 1, y + offsetZ, z + offsetX + sizeWidth))) {
				for (int zz = z + offsetX; zz < z + offsetX + sizeWidth; zz++)
					for (int xx = x + width - offsetZ - 1; xx > x + width - offsetZ - sizeDepth - 1; xx--) {
						int yy = y + offsetY;
						int times = 0;
						while (world.getBlockState(this.getCheckPos(xx, yy, zz)).getBlock().isReplaceable(world, this.getCheckPos(xx, yy, zz))) {
							if (!simulate)
								world.setBlockState(new BlockPos(xx, yy, zz), BlockRegistry.PITSTONE.getDefaultState(), 2 | 16);
							yy--;
							times++;
							if (times > 4) {
								if (simulate) {
									return false;
								} else {
									break;
								}
							}
						}
					}
			} else
				return false;
			break;
		}

		return true;
	}

@Override
	public boolean generate(World world, Random random, BlockPos position) {
		boolean shouldStop = true;
		int x = position.getX();
		int y = position.getY();
		int z = position.getZ();
		while (y > WorldProviderBetweenlands.CAVE_WATER_HEIGHT) {
			if (world.getBlockState(this.getCheckPos(x, y - 1, z)).getBlock() == BlockRegistry.PITSTONE && world.isAirBlock(this.getCheckPos(x, y, z))) {
				shouldStop = false;
				break;
			}
			y--;
		}
		if (shouldStop)
			return false;

		BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);
		LocationStorage locationStorage = new LocationStorage(worldStorage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(position), "underground_ruins", EnumLocationType.RUINS);

		boolean generated = false;

		int randomInt = random.nextInt(6);
		switch (randomInt) {
		case 0:
			generated = structure1(world, random, x, y, z, locationStorage);
			break;
		case 1:
			generated = structure2(world, random, x, y, z, locationStorage);
			break;
		case 2:
			generated = structure3(world, random, x, y, z, locationStorage);
			break;
		case 3:
			generated = structure4(world, random, x, y, z, locationStorage);
			break;
		case 4:
			generated = structure5(world, random, x, y, z, locationStorage);
			break;
		case 5:
			generated = structure6(world, random, x, y, z, locationStorage);
			break;
		default:
		}

		if(generated) {
			locationStorage.setVisible(true);
			locationStorage.setSeed(random.nextLong());
			locationStorage.setDirty(true);
			worldStorage.getLocalStorageHandler().addLocalStorage(locationStorage);
			return true;
		}

		return false;
	}

public WorldGenUnderwaterRuins() {
		super();
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);
		LocationStorage locationStorage = new LocationStorage(worldStorage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(position), "underwater_ruins", EnumLocationType.RUINS);

		//Pick a random feature
		boolean generated;
		switch (rand.nextInt(5)) {
			case 1:
				generated = structureArch(world, rand, position);
				break;
			case 2:
				generated = structurePillars(world, rand, position);
				break;
			case 3:
				generated = structureRing(world, rand, position);
				break;
			case 4:
				generated = structureShrine(world, rand, position);
				break;
			case 0:
			default:
				generated = structureShelter(world, rand, position);
				break;
		}

		if (generated) {
			//Decorate some plants
			for (int x = -8; x <= 8; x++) {
				for (int z = -8; z <= 8; z++) {
					if (rand.nextInt(4) == 0) {
						IBlockState plant = UNDERWATER_PLANTS.get(rand.nextInt(UNDERWATER_PLANTS.size()));
						BlockPos pos = position.add(x, 0, z);

						if (plant == BlockRegistry.SWAMP_REED_UNDERWATER.getDefaultState() || plant == BlockRegistry.SWAMP_KELP.getDefaultState()) {
							if (SurfaceType.DIRT.matches(world.getBlockState(pos))) {
								int height = rand.nextInt(6) + 3;
								for (int y = 0; y <= height; y++) {
									BlockPos plantPos = pos.up(y + 1);
									IBlockState state = world.getBlockState(plantPos);
									if(state.getBlock() != Blocks.AIR && !SurfaceType.WATER.matches(state)) {
										break;
									}
									if(SurfaceType.WATER.matches(state) && state.getBlock().isReplaceable(world, plantPos)) {
										world.setBlockState(plantPos, plant, 2 | 16);
									}
								}
							}
						} else {
							//We assume that other plants do not have a stacking height
							IBlockState state = world.getBlockState(pos.up());
							if (SurfaceType.DIRT.matches(world.getBlockState(pos)) && SurfaceType.WATER.matches(state) && state.getBlock().isReplaceable(world, pos.up())) {
								world.setBlockState(pos.up(), plant, 2 | 16);
							}
						}
					}
				}
			}

			//location storage
			locationStorage.addBounds(new AxisAlignedBB(position.up(4)).grow(8.0D, 4.0D, 8.0D));
			locationStorage.setLayer(0);
			locationStorage.setSeed(world.getSeed());
			locationStorage.setVisible(true);
			locationStorage.setDirty(true);
			worldStorage.getLocalStorageHandler().addLocalStorage(locationStorage);
		}

		return generated;
	}

private boolean structureRing(World world, Random rand, BlockPos position) {
		//NOTE: Ring size is 3, 5, 7. Generate 2-7, ring size 7 has a middle pillar
		int ringsize = MathHelper.clamp(rand.nextInt(6) + 2, 4, 7); // 0, 1, 2, 3, 4, 5 -> 2, 3, 4, 5, 6, 7
		int center = ringsize / 2;
		int pillarheight = ringsize + rand.nextInt(3); // + 0, 1, 2

		if (!checkValidSpace(world, position.getX(), position.getY(), position.getZ(), ringsize, pillarheight + 1, ringsize))
			return false;

		//floor
		for (int fx = -center; fx <= center; fx++) {
			for (int fz = -center; fz <= center; fz++) {
				//floor
				world.setBlockState(position.add(fx, 0, fz), getTileGrade(rand), 2 | 16);

				//put a pot in the middle of the ring
				if (fx > -center + 1 && fx < center - 1) {
					//do not put a pot in the middle, especially for ringsize = 7
					if (fx != 0 && fz != 0) {
						if (rand.nextInt(7) == 0) {
							setLootPot(world, rand, position.add(fx, 1, fz));
						}
					}
				}

				//ring
				if (!(Math.abs(fx) == center && Math.abs(fz) == center)) {
					if (Math.abs(fx) == center || Math.abs(fz) == center) {
						world.setBlockState(position.add(fx, 1, fz), getBrickGrade(rand), 2 | 16);

						//put a pot on the ring
						if (rand.nextInt(5) == 0) {
							setLootPot(world, rand, position.add(fx, 2, fz));
						}
					}
				} else {
					//pillar
					buildPillar(world, rand, position.add(fx, 1, fz), pillarheight);
				}

				//middle pillar
				if (ringsize >= 7 && (fx == 0 && fz == 0)) {
					buildPillar(world, rand, position.add(fx, 1, fz), ringsize);
				}
			}
		}

		return true;
	}

private void buildPillar(World world, Random rand, BlockPos pos, int height) {
		for (int y = 0; y <= height; y++) {
			world.setBlockState(pos.add(0, y, 0), getTileGrade(rand), 2 | 16);
		}
		//put a pot on top
		if (rand.nextInt(4) == 0) {
			setLootPot(world, rand, pos.add(0, height + 1, 0));
		}
	}

private boolean structurePillars(World world, Random rand, BlockPos position) {
		if (!checkValidSpace(world, position.getX(), position.getY(), position.getZ(), 7, 9, 7))
			return false;

		//7x7 grid, 5x5 grid of tiles
		int basepillar = 3; //max height 8

		//floor
		for (int x = -2; x <= 2; x++) {
			for (int z = -2; z <= 2; z++) {
				if (rand.nextInt(3) == 0) {
					world.setBlockState(position.add(x, 0, z), getTileGrade(rand), 2 | 16);
				}
				if (rand.nextInt(8) == 0) {
					setMudLootPot(world, rand, position.add(x, 0, z));
				}
			}
		}
		world.setBlockState(position.add(-1, 0, 0), getBrickGrade(rand), 2 | 16);
		world.setBlockState(position.add(1, 0, 0), getBrickGrade(rand), 2 | 16);
		world.setBlockState(position.add(0, 0, -1), getBrickGrade(rand), 2 | 16);
		world.setBlockState(position.add(0, 0, 1), getBrickGrade(rand), 2 | 16);

		position.add(0, 1, 0);

		//north
		buildPillar2(world, rand, position.add(0, 0, -3), rand.nextInt(6) + basepillar);
		//ne
		buildPillar2(world, rand, position.add(2, 0, -2), rand.nextInt(6) + basepillar);
		//east
		buildPillar2(world, rand, position.add(3, 0, 0), rand.nextInt(6) + basepillar);
		//se
		buildPillar2(world, rand, position.add(2, 0, 2), rand.nextInt(6) + basepillar);
		//south
		buildPillar2(world, rand, position.add(0, 0, 3), rand.nextInt(6) + basepillar);
		//sw
		buildPillar2(world, rand, position.add(-2, 0, 2), rand.nextInt(6) + basepillar);
		//west
		buildPillar2(world, rand, position.add(-3, 0, 0), rand.nextInt(6) + basepillar);
		//nw
		buildPillar2(world, rand, position.add(-2, 0, -2), rand.nextInt(6) + basepillar);

		return true;
	}

private void buildPillar2(World world, Random rand, BlockPos pos, int height) {
		for (int y = 0; y <= height; y++) {
			//if we hit the top, make it chiselled
			world.setBlockState(pos.add(0, y, 0), y == height ? cragrockChisel : getTileGrade(rand), 2 | 16);
		}
		//put a pot on top
		if (rand.nextInt(4) == 0) {
			setLootPot(world, rand, pos.add(0, height + 1, 0));
		}
	}

private boolean structureArch(World world, Random rand, BlockPos pos) {
		if (!checkValidSpace(world, pos.getX(), pos.getY(), pos.getZ(), 7, 7, 7))
			return false;

		boolean north, south, east, west;
		do {
			north = buildArch(world, rand, pos.add(1, 0, 1), EnumFacing.NORTH); //north
			east = buildArch(world, rand, pos.add(1, 0, 0), EnumFacing.EAST); //east
			south = buildArch(world, rand, pos, EnumFacing.SOUTH); //south
			west = buildArch(world, rand, pos.add(0, 0, 1), EnumFacing.WEST); //west
		} while (!north && !south && !east && !west);

		for (int x = -3; x <= 3; x++) {
			for (int z = -3; z <= 3; z++) {
				if (rand.nextInt(9) == 0) {
					world.setBlockState(pos.add(x, 0, z), BlockRegistry.PEARL_BLOCK.getDefaultState(), 2 | 16);
				}
			}
		}

		return true;
	}

private boolean buildArch(World world, Random rand, BlockPos pos, EnumFacing directionIn) {
		if (rand.nextBoolean()) {
			int direction = directionIn.getHorizontalIndex();
			int x = pos.getX();
			int y = pos.getY();
			int z = pos.getZ();

			rotatedCubeVolume(world, x, y, z, 0, 0, -3, getBrickGrade(rand), 1, 4, 1, direction);
			rotatedCubeVolume(world, x, y, z, 0, 4, -3, getStateFromRotation(3, direction, cragrockBrickStairs, EnumRotationSequence.STAIR), 1, 1, 1, direction);
			rotatedCubeVolume(world, x, y, z, 0, 4, -2, getStateFromRotation(1, direction, cragrockBrickStairs, EnumRotationSequence.UPSIDE_DOWN_STAIR), 1, 1, 1, direction);
			rotatedCubeVolume(world, x, y, z, 0, 5, -2, getStateFromRotation(3, direction, cragrockBrickStairs, EnumRotationSequence.STAIR), 1, 1, 1, direction);
			rotatedCubeVolume(world, x, y, z, 0, 5, -1, getStateFromRotation(1, direction, cragrockBrickStairs, EnumRotationSequence.UPSIDE_DOWN_STAIR), 1, 1, 1, direction);

			return true;
		}

		return false;
	}

private boolean structureShelter(World world, Random random, BlockPos pos) {
		int length = (random.nextInt(3) + 7) / 2;
		int width = (random.nextInt(3) + 7) / 2;
		boolean basement = random.nextInt(5) == 0;

		if (!checkValidSpace(world, pos.getX(), pos.getY(), pos.getZ(), length * 2, 5, width * 2))
			return false;

		for (int x = -length; x <= length; x++) {
			for (int z = -width; z <= width; z++) {
				world.setBlockState(pos.add(x, 0, z), getTileGrade(random), 2 | 16);

				//build wall
				if (Math.abs(x) == length || Math.abs(z) == width) {
					int height = random.nextInt(3) + 2;
					for (int y = 0; y <= height; y++) {
						world.setBlockState(pos.add(x, y + 1, z), getBrickGrade(random), 2 | 16);
					}
				}

				//floor pots
				if ((Math.abs(x) != length || Math.abs(z) != width)) {
					if (random.nextInt(10) == 0) {
						setMudLootPot(world, random, pos.add(x, 0, z));
					}
				}

				//basement
				if (basement) {
					for (int y = -1; y >= -3; y--) {

						if (Math.abs(x) == length || Math.abs(z) == width) { //underground wall
							world.setBlockState(pos.add(x, y, z), getBrickGrade(random), 2 | 16);
						} else if (y == -3) { //floor
							world.setBlockState(pos.add(x, y, z), getTileGrade(random), 2 | 16);
						} else { //clear, make it water
							world.setBlockState(pos.add(x, y, z), BlockRegistry.SWAMP_WATER.getDefaultState());
						}

						//pots
						if ((Math.abs(x) != length || Math.abs(z) != width) && y == -2) {
							if (random.nextInt(3) == 0) {
								setLootPot(world, random, pos.add(x, y, z));
							}
						}
					}
				}
			}
		}

		return true;
	}

private boolean structureShrine(World world, Random random, BlockPos pos) {
		int basepillar = 5;

		if (!checkValidSpace(world, pos.getX(), pos.getY(), pos.getZ(), 10, basepillar + 5, 10))
			return false;

		//make floor
		for (int fx = -4; fx <= 4; fx++) {
			for (int fz = -4; fz <= 4; fz++) {
				if (random.nextBoolean()) {
					world.setBlockState(pos.add(fx, 0, fz), getTileGrade(random), 2 | 16);
				}
			}
		}

		//make pillar ring
		//n
		buildPillar3(world, random, pos.add(-2 , 0, -5), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(0, 0, -5), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(2, 0, -5), random.nextInt(4) + basepillar);
		//e
		buildPillar3(world, random, pos.add(-5, 0, -2), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(-5, 0, 0), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(-5, 0, 2), random.nextInt(4) + basepillar);
		//s
		buildPillar3(world, random, pos.add(-2 , 0, 5), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(0, 0, 5), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(2, 0, 5), random.nextInt(4) + basepillar);
		//w
		buildPillar3(world, random, pos.add(5, 0, -2), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(5, 0, 0), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(5, 0, 2), random.nextInt(4) + basepillar);
		//corners
		buildPillar3(world, random, pos.add(-4, 0, -4), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(4, 0, -4), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(-4, 0, 4), random.nextInt(4) + basepillar);
		buildPillar3(world, random, pos.add(4, 0, 4), random.nextInt(4) + basepillar);

		//shrine
		for (int sx = -2; sx <= 2; sx++) {
			for (int sz = -2; sz <= 2; sz++) {
				for (int sy = 1; sy <= 5; sy++) {
					if ((Math.abs(sx) != 2 || Math.abs(sz) != 2) && sy == 1) {
						world.setBlockState(pos.add(sx, sy, sz), getTileGrade(random), 2 | 16);
					}

					if ((Math.abs(sx) == 2 && Math.abs(sz) == 2) && sy <= 3) {
						world.setBlockState(pos.add(sx, sy, sz), getBrickGrade(random), 2 | 16);
					}

					if (!(Math.abs(sx) == 2 && Math.abs(sz) == 2) && sy == 4) {
						if (Math.abs(sx) == 2 || Math.abs(sz) == 2) {
							world.setBlockState(pos.add(sx, sy, sz), getBrickGrade(random), 2 | 16);
						}
					}

					if (((Math.abs(sx) == 2 && Math.abs(sz) == 0) || (Math.abs(sx) == 0 && Math.abs(sz) == 2)) && sy == 5) {
						world.setBlockState(pos.add(sx, sy, sz), getBrickGrade(random), 2 | 16);
					}

					if (sx == 0 && sz == 0 && sy == 2) {
						BlockPos spawnerpos = pos.add(sx, sy, sz);
						world.setBlockState(spawnerpos, BlockRegistry.MOB_SPAWNER.getDefaultState());
						TileEntity te = world.getTileEntity(spawnerpos);
						if (te instanceof TileEntityMobSpawnerBetweenlands) {
							MobSpawnerLogicBetweenlands logic = ((TileEntityMobSpawnerBetweenlands)te).getSpawnerLogic();
							logic.setNextEntityName("thebetweenlands:angler").setCheckRange(32.0D).setSpawnRange(6).setSpawnInAir(false).setMaxEntities(1 + world.rand.nextInt(3));
						}
					}
				}
			}
		}

		return true;
	}

private void buildPillar3(World world, Random rand, BlockPos pos, int height) {
		for (int y = 0; y <= height; y++) {
			world.setBlockState(pos.add(0, y, 0), getBrickGrade(rand), 2 | 16);
		}
		if (rand.nextInt(4) == 0) {
			setLootPot(world, rand, pos.add(0, height + 1, 0));
		}
	}

private boolean checkValidSpace(World world, int posX, int posY, int posZ, int width, int height, int depth) {
		int x = width / 2;
		int z = depth / 2;

		//Check the area for suitable placement.
		BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos();
		for (int mx = posX - x; mx <= posX + x; mx++) {
			for (int mz = posZ - z; mz <= posZ + z; mz++) {
				for (int my = posY; my <= posY + height; my++) {
					mutable.setPos(mx, my, mz);
					if (my <= posY + 1) {
						if (!world.getBlockState(mutable.down()).isFullCube()) {
							return false;
						}
					} else {
						if (!world.isAirBlock(mutable) && !world.getBlockState(mutable).getBlock().isReplaceable(world, mutable)) {
							return false;
						}
					}
				}
			}
		}

		return true;
	}

private IBlockState getBrickGrade(Random rand) {
		switch (rand.nextInt(3)) {
			case 0:
				return cragrockBrick;
			case 1:
				return cragrockBrickCracked;
			case 2:
				return cragrockBrickMossy;
		}
		return cragrockBrick;
	}

private IBlockState getTileGrade(Random rand) {
		switch (rand.nextInt(3)) {
			case 0:
				return cragrockTile;
			case 1:
				return cragrockTileCracked;
			case 2:
				return cragrockTileMossy;
		}
		return cragrockTile;
	}

private void setLootPot(World world, Random random, BlockPos pos) {
		IBlockState loot;
		if (world.getBlockState(pos) == BlockRegistry.SWAMP_WATER.getDefaultState()) {
			if (random.nextInt(4) == 0) {
				loot = BlockRegistry.PEARL_BLOCK.getDefaultState();
			} else {
				loot = this.getRandomMudPot(random);
			}
		} else {
			loot = this.getRandomPot(random);
		}
		this.setBlockAndNotifyAdequately(world, pos, loot);
		TileEntityLootPot lootPot = BlockLootPot.getTileEntity(world, pos);
		if (lootPot != null) {
			lootPot.setLootTable(LootTableRegistry.CAVE_POT, random.nextLong()); //TODO: replace?
		}
	}

private IBlockState getRandomPot(Random rand) {
		switch (rand.nextInt(3)) {
			case 1:
				return BlockRegistry.LOOT_POT.getDefaultState().withProperty(BlockLootPot.VARIANT, BlockLootPot.EnumLootPot.POT_2);
			case 2:
				return BlockRegistry.LOOT_POT.getDefaultState().withProperty(BlockLootPot.VARIANT, BlockLootPot.EnumLootPot.POT_3);
			case 0:
			default:
				return BlockRegistry.LOOT_POT.getDefaultState().withProperty(BlockLootPot.VARIANT, BlockLootPot.EnumLootPot.POT_1);
		}
	}

private void setMudLootPot(World world, Random random, BlockPos pos) {
		this.setBlockAndNotifyAdequately(world, pos, this.getRandomMudPot(random));
		TileEntityLootPot lootPot = BlockLootPot.getTileEntity(world, pos);
		if(lootPot != null) {
			lootPot.setLootTable(LootTableRegistry.UNDERWATER_RUINS_POT, random.nextLong()); //TODO: replace
		}
	}

private IBlockState getRandomMudPot(Random rand) {
		switch (rand.nextInt(3)) {
			case 1:
				return BlockRegistry.MUD_LOOT_POT.getDefaultState().withProperty(BlockMudLootPot.VARIANT, BlockMudLootPot.EnumLootPot.POT_2);
			case 2:
				return BlockRegistry.MUD_LOOT_POT.getDefaultState().withProperty(BlockMudLootPot.VARIANT, BlockMudLootPot.EnumLootPot.POT_3);
			case 0:
			default:
				return BlockRegistry.MUD_LOOT_POT.getDefaultState().withProperty(BlockMudLootPot.VARIANT, BlockMudLootPot.EnumLootPot.POT_1);
		}
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		if(SurfaceType.MIXED_GROUND.matches(world.getBlockState(pos.down()))) {
			IBlockState state1 = world.getBlockState(pos);
			IBlockState state2 = world.getBlockState(pos.up());
			IBlockState state3 = world.getBlockState(pos.up(2));

			if(!state1.getMaterial().isLiquid() && state1.getBlock().isReplaceable(world, pos)
					&& !state2.getMaterial().isLiquid() && state2.getBlock().isReplaceable(world, pos.up())
					&& !state3.getMaterial().isLiquid() && state3.getBlock().isReplaceable(world, pos.up(2))) {

				IBlockState state = BlockRegistry.WAYSTONE.getDefaultState();

				world.setBlockState(pos, state.withProperty(BlockWaystone.PART, BlockWaystone.Part.BOTTOM));
				world.setBlockState(pos.up(2), state.withProperty(BlockWaystone.PART, BlockWaystone.Part.TOP));
				world.setBlockState(pos.up(1), state.withProperty(BlockWaystone.PART, BlockWaystone.Part.MIDDLE));

				BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);
				AxisAlignedBB locationAABB = new AxisAlignedBB(pos.up()).grow(4, 3, 4);
				LocationStorage locationStorage = new LocationStorage(worldStorage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(pos.getX(), pos.getZ()), "waystone", EnumLocationType.WAYSTONE);
				locationStorage.setSeed(rand.nextLong());
				locationStorage.addBounds(locationAABB);
				locationStorage.setVisible(false);
				locationStorage.setDirty(true);
				worldStorage.getLocalStorageHandler().addLocalStorage(locationStorage);
			}
		}
		return false;
	}

@Override
	public void generate(Random random, int chunkX, int chunkZ, World world, IChunkGenerator chunkGenerator, IChunkProvider chunkProvider) {
		if(world.provider.getDimension() == BetweenlandsConfig.WORLD_AND_DIMENSION.dimensionId) {
			int gridSizePower2 = 3;

			int gridBlockSize = 1 << (gridSizePower2 + 4);

			int regionX = chunkX >> gridSizePower2;
			int regionZ = chunkZ >> gridSizePower2;

			long regionSeed = (long)(regionX * 3129871) ^ (long)regionZ * 116129781L ^ world.getSeed();
			regionSeed = regionSeed * regionSeed * 42317861L + regionSeed * 11L;

			Random seededRandom = new Random(regionSeed);

			int blockX = (regionX << (gridSizePower2 + 4)) + gridBlockSize / 4 + seededRandom.nextInt(gridBlockSize / 2 + 1);
			int blockZ = (regionZ << (gridSizePower2 + 4)) + gridBlockSize / 4 + seededRandom.nextInt(gridBlockSize / 2 + 1);

			if(blockX > chunkX * 16 + 5 && blockZ > chunkZ * 16 + 5 && blockX < (chunkX + 2) * 16 - 5 && blockZ < (chunkZ + 2) * 16 - 5) {
				int height = world.getHeight(blockX, blockZ);
				this.generate(world, random, new BlockPos(blockX, height, blockZ));
			}
		}
	}

public WorldGenWeedwoodPortalTree() {
		super(true);
	}

public WorldGenWeedwoodPortalTree(int targetDim) {
		this.targetDimSet = true;
		this.targetDim = targetDim;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		if(pos.getY() > world.getActualHeight() - 20) {
			return false;
		}

		int radius = 4;
		int height = 16;
		int maxRadius = 9;

		int checkHeight = 20;

		this.bark = BlockRegistry.LOG_PORTAL.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.NONE);
		this.wood = BlockRegistry.WEEDWOOD.getDefaultState();
		this.leaves = BlockRegistry.LEAVES_WEEDWOOD_TREE.getDefaultState();

		for (int yy = 1; yy < 1 + checkHeight; yy++) {
			int checkRadius = 6;
			if(yy > 11) {
				checkRadius = 10;
			}
			for (int xx = -checkRadius; xx <= checkRadius; xx++) {
				for (int zz = -checkRadius; zz <= checkRadius; zz++) {
					if(xx*xx + zz*zz <= checkRadius*checkRadius) {
						IBlockState blockState = world.getBlockState(pos.add(xx, yy, zz));
						boolean isReplaceable = blockState.getBlock() == Blocks.AIR || blockState.getMaterial() == Material.LEAVES || blockState.getMaterial() == Material.PLANTS || 
								blockState.getMaterial() == Material.VINE || blockState.getBlock().isReplaceable(world, pos.add(xx, yy, zz));
						if (!isReplaceable) {
							return false;
						}
					}
				}
			}
		}

		createMainCanopy(world, rand, pos.add(0, height/2 + 4, 0), maxRadius);

		for (int yy = 0; yy < height; ++yy) {
			if (yy % 3 == 0 && radius > 1 && yy > 5)
				--radius;

			for (int i = radius * -1; i <= radius; ++i)
				for (int j = radius * -1; j <= radius; ++j) {
					double dSq = i * i + j * j;
					if (Math.round(Math.sqrt(dSq)) < radius && yy <= 1)
						this.setBlockIfValid(world, pos.add(i, yy, j), wood);
					if (Math.round(Math.sqrt(dSq)) == radius && yy == 0 || Math.round(Math.sqrt(dSq)) == radius && yy <= height - 1)
						this.setBlockIfValid(world, pos.add(i, yy, j), bark);
					if (Math.round(Math.sqrt(dSq)) < radius && yy <= height - 1 && yy > 1 && yy <= 10)
						this.setBlockIfValid(world, pos.add(i, yy, j), Blocks.AIR.getDefaultState());
				}

			if(yy == 4) {
				BlockTreePortal.makePortalX(world, pos.add(radius, yy - 2, 0));
				BlockTreePortal.makePortalX(world, pos.add(- radius, yy - 2, 0));
				BlockTreePortal.makePortalZ(world, pos.add(0, yy - 2, radius));
				BlockTreePortal.makePortalZ(world, pos.add(0, yy - 2, - radius));
			}

			if (yy == height/2 + 2) {
				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), 0), 1, false, rand.nextInt(2) + 4);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), 0), 2, false, rand.nextInt(2) + 4);
				createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), radius + 1), 3, false, rand.nextInt(2) + 4);
				createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), - radius - 1), 4, false, rand.nextInt(2) + 4);

				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), radius + 1), 5, false, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), - radius - 1), 6, false, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), radius + 1), 7, false, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), - radius - 1), 8, false, rand.nextInt(2) + 3);
			}

			if (yy == height/2 + 4) {
				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), 0), 1, 4);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), 0), 2, 4);
				createSmallBranch(world, rand, pos.add(0, yy - rand.nextInt(2), radius + 1), 3, 4);
				createSmallBranch(world, rand, pos.add(0, yy - rand.nextInt(2), - radius - 1), 4, 4);

				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), radius + 1), 5, 3);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), - radius - 1), 6, 3);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), radius + 1), 7, 3);
				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), - radius - 1), 8, 3);
			}

			if (yy == height/2 + 7) {
				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), 0), 1, 2);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), 0), 2, 2);
				createSmallBranch(world, rand, pos.add(0, yy - rand.nextInt(3), radius + 1), 3, 2);
				createSmallBranch(world, rand, pos.add(0, yy - rand.nextInt(3), - radius - 1), 4, 2);

				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), radius + 1), 5, 2);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), - radius - 1), 6, 2);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), radius + 1), 7, 2);
				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), - radius - 1), 8, 2);
			}

			if (yy == 0) {
				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), 0), 1, true, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), 0), 2, true, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), radius + 1), 3, true, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), - radius - 1), 4, true, rand.nextInt(2) + 3);

				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), radius + 1), 5, true, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), - radius - 1), 6, true, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), radius + 1), 7, true, rand.nextInt(2) + 3);
				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), - radius - 1), 8, true, rand.nextInt(2) + 3);
			}
		}

		BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);
		LocationPortal location = new LocationPortal(worldStorage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(pos), pos);
		location.addBounds(new AxisAlignedBB(pos).grow(8, 7, 8).offset(0, 7, 0));
		location.setSeed(rand.nextLong());
		if(this.targetDimSet) {
			location.setTargetDimension(this.targetDim);
		}
		location.setDirty(true);
		location.setVisible(false);
		worldStorage.getLocalStorageHandler().addLocalStorage(location);

		return true;
	}

private void createSmallBranch(World world, Random rand, BlockPos pos, int dir, int branchLength) {
		int y = 0;
		for (int i = 0; i <= branchLength; ++i) {

			if (i >= 2)
				y++;

			switch (dir) {
			case 1:
				this.setBlockIfValid(world, pos.east(i).up(y), bark);
				break;

			case 2:
				this.setBlockIfValid(world, pos.west(i).up(y), bark);
				break;

			case 3:
				this.setBlockIfValid(world, pos.south(i).up(y), bark);
				break;

			case 4:
				this.setBlockIfValid(world, pos.north(i).up(y), bark);
				break;

			case 5:
				this.setBlockIfValid(world, pos.east(i).up(y).south(i), bark);
				break;

			case 6:
				this.setBlockIfValid(world, pos.west(i).up(y).north(i), bark);
				break;

			case 7:
				this.setBlockIfValid(world, pos.west(i).up(y).south(i), bark);
				break;

			case 8:
				this.setBlockIfValid(world, pos.east(i).up(y).north(i), bark);
				break;
			}
		}
	}

private void createMainCanopy(World world, Random rand, BlockPos pos, int maxRadius) {
		for (int x1 = - maxRadius; x1 <= maxRadius; x1++)
			for (int z1 = - maxRadius; z1 <= maxRadius; z1++)
				for (int y1 = 0; y1 < maxRadius; y1++) {
					double dSq = Math.pow(x1, 2.0D) + Math.pow(z1, 2.0D) + Math.pow(y1, 2.5D);
					if (Math.round(Math.sqrt(dSq)) <= maxRadius)
						if (world.getBlockState(pos.add(x1, y1, z1)) != bark && rand.nextInt(5) != 0)
							this.setBlockIfValid(world, pos.add(x1, y1, z1), leaves);
					if (Math.round(Math.sqrt(dSq)) < maxRadius - 1 && rand.nextInt(5) == 0 && y1 > 0)
						if (world.getBlockState(pos.add(x1, y1, z1)) != bark)
							this.setBlockIfValid(world, pos.add(x1, y1, z1), bark);
					if (Math.round(Math.sqrt(dSq)) <= maxRadius && rand.nextInt(3) == 0 && y1 == 0)
						if (world.getBlockState(pos.add(x1, y1, z1)) != bark)
							for (int i = 1; i < 1 + rand.nextInt(3); i++)
								this.setBlockIfValid(world, pos.add(x1, y1 - i, z1), leaves);
				}
	}

private void createBranch(World world, Random rand, BlockPos pos, int dir, boolean root, int branchLength) {
		int y = 0;
		for (int i = 0; i <= branchLength; ++i) {

			if (i >= 3)
				y++;

			switch (dir) {
			case 1:
				if (!root)
					this.setBlockIfValid(world, pos.east(i).up(y), bark);
				else {
					this.setBlockIfValid(world, pos.east(i).down(y), bark);
					this.setBlockIfValid(world, pos.east(i).down(y - 1), bark);
				}
				break;

			case 2:
				if (!root)
					this.setBlockIfValid(world, pos.west(i).up(y), bark);
				else {
					this.setBlockIfValid(world, pos.west(i).down(y), bark);
					this.setBlockIfValid(world, pos.west(i).down(y - 1), bark);
				}
				break;

			case 3:
				if (!root)
					this.setBlockIfValid(world, pos.south(i).up(y), bark);
				else {
					this.setBlockIfValid(world, pos.south(i).down(y), bark);
					this.setBlockIfValid(world, pos.south(i).down(y - 1), bark);
				}
				break;

			case 4:
				if (!root)
					this.setBlockIfValid(world, pos.north(i).up(y), bark);
				else {
					this.setBlockIfValid(world, pos.north(i).down(y), bark);
					this.setBlockIfValid(world, pos.north(i).down(y - 1), bark);
				}
				break;

			case 5:
				if (!root)
					this.setBlockIfValid(world, pos.east(i - 1).up(y).south(i - 1),
							bark);
				else {
					this.setBlockIfValid(world, pos.east(i - 1).down(y).south(i - 1), bark);
					this.setBlockIfValid(world, pos.east(i - 1).down(y - 1).south(i - 1), bark);
				}
				break;

			case 6:
				if (!root)
					this.setBlockIfValid(world, pos.west(i - 1).up(y).north(i - 1), bark);
				else {
					this.setBlockIfValid(world, pos.west(i - 1).down(y).north(i - 1), bark);
					this.setBlockIfValid(world, pos.west(i - 1).down(y - 1).north(i - 1), bark);
				}
				break;

			case 7:
				if (!root)
					this.setBlockIfValid(world, pos.west(i - 1).up(y).south(i - 1), bark);
				else {
					this.setBlockIfValid(world, pos.west(i - 1).down(y).south(i - 1), bark);
					this.setBlockIfValid(world, pos.west(i - 1).down(y - 1).south(i - 1), bark);
				}
				break;

			case 8:
				if (!root)
					this.setBlockIfValid(world, pos.east(i - 1).up(y).north(i - 1), bark);
				else {
					this.setBlockIfValid(world, pos.east(i - 1).down(y).north(i - 1), bark);
					this.setBlockIfValid(world, pos.east(i - 1).down(y - 1).north(i - 1), bark);
				}
				break;
			}
		}
	}

