protected int getRadius(int baseRadius, int dy) {
		// https://www.desmos.com/calculator/s8otj3uq6b
		return (STEEPNESS * MIN_TRUNK_RADIUS - baseRadius * STEEPNESS) / (-baseRadius * dy - STEEPNESS + MIN_TRUNK_RADIUS * dy) + MIN_TRUNK_RADIUS;
	}

public static void initTrunkLayers() {
		float slope = 1.5F / (MAX_TRUNK_RADIUS - MIN_TRUNK_RADIUS);
		for (int i = 0; i < TRUNK_LAYERS.length; i++) {
			int radius = i + MIN_TRUNK_RADIUS;
			int size = radius * 2 + 1;
			TRUNK_LAYERS[i] = new byte[size * size];
			for (int x = -radius; x <= radius; x++) {
				for (int z = -radius; z <= radius; z++) {
					float angle = (float) Math.atan2(z, x);
					float dist = MathHelper.sqrt(x * x + z * z) + (i < 3 ? 0 : 0);
					float fold = (MathHelper.sin(angle * 2 * (float) Math.PI * 2) + 1) * (slope * (radius - MIN_TRUNK_RADIUS));
					if (dist <= radius - fold) {
						TRUNK_LAYERS[i][x + radius + (z + radius) * size] = 1;
					}
				}
			}
			for (int x = 0; x < size; x++) {
				for (int z = 0; z < size; z++) {
					int index = x + z * size;
					int state = TRUNK_LAYERS[i][index];
					if (state == 1) {
						if (x > 0) {
							if (TRUNK_LAYERS[i][x - 1 + z * size] == 0) {
								TRUNK_LAYERS[i][index] = 2;
								continue;
							}
						}
						if (z > 0) {
							if (TRUNK_LAYERS[i][x + (z - 1) * size] == 0) {
								TRUNK_LAYERS[i][index] = 2;
								continue;
							}
						}
						if (x < size - 1) {
							if (TRUNK_LAYERS[i][x + 1 + z * size] == 0) {
								TRUNK_LAYERS[i][index] = 2;
								continue;
							}
						}
						if (z < size - 1) {
							if (TRUNK_LAYERS[i][x + (z + 1) * size] == 0) {
								TRUNK_LAYERS[i][index] = 2;
								continue;
							}
						}
					}
				}
			}
		}
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		final int x = pos.getX();
		final int y = pos.getY();
		final int z = pos.getZ();

		int height = rand.nextInt(4) + 9;
		int canopySize = (int)(((rand.nextDouble() * height) / 12.0D) * 4 + 5);

		if(!this.rotatedCubeCantReplace(world, x, y + 2, z, 0, 0, 0, 1, height, 1, 0) && 
				!this.rotatedCubeCantReplace(world, x, y + 2, z, -canopySize+2, 0, -canopySize+2, canopySize*2-4, height, canopySize*2-4, 0)) {

			IBlockState log = BlockRegistry.LOG_HEARTHGROVE.getDefaultState().withProperty(BlockLogBetweenlands.LOG_AXIS, BlockLog.EnumAxis.NONE);
			IBlockState logY = BlockRegistry.LOG_HEARTHGROVE.getDefaultState().withProperty(BlockLogBetweenlands.LOG_AXIS, BlockLog.EnumAxis.Y);
			IBlockState leaves = BlockRegistry.LEAVES_HEARTHGROVE_TREE.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
			IBlockState hangers = BlockRegistry.HANGER.getDefaultState();

			int rootHeight = rand.nextInt(3) + 1;

			int canopyStart = canopySize / 2 - 1;

			for(int i = rootHeight; i <= height - canopyStart - 1; i++) {
				this.setBlockAndNotifyAdequately(world, pos.up(i), logY);
			}

			List<BlockPos> blobs = new ArrayList<>();
			for(int i = 0; i < 4; i++) {
				blobs.add(new BlockPos(x + rand.nextInt(canopySize*2) - canopySize, y + height - canopyStart / 2, z + rand.nextInt(canopySize*2) - canopySize));
			}

			double circumference = Math.PI * (canopySize - 1);

			int branches = (int)(circumference / 4.0D) + 1;

			double angleStep = Math.PI * 2 / (branches-1);

			List<Pair<BlockPos, Float>> leavesSupportPoints = new ArrayList<>();

			List<BlockPos> subbranchEndpoints = new ArrayList<>();

			if(canopySize > 3) {
				for(int i = 0; i < branches; i++) {
					BlockPos branchStart = pos.up(height - canopyStart - 2);
					double randRot = rand.nextDouble() * angleStep / 3.0D;
					BlockPos branchEnd = pos.add(Math.cos(Math.PI * 2 / (branches-1) * i + randRot) * (canopySize - 4), height - canopyStart, Math.sin(Math.PI * 2 / (branches-1) * i + randRot) * (canopySize - 4));

					List<Vec3d> branchPoints = new ArrayList<>();

					branchPoints.add(new Vec3d(branchStart.up()));
					branchPoints.add(new Vec3d(branchStart));


					branchPoints.add(new Vec3d(branchEnd));
					branchPoints.add(new Vec3d(branchEnd.up()));

					ISpline spline = new CatmullRomSpline(branchPoints.toArray(new Vec3d[0]));

					BlockPos setBranchPos = null;


					boolean support = false;
					int steps = 30;
					for(int j = 0; j < steps; j++) {
						BlockPos branchPos = new BlockPos(spline.interpolate(1.0F / (steps-1) * j).add(0.5, 0.5, 0.5));
						if(!branchPos.equals(setBranchPos) && world.isAirBlock(branchPos)) {
							this.setBlockAndNotifyAdequately(world, branchPos, log);

							if(!support && branchPos.distanceSq(x, branchPos.getY(), z) >= 2.5D) {
								EnumFacing supportDir = EnumFacing.getFacingFromVector(branchPos.getX() - x, 0, branchPos.getZ() - z);

								int supportYO = 0;
								int supportXO = 0;
								int supportZO = 0;

								int supportHeight = height - (branchPos.getY() - y) + (canopySize <= 6 ? -1 : 0);

								for(int k = 0; k < supportHeight; k++) {
									this.setBlockAndNotifyAdequately(world, branchPos.add(supportXO, 1 + supportYO, supportZO), logY);

									if((k+1) % 3 == 0) {
										supportXO += supportDir.getXOffset();
										supportZO += supportDir.getZOffset();
										k++;
									}
									supportYO++;
								}

								leavesSupportPoints.add(Pair.of(branchPos.add(supportXO, 1 + supportYO, supportZO), 6.0F));

								support = true;
							}
						}
						setBranchPos = branchPos;
					}
					if(setBranchPos != null) {
						leavesSupportPoints.add(Pair.of(setBranchPos, 10.0F));
						if(canopySize >= 5) {
							subbranchEndpoints.add(setBranchPos);
						}
					}
				}
			}

			float centerSquashX = 0.8F + rand.nextFloat() * 0.4F;
			float centerSquashZ = 0.8F + rand.nextFloat() * 0.4F;
			for(int i = 0; i < canopyStart + 2; i++) {
				final int k = i;
				this.generateCanopyLayer(world, pos.up(height - canopyStart + i), canopySize - i, leaves, p -> {
					boolean nearSupport = false;
					Random supportRand = new Random();
					for(Pair<BlockPos, Float> support : leavesSupportPoints) {
						BlockPos supportPos = support.getKey();
						supportRand.setSeed(MathHelper.getCoordinateRandom(supportPos.getX(), supportPos.getY(), supportPos.getZ()));
						float squashX = 0.6F + supportRand.nextFloat() * 1.2F;
						float squashY = 0.6F + supportRand.nextFloat() * 1.2F;
						float squashZ = 0.6F + supportRand.nextFloat() * 1.2F;
						if((supportPos.getX()-p.getX())*(supportPos.getX()-p.getX())*squashX +
								(supportPos.getY()-p.getY())*(supportPos.getY()-p.getY())*squashY + 
								(supportPos.getZ()-p.getZ())*(supportPos.getZ()-p.getZ())*squashZ <= support.getValue() + rand.nextFloat() * 0.8F) {
							nearSupport = true;
							break;
						}
					}
					if(!nearSupport) return false;
					return world.isAirBlock(p) && (k > 1 || (canopySize - k) < 4 || Math.sqrt((p.getX()-x)*(p.getX()-x)*centerSquashX+(p.getZ()-z)*(p.getZ()-z)*centerSquashZ) >= canopySize - k - 3 - rand.nextFloat() * 0.8F);
				}, p -> {
					if(k == 0 && rand.nextInt(6) == 0) {
						int hangerLength = rand.nextInt(5) + 1;
						for(int yo = 0; yo < hangerLength; yo++) {
							BlockPos hangerPos = p.down(1 + yo);
							if(world.isAirBlock(hangerPos)) {
								this.setBlockAndNotifyAdequately(world, hangerPos, hangers);
							} else {
								break;
							}
						}
					}
				});
			}

			for(BlockPos endpoint : subbranchEndpoints) {
				EnumFacing branchDir = EnumFacing.getFacingFromVector(endpoint.getX() - x, 0, endpoint.getZ() - z);
				BlockPos branch1 = endpoint.offset(branchDir).offset(branchDir.rotateY());
				BlockPos branch2 = endpoint.offset(branchDir).offset(branchDir.rotateYCCW());
				if(world.isAirBlock(branch1)) this.setBlockAndNotifyAdequately(world, branch1, log);
				if(world.isAirBlock(branch2)) this.setBlockAndNotifyAdequately(world, branch2, log);
			}

			boolean[] generatedRoots = new boolean[5*5];

			int roots = 0;

			for(int i = 0; i < 50 && roots < 3; i++) {
				int rootX = rand.nextInt(3) - 1;
				int rootZ = rand.nextInt(3) - 1;

				if(rootX != 0 || rootZ != 0) {
					int rootIndex = rootX + 1 + 1 + (rootZ + 1 + 1) * 5;
					int rootIndexN = rootIndex - 5;
					int rootIndexS = rootIndex + 5;
					int rootIndexE = rootIndex + 1;
					int rootIndexW = rootIndex - 1;

					if(!generatedRoots[rootIndex] && !generatedRoots[rootIndexN] && !generatedRoots[rootIndexS] &&
							!generatedRoots[rootIndexE] && !generatedRoots[rootIndexW]) {
						int rootXO = 0;
						int rootZO = 0;

						for(int j = rootHeight; j >= -4; j--) {
							if(j < rootHeight && rand.nextInt(3) == 0) {
								EnumFacing offset = EnumFacing.HORIZONTALS[rand.nextInt(EnumFacing.HORIZONTALS.length)];
								rootXO += rootX * Math.abs(offset.getXOffset());
								rootZO += rootZ * Math.abs(offset.getZOffset());
							}
							BlockPos rootPos = pos.add(rootX + rootXO, j, rootZ + rootZO);
							if(world.getBlockState(rootPos).getBlock().isReplaceable(world, rootPos)) {
								this.setBlockAndNotifyAdequately(world, rootPos, log);
							} else {
								break;
							}
						}

						generatedRoots[rootIndex] = true;
						roots++;
					}
				}
			}

			return true;
		}

		return false;
	}

protected void generateCanopyLayer(World world, BlockPos center, final int size, IBlockState leaves, final @Nullable Predicate<BlockPos> pred, @Nullable Consumer<BlockPos> postprocessor) {
		int x = center.getX();
		int y = center.getY();
		int z = center.getZ();

		switch(size) {
		default:
			int radius = size - 1;
			int span = MathHelper.floor(size / 2.0F);
			span += (span-1) % 2;

			boolean[] setStates = new boolean[(size*2)*(size*2)];

			Predicate<BlockPos> fullPred = pos -> {
				if(pred.test(pos)) {
					int xo = pos.getX() - x;
					int zo = pos.getZ() - z;
					int index = xo + radius + 1 + (zo + radius + 1) * (size*2);
					return !setStates[index];
				}
				return false;
			};

			Consumer<BlockPos> consumer = pos -> {
				int xo = pos.getX() - x;
				int zo = pos.getZ() - z;
				int index = xo + radius + 1 + (zo + radius + 1) * (size*2);
				if(!setStates[index]) {
					setStates[index] = true;
				}
				if(postprocessor != null) {
					postprocessor.accept(pos);
				}
			};

			for(int i = 0; i <= span; i++) {
				this.rotatedCubeVolume(world, fullPred, x, y, z, -(radius-i), 0, -(span+2*i-1)/2, leaves, (radius-i)*2+1, 1, span+2*i, 0, consumer);
				this.rotatedCubeVolume(world, fullPred, x, y, z, -(span+2*i-1)/2, 0, -(radius-i), leaves, span+2*i, 1, (radius-i)*2+1, 0, consumer);
			}
			break;
		case 4:
			this.rotatedCubeVolume(world, pred, x, y, z, -2, 0, -2, leaves, 5, 1, 5, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, -3, 0, 0, leaves, 1, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, 3, 0, 0, leaves, 1, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, 0, 0, -3, leaves, 1, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, 0, 0, 3, leaves, 1, 1, 1, 0, postprocessor);
			break;
		case 3:
			this.rotatedCubeVolume(world, pred, x, y, z, -1, 0, -1, leaves, 3, 1, 3, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, -2, 0, 0, leaves, 1, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, 2, 0, 0, leaves, 1, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, 0, 0, -2, leaves, 1, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, 0, 0, 2, leaves, 1, 1, 1, 0, postprocessor);
			break;
		case 2:
			this.rotatedCubeVolume(world, pred, x, y, z, 0, 0, 0, leaves, 2, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, -1, 0, 0, leaves, 1, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, 0, 0, 1, leaves, 1, 1, 1, 0, postprocessor);
			this.rotatedCubeVolume(world, pred, x, y, z, 0, 0, -1, leaves, 1, 1, 1, 0, postprocessor);
			break;
		case 1:
			this.rotatedCubeVolume(world, pred, x, y, z, 0, 0, 0, leaves, 1, 1, 1, 0, postprocessor);
			break;
		}
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		int x = pos.getX();
		int y = pos.getY();
		int z = pos.getZ();

		double foldedNormalDist = (Math.abs(rand.nextGaussian()) + 0.2D) / 3.0D;
		int height = (int)(Math.pow((1 - Math.min(foldedNormalDist, 1)), 1.5D) * 10) + 5;

		if(!this.rotatedCubeCantReplace(world, x, y + 2, z, -2, 0, -2, 5, height, 5, 0)) {
			int bend1 = rand.nextInt(3) + 6;
			int bend2 = rand.nextInt(2) == 0 ? rand.nextInt(3) + 10 : -1;

			int canopy1 = rand.nextInt(3) + 3;

			IBlockState log = BlockRegistry.LOG_NIBBLETWIG.getDefaultState().withProperty(BlockLogBetweenlands.LOG_AXIS, BlockLog.EnumAxis.NONE);
			IBlockState leaves = BlockRegistry.LEAVES_NIBBLETWIG_TREE.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
			IBlockState ivy = BlockRegistry.POISON_IVY.getDefaultState();

			int xo[] = new int[height+1];
			int zo[] = new int[height+1];
			for(int i = 0; i <= height; i++) {
				int bxo = i == 0 ? 0 : xo[i-1];
				int bzo = i == 0 ? 0 : zo[i-1];
				if(i == bend1 || i == bend2) {
					EnumFacing randOffset = EnumFacing.HORIZONTALS[rand.nextInt(EnumFacing.HORIZONTALS.length)];
					bxo += randOffset.getXOffset();
					bzo += randOffset.getZOffset();
				}
				xo[i] = bxo;
				zo[i] = bzo;
				this.setBlockAndNotifyAdequately(world, pos.add(bxo, i, bzo), log);
			}

			this.rotatedCubeVolume(world, setPos -> world.isAirBlock(setPos), xo[canopy1] + x, y + canopy1, zo[canopy1] + z, -1, 0, -1, leaves, 3, 1, 3, 0);
			for(EnumFacing offset : EnumFacing.HORIZONTALS) {
				BlockPos offsetPos = pos.add(xo[canopy1] + offset.getXOffset(), canopy1 + 1, zo[canopy1] + offset.getZOffset());
				if(world.isAirBlock(offsetPos)) {
					this.setBlockAndNotifyAdequately(world, offsetPos, leaves);
				}

				BlockPos droopPos = pos.add(xo[canopy1] + offset.getXOffset()*2, canopy1, zo[canopy1] + offset.getZOffset()*2);
				int droopLength = rand.nextInt(2) + 2;
				for(int yo = 0; yo < droopLength; yo++) {
					BlockPos droopPosY = droopPos.down(yo);
					if(world.isAirBlock(droopPosY)) {
						this.setBlockAndNotifyAdequately(world, droopPosY, leaves);
					}
				}

				if(rand.nextInt(3) == 0) {
					BlockPos ivyPos = pos.add(xo[canopy1] + offset.getXOffset()*3, canopy1, zo[canopy1] + offset.getZOffset()*3);
					int ivyLength = rand.nextInt(5) + 3;
					for(int yo = 0; yo < ivyLength; yo++) {
						BlockPos ivyPosY = ivyPos.down(yo);
						if(world.isAirBlock(ivyPosY)) {
							this.setBlockAndNotifyAdequately(world, ivyPosY, ivy.withProperty(BlockPoisonIvy.getPropertyFor(offset.getOpposite()), true));
						} else {
							break;
						}
					}
				}
			}

			this.rotatedCubeVolume(world, setPos -> world.isAirBlock(setPos), xo[height-1] + x, y + height-1, zo[height-1] + z, -1, 0, -2, leaves, 3, 2, 5, 0);
			this.rotatedCubeVolume(world, setPos -> world.isAirBlock(setPos), xo[height-1] + x, y + height-1, zo[height-1] + z, -2, 0, -1, leaves, 5, 2, 3, 0);

			this.rotatedCubeVolume(world, setPos -> world.isAirBlock(setPos), xo[height-1] + x, y + height-1 + 2, zo[height-1] + z, -1, 0, 0, leaves, 3, 1, 1, 0);
			this.rotatedCubeVolume(world, setPos -> world.isAirBlock(setPos), xo[height-1] + x, y + height-1 + 2, zo[height-1] + z, 0, 0, -1, leaves, 1, 1, 3, 0);
			this.rotatedCubeVolume(world, setPos -> world.isAirBlock(setPos), xo[height-1] + x, y + height-1 + 3, zo[height-1] + z, 0, 0, 0, leaves, 1, 1, 1, 0);

			boolean generatedDroops[] = new boolean[9*9];

			int droops = 4 + rand.nextInt(8);
			for(int i = 0; i < droops; i++) {
				int droopXO = rand.nextInt(7) - 3;
				int droopZO = 0;
				if(Math.abs(droopXO) <= 1) {
					droopZO = rand.nextInt(7) - 3;
				} else {
					droopZO = rand.nextInt(3) - 1;
				}

				int droopIndex = droopXO + 3 + 1 + (droopZO + 3 + 1) * 9;
				int droopIndexN = droopIndex - 9;
				int droopIndexS = droopIndex + 9;
				int droopIndexE = droopIndex + 1;
				int droopIndexW = droopIndex - 1;

				if(Math.abs(droopXO) + Math.abs(droopZO) > 1 && !generatedDroops[droopIndex] &&
						!generatedDroops[droopIndexN] && !generatedDroops[droopIndexS] &&
						!generatedDroops[droopIndexE] && !generatedDroops[droopIndexW]) {
					BlockPos droopPos = pos.add(xo[height-1] + droopXO, height-1, zo[height-1] + droopZO);

					int droopLength = rand.nextInt(3) + 2;
					for(int yo = 0; yo < droopLength; yo++) {
						BlockPos droopPosY = droopPos.down(yo);
						if(world.isAirBlock(droopPosY)) {
							this.setBlockAndNotifyAdequately(world, droopPosY, leaves);
						}
					}

					EnumFacing ivyOffset = EnumFacing.HORIZONTALS[rand.nextInt(EnumFacing.HORIZONTALS.length)];
					BlockPos ivyPos = pos.add(xo[height-1] + droopXO + ivyOffset.getXOffset(), height-1, zo[height-1] + droopZO + ivyOffset.getZOffset());
					int ivyLength = rand.nextInt(9) + 3;
					for(int yo = 0; yo < ivyLength; yo++) {
						BlockPos ivyPosY = ivyPos.down(yo);
						if(world.isAirBlock(ivyPosY)) {
							this.setBlockAndNotifyAdequately(world, ivyPosY, ivy.withProperty(BlockPoisonIvy.getPropertyFor(ivyOffset.getOpposite()), true));
						} else {
							break;
						}
					}

					generatedDroops[droopIndex] = true;
				}
			}
			return true;
		}

		return false;
	}

private void createBranch(World world, Random rand, int x, int y, int z, int dir, int branchLength) {
		for (int i = 0; i <= branchLength; ++i) {

			if (i >= 1) {
				y++;
			}

			if (dir == 1) {
				world.setBlockState(new BlockPos(x + i, y, z), log, 2);
				world.setBlockState(new BlockPos(x + i + 1, y, z), log, 2);
			}

			if (dir == 2) {
				world.setBlockState(new BlockPos(x - i, y, z), log, 2);
				world.setBlockState(new BlockPos(x - i - 1, y, z), log, 2);
			}

			if (dir == 3) {
				world.setBlockState(new BlockPos(x, y, z + i), log, 2);
				world.setBlockState(new BlockPos(x, y, z + i + 1), log, 2);
			}

			if (dir == 4) {
				world.setBlockState(new BlockPos(x, y, z - i), log, 2);
				world.setBlockState(new BlockPos(x, y, z - i - 1), log, 2);
			}

		}
	}

private void createMainCanopy(World world, Random rand, int x, int y, int z, int maxRadius) {
		for (int x1 = x - maxRadius; x1 <= x + maxRadius; x1++)
			for (int z1 = z - maxRadius; z1 <= z + maxRadius; z1++)
				for (int y1 = y; y1 < y + maxRadius; y1++) {
					double dSq = Math.pow(x1 - x, 2.0D) + Math.pow(z1 - z, 2.0D) + Math.pow(y1 - y, 2.0D);
					if (Math.round(Math.sqrt(dSq)) <= maxRadius)
						if (world.getBlockState(this.checkPos.setPos(x1, y1, z1)).getBlock() != log.getBlock() && rand.nextInt(5) != 0)
							world.setBlockState(new BlockPos(x1, y1, z1), leaves, 2);
				}
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		int x = position.getX();
		int y = position.getY();
		int z = position.getZ();

		int height = rand.nextInt(8) + 8;
		int maxRadius = 4;

		this.log = BlockRegistry.LOG_RUBBER.getDefaultState().withProperty(BlockRubberLog.NATURAL, true);
		this.leaves = BlockRegistry.LEAVES_RUBBER_TREE.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);



		for (int xx = x - maxRadius; xx <= x + maxRadius; xx++)
			for (int zz = z - maxRadius; zz <= z + maxRadius; zz++)
				for (int yy = y + 2; yy < y + height; yy++)
					if (!world.isAirBlock(checkPos.setPos(xx, yy, zz)) && !world.getBlockState(checkPos.setPos(xx, yy, zz)).getBlock().isReplaceable(world, checkPos.setPos(xx, yy, zz)))
						return false;

		for (int yy = y; yy < y + height; ++yy) {
			world.setBlockState(new BlockPos(x, yy, z), log, 2);

			if (yy == y + height - 1)
				createMainCanopy(world, rand, x, yy, z, maxRadius);

			if (yy == y + height - 2) {
				createBranch(world, rand, x + 1, yy, z, 1, 1);
				createBranch(world, rand, x- 1, yy, z, 2, 1);
				createBranch(world, rand, x, yy, z + 1, 3, 1);
				createBranch(world, rand, x, yy, z - 1, 4, 1);
			}
		}
		return true;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		int height = rand.nextInt(3) + 16;
		int maxRadius = 6;

		this.logX = BlockRegistry.LOG_SAP.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.X);
		this.logY = BlockRegistry.LOG_SAP.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.Y);
		this.logZ = BlockRegistry.LOG_SAP.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.Z);
		this.roots = BlockRegistry.LOG_SAP.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.NONE);
		this.leaves = BlockRegistry.LEAVES_SAP_TREE.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);

		for (int xx = - maxRadius; xx <= maxRadius; xx++)
			for (int zz = - maxRadius; zz <= maxRadius; zz++)
				for (int yy = 2; yy < height; yy++)
					if (!world.isAirBlock(pos.add(xx, yy, zz)) && !world.getBlockState(pos.add(xx, yy, zz)).getBlock().isReplaceable(world, pos.add(xx, yy, zz)))
						return false;

		for (int yy = 0; yy < height; ++yy) {
			world.setBlockState(pos.add(0, yy, 0), logY, 2);

			if (yy == 0)
				createRoots(world, pos);

			if (yy == height - 1)
				createLeaves(world, pos.add(0, yy, 0), true);

			if (yy == height - 8 || yy == height - 12) {
				if (rand.nextBoolean()) {
					createBranch(world, rand, pos.add(1, yy - rand.nextInt(2), 0), 1, 2);
					createBranch(world, rand, pos.add(- 1, yy - rand.nextInt(2), 0), 2, 2);
					createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), 1), 3, 2);
					createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), - 1), 4, 2);
				} else {
					createBranch(world, rand, pos.add(2, yy - rand.nextInt(2), 2), 5, 2);
					createBranch(world, rand, pos.add(- 2, yy - rand.nextInt(2), - 2), 6, 2);
					createBranch(world, rand, pos.add(- 2, yy - rand.nextInt(2), 2), 7, 2);
					createBranch(world, rand, pos.add(2, yy - rand.nextInt(2), - 2), 8, 2);
				}
			}

			if (yy == height - 4) {
				if (rand.nextBoolean()) {
					createBranch(world, rand, pos.add(1, yy - rand.nextInt(2), 0), 1, 1);
					createBranch(world, rand, pos.add(- 1, yy - rand.nextInt(2), 0), 2, 1);
					createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), 1), 3, 1);
					createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), - 1), 4, 1);
				} else {
					createBranch(world, rand, pos.add(2, yy - rand.nextInt(2), 2), 5, 1);
					createBranch(world, rand, pos.add(- 2, yy - rand.nextInt(2), - 2), 6, 1);
					createBranch(world, rand, pos.add(- 2, yy - rand.nextInt(2), 2), 7, 1);
					createBranch(world, rand, pos.add(2, yy - rand.nextInt(2), - 2), 8, 1);
				}
			}
		}
		return true;
	}

private void createBranch(World world, Random rand, BlockPos pos, int dir, int branchLength) {
		boolean branchBend = false;
		int y = 0;
		for (int i = 0; i <= branchLength; ++i) {

			if (i >= 1) {
				y++;
				branchBend = true;
			}

			if (dir == 1) {
				world.setBlockState(pos.add(i, y, 0), branchBend ? logY : logX, 2);
				if(i == branchLength) {
					createLeaves(world, pos.add(i, y, 0), false);
				}
			}

			if (dir == 2) {
				world.setBlockState(pos.add(- i, y, 0), branchBend ? logY : logX, 2);
				if(i == branchLength) {
					createLeaves(world, pos.add(- i, y, 0), false);
				}
			}

			if (dir == 3) {
				world.setBlockState(pos.add(0, y, i), branchBend ? logY : logZ, 2);
				if(i == branchLength) {
					createLeaves(world, pos.add(0, y, i), false);
				}
			}

			if (dir == 4) {
				world.setBlockState(pos.add(0, y, - i), branchBend ? logY : logZ, 2);
				if(i == branchLength) {
					createLeaves(world, pos.add(0, y, - i), false);
				}
			}

			if (dir == 5) {
				world.setBlockState(pos.add(i - 1, y, i - 1),branchBend ? logY : logX, 2);
				if(i == branchLength) {
					createLeaves(world, pos.add(i - 1, y, i - 1), false);
				}
			}

			if (dir == 6) {
				world.setBlockState(pos.add(- i + 1, y, - i + 1), branchBend ? logY : logX, 2);
				if(i == branchLength) {
					createLeaves(world, pos.add(- i + 1, y, - i + 1), false);
				}
			}

			if (dir == 7) {
				world.setBlockState(pos.add(- i + 1, y, i - 1), branchBend ? logY : logZ, 2);
				if(i == branchLength) {
					createLeaves(world, pos.add(- i + 1, y, i - 1), false);
				}
			}

			if (dir == 8) {
				world.setBlockState(pos.add(i - 1, y, - i + 1), branchBend ? logY : logZ, 2);
				if(i == branchLength) {
					createLeaves(world, pos.add(i - 1, y, - i + 1), false);
				}
			}
		}
	}

private void createLeaves(World world, BlockPos pos, boolean top) {
		world.setBlockState(pos.add(0, 0, 1), leaves, 2);
		world.setBlockState(pos.add(0, 0, - 1), leaves, 2);
		world.setBlockState(pos.add(1, 0, 0), leaves, 2);
		world.setBlockState(pos.add(- 1, 0, 0), leaves, 2);

		if(top)
			world.setBlockState(pos.add(0, 1, 0), leaves, 2);
		else
			world.setBlockState(pos.add(0, - 1, 0), leaves, 2);
	}

private void createRoots(World world, BlockPos pos) {
		world.setBlockState(pos.add(0, 0, 1), roots, 2);
		world.setBlockState(pos.add(0, 0, - 1), roots, 2);
		world.setBlockState(pos.add(1, 0, 0), roots, 2);
		world.setBlockState(pos.add(- 1, 0, 0), roots, 2);
	}

public WorldGenSpiritTree(@Nullable ILocationGuard guard, @Nullable LocationSpiritTree location) {
		this.guard = guard;
		this.location = location;
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		int checkRadius = 9;

		for (int xx = -checkRadius; xx <= checkRadius; xx++) {
			for (int zz = -checkRadius; zz <= checkRadius; zz++) {
				for (int yy = 3; yy < 16; yy++) {
					if (!world.isAirBlock(position.add(xx, yy, zz)) && world.getBlockState(position.add(xx, yy, zz)).isNormalCube()) {
						return false;
					}
				}
			}
		}

		this.log = BlockRegistry.LOG_SPIRIT_TREE.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.NONE);
		this.leavesTop = BlockRegistry.LEAVES_SPIRIT_TREE_TOP.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
		this.leavesMiddle = BlockRegistry.LEAVES_SPIRIT_TREE_MIDDLE.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
		this.leavesBottom = BlockRegistry.LEAVES_SPIRIT_TREE_BOTTOM.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
		this.roots = BlockRegistry.ROOT.getDefaultState();

		int trunkX = position.getX();
		int trunkY = position.getY();
		int trunkZ = position.getZ();

		int height = 8 + rand.nextInt(4);

		for(int yo = 0; yo < height; yo++) {
			this.generateTrunkCrossSection(world, rand, trunkX, trunkY + yo, trunkZ, this.log, trunkX, trunkY, trunkZ);
			if(this.location != null) {
				this.location.addLargeFacePosition(new BlockPos(trunkX, trunkY + yo, trunkZ));
			}
		}

		Map<List<BlockPos>, BlockPos> branches = new HashMap<>();

		BlockPos sideBranch;

		//Generate 4 main branches in the cardinal directions

		sideBranch = new BlockPos(trunkX + rand.nextInt(2), trunkY + height - 3, trunkZ);
		branches.put(this.generateSideBranch(world, rand, sideBranch, 0, trunkX, trunkY, trunkZ), sideBranch);

		sideBranch = new BlockPos(trunkX, trunkY + height - 3, trunkZ + rand.nextInt(2));
		branches.put(this.generateSideBranch(world, rand, sideBranch, 2, trunkX, trunkY, trunkZ), sideBranch);

		sideBranch = new BlockPos(trunkX + rand.nextInt(2), trunkY + height - 3, trunkZ + 1);
		branches.put(this.generateSideBranch(world, rand, sideBranch, 4, trunkX, trunkY, trunkZ), sideBranch);

		sideBranch = new BlockPos(trunkX + 1, trunkY + height - 3, trunkZ + rand.nextInt(2));
		branches.put(this.generateSideBranch(world, rand, sideBranch, 6, trunkX, trunkY, trunkZ), sideBranch);

		//Generate 1-3 diagonal branches
		List<Integer> diagonals = new ArrayList<>(Arrays.asList(1, 3, 5, 7));
		int numDiagonals = 1 + rand.nextInt(3);
		for(int i = 0; i < numDiagonals; i++) {
			int dir = diagonals.remove(rand.nextInt(diagonals.size()));
			int[] offset = this.getDirOffset(dir);
			int bx = trunkX + (offset[0] > 0 ? offset[0] * 2 : offset[0]);
			int bz = trunkZ + (offset[1] > 0 ? offset[1] * 2 : offset[1]);
			sideBranch = new BlockPos(bx, trunkY + height, bz);
			branches.put(this.generateSideBranch(world, rand, sideBranch, dir, trunkX, trunkY, trunkZ), sideBranch);
		}

		//Generate two tall branches at top of trunk
		if(rand.nextBoolean()) {
			sideBranch = new BlockPos(trunkX, trunkY + height, trunkZ);
			branches.put(this.generateTopBranch(world, rand, sideBranch, 1, trunkX, trunkY, trunkZ), sideBranch);

			sideBranch = new BlockPos(trunkX + 1, trunkY + height, trunkZ + 1);
			branches.put(this.generateTopBranch(world, rand, sideBranch, 5, trunkX, trunkY, trunkZ), sideBranch);
		} else {
			sideBranch = new BlockPos(trunkX, trunkY + height, trunkZ + 1);
			branches.put(this.generateTopBranch(world, rand, sideBranch, 3, trunkX, trunkY, trunkZ), sideBranch);

			sideBranch = new BlockPos(trunkX + 1, trunkY + height, trunkZ);
			branches.put(this.generateTopBranch(world, rand, sideBranch, 7, trunkX, trunkY, trunkZ), sideBranch);
		}

		for(Entry<List<BlockPos>, BlockPos> branch : branches.entrySet()) {
			this.generateBranchLeaves(world, rand, branch.getValue(), branch.getKey(), trunkX, trunkY, trunkZ);
		}

		//Generate roots

		List<BlockPos> rootBlocks = new ArrayList<>();

		sideBranch = new BlockPos(trunkX + rand.nextInt(2), trunkY, trunkZ);
		rootBlocks.addAll(this.generateRoot(world, rand, sideBranch, 0, trunkX, trunkY, trunkZ));

		sideBranch = new BlockPos(trunkX, trunkY, trunkZ + rand.nextInt(2));
		rootBlocks.addAll(this.generateRoot(world, rand, sideBranch, 2, trunkX, trunkY, trunkZ));

		sideBranch = new BlockPos(trunkX + rand.nextInt(2), trunkY, trunkZ + 1);
		rootBlocks.addAll(this.generateRoot(world, rand, sideBranch, 4, trunkX, trunkY, trunkZ));

		sideBranch = new BlockPos(trunkX + 1, trunkY, trunkZ + rand.nextInt(2));
		rootBlocks.addAll(this.generateRoot(world, rand, sideBranch, 6, trunkX, trunkY, trunkZ));

		for(BlockPos rootBlock : rootBlocks) {
			if(rand.nextInt(4) == 0 && new Vec3d(rootBlock.getX() + 0.5D, 0, rootBlock.getZ() + 0.5D).squareDistanceTo(trunkX + 1.0D, 0, trunkZ + 1.0D) >= 9 && world.isAirBlock(rootBlock.up())) {
				int rootHeight = 1 + rand.nextInt(3);
				for(int yo = 0; yo < rootHeight; yo++) {
					BlockPos pos = rootBlock.up(1 + yo);
					if(world.isAirBlock(pos)) {
						this.setBlock(world, pos, this.roots, true, trunkX, trunkY, trunkZ);
					} else {
						break;
					}
				}
			}
		}

		return true;
	}

private void generateTrunkCrossSection(World world, Random rand, int x, int y, int z, IBlockState log, int trunkX, int trunkY, int trunkZ) {
		for(int xo = 0; xo < 2; xo++) {
			for(int zo = 0; zo < 2; zo++) {
				this.setBlock(world, new BlockPos(x + xo, y, z + zo), log, false, trunkX, trunkY, trunkZ);
			}
		}
	}

private int[] getDirOffset(int dir) {
		int[] offset = new int[2];
		switch(dir) {
		case 0: //N
			offset[1] = -1;
			break;
		case 1: //NW
			offset[0] = -1;
			offset[1] = -1;
			break;
		case 2: //W
			offset[0] = -1;
			break;
		case 3: //SW
			offset[0] = -1;
			offset[1] = 1;
			break;
		case 4: //S
			offset[1] = 1;
			break;
		case 5: //SE
			offset[0] = 1;
			offset[1] = 1;
			break;
		case 6: //E
			offset[0] = 1;
			break;
		case 7: //NE
			offset[0] = 1;
			offset[1] = -1;
			break;
		}
		return offset;
	}

private List<BlockPos> generateRoot(World world, Random rand, BlockPos start, int dir, int trunkX, int trunkY, int trunkZ) {
		List<BlockPos> root = this.generateBranchPositions(rand, start, dir, 2 + rand.nextInt(2), 0.9D, 0.8D, (i, remainingBlocks) -> i < 2 ? 0 : rand.nextInt((i - 2) * 2 + 2) == 0 ? 0 : -1, (i, length) -> true);
		for(BlockPos pos : root) {
			BlockPos rel = pos.subtract(start);
			if(Math.abs(rel.getX()) + Math.abs(rel.getY()) + Math.abs(rel.getZ()) >= 1) {
				root.add(root.indexOf(pos), pos.up());
				break;
			}
		}
		BlockPos end = root.get(root.size() - 1);
		switch(dir) {
		case 0:
			root.addAll(this.generateSubRootPositions(world, rand, end, 1));
			root.addAll(this.generateSubRootPositions(world, rand, end, 7));
			break;
		case 1:
			root.addAll(this.generateSubRootPositions(world, rand, end, 0));
			root.addAll(this.generateSubRootPositions(world, rand, end, 2));
			break;
		case 2:
			root.addAll(this.generateSubRootPositions(world, rand, end, 1));
			root.addAll(this.generateSubRootPositions(world, rand, end, 3));
			break;
		case 3:
			root.addAll(this.generateSubRootPositions(world, rand, end, 2));
			root.addAll(this.generateSubRootPositions(world, rand, end, 4));
			break;
		case 4:
			root.addAll(this.generateSubRootPositions(world, rand, end, 3));
			root.addAll(this.generateSubRootPositions(world, rand, end, 5));
			break;
		case 5:
			root.addAll(this.generateSubRootPositions(world, rand, end, 4));
			root.addAll(this.generateSubRootPositions(world, rand, end, 6));
			break;
		case 6:
			root.addAll(this.generateSubRootPositions(world, rand, end, 5));
			root.addAll(this.generateSubRootPositions(world, rand, end, 7));
			break;
		case 7:
			root.addAll(this.generateSubRootPositions(world, rand, end, 6));
			root.addAll(this.generateSubRootPositions(world, rand, end, 1));
			break;
		}
		for(BlockPos pos : root) {
			this.setBlock(world, pos, this.log, true, trunkX, trunkY, trunkZ);
		}
		return root;
	}

private List<BlockPos> generateSubRootPositions(World world, Random rand, BlockPos start, int dir) {
		return this.generateBranchPositions(rand, start, dir, 1 + rand.nextInt(4), 0.5D, 1, (i, remainingBlocks) -> rand.nextInt(i * 2 + 1) == 0 ? 0 : -1, (i, length) -> true);
	}

private List<BlockPos> generateSideBranch(World world, Random rand, BlockPos start, int dir, int trunkX, int trunkY, int trunkZ) {
		List<BlockPos> branch = this.generateSideBranchPositions(rand, start, dir);
		if(branch.size() > 3) {
			BlockPos end = branch.get(3);
			switch(dir) {
			case 0:
				branch.addAll(this.generateSideBranchPositions(rand, end, 1));
				branch.addAll(this.generateSideBranchPositions(rand, end, 7));
				break;
			case 1:
				branch.addAll(this.generateSideBranchPositions(rand, end, 0));
				branch.addAll(this.generateSideBranchPositions(rand, end, 2));
				break;
			case 2:
				branch.addAll(this.generateSideBranchPositions(rand, end, 1));
				branch.addAll(this.generateSideBranchPositions(rand, end, 3));
				break;
			case 3:
				branch.addAll(this.generateSideBranchPositions(rand, end, 2));
				branch.addAll(this.generateSideBranchPositions(rand, end, 4));
				break;
			case 4:
				branch.addAll(this.generateSideBranchPositions(rand, end, 3));
				branch.addAll(this.generateSideBranchPositions(rand, end, 5));
				break;
			case 5:
				branch.addAll(this.generateSideBranchPositions(rand, end, 4));
				branch.addAll(this.generateSideBranchPositions(rand, end, 6));
				break;
			case 6:
				branch.addAll(this.generateSideBranchPositions(rand, end, 5));
				branch.addAll(this.generateSideBranchPositions(rand, end, 7));
				break;
			case 7:
				branch.addAll(this.generateSideBranchPositions(rand, end, 6));
				branch.addAll(this.generateSideBranchPositions(rand, end, 1));
				break;
			}
		}
		for(BlockPos pos : branch) {
			this.setBlock(world, pos, this.log, true, trunkX, trunkY, trunkZ);
		}
		return branch;
	}

private List<BlockPos> generateSideBranchPositions(Random rand, BlockPos start, int dir) {
		return this.generateBranchPositions(rand, start, dir, 6 + rand.nextInt(5), 0.3D, 0.6D, (i, remainingBlocks) -> i < remainingBlocks / 2 ? 1 : (i >= remainingBlocks - 1 && rand.nextInt(2) == 0 ? -1  : 0), (i, length) -> true);
	}

private List<BlockPos> generateTopBranch(World world, Random rand, BlockPos start, int dir, int trunkX, int trunkY, int trunkZ) {
		List<BlockPos> branch = this.generateBranchPositions(rand, start, dir, 5 + rand.nextInt(5), 0.1D, 0.2D, (i, remainingBlocks) -> i < remainingBlocks - 1 ? 1 : 0, (i, length) -> i >= length - 1);
		for(BlockPos pos : branch) {
			this.setBlock(world, pos, this.log, true, trunkX, trunkY, trunkZ);
		}
		return branch;
	}

public List<BlockPos> generateBranchPositions(Random rand, BlockPos start, int dir, int length, double defaultCurveWeight, double directedCurveWeight,
			BiFunction<Integer, Double, Integer> heightFunction, BiFunction<Integer, Double, Boolean> forceMoveFunction) {
		double remainingBlocks = length;

		List<BlockPos> branchBlocks = new ArrayList<>(length);

		BlockPos branch = start;

		double rx = rand.nextDouble() * defaultCurveWeight * 2 - defaultCurveWeight;
		double rz = rand.nextDouble() * defaultCurveWeight * 2 - defaultCurveWeight;

		int[] offset = this.getDirOffset(dir);

		if(offset[0] != 0) {
			rx = offset[0] * directedCurveWeight;
		}

		if(offset[1] != 0) {
			rz = offset[1] * directedCurveWeight;
		}

		branchBlocks.add(branch);

		for(int i = 0; i < remainingBlocks; i++) {
			int xo = rand.nextDouble() < Math.abs(rx) ? (int)Math.signum(rx) : 0;
			int zo = rand.nextDouble() < Math.abs(rz) ? (int)Math.signum(rz) : 0;
			if(zo == 0 && xo == 0 && forceMoveFunction.apply(i, remainingBlocks)) {
				if(rand.nextDouble() * Math.abs(rx) > rand.nextDouble() * Math.abs(rz)) {
					xo = (int)Math.signum(rx);
				} else {
					zo = (int)Math.signum(rz);
				}
			}
			if(Math.abs(xo) == Math.abs(zo) && xo != 0) {
				remainingBlocks -= 0.414D; //sqrt(2)-1
			}
			branch = branch.add(xo, heightFunction.apply(i, remainingBlocks), zo);

			branchBlocks.add(branch);
		}

		return branchBlocks;
	}

private void generateBranchLeaves(World world, Random rand, BlockPos start, List<BlockPos> branchBlocks, int trunkX, int trunkY, int trunkZ) {
		for(BlockPos branchBlock : branchBlocks) {
			int dist = (int) branchBlock.getDistance(start.getX(), start.getY(), start.getZ());
			if(dist >= 2) {
				for(EnumFacing side : LEAVES_OFFSETS) {
					int leavesLength = 3 + (rand.nextInt(5) == 0 ? rand.nextInt(dist + 1) : rand.nextInt(dist / 2 + 1));
					for(int yo = 0; yo > -leavesLength; yo--) {
						BlockPos leafPos = branchBlock.offset(side).add(0, yo, 0);
						IBlockState state;
						if(yo == 0) {
							state = this.leavesTop;
						} else {
							state = this.leavesMiddle;
						}
						if(world.isAirBlock(leafPos)) {
							if(yo == -leavesLength + 1 || (yo < -1 && !world.isAirBlock(leafPos.down()))) {
								state = this.leavesBottom;
								this.setBlock(world, leafPos, state, true, trunkX, trunkY, trunkZ);
								break;
							} else {
								this.setBlock(world, leafPos, state, true, trunkX, trunkY, trunkZ);
							}
						} else {
							break;
						}
					}
				}
			}
		}
	}

protected void setBlock(World world, BlockPos pos, IBlockState state, boolean registerSmallFacePositions, int trunkX, int trunkY, int trunkZ) {
		this.setBlockAndNotifyAdequately(world, pos, state);

		if(this.guard != null) {
			this.guard.setGuarded(world, pos, true);
		}

		if(!(pos.getX() >= trunkX && pos.getZ() >= trunkZ && pos.getX() <= trunkX + 1 && pos.getZ() <= trunkZ + 1) && registerSmallFacePositions && this.location != null && state.getBlock() == BlockRegistry.LOG_SPIRIT_TREE) {
			this.location.addSmallFacePosition(pos);
		}
	}

@Override
		protected Boolean initialValue() {
			return false;
		}

public WorldGenSpiritTreeStructure() {
		super(true);
	}

@Override
	public boolean generate(World world, Random rand, BlockPos position) {
		if(CASCADING_GEN_MUTEX.get()) {
			return false;
		}

		CASCADING_GEN_MUTEX.set(true);

		try {
			BetweenlandsWorldStorage worldStorage = BetweenlandsWorldStorage.forWorld(world);
			LocationSpiritTree location = new LocationSpiritTree(worldStorage, new StorageUUID(UUID.randomUUID()), LocalRegion.getFromBlockPos(position));
			location.addBounds(new AxisAlignedBB(new BlockPos(position)).grow(14 + 18, 16, 14 + 18).offset(0, 6, 0));
			location.setLayer(0);
			location.setSeed(rand.nextLong());
			location.setVisible(true);

			WorldGenSpiritTree genSpiritTree = new WorldGenSpiritTree(location.getGuard(), location);
			if(genSpiritTree.generate(world, rand, position)) {
				this.generateWispCircle(world, rand, position, RADIUS_INNER_CIRLCE, 1, 2, location);
				this.generateWispCircle(world, rand, position, RADIUS_OUTER_CIRCLE, 1, 1, location);

				int rootsGenerated = 0;
				for(int i = 0; i < 80; i++) {
					double dir = rand.nextDouble() * Math.PI * 2;
					double dx = Math.cos(dir);
					double dz = Math.sin(dir);
					double bx = dx * 16 + dx * rand.nextDouble() * 16;
					double bz = dz * 16 + dz * rand.nextDouble() * 16;
					BlockPos root = position.add(bx, 0, bz);
					root = this.findGroundPosition(world, root);
					if(root != null && world.isAirBlock(root) && world.isAirBlock(root.up())) {
						this.generateRoot(world, rand, root, genSpiritTree, location);
						if(rootsGenerated++ > 12) {
							break;
						}
					}
				}

				for(int i = 0; i < 120; i++) {
					double dir = rand.nextDouble() * Math.PI * 2;
					double dx = Math.cos(dir);
					double dz = Math.sin(dir);
					double bx = dx * 16 + dx * rand.nextDouble() * 16;
					double bz = dz * 16 + dz * rand.nextDouble() * 16;
					BlockPos root = position.add(bx, 0, bz);
					root = this.findGroundPosition(world, root);
					if(root != null && world.isAirBlock(root) && world.isAirBlock(root.up())) {
						int height = 2 + rand.nextInt(4);
						for(int yo = 0; yo < height; yo++) {
							this.setBlock(world, root.up(yo), BlockRegistry.ROOT.getDefaultState(), location);
						}
					}
				}

				this.trySpawnFace(world, rand, new EntitySpiritTreeFaceLarge(world), location.getLargeFacePositions());

				for(int i = 0; i < 8; i++) {
					this.trySpawnFace(world, rand, new EntitySpiritTreeFaceSmall(world), location.getSmallFacePositions());
				}

				location.setDirty(true);
				worldStorage.getLocalStorageHandler().addLocalStorage(location);

				return true;
			}

			return false;
		} finally {
			CASCADING_GEN_MUTEX.set(false);
		}
	}

private void trySpawnFace(World world, Random rand, EntitySpiritTreeFace face, List<BlockPos> locations) {
		BlockPos faceAnchor = null;
		EnumFacing faceFacing = null;

		List<BlockPos> largeFacePositions = new ArrayList<>();
		largeFacePositions.addAll(locations);
		Collections.shuffle(largeFacePositions, rand);
		largeFaceLoop: for(BlockPos anchor : largeFacePositions) {
			List<EnumFacing> facings = new ArrayList<>();
			facings.addAll(Arrays.asList(EnumFacing.HORIZONTALS));
			Collections.shuffle(facings, rand);
			for(EnumFacing facing : facings) {
				if(face.checkAnchorAt(anchor, facing, EnumFacing.UP, AnchorChecks.ALL) == 0) {
					faceAnchor = anchor;
					faceFacing = facing;
					break largeFaceLoop;
				}
			}
		}

		if(faceAnchor != null && faceFacing != null) {
			face.onInitialSpawn(world.getDifficultyForLocation(faceAnchor), null);
			face.setPositionToAnchor(faceAnchor, faceFacing, EnumFacing.UP);
			world.spawnEntity(face);
		}
	}

@Nullable
	private BlockPos findGroundPosition(World world, BlockPos pos) {
		boolean hadAir = false;
		for(int yo = 6; yo >= -6; yo--) {
			BlockPos offsetPos = pos.up(yo);
			IBlockState state = world.getBlockState(offsetPos);
			if(hadAir && SurfaceType.MIXED_GROUND.test(state)) {
				return offsetPos.up();
			}
			if(state.getBlock().isAir(state, world, offsetPos)) {
				hadAir = true;
			}
		}
		return null;
	}

private void generateWispCircle(World world, Random rand, BlockPos center, int radius, int minHeight, int heightVar, LocationSpiritTree location) {
		List<BlockPos> circle = BlockShapeUtils.getCircle(center, radius, new ArrayList<>());
		for(int i = 0; i < circle.size(); i += 2 + rand.nextInt(2)) {
			if(i == circle.size() - 1) {
				break;
			}
			BlockPos pos = circle.get(i);
			pos = this.findGroundPosition(world, pos);
			if(pos != null && (world.isAirBlock(pos) || world.getBlockState(pos).getBlock() instanceof IPlantable)) {
				BlockPos wall = pos.down();
				this.setBlock(world, wall, BlockRegistry.MOSSY_BETWEENSTONE_BRICKS.getDefaultState(), location);
				int height = minHeight + rand.nextInt(heightVar + 1);
				for(int yo = 0; yo < height; yo++) {
					wall = pos.up(yo);
					this.setBlock(world, wall, BlockRegistry.MOSSY_BETWEENSTONE_BRICK_WALL.getDefaultState(), location);
				}
				BlockPos wisp = pos.up(height);
				if(rand.nextInt(4) == 0) {
					this.setBlock(world, wisp, BlockRegistry.WISP.getDefaultState(), location);
					location.addGeneratedWispPosition(wisp);
				} else {
					location.addNotGeneratedWispPosition(wisp);
				}
			}
		}
	}

private void generateRoot(World world, Random rand, BlockPos pos, WorldGenSpiritTree tree, LocationSpiritTree location) {
		List<BlockPos> potentialBlocks = tree.generateBranchPositions(rand, pos, rand.nextInt(7), 32, 0.4D, 0.3D, (i, remainingBlocks) -> i < 2 ? 1 : (i > 4 ? -1 : 0), (i, length) -> true);
		int length = 0;
		for(int i = 0; i < potentialBlocks.size(); i++) {
			BlockPos block = potentialBlocks.get(i);
			if(i > 2 && !world.isAirBlock(block)) {
				length = i + 1;
				break;
			}
		}
		BlockPos prevPos = null;
		for(int i = 0; i < length; i++) {
			BlockPos block = potentialBlocks.get(i);
			if(prevPos != null) {
				int xo = block.getX() - prevPos.getX();
				int yo = block.getY() - prevPos.getY();
				int zo = block.getZ() - prevPos.getZ();
				int moves = Math.abs(xo) + Math.abs(yo) + Math.abs(zo);
				if(moves > 1) {
					List<BlockPos> choices = new ArrayList<>();
					if(xo != 0) {
						choices.add(new BlockPos(xo, 0, 0));
					}
					if(yo != 0) {
						choices.add(new BlockPos(0, yo, 0));
					}
					if(zo != 0) {
						choices.add(new BlockPos(0, 0, zo));
					}
					BlockPos filler = prevPos;
					for(int j = 0; j < moves; j++) {
						filler = filler.add(choices.remove(rand.nextInt(choices.size())));
						this.setBlock(world, filler, BlockRegistry.LOG_SPIRIT_TREE.getDefaultState(), location);
					}
				}
			}
			this.setBlock(world, block, BlockRegistry.LOG_SPIRIT_TREE.getDefaultState(), location);
			prevPos = block;
		}
	}

protected void setBlock(World world, BlockPos pos, IBlockState state, LocationSpiritTree location) {
		this.setBlockAndNotifyAdequately(world, pos, state);

		if(state.getBlock() != BlockRegistry.WISP) {
			location.getGuard().setGuarded(world, pos, true);
		}

		if(state.getBlock() == BlockRegistry.LOG_SPIRIT_TREE) {
			location.addSmallFacePosition(pos);
		}
	}

@Override
	public boolean generate(World world, Random rand, BlockPos pos) {
		int radius = rand.nextInt(2) + 3;
		int height = rand.nextInt(5) + 15;
		int maxRadius = 9;

		this.logX = BlockRegistry.LOG_WEEDWOOD.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.X);
		this.logY = BlockRegistry.LOG_WEEDWOOD.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.Y);
		this.logZ = BlockRegistry.LOG_WEEDWOOD.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.Z);
		this.bark = BlockRegistry.LOG_WEEDWOOD.getDefaultState().withProperty(BlockLog.LOG_AXIS, BlockLog.EnumAxis.NONE);
		this.wood = BlockRegistry.WEEDWOOD.getDefaultState();
		this.leaves = BlockRegistry.LEAVES_WEEDWOOD_TREE.getDefaultState().withProperty(BlockLeavesBetweenlands.CHECK_DECAY, false);
		this.ivy = BlockRegistry.POISON_IVY.getDefaultState();

		if (!world.isAreaLoaded(pos, maxRadius))
			return false;

		boolean hasPoisonIvy = rand.nextInt(7) == 0;

		for (int xx = - maxRadius; xx <= maxRadius; xx++)
			for (int zz = - maxRadius; zz <= maxRadius; zz++)
				for (int yy = 2; yy < height; yy++)
					if (!world.isAirBlock(pos.add(xx, yy, zz)) && world.getBlockState(pos.add(xx, yy, zz)).isNormalCube()) {
						return false;
					}

		for (int yy = 0; yy < height; ++yy) {
			if (yy % 3 == 0 && radius > 1 && yy > 3)
				--radius;

			for (int i = radius * -1; i <= radius; ++i)
				for (int j = radius * -1; j <= radius; ++j) {
					double dSq = i * i + j * j;
					if (Math.round(Math.sqrt(dSq)) < radius && yy <= 1 + height - 2)
						world.setBlockState(pos.add(i, yy, j), wood, 2);
					if (Math.round(Math.sqrt(dSq)) == radius && yy == 0 || Math.round(Math.sqrt(dSq)) == radius && yy <= height - 1)
						world.setBlockState(pos.add(i, yy, j), bark, 2);
				}

			if (yy == height/2 + 2) {
				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), 0), 1, false, rand.nextInt(2) + 4, hasPoisonIvy);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), 0), 2, false, rand.nextInt(2) + 4, hasPoisonIvy);
				createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), radius + 1), 3, false, rand.nextInt(2) + 4, hasPoisonIvy);
				createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), - radius - 1), 4, false, rand.nextInt(2) + 4, hasPoisonIvy);

				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), radius + 1), 5, false, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), - radius - 1), 6, false, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), radius + 1), 7, false, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), - radius - 1), 8, false, rand.nextInt(2) + 3, hasPoisonIvy);
			}

			if (yy == height/2 + 4) {
				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), 0), 1, 4);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), 0), 2, 4);
				createSmallBranch(world, rand, pos.add(0, yy - rand.nextInt(2), radius + 1), 3, 4);
				createSmallBranch(world, rand, pos.add(0, yy - rand.nextInt(2), - radius - 1), 4, 4);

				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), radius + 1), 5, 3);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), - radius - 1), 6, 3);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), radius + 1), 7, 3);
				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), - radius - 1), 8, 3);
			}

			if (yy == height/2 + 7) {
				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), 0), 1, 2);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), 0), 2, 2);
				createSmallBranch(world, rand, pos.add(0, yy - rand.nextInt(3), radius + 1), 3, 2);
				createSmallBranch(world, rand, pos.add(0, yy - rand.nextInt(3), - radius - 1), 4, 2);

				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), radius + 1), 5, 2);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), - radius - 1), 6, 2);
				createSmallBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), radius + 1), 7, 2);
				createSmallBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), - radius - 1), 8, 2);
			}

			if (yy == 0) {
				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), 0), 1, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), 0), 2, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), radius + 1), 3, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(0, yy - rand.nextInt(2), - radius - 1), 4, true, rand.nextInt(2) + 3, hasPoisonIvy);

				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), radius + 1), 5, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), - radius - 1), 6, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(- radius - 1, yy - rand.nextInt(2), radius + 1), 7, true, rand.nextInt(2) + 3, hasPoisonIvy);
				createBranch(world, rand, pos.add(radius + 1, yy - rand.nextInt(2), - radius - 1), 8, true, rand.nextInt(2) + 3, hasPoisonIvy);
			}
		}

		createMainCanopy(world, rand, pos.add(0, height/2 + 4, 0), maxRadius);

		return true;
	}

private void createSmallBranch(World world, Random rand, BlockPos pos, int dir, int branchLength) {
		int y = 0;
		boolean branchBend = false;
		for (int i = 0; i <= branchLength; ++i) {

			if (i >= 2) {
				y++;
				branchBend = true;
			}

			switch (dir) {
			case 1:
				world.setBlockState(pos.east(i).up(y), branchBend ? logY : logX, 2);
				break;

			case 2:
				world.setBlockState(pos.west(i).up(y),  branchBend ? logY : logX, 2);
				break;

			case 3:
				world.setBlockState(pos.south(i).up(y),  branchBend ? logY : logZ, 2);
				break;

			case 4:
				world.setBlockState(pos.north(i).up(y),  branchBend ? logY : logZ, 2);
				break;

			case 5:
				world.setBlockState(pos.east(i).up(y).south(i), branchBend ? logY : logX, 2);
				break;

			case 6:
				world.setBlockState(pos.west(i).up(y).north(i), branchBend ? logY : logX, 2);
				break;

			case 7:
				world.setBlockState(pos.west(i).up(y).south(i), branchBend ? logY : logZ, 2);
				break;

			case 8:
				world.setBlockState(pos.east(i).up(y).north(i), branchBend ? logY : logZ, 2);
				break;
			}
		}
	}

private void createMainCanopy(World world, Random rand, BlockPos pos, int maxRadius) {
		for (int x1 = - maxRadius; x1 <= maxRadius; x1++)
			for (int z1 = - maxRadius; z1 <= maxRadius; z1++)
				for (int y1 = 0; y1 < maxRadius; y1++) {
					double dSq = Math.pow(x1, 2.0D) + Math.pow(z1, 2.0D) + Math.pow(y1, 2.5D);
					if (Math.round(Math.sqrt(dSq)) < maxRadius - 1 && y1 > 0)
						if (!isALog(world.getBlockState(pos.add(x1, y1, z1))))
							world.setBlockState(pos.add(x1, y1, z1), logY);
				}

		//Generate leaves after generating logs so that it doesn't trigger breakBlock when replacing blocks, causing BlockLeaves' CHECK_DECAY to become true
		for (int x1 = - maxRadius; x1 <= maxRadius; x1++)
			for (int z1 = - maxRadius; z1 <= maxRadius; z1++)
				for (int y1 = 0; y1 < maxRadius; y1++) {
					double dSq = Math.pow(x1, 2.0D) + Math.pow(z1, 2.0D) + Math.pow(y1, 2.5D);
					if (Math.round(Math.sqrt(dSq)) <= maxRadius)
						if (!isALog(world.getBlockState(pos.add(x1, y1, z1))) && rand.nextInt(5) != 0)
							world.setBlockState(pos.add(x1, y1, z1), leaves, 2);
					if (Math.round(Math.sqrt(dSq)) <= maxRadius && rand.nextInt(3) == 0 && y1 == 0)
						if (world.getBlockState(pos.add(x1, y1, z1)) == leaves)
							for (int i = 1; i < 1 + rand.nextInt(3); i++)
								if (!isALog(world.getBlockState(pos.add(x1, y1 - i, z1))))
									world.setBlockState(pos.add(x1, y1 - i, z1), leaves, 2);
				}
	}

private boolean isALog(IBlockState state) {
		return state.getBlock() instanceof BlockLog;
	}

private void createBranch(World world, Random rand, BlockPos pos, int dir, boolean root, int branchLength, boolean ivy) {
		int y = 0;
		boolean branchBend = false;
		for (int i = 0; i <= branchLength; ++i) {

			if (i >= 3) {
				y++;
				branchBend = true;
			}

			switch (dir) {
			case 1:

				if (!root) {
					world.setBlockState(pos.east(i).up(y), branchBend ? logY : logX, 2);
					if (i <= branchLength && ivy)
						addVines(world, rand, pos.east(i).up(y - 1), EnumFacing.EAST);
				}
				else {
					world.setBlockState(pos.east(i).down(y), bark, 2);
					world.setBlockState(pos.east(i).down(y - 1), bark, 2);
				}
				break;

			case 2:
				if (!root) {
					world.setBlockState(pos.west(i).up(y), branchBend ? logY : logX, 2);
					if (i <= branchLength && ivy)
						addVines(world, rand, pos.west(i).up(y - 1), EnumFacing.WEST);
				}
				else {
					world.setBlockState(pos.west(i).down(y), bark, 2);
					world.setBlockState(pos.west(i).down(y - 1), bark, 2);
				}
				break;

			case 3:
				if (!root) {
					world.setBlockState(pos.south(i).up(y), branchBend ? logY : logZ, 2);
					if (i <= branchLength && ivy)
						addVines(world, rand, pos.south(i).up(y - 1), EnumFacing.SOUTH);
				}
				else {
					world.setBlockState(pos.south(i).down(y), bark, 2);
					world.setBlockState(pos.south(i).down(y - 1), bark, 2);
				}
				break;

			case 4:
				if (!root) {
					world.setBlockState(pos.north(i).up(y), branchBend ? logY : logZ, 2);
					if (i <= branchLength && ivy)
						addVines(world, rand, pos.north(i).up(y - 1), EnumFacing.NORTH);
				}
				else {
					world.setBlockState(pos.north(i).down(y), bark, 2);
					world.setBlockState(pos.north(i).down(y - 1), bark, 2);
				}
				break;

			case 5:
				if (!root) {
					world.setBlockState(pos.east(i - 1).up(y).south(i - 1), branchBend ? logY : logX, 2);
					if (i <= branchLength && ivy)
						addVines(world, rand, pos.east(i - 1).up(y - 1).south(i - 1), EnumFacing.EAST);
				}
				else {
					world.setBlockState(pos.east(i - 1).down(y).south(i - 1), bark, 2);
					world.setBlockState(pos.east(i - 1).down(y - 1).south(i - 1), bark, 2);
				}
				break;

			case 6:
				if (!root) {
					world.setBlockState(pos.west(i - 1).up(y).north(i - 1), branchBend ? logY : logX, 2);
					if (i <= branchLength && ivy)
						addVines(world, rand, pos.west(i - 1).up(y - 1).north(i - 1), EnumFacing.WEST);
				}
				else {
					world.setBlockState(pos.west(i - 1).down(y).north(i - 1), bark, 2);
					world.setBlockState(pos.west(i - 1).down(y - 1).north(i - 1), bark, 2);
				}
				break;

			case 7:
				if (!root) {
					world.setBlockState(pos.west(i - 1).up(y).south(i - 1), branchBend ? logY : logZ, 2);
					if (i <= branchLength && ivy)
						addVines(world, rand, pos.west(i - 1).up(y - 1).south(i - 1), EnumFacing.SOUTH);
				}
				else {
					world.setBlockState(pos.west(i - 1).down(y).south(i - 1), bark, 2);
					world.setBlockState(pos.west(i - 1).down(y - 1).south(i - 1), bark, 2);
				}
				break;

			case 8:
				if (!root) {
					world.setBlockState(pos.east(i - 1).up(y).north(i - 1), branchBend ? logY : logZ, 2);
					if (i <= branchLength && ivy)
						addVines(world, rand, pos.east(i - 1).up(y - 1).north(i - 1), EnumFacing.NORTH);
				}
				else {
					world.setBlockState(pos.east(i - 1).down(y).north(i - 1), bark, 2);
					world.setBlockState(pos.east(i - 1).down(y - 1).north(i - 1), bark, 2);
				}
				break;
			}
		}
	}

private void addVines(World world, Random rand, BlockPos pos, EnumFacing facing) {
		if (rand.nextInt(4) != 0) {
			int length = rand.nextInt(4) + 4;
			for (int yy = 0; yy < length; ++yy)
				if (world.isAirBlock(pos.down(yy)))
					world.setBlockState(pos.down(yy), ivy.withProperty(BlockVineBL.getPropertyFor(facing.getOpposite()), Boolean.valueOf(true)), 2);
				else
					break;
		}
	}

