public GenLayerSurrounded(InstancedIntCache cache, long seed, GenLayer parentGenLayer, Biome surrounding, Biome biome, int checkRange, float spawnChance) {
		super(cache, seed);
		this.parent = parentGenLayer;
		this.checkRange = checkRange;
		this.spawnChance = spawnChance;
		this.surrounding = Biome.getIdForBiome(surrounding);
		this.biome = Biome.getIdForBiome(biome);
	}

@Override
	public int[] getInts(int areaX, int areaZ, int sizeX, int sizeZ) {
		int[] currentBiomeInts = this.parent.getInts(areaX - this.checkRange, areaZ - this.checkRange, sizeX + this.checkRange * 2, sizeZ + this.checkRange * 2);
		int[] biomeInts = this.cache.getIntCache(sizeX * sizeZ);

		for (int zz = 0; zz < sizeZ; ++zz) {
			for (int xx = 0; xx < sizeX; ++xx) {
				this.initChunkSeed(areaX + xx, areaZ + zz);

				biomeInts[xx + zz * sizeX] = currentBiomeInts[xx + this.checkRange + (zz + this.checkRange) * (sizeX + this.checkRange * 2)];

				boolean surrounded = true;

				check: for(int xo = -this.checkRange; xo <= this.checkRange; xo++) {
					for(int zo = -this.checkRange; zo <= this.checkRange; zo++) {
						if(xo * xo + zo * zo <= this.checkRange * this.checkRange + 1) {
							int biomeID = currentBiomeInts[xx + this.checkRange + xo + (zz + this.checkRange + zo) * (sizeX + this.checkRange * 2)];
							if(biomeID != this.surrounding) {
								surrounded = false;
								break check;
							}
						}
					}
				}

				if(surrounded && this.nextInt(10000) <= this.spawnChance * 10000) {
					biomeInts[xx + zz * sizeX] = this.biome;
				}
			}
		}

		return biomeInts;
	}

public GenLayerThinMask(InstancedIntCache cache, long seed, GenLayer parentGenLayer, int id, int range, float removeChance) {
		super(cache, seed);
		this.parent = parentGenLayer;
		this.id = id;
		this.range = range;
		this.removeChance = removeChance;
	}

@Override
	public int[] getInts(int areaX, int areaZ, int sizeX, int sizeZ) {
		int[] currentInts = this.parent.getInts(areaX - this.range, areaZ - this.range, sizeX + this.range * 2, sizeZ + this.range * 2);
		int[] ints = this.cache.getIntCache(sizeX * sizeZ);

		for (int zz = 0; zz < sizeZ; ++zz) {
			for (int xx = 0; xx < sizeX; ++xx) {
				this.initChunkSeed(areaX + xx, areaZ + zz);

				int id = currentInts[xx + this.range + (zz + this.range) * (sizeX + this.range * 2)];
				ints[xx + zz * sizeX] = id;

				if(id == this.id) {
					check: for(int xo = -this.range; xo <= this.range; xo++) {
						for(int zo = -this.range; zo <= this.range; zo++) {
							if((xo != 0 || zo != 0) && xo * xo + zo * zo <= this.range * this.range + 1) {
								if(currentInts[xx + this.range + xo + (zz + this.range + zo) * (sizeX + this.range * 2)] == this.id && this.nextInt(10000) <= this.removeChance * 10000) {
									ints[xx + zz * sizeX] = -1;
									break check;
								}
							}
						}
					}
				}
			}
		}

		return ints;
	}

public static GenLayer thin(InstancedIntCache cache, long seed, GenLayer layer, int id, int range, float removeChance, int num) {
		GenLayer genlayer = layer;

		for (int i = 0; i < num; ++i) {
			genlayer = new GenLayerThinMask(cache, seed + i, genlayer, id, range, removeChance);
		}

		return genlayer;
	}

public GenLayerVoronoiZoomInstanced(InstancedIntCache cache, long seed, GenLayer parent) {
		super(cache, seed);
		super.parent = parent;
	}

@Override
	public int[] getInts(int areaX, int areaY, int areaWidth, int areaHeight) {
		areaX = areaX - 2;
		areaY = areaY - 2;
		int i = areaX >> 2;
		int j = areaY >> 2;
		int k = (areaWidth >> 2) + 2;
		int l = (areaHeight >> 2) + 2;
		int[] aint = this.parent.getInts(i, j, k, l);
		int i1 = k - 1 << 2;
		int j1 = l - 1 << 2;
		int[] aint1 = this.cache.getIntCache(i1 * j1);

		for (int k1 = 0; k1 < l - 1; ++k1)
		{
			int l1 = 0;
			int i2 = aint[l1 + 0 + (k1 + 0) * k];

			for (int j2 = aint[l1 + 0 + (k1 + 1) * k]; l1 < k - 1; ++l1)
			{
				this.initChunkSeed((long)(l1 + i << 2), (long)(k1 + j << 2));
				double d1 = ((double)this.nextInt(1024) / 1024.0D - 0.5D) * 3.6D;
				double d2 = ((double)this.nextInt(1024) / 1024.0D - 0.5D) * 3.6D;
				this.initChunkSeed((long)(l1 + i + 1 << 2), (long)(k1 + j << 2));
				double d3 = ((double)this.nextInt(1024) / 1024.0D - 0.5D) * 3.6D + 4.0D;
				double d4 = ((double)this.nextInt(1024) / 1024.0D - 0.5D) * 3.6D;
				this.initChunkSeed((long)(l1 + i << 2), (long)(k1 + j + 1 << 2));
				double d5 = ((double)this.nextInt(1024) / 1024.0D - 0.5D) * 3.6D;
				double d6 = ((double)this.nextInt(1024) / 1024.0D - 0.5D) * 3.6D + 4.0D;
				this.initChunkSeed((long)(l1 + i + 1 << 2), (long)(k1 + j + 1 << 2));
				double d7 = ((double)this.nextInt(1024) / 1024.0D - 0.5D) * 3.6D + 4.0D;
				double d8 = ((double)this.nextInt(1024) / 1024.0D - 0.5D) * 3.6D + 4.0D;
				int k2 = aint[l1 + 1 + (k1 + 0) * k] & 255;
				int l2 = aint[l1 + 1 + (k1 + 1) * k] & 255;

				for (int i3 = 0; i3 < 4; ++i3)
				{
					int j3 = ((k1 << 2) + i3) * i1 + (l1 << 2);

					for (int k3 = 0; k3 < 4; ++k3)
					{
						double d9 = ((double)i3 - d2) * ((double)i3 - d2) + ((double)k3 - d1) * ((double)k3 - d1);
						double d10 = ((double)i3 - d4) * ((double)i3 - d4) + ((double)k3 - d3) * ((double)k3 - d3);
						double d11 = ((double)i3 - d6) * ((double)i3 - d6) + ((double)k3 - d5) * ((double)k3 - d5);
						double d12 = ((double)i3 - d8) * ((double)i3 - d8) + ((double)k3 - d7) * ((double)k3 - d7);

						if (d9 < d10 && d9 < d11 && d9 < d12)
						{
							aint1[j3++] = i2;
						}
						else if (d10 < d9 && d10 < d11 && d10 < d12)
						{
							aint1[j3++] = k2;
						}
						else if (d11 < d9 && d11 < d10 && d11 < d12)
						{
							aint1[j3++] = j2;
						}
						else
						{
							aint1[j3++] = l2;
						}
					}
				}

				i2 = k2;
				j2 = l2;
			}
		}

		int[] aint2 = this.cache.getIntCache(areaWidth * areaHeight);

		for (int l3 = 0; l3 < areaHeight; ++l3)
		{
			System.arraycopy(aint1, (l3 + (areaY & 3)) * i1 + (areaX & 3), aint2, l3 * areaWidth, areaWidth);
		}

		return aint2;
	}

public GenLayerZoomIncrement(InstancedIntCache cache, long seed, GenLayer parent, boolean increment) {
		super(cache, seed);
		this.parent = parent;
		this.increment = increment;
	}

@Override
	public int[] getInts(int areaX, int areaZ, int sizeX, int sizeZ) {
		int parentAreaX = areaX >> 1;
		int parentAreaZ = areaZ >> 1;	
		int parentSizeX = (sizeX >> 1) + 2;
		int parentSizeZ = (sizeZ >> 1) + 2;
		int[] parentInts = this.parent.getInts(parentAreaX, parentAreaZ, parentSizeX, parentSizeZ);
		int newSizeX = parentSizeX - 1 << 1;
		int newSizeZ = parentSizeZ - 1 << 1;
		int[] newInts = this.cache.getIntCache(newSizeX * newSizeZ);

		for (int zo = 0; zo < parentSizeZ - 1; ++zo) {
			int index = (zo << 1) * newSizeX;

			int xnzn = parentInts[0 + 0 + (zo + 0) * parentSizeX];
			int xnzp = parentInts[0 + 0 + (zo + 1) * parentSizeX];

			for (int xo = 0; xo < parentSizeX - 1; ++xo) {
				this.initChunkSeed((long)(xo + parentAreaX << 1), (long)(zo + parentAreaZ << 1));

				int xpzn = parentInts[xo + 1 + (zo + 0) * parentSizeX];
				int xpzp = parentInts[xo + 1 + (zo + 1) * parentSizeX];

				newInts[index] = xnzn;

				int rnd1 = this.selectRandom(new int[] {xnzn, xnzp});
				newInts[index++ + newSizeX] = rnd1 + (this.increment && rnd1 != -1 ? 1 : 0);

				int rnd2 = this.selectRandom(new int[] {xnzn, xpzn});
				newInts[index] = rnd2 + (this.increment && rnd2 != -1 ? 1 : 0);

				int rnd3 = this.selectModeOrRandom(xnzn, xpzn, xnzp, xpzp);
				newInts[index++ + newSizeX] = rnd3 + (this.increment && rnd3 != -1 ? 1 : 0);

				xnzn = xpzn;
				xnzp = xpzp;
			}
		}

		int[] ints = this.cache.getIntCache(sizeX * sizeZ);

		for (int i = 0; i < sizeZ; ++i) {
			System.arraycopy(newInts, (i + (areaZ & 1)) * newSizeX + (areaX & 1), ints, i * sizeX, sizeX);
		}

		return ints;
	}

public static GenLayer magnify(InstancedIntCache cache, long seed, GenLayer layer, boolean increment, int num) {
		GenLayer genlayer = layer;

		for (int i = 0; i < num; ++i) {
			genlayer = new GenLayerZoomIncrement(cache, seed, genlayer, increment);
		}

		return genlayer;
	}

public synchronized int[] getIntCache(int size) {
		if (size <= 256) {
			if (freeSmallArrays.isEmpty()) {
				int[] aint4 = new int[256];
				inUseSmallArrays.add(aint4);
				return aint4;
			} else {
				int[] aint3 = freeSmallArrays.remove(freeSmallArrays.size() - 1);
				inUseSmallArrays.add(aint3);
				return aint3;
			}
		} else if (size > intCacheSize) {
			intCacheSize = size;
			freeLargeArrays.clear();
			inUseLargeArrays.clear();
			int[] aint2 = new int[intCacheSize];
			inUseLargeArrays.add(aint2);
			return aint2;
		} else if (freeLargeArrays.isEmpty()) {
			int[] aint1 = new int[intCacheSize];
			inUseLargeArrays.add(aint1);
			return aint1;
		} else {
			int[] aint = freeLargeArrays.remove(freeLargeArrays.size() - 1);
			inUseLargeArrays.add(aint);
			return aint;
		}
	}

public synchronized void resetIntCache() {
		if (!freeLargeArrays.isEmpty()) {
			freeLargeArrays.remove(freeLargeArrays.size() - 1);
		}

		if (!freeSmallArrays.isEmpty()) {
			freeSmallArrays.remove(freeSmallArrays.size() - 1);
		}

		freeLargeArrays.addAll(inUseLargeArrays);
		freeSmallArrays.addAll(inUseSmallArrays);
		inUseLargeArrays.clear();
		inUseSmallArrays.clear();
	}

