public static Location getLocation(LocationStorage storage) {
                if (storage instanceof LocationPortal) {
                    return PORTAL;
                }
                if(storage.getType() == EnumLocationType.WAYSTONE) {
                	return WAYSTONE;
                }
                String name = storage.getName();
                switch (name) {
                    case "small_dungeon":
                        return SHRINE;
                    case "giant_tree":
                        return GIANT_TREE;
                    case "abandoned_shack":
                    case "ruins":
                        return RUINS;
                    case "cragrock_tower":
                        return TOWER;
                    case "idol_head":
                        return IDOL;
                    case "wight_tower":
                        return FORTRESS;
                    case "spirit_tree":
                        return SPIRIT_TREE;
                    case "sludge_worm_dungeon":
                    	return SLUDGE_WORM_DUNGEON;
                    case "floating_island":
                    	return FLOATING_ISLAND;
                }
                return NONE;
            }

