		if (entity instanceof EntityPlayerMP) {
			((EntityPlayerMP)entity).connection.setPlayerLocation(x, y, z, yaw, pitch);
		} else {
			entity.setLocationAndAngles(x, y, z, yaw, pitch);
		}
