        // stained shingles
        for(EnumBLDyeColor color : EnumBLDyeColor.values()) {
            recipes.add(new ShapedOreRecipe(null, new ItemStack(BlockRegistry.MUD_BRICK_SHINGLE_STAINED, 8, color.getMetadata()),
