private static boolean isValidToolRecipe(ToolRepairAnimatorRecipe recipe) {
        ItemStack stack = new ItemStack(recipe.getTool());
        stack.setItemDamage(stack.getMaxDamage() - 1);
        return recipe.matchesInput(stack);
    }

