@Override
	public byte[] transform(String name, String transformedName, byte[] basicClass) {
		if(name != null) {
			return writeClass(transformClass(readClass(basicClass)));
		}
		return basicClass;
	}

private ClassNode readClass(byte[] classBytes) {
		ClassNode classNode = new ClassNode();
		ClassReader classReader = new ClassReader(classBytes);
		classReader.accept(classNode, 0);
		return classNode;
	}

private byte[] writeClass(ClassNode classNode) {
		ClassWriter classWriter = new ClassWriter(ClassWriter.COMPUTE_MAXS);
		classNode.accept(classWriter);
		return classWriter.toByteArray();
	}

private ClassNode transformClass(ClassNode classNode) {
		for (MethodNode method : classNode.methods) {
			for (int i = 0; i < method.instructions.size(); i++) {
				AbstractInsnNode insnNode = method.instructions.get(i);
				if (insnNode.getOpcode() == Opcodes.INVOKESTATIC) {
					MethodInsnNode methodInsn = (MethodInsnNode) insnNode;
					if(!this.isExcluded(methodInsn.name) && methodInsn.owner.startsWith("org/lwjgl/opengl")) {
						InsnList checkErrorInsns = new InsnList();
						method.instructions.insert(methodInsn, new MethodInsnNode(INVOKESTATIC, OpenGLDebug.class.getCanonicalName().replace(".", "/"), "checkThrowError", "()V", false));
						System.out.println(String.format("[OpenGLDebug] Hooked method '%s' at '%s' (%s)", classNode.name + "#" + method.name, methodInsn.name + methodInsn.desc, i));
					}
				}
			}
		}
		return classNode;
	}

private boolean isExcluded(String method) {
		for(String exclusion : checkExclusions)
			if(method.startsWith(exclusion))
				return true;
		return false;
	}

public OpenGLError(String errors) {
			super("An OpenGL Error has occurred: " + errors);
		}

public static void checkThrowError() {
		if(checkGlContext()) {
			int glErrorId;
			while((glErrorId = GL11.glGetError()) != 0) {
				foundErrors.add(glErrorId);
			}
			if (!foundErrors.isEmpty()) {
				StringBuilder errors = new StringBuilder();
				for(int i = 0; i < foundErrors.size(); i++) {
					errors.append(GLU.gluErrorString(foundErrors.get(i))).append(" (").append(foundErrors.get(i)).append(")");
					if(i < foundErrors.size() - 1)
						errors.append(", ");
				}
				foundErrors.clear();
				new OpenGLError(errors.toString()).printStackTrace();
			}
		}
	}

public static boolean checkGlContext() {
		try {
			ContextCapabilities capabilities = GLContext.getCapabilities();
			return capabilities != null;
		} catch(Exception ex) { 
			return false;
		}
	}

public TheBetweenlandsClassTransformer() {
		constructed = true;
	}

public static void registerModule(TransformerModule module) {
		modules.add(module);
	}

public static List<TransformerModule> getModules() {
		return ImmutableList.copyOf(modules);
	}

@Override
	public byte[] transform(String name, String transformedName, byte[] classBytes) {
		List<TransformerModule> currentClassModules = new ArrayList<TransformerModule>();

		for(TransformerModule module : modules) {
			if(module.acceptsClass(name)) {
				module.reset();
				currentClassModules.add(module);
			}
		}

		ClassNode classNode = null;

		if(!currentClassModules.isEmpty()) {
			classNode = readClass(classBytes);

			for(TransformerModule module : currentClassModules) {
				module.transformClass(classNode);
			}

			List<TransformerModule> currentMethodModules = new ArrayList<TransformerModule>();

			for(MethodNode method : classNode.methods) {
				currentMethodModules.clear();

				for(TransformerModule module : currentClassModules) {
					if(!module.wasSuccessful() && module.acceptsMethod(method)) {
						module.transformMethod(method);
						currentMethodModules.add(module);
					}
				}

				for (int i = 0; i < method.instructions.size(); i++) {
					AbstractInsnNode insnNode = method.instructions.get(i);

					for(TransformerModule module : currentMethodModules) {
						if(!module.wasSuccessful())
							module.transformMethodInstruction(method, insnNode, i);
					}
				}
			}

			checkModules(currentClassModules);
		}

		return classNode == null ? classBytes : writeClass(classNode);
	}

public static void checkModules() {
		checkModules(modules);
	}

private static void checkModules(List<TransformerModule> modules) {
		for(TransformerModule module : modules) {
			if(!module.wasSuccessful()) {
				throw new ClassTransformationException(String.format("Transformer module %s failed", module.getName()));
			}
		}
	}

private ClassNode readClass(byte[] classBytes) {
		ClassNode classNode = new ClassNode();
		ClassReader classReader = new ClassReader(classBytes);
		classReader.accept(classNode, 0);
		return classNode;
	}

private byte[] writeClass(ClassNode classNode) {
		ClassWriter classWriter = new ClassWriter(ClassWriter.COMPUTE_FRAMES | ClassWriter.COMPUTE_MAXS);
		classNode.accept(classWriter);
		return classWriter.toByteArray();
	}

