public AnimationMathHelper() {
        b = 0.0F;
        c = 0.0F;
        h = 1.0F;
    }

public float swing(float speed, float max, boolean reset) {
        if (reset) {
            b = 0.0F;
            c = 0.0F;
            h = 1.0F;
        }
        e = b;
        d = c;
        c = (float) ((double) c + 4 * 0.8F);

        if (c < 0.0F)
            c = 0.0F;

        if (c > speed)
            c = speed;

        if (h < speed)
            h = speed;

        h = (float) ((double) h * 0.8F);
        b += h * 0.5F;

        float f1 = e + (b - e);
        float f2 = d + (c - d);
        float f3 = (MathHelper.sin(f1) + 0.5F) * f2 * max;
        return f3;
    }

public static void renderIcon(int x, int y, int width, int height, ResourceLocation icon) {
		Minecraft.getMinecraft().renderEngine.bindTexture(icon);
		GlStateManager.pushMatrix();
		GlStateManager.translate(x, y, 0);
		GlStateManager.disableBlend();
		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder vertexBuffer = tessellator.getBuffer();
		vertexBuffer.begin(7, DefaultVertexFormats.POSITION_TEX);
		vertexBuffer.pos(0, 0, 0).tex(0, 0).endVertex();
		vertexBuffer.pos(0, height, 0).tex(0, 1).endVertex();
		vertexBuffer.pos(width, height, 0).tex(1, 1).endVertex();
		vertexBuffer.pos(width, 0, 0).tex(1, 0).endVertex();
		tessellator.draw();
		GlStateManager.enableBlend();
		GlStateManager.popMatrix();
	}

public static void allBernstein(int curveDegree, float t, float scalars[]) {
		int j, k;
		float nt = 1 - t;
		float saved;
		scalars[0] = 1;
		for (j = 1; j <= curveDegree; j++) {
			saved = 0;
			for (k = 0; k < j; k++) {
				float temp = scalars[k];
				scalars[k] = saved + nt * temp;
				saved = t * temp;
			}
			scalars[j] = saved;
		}
	}

public static void pointOnBezierCurve(float controlPoints[][], int curveDegree, float t, float point[]) {
		float scalars[] = new float[curveDegree + 1];
		int k;
		allBernstein(curveDegree, t, scalars);
		point[0] = point[1] = point[2] = 0;
		for (k = 0; k <= curveDegree; k++) {
			point[0] += scalars[k] * controlPoints[k][0];
			point[1] += scalars[k] * controlPoints[k][1];
			point[2] += scalars[k] * controlPoints[k][2];
		}
	}

public static float approximateLength(float controlPoints[][]) {
		float length = 0;
		for (int i = 0; i < controlPoints.length - 1; i++) {
			float xDif = controlPoints[i + 1][0] - controlPoints[i][0];
			float yDif = controlPoints[i + 1][1] - controlPoints[i][1];
			float zDif = controlPoints[i + 1][2] - controlPoints[i][2];
			length += Math.sqrt(xDif * xDif + yDif * yDif + zDif * zDif);
		}
		return length;
	}

public static int tesselationSegementsForLength(float length, float scale) {
		float noLessThan = 10 * scale;
		float segs = length * scale / 30f;
		return (int) Math.ceil(Math.sqrt(segs * segs * 0.6 + noLessThan * noLessThan));
	}

public static float[][] curve(float controlPoints[][]) {
		return curve(controlPoints, 1);
	}

public static float[][] curve(float controlPoints[][], float scale) {
		int count = tesselationSegementsForLength(approximateLength(controlPoints), scale);
		float[][] points = new float[count][3];
		for (int i = 0; i < count; i++) {
			float t = i / (float) (count - 1);
			float[] point = new float[3];
			pointOnBezierCurve(controlPoints, controlPoints.length - 1, t, point);
			points[i] = point;
		}
		return points;
	}

public static float[][] derivative(float[][] controlPoints) {
		float[][] derivative = new float[controlPoints.length - 1][controlPoints[0].length];
		for (int i = 0; i < derivative.length; i++) {
			float[] point = derivative[i];
			for (int n =  0; n < point.length; n++) {
				point[n] = derivative.length * (controlPoints[i + 1][n] - controlPoints[i][n]);
			}
		}
		return derivative;
	}

public static List<BlockPos> getCircle(BlockPos pos, int radius, List<BlockPos> list) {
		int xo = radius;
		int zo = 0;
		int err = 1 - radius;

		List<BlockPos> s1 = new ArrayList<>();
		List<BlockPos> s2 = new ArrayList<>();
		List<BlockPos> s3 = new ArrayList<>();
		List<BlockPos> s4 = new ArrayList<>();
		List<BlockPos> s5 = new ArrayList<>();
		List<BlockPos> s6 = new ArrayList<>();
		List<BlockPos> s7 = new ArrayList<>();
		List<BlockPos> s8 = new ArrayList<>();

		while (xo >= zo) {
			s1.add(pos.add(xo, 0, zo));
			if(xo != zo) s2.add(pos.add(zo, 0, xo));
			if(zo != 0) s3.add(pos.add(-zo, 0, xo));
			if(xo != zo) s4.add(pos.add(-xo, 0, zo));
			if(zo != 0) s5.add(pos.add(-xo, 0, -zo));
			if(xo != zo) s6.add(pos.add(-zo, 0, -xo));
			if(zo != 0) s7.add(pos.add(zo, 0, -xo));
			if(xo != zo && zo != 0) s8.add(pos.add(xo, 0, -zo));

			if(err < 0) {
				zo++;
				err = err + 2 * zo + 1;
			} else {
				zo++;
				xo--;
				err = err + 2 * (zo - xo) + 1;
			}
		}

		list.addAll(s1);
		for(ListIterator<BlockPos> it = s2.listIterator(s2.size()); it.hasPrevious();) {
			list.add(it.previous());
		}
		list.addAll(s3);
		for(ListIterator<BlockPos> it = s4.listIterator(s4.size()); it.hasPrevious();) {
			list.add(it.previous());
		}
		list.addAll(s5);
		for(ListIterator<BlockPos> it = s6.listIterator(s6.size()); it.hasPrevious();) {
			list.add(it.previous());
		}
		list.addAll(s7);
		for(ListIterator<BlockPos> it = s8.listIterator(s8.size()); it.hasPrevious();) {
			list.add(it.previous());
		}

		return list;
	}

public static List<BlockPos> getRingSegment(BlockPos pos, double startAngle, double endAngle, double innerRadius, double outerRadius, boolean includeCenter, List<BlockPos> list) {
		final double twoPi = Math.PI * 2;
		final double halfPi = Math.PI / 2;

		startAngle %= twoPi;
		if(startAngle < 0) startAngle += twoPi;

		endAngle %= twoPi;
		if(endAngle < 0) endAngle += twoPi;

		int qa1 = MathHelper.floor(startAngle / halfPi);

		startAngle -= qa1 * halfPi;
		endAngle -= qa1 * halfPi;

		double radiusSq = outerRadius * outerRadius;

		int rotation = (4 - qa1) % 4;
		int maxRot = MathHelper.floor(endAngle / halfPi);

		for(int rot = 0; rot <= maxRot; rot++) {
			double ca1 = rot == 0 ? startAngle : 0;
			double ca2 = rot == maxRot ? (endAngle % halfPi) : halfPi;

			double cos1 = Math.cos(ca1);
			double tan1 = Math.tan(ca1);
			double tan2 = Math.tan(ca2);

			int minX = 0;
			int maxX = MathHelper.ceil(cos1 * outerRadius);

			for(int xo = minX; xo <= maxX; xo++) {
				double dxSq = (xo - 0.5D) * (xo - 0.5D);

				int minZ = MathHelper.floor(tan1 * xo);
				int maxZ = MathHelper.floor(Math.min(tan2 * xo, outerRadius));

				if(xo <= innerRadius) {
					minZ += MathHelper.ceil(innerRadius - Math.sqrt(xo * xo + minZ * minZ));
				}

				for(int zo = minZ; zo < maxZ; zo++) {
					double dstSq = dxSq + (zo + 0.5D) * (zo + 0.5D);

					if(dstSq >= radiusSq) {
						break;
					}

					if(dstSq <= innerRadius*innerRadius) {
						continue;
					}

					int nx;
					switch(rotation) {
					default:
					case 0:
						nx = xo - 1;
						break;
					case 1:
						nx = zo;
						break;
					case 2:
						nx = -xo + 1;
						break;
					case 3:
						nx = -zo;
						break;
					}

					int nz;
					switch(rotation) {
					default:
					case 0:
						nz = zo;
						break;
					case 1:
						nz = -xo + 1;
						break;
					case 2:
						nz = -zo;
						break;
					case 3:
						nz = xo - 1;
						break;
					}

					if(!includeCenter && nx == 0 && nz == 0) {
						continue;
					}

					list.add(pos.add(nx, 0, nz));
				}
			}

			rotation = rotation - 1;
			if(rotation < 0) {
				rotation += 4;
			}
		}

		return list;
	}

private BlockStatePropertiesMatcher(BlockStateMatcher matcher) {
