private float getT(float t, Vec3d p0, Vec3d p1) {
		//alpha = 0.0F: standard
		//alpha = 0.5F: centripetal
		//alpha = 1.0F: chordal
		float alpha = 0.5F;

		return (float)Math.pow(p1.subtract(p0).length(), alpha) + t;
	}

