public float eval(float t) {
		float[] scalars = new float[4];
		BezierUtils.allBernstein(3, t, scalars);
		float p = 0;
		for (int i = 0; i < 4; i++) {
			p += scalars[i] * controlPoints[i][1];
		}
		return p;
	}

