public void asRotation(double x, double y, double z, double angle) {
        asIdentity();
        double c = Math.cos(angle);
        double s = Math.sin(angle);
        double t = 1 - c;
        m00 = c + x * x * t;
        m11 = c + y * y * t;
        m22 = c + z * z * t;
        double a = x * y * t;
        double b = z * s;
        m10 = a + b;
        m01 = a - b;
        a = x * z * t;
        b = y * s;
        m20 = a - b;
        m02 = a + b;
        a = y * z * t;
        b = x * s;
        m21 = a + b;
        m12 = a - b;
    }

public void asQuaternion(Quat quat) {
        asQuaternion(quat.x, quat.y, quat.z, quat.w);
    }

public void asQuaternion(double x, double y, double z, double w) {
        m00 = 1 - 2 * y * y - 2 * z * z;
        m10 = 2 * (x * y + w * z);
        m20 = 2 * (x * z - w * y);
        m01 = 2 * (x * y - w * z);
        m11 = 1 - 2 * x * x - 2 * z * z;
        m21 = 2 * (y * z + w * x);
        m02 = 2 * (x * z + w * y);
        m12 = 2 * (y * z - w * x);
        m22 = 1 - 2 * x * x - 2 * y * y;
        m03 = 0;
        m13 = 0;
        m23 = 0;
        m30 = 0;
        m31 = 0;
        m32 = 0;
        m33 = 1;
    }

public void mul(Mat4d m) {
        double m00, m01, m02, m03, m10, m11, m12, m13, m20, m21, m22, m23, m30, m31, m32, m33;
        m00 = this.m00 * m.m00 + this.m01 * m.m10 + this.m02 * m.m20 + this.m03 * m.m30;
        m01 = this.m00 * m.m01 + this.m01 * m.m11 + this.m02 * m.m21 + this.m03 * m.m31;
        m02 = this.m00 * m.m02 + this.m01 * m.m12 + this.m02 * m.m22 + this.m03 * m.m32;
        m03 = this.m00 * m.m03 + this.m01 * m.m13 + this.m02 * m.m23 + this.m03 * m.m33;
        m10 = this.m10 * m.m00 + this.m11 * m.m10 + this.m12 * m.m20 + this.m13 * m.m30;
        m11 = this.m10 * m.m01 + this.m11 * m.m11 + this.m12 * m.m21 + this.m13 * m.m31;
        m12 = this.m10 * m.m02 + this.m11 * m.m12 + this.m12 * m.m22 + this.m13 * m.m32;
        m13 = this.m10 * m.m03 + this.m11 * m.m13 + this.m12 * m.m23 + this.m13 * m.m33;
        m20 = this.m20 * m.m00 + this.m21 * m.m10 + this.m22 * m.m20 + this.m23 * m.m30;
        m21 = this.m20 * m.m01 + this.m21 * m.m11 + this.m22 * m.m21 + this.m23 * m.m31;
        m22 = this.m20 * m.m02 + this.m21 * m.m12 + this.m22 * m.m22 + this.m23 * m.m32;
        m23 = this.m20 * m.m03 + this.m21 * m.m13 + this.m22 * m.m23 + this.m23 * m.m33;
        m30 = this.m30 * m.m00 + this.m31 * m.m10 + this.m32 * m.m20 + this.m33 * m.m30;
        m31 = this.m30 * m.m01 + this.m31 * m.m11 + this.m32 * m.m21 + this.m33 * m.m31;
        m32 = this.m30 * m.m02 + this.m31 * m.m12 + this.m32 * m.m22 + this.m33 * m.m32;
        m33 = this.m30 * m.m03 + this.m31 * m.m13 + this.m32 * m.m23 + this.m33 * m.m33;
        this.m00 = m00;
        this.m01 = m01;
        this.m02 = m02;
        this.m03 = m03;
        this.m10 = m10;
        this.m11 = m11;
        this.m12 = m12;
        this.m13 = m13;
        this.m20 = m20;
        this.m21 = m21;
        this.m22 = m22;
        this.m23 = m23;
        this.m30 = m30;
        this.m31 = m31;
        this.m32 = m32;
        this.m33 = m33;
    }

public Vec3d transform(Vec3d point) {
        return new Vec3d(m00 * point.x + m01 * point.y + m02 * point.z + m03, m10 * point.x + m11 * point.y + m12 * point.z + m13, m20 * point.x + m21 * point.y + m22 * point.z + m23);
    }

public static double linearTransformd(double x, double domainMin, double domainMax, double rangeMin, double rangeMax) {
        x = x < domainMin ? domainMin : x > domainMax ? domainMax : x;
        return (rangeMax - rangeMin) * (x - domainMin) / (domainMax - domainMin) + rangeMin;
    }

public static float linearTransformf(float x, float domainMin, float domainMax, float rangeMin, float rangeMax) {
        x = x < domainMin ? domainMin : x > domainMax ? domainMax : x;
        return (rangeMax - rangeMin) * (x - domainMin) / (domainMax - domainMin) + rangeMin;
    }

public static int[][] permutationsOf(int x) {
        return permutationsOf(sequence(x));
    }

public static int[][] permutationsOf(int[] x) {
        if (x.length == 1) {
            return new int[][]{x};
        }
        int[] part = new int[x.length - 1];
        System.arraycopy(x, 1, part, 0, part.length);
        int[][] perms = permutationsOf(part);
        int element = x[0];
        int[][] result = new int[perms.length * (perms[0].length + 1)][];
        for (int n = 0; n < perms.length; n++) {
            int[] perm = perms[n];
            for (int i = 0; i <= perm.length; i++) {
                int[] r = result[i + n * (perm.length + 1)] = new int[x.length];
                System.arraycopy(perm, 0, r, 0, i);
                r[i] = element;
                System.arraycopy(perm, i, r, i + 1, perm.length - i);
            }
        }
        return result;
    }

public static int factorial(int x) {
        int factorial = 1;
        for (int i = 2; i <= x; i++) {
            factorial *= i;
        }
        return factorial;
    }

public static int[] sequence(int n) {
        int[] sequence = new int[n];
        for (int k = 0; k < n; k++) {
            sequence[k] = k;
        }
        return sequence;
    }

public static float wrapAngle(float angle) {
        angle %= 360;
        if (angle < 0) {
            angle += 360;
        }
        return angle;
    }

public static String radiansToDMS(float angle) {
        angle *= RAD_TO_DEG;
        int degrees = (int) angle;
        angle -= (int) angle;
        angle *= 60;
        int minutes = (int) angle;
        angle -= (int) angle;
        angle *= 60;
        return String.format("%s\u00B0%s'%.3f\"", degrees, minutes, angle);
    }

public static float mod(float a, float b) {
        return (a % b + b) % b;
    }

public static double mod(double a, double b) {
        return (a % b + b) % b;
    }

public static float lerpAngle(float a, float b, float t) {
        return lerpValue(a, b, t, 360);
    }

public static float lerpValue(float a, float b, float t, float range) {
        return t * modularDelta(a, b, range) + a;
    }

public static float modularDelta(float a, float b, float range) {
        return mod(-a + b + range / 2, range) - range / 2;
    }

public static double modularDelta(double a, double b, double range) {
        return mod(-a + b + range / 2, range) - range / 2;
    }

public static boolean epsilonEquals(float a, float b) {
        return MathHelper.abs(b - a) < 1.0E-5F;
    }

public static float adjustAngleForInterpolation(float angle, float prevAngle) {
        return adjustValueForInterpolation(angle, prevAngle, -180, 180);
    }

public static float adjustValueForInterpolation(float x, float prevX, float min, float max) {
        float range = max - min;
        while (x - prevX < min) {
            prevX -= range;
        }
        while (x - prevX >= max) {
            prevX += range;
        }
        return prevX;
    }

public static int degToByte(float angle) {
        return MathHelper.floor(angle * (256F / 360));
    }

public static int hash(int x) {
        x = (x >> 16 ^ x) * 0x45D9F3B;
        x = (x >> 16 ^ x) * 0x45D9F3B;
        x = x >> 16 ^ x;
        return x;
    }

public static void minmax(Point3f min, Point3f max, float x, float y, float z) {
        if (min.x != min.x) {
            min.x = x;
            min.y = y;
            min.z = z;
        }
        if (max.x != max.x) {
            max.x = x;
            max.y = y;
            max.z = z;
        }
        min.x = x < min.x ? x : min.x;
        min.y = y < min.y ? y : min.y;
        min.z = z < min.z ? z : min.z;
        max.x = x > max.x ? x : max.x;
        max.y = y > max.y ? y : max.y;
        max.z = z > max.z ? z : max.z;
    }

public Matrix() {
        matrixStack = new Stack<Mat4d>();
        Mat4d mat = new Mat4d();
        mat.asIdentity();
        matrixStack.push(mat);
    }

public void push() {
        matrixStack.push(new Mat4d(matrixStack.peek()));
    }

public void pop() {
        if (matrixStack.size() < 2) {
            throw new RuntimeException("Stack underflow");
        }
        matrixStack.pop();
    }

public void setIdentity() {
        matrixStack.peek().asIdentity();
    }

public void translate(double x, double y, double z) {
        Mat4d mat = matrixStack.peek();
        Mat4d translation = new Mat4d();
        translation.asTranslation(x, y, z);
        mat.mul(translation);
    }

public void rotate(double angle, double x, double y, double z) {
