                        dz_ext2 -= 2;
                    } else {
                        wsv_ext2 += 2;
                        dw_ext2 -= 2;
                    }

                } else { // Both closest points on the smaller side
                    // One of the two extra points is (0,0,0,0)
                    xsv_ext2 = xsb;
                    ysv_ext2 = ysb;
                    zsv_ext2 = zsb;
                    wsv_ext2 = wsb;
                    dx_ext2 = dx0;
                    dy_ext2 = dy0;
                    dz_ext2 = dz0;
                    dw_ext2 = dw0;

                    // Other two points are based on the omitted axes.
                    byte c = (byte) (aPoint | bPoint);

                    if ((c & 0x01) == 0) {
                        xsv_ext0 = xsb - 1;
                        xsv_ext1 = xsb;
                        dx_ext0 = dx0 + 1 - SQUISH_CONSTANT_4D;
                        dx_ext1 = dx0 - SQUISH_CONSTANT_4D;
                    } else {
                        xsv_ext0 = xsv_ext1 = xsb + 1;
                        dx_ext0 = dx_ext1 = dx0 - 1 - SQUISH_CONSTANT_4D;
                    }

                    if ((c & 0x02) == 0) {
                        ysv_ext0 = ysv_ext1 = ysb;
                        dy_ext0 = dy_ext1 = dy0 - SQUISH_CONSTANT_4D;
                        if ((c & 0x01) == 0x01) {
                            ysv_ext0 -= 1;
                            dy_ext0 += 1;
                        } else {
                            ysv_ext1 -= 1;
                            dy_ext1 += 1;
                        }
                    } else {
                        ysv_ext0 = ysv_ext1 = ysb + 1;
                        dy_ext0 = dy_ext1 = dy0 - 1 - SQUISH_CONSTANT_4D;
                    }

                    if ((c & 0x04) == 0) {
                        zsv_ext0 = zsv_ext1 = zsb;
                        dz_ext0 = dz_ext1 = dz0 - SQUISH_CONSTANT_4D;
                        if ((c & 0x03) == 0x03) {
                            zsv_ext0 -= 1;
                            dz_ext0 += 1;
                        } else {
                            zsv_ext1 -= 1;
                            dz_ext1 += 1;
                        }
                    } else {
                        zsv_ext0 = zsv_ext1 = zsb + 1;
                        dz_ext0 = dz_ext1 = dz0 - 1 - SQUISH_CONSTANT_4D;
                    }

                    if ((c & 0x08) == 0) {
                        wsv_ext0 = wsb;
                        wsv_ext1 = wsb - 1;
                        dw_ext0 = dw0 - SQUISH_CONSTANT_4D;
                        dw_ext1 = dw0 + 1 - SQUISH_CONSTANT_4D;
                    } else {
                        wsv_ext0 = wsv_ext1 = wsb + 1;
                        dw_ext0 = dw_ext1 = dw0 - 1 - SQUISH_CONSTANT_4D;
                    }

                }
            } else { // One point on each "side"
                byte c1, c2;
                if (aIsBiggerSide) {
                    c1 = aPoint;
                    c2 = bPoint;
                } else {
                    c1 = bPoint;
                    c2 = aPoint;
                }

                // Two contributions are the bigger-sided point with each 0 replaced with -1.
                if ((c1 & 0x01) == 0) {
                    xsv_ext0 = xsb - 1;
                    xsv_ext1 = xsb;
                    dx_ext0 = dx0 + 1 - SQUISH_CONSTANT_4D;
                    dx_ext1 = dx0 - SQUISH_CONSTANT_4D;
                } else {
                    xsv_ext0 = xsv_ext1 = xsb + 1;
                    dx_ext0 = dx_ext1 = dx0 - 1 - SQUISH_CONSTANT_4D;
                }

                if ((c1 & 0x02) == 0) {
                    ysv_ext0 = ysv_ext1 = ysb;
                    dy_ext0 = dy_ext1 = dy0 - SQUISH_CONSTANT_4D;
                    if ((c1 & 0x01) == 0x01) {
                        ysv_ext0 -= 1;
                        dy_ext0 += 1;
                    } else {
                        ysv_ext1 -= 1;
                        dy_ext1 += 1;
                    }
                } else {
                    ysv_ext0 = ysv_ext1 = ysb + 1;
                    dy_ext0 = dy_ext1 = dy0 - 1 - SQUISH_CONSTANT_4D;
                }

                if ((c1 & 0x04) == 0) {
                    zsv_ext0 = zsv_ext1 = zsb;
                    dz_ext0 = dz_ext1 = dz0 - SQUISH_CONSTANT_4D;
                    if ((c1 & 0x03) == 0x03) {
                        zsv_ext0 -= 1;
                        dz_ext0 += 1;
                    } else {
                        zsv_ext1 -= 1;
                        dz_ext1 += 1;
                    }
                } else {
                    zsv_ext0 = zsv_ext1 = zsb + 1;
                    dz_ext0 = dz_ext1 = dz0 - 1 - SQUISH_CONSTANT_4D;
                }

                if ((c1 & 0x08) == 0) {
                    wsv_ext0 = wsb;
                    wsv_ext1 = wsb - 1;
                    dw_ext0 = dw0 - SQUISH_CONSTANT_4D;
                    dw_ext1 = dw0 + 1 - SQUISH_CONSTANT_4D;
                } else {
                    wsv_ext0 = wsv_ext1 = wsb + 1;
                    dw_ext0 = dw_ext1 = dw0 - 1 - SQUISH_CONSTANT_4D;
                }

                // One contribution is a permutation of (0,0,0,2) based on the smaller-sided point
                xsv_ext2 = xsb;
                ysv_ext2 = ysb;
                zsv_ext2 = zsb;
                wsv_ext2 = wsb;
                dx_ext2 = dx0 - 2 * SQUISH_CONSTANT_4D;
                dy_ext2 = dy0 - 2 * SQUISH_CONSTANT_4D;
                dz_ext2 = dz0 - 2 * SQUISH_CONSTANT_4D;
                dw_ext2 = dw0 - 2 * SQUISH_CONSTANT_4D;
                if ((c2 & 0x01) != 0) {
                    xsv_ext2 += 2;
                    dx_ext2 -= 2;
                } else if ((c2 & 0x02) != 0) {
                    ysv_ext2 += 2;
                    dy_ext2 -= 2;
                } else if ((c2 & 0x04) != 0) {
                    zsv_ext2 += 2;
                    dz_ext2 -= 2;
                } else {
                    wsv_ext2 += 2;
                    dw_ext2 -= 2;
                }
            }

            // Contribution (1,0,0,0)
            double dx1 = dx0 - 1 - SQUISH_CONSTANT_4D;
            double dy1 = dy0 - 0 - SQUISH_CONSTANT_4D;
            double dz1 = dz0 - 0 - SQUISH_CONSTANT_4D;
            double dw1 = dw0 - 0 - SQUISH_CONSTANT_4D;
            double attn1 = 2 - dx1 * dx1 - dy1 * dy1 - dz1 * dz1 - dw1 * dw1;
            if (attn1 > 0) {
                attn1 *= attn1;
                value += attn1 * attn1 * extrapolate(xsb + 1, ysb + 0, zsb + 0, wsb + 0, dx1, dy1, dz1, dw1);
            }

            // Contribution (0,1,0,0)
            double dx2 = dx0 - 0 - SQUISH_CONSTANT_4D;
            double dy2 = dy0 - 1 - SQUISH_CONSTANT_4D;
            double dz2 = dz1;
            double dw2 = dw1;
            double attn2 = 2 - dx2 * dx2 - dy2 * dy2 - dz2 * dz2 - dw2 * dw2;
            if (attn2 > 0) {
                attn2 *= attn2;
                value += attn2 * attn2 * extrapolate(xsb + 0, ysb + 1, zsb + 0, wsb + 0, dx2, dy2, dz2, dw2);
            }

            // Contribution (0,0,1,0)
            double dx3 = dx2;
            double dy3 = dy1;
            double dz3 = dz0 - 1 - SQUISH_CONSTANT_4D;
            double dw3 = dw1;
            double attn3 = 2 - dx3 * dx3 - dy3 * dy3 - dz3 * dz3 - dw3 * dw3;
            if (attn3 > 0) {
                attn3 *= attn3;
                value += attn3 * attn3 * extrapolate(xsb + 0, ysb + 0, zsb + 1, wsb + 0, dx3, dy3, dz3, dw3);
            }

            // Contribution (0,0,0,1)
            double dx4 = dx2;
            double dy4 = dy1;
            double dz4 = dz1;
            double dw4 = dw0 - 1 - SQUISH_CONSTANT_4D;
            double attn4 = 2 - dx4 * dx4 - dy4 * dy4 - dz4 * dz4 - dw4 * dw4;
            if (attn4 > 0) {
                attn4 *= attn4;
                value += attn4 * attn4 * extrapolate(xsb + 0, ysb + 0, zsb + 0, wsb + 1, dx4, dy4, dz4, dw4);
            }

            // Contribution (1,1,0,0)
            double dx5 = dx0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dy5 = dy0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dz5 = dz0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dw5 = dw0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double attn5 = 2 - dx5 * dx5 - dy5 * dy5 - dz5 * dz5 - dw5 * dw5;
            if (attn5 > 0) {
                attn5 *= attn5;
                value += attn5 * attn5 * extrapolate(xsb + 1, ysb + 1, zsb + 0, wsb + 0, dx5, dy5, dz5, dw5);
            }

            // Contribution (1,0,1,0)
            double dx6 = dx0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dy6 = dy0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dz6 = dz0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dw6 = dw0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double attn6 = 2 - dx6 * dx6 - dy6 * dy6 - dz6 * dz6 - dw6 * dw6;
            if (attn6 > 0) {
                attn6 *= attn6;
                value += attn6 * attn6 * extrapolate(xsb + 1, ysb + 0, zsb + 1, wsb + 0, dx6, dy6, dz6, dw6);
            }

            // Contribution (1,0,0,1)
            double dx7 = dx0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dy7 = dy0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dz7 = dz0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dw7 = dw0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double attn7 = 2 - dx7 * dx7 - dy7 * dy7 - dz7 * dz7 - dw7 * dw7;
            if (attn7 > 0) {
                attn7 *= attn7;
                value += attn7 * attn7 * extrapolate(xsb + 1, ysb + 0, zsb + 0, wsb + 1, dx7, dy7, dz7, dw7);
            }

            // Contribution (0,1,1,0)
            double dx8 = dx0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dy8 = dy0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dz8 = dz0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dw8 = dw0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double attn8 = 2 - dx8 * dx8 - dy8 * dy8 - dz8 * dz8 - dw8 * dw8;
            if (attn8 > 0) {
                attn8 *= attn8;
                value += attn8 * attn8 * extrapolate(xsb + 0, ysb + 1, zsb + 1, wsb + 0, dx8, dy8, dz8, dw8);
            }

            // Contribution (0,1,0,1)
            double dx9 = dx0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dy9 = dy0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dz9 = dz0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dw9 = dw0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double attn9 = 2 - dx9 * dx9 - dy9 * dy9 - dz9 * dz9 - dw9 * dw9;
            if (attn9 > 0) {
                attn9 *= attn9;
                value += attn9 * attn9 * extrapolate(xsb + 0, ysb + 1, zsb + 0, wsb + 1, dx9, dy9, dz9, dw9);
            }

            // Contribution (0,0,1,1)
            double dx10 = dx0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dy10 = dy0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dz10 = dz0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dw10 = dw0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double attn10 = 2 - dx10 * dx10 - dy10 * dy10 - dz10 * dz10 - dw10 * dw10;
            if (attn10 > 0) {
                attn10 *= attn10;
                value += attn10 * attn10 * extrapolate(xsb + 0, ysb + 0, zsb + 1, wsb + 1, dx10, dy10, dz10, dw10);
            }
        } else { // We're inside the second dispentachoron (Rectified 4-Simplex)
            double aScore;
            byte aPoint;
            boolean aIsBiggerSide = true;
            double bScore;
            byte bPoint;
            boolean bIsBiggerSide = true;

            // Decide between (0,0,1,1) and (1,1,0,0)
            if (xins + yins < zins + wins) {
                aScore = xins + yins;
                aPoint = 0x0C;
            } else {
                aScore = zins + wins;
                aPoint = 0x03;
            }

            // Decide between (0,1,0,1) and (1,0,1,0)
            if (xins + zins < yins + wins) {
                bScore = xins + zins;
                bPoint = 0x0A;
            } else {
                bScore = yins + wins;
                bPoint = 0x05;
            }

            // Closer between (0,1,1,0) and (1,0,0,1) will replace the further of a and b, if closer.
            if (xins + wins < yins + zins) {
                double score = xins + wins;
                if (aScore <= bScore && score < bScore) {
                    bScore = score;
                    bPoint = 0x06;
                } else if (aScore > bScore && score < aScore) {
                    aScore = score;
                    aPoint = 0x06;
                }
            } else {
                double score = yins + zins;
                if (aScore <= bScore && score < bScore) {
                    bScore = score;
                    bPoint = 0x09;
                } else if (aScore > bScore && score < aScore) {
                    aScore = score;
                    aPoint = 0x09;
                }
            }

            // Decide if (0,1,1,1) is closer.
            double p1 = 3 - inSum + xins;
            if (aScore <= bScore && p1 < bScore) {
                bScore = p1;
                bPoint = 0x0E;
                bIsBiggerSide = false;
            } else if (aScore > bScore && p1 < aScore) {
                aScore = p1;
                aPoint = 0x0E;
                aIsBiggerSide = false;
            }

            // Decide if (1,0,1,1) is closer.
            double p2 = 3 - inSum + yins;
            if (aScore <= bScore && p2 < bScore) {
                bScore = p2;
                bPoint = 0x0D;
                bIsBiggerSide = false;
            } else if (aScore > bScore && p2 < aScore) {
                aScore = p2;
                aPoint = 0x0D;
                aIsBiggerSide = false;
            }

            // Decide if (1,1,0,1) is closer.
            double p3 = 3 - inSum + zins;
            if (aScore <= bScore && p3 < bScore) {
                bScore = p3;
                bPoint = 0x0B;
                bIsBiggerSide = false;
            } else if (aScore > bScore && p3 < aScore) {
                aScore = p3;
                aPoint = 0x0B;
                aIsBiggerSide = false;
            }

            // Decide if (1,1,1,0) is closer.
            double p4 = 3 - inSum + wins;
            if (aScore <= bScore && p4 < bScore) {
                bScore = p4;
                bPoint = 0x07;
                bIsBiggerSide = false;
            } else if (aScore > bScore && p4 < aScore) {
                aScore = p4;
                aPoint = 0x07;
                aIsBiggerSide = false;
            }

            // Where each of the two closest points are determines how the extra three vertices are calculated.
            if (aIsBiggerSide == bIsBiggerSide) {
                if (aIsBiggerSide) { // Both closest points on the bigger side
                    byte c1 = (byte) (aPoint & bPoint);
                    byte c2 = (byte) (aPoint | bPoint);

                    // Two contributions are permutations of (0,0,0,1) and (0,0,0,2) based on c1
                    xsv_ext0 = xsv_ext1 = xsb;
                    ysv_ext0 = ysv_ext1 = ysb;
                    zsv_ext0 = zsv_ext1 = zsb;
                    wsv_ext0 = wsv_ext1 = wsb;
                    dx_ext0 = dx0 - SQUISH_CONSTANT_4D;
                    dy_ext0 = dy0 - SQUISH_CONSTANT_4D;
                    dz_ext0 = dz0 - SQUISH_CONSTANT_4D;
                    dw_ext0 = dw0 - SQUISH_CONSTANT_4D;
                    dx_ext1 = dx0 - 2 * SQUISH_CONSTANT_4D;
                    dy_ext1 = dy0 - 2 * SQUISH_CONSTANT_4D;
                    dz_ext1 = dz0 - 2 * SQUISH_CONSTANT_4D;
                    dw_ext1 = dw0 - 2 * SQUISH_CONSTANT_4D;
                    if ((c1 & 0x01) != 0) {
                        xsv_ext0 += 1;
                        dx_ext0 -= 1;
                        xsv_ext1 += 2;
                        dx_ext1 -= 2;
                    } else if ((c1 & 0x02) != 0) {
                        ysv_ext0 += 1;
                        dy_ext0 -= 1;
                        ysv_ext1 += 2;
                        dy_ext1 -= 2;
                    } else if ((c1 & 0x04) != 0) {
                        zsv_ext0 += 1;
                        dz_ext0 -= 1;
                        zsv_ext1 += 2;
                        dz_ext1 -= 2;
                    } else {
                        wsv_ext0 += 1;
                        dw_ext0 -= 1;
                        wsv_ext1 += 2;
                        dw_ext1 -= 2;
                    }

                    // One contribution is a permutation of (1,1,1,-1) based on c2
                    xsv_ext2 = xsb + 1;
                    ysv_ext2 = ysb + 1;
                    zsv_ext2 = zsb + 1;
                    wsv_ext2 = wsb + 1;
                    dx_ext2 = dx0 - 1 - 2 * SQUISH_CONSTANT_4D;
                    dy_ext2 = dy0 - 1 - 2 * SQUISH_CONSTANT_4D;
                    dz_ext2 = dz0 - 1 - 2 * SQUISH_CONSTANT_4D;
                    dw_ext2 = dw0 - 1 - 2 * SQUISH_CONSTANT_4D;
                    if ((c2 & 0x01) == 0) {
                        xsv_ext2 -= 2;
                        dx_ext2 += 2;
                    } else if ((c2 & 0x02) == 0) {
                        ysv_ext2 -= 2;
                        dy_ext2 += 2;
                    } else if ((c2 & 0x04) == 0) {
                        zsv_ext2 -= 2;
                        dz_ext2 += 2;
                    } else {
                        wsv_ext2 -= 2;
                        dw_ext2 += 2;
                    }
                } else { // Both closest points on the smaller side
                    // One of the two extra points is (1,1,1,1)
                    xsv_ext2 = xsb + 1;
                    ysv_ext2 = ysb + 1;
                    zsv_ext2 = zsb + 1;
                    wsv_ext2 = wsb + 1;
                    dx_ext2 = dx0 - 1 - 4 * SQUISH_CONSTANT_4D;
                    dy_ext2 = dy0 - 1 - 4 * SQUISH_CONSTANT_4D;
                    dz_ext2 = dz0 - 1 - 4 * SQUISH_CONSTANT_4D;
                    dw_ext2 = dw0 - 1 - 4 * SQUISH_CONSTANT_4D;

                    // Other two points are based on the shared axes.
                    byte c = (byte) (aPoint & bPoint);

                    if ((c & 0x01) != 0) {
                        xsv_ext0 = xsb + 2;
                        xsv_ext1 = xsb + 1;
                        dx_ext0 = dx0 - 2 - 3 * SQUISH_CONSTANT_4D;
                        dx_ext1 = dx0 - 1 - 3 * SQUISH_CONSTANT_4D;
                    } else {
                        xsv_ext0 = xsv_ext1 = xsb;
                        dx_ext0 = dx_ext1 = dx0 - 3 * SQUISH_CONSTANT_4D;
                    }

                    if ((c & 0x02) != 0) {
                        ysv_ext0 = ysv_ext1 = ysb + 1;
                        dy_ext0 = dy_ext1 = dy0 - 1 - 3 * SQUISH_CONSTANT_4D;
                        if ((c & 0x01) == 0) {
                            ysv_ext0 += 1;
                            dy_ext0 -= 1;
                        } else {
                            ysv_ext1 += 1;
                            dy_ext1 -= 1;
                        }
                    } else {
                        ysv_ext0 = ysv_ext1 = ysb;
                        dy_ext0 = dy_ext1 = dy0 - 3 * SQUISH_CONSTANT_4D;
                    }

                    if ((c & 0x04) != 0) {
                        zsv_ext0 = zsv_ext1 = zsb + 1;
                        dz_ext0 = dz_ext1 = dz0 - 1 - 3 * SQUISH_CONSTANT_4D;
                        if ((c & 0x03) == 0) {
                            zsv_ext0 += 1;
                            dz_ext0 -= 1;
                        } else {
                            zsv_ext1 += 1;
                            dz_ext1 -= 1;
                        }
                    } else {
                        zsv_ext0 = zsv_ext1 = zsb;
                        dz_ext0 = dz_ext1 = dz0 - 3 * SQUISH_CONSTANT_4D;
                    }

                    if ((c & 0x08) != 0) {
                        wsv_ext0 = wsb + 1;
                        wsv_ext1 = wsb + 2;
                        dw_ext0 = dw0 - 1 - 3 * SQUISH_CONSTANT_4D;
                        dw_ext1 = dw0 - 2 - 3 * SQUISH_CONSTANT_4D;
                    } else {
                        wsv_ext0 = wsv_ext1 = wsb;
                        dw_ext0 = dw_ext1 = dw0 - 3 * SQUISH_CONSTANT_4D;
                    }
                }
            } else { // One point on each "side"
                byte c1, c2;
                if (aIsBiggerSide) {
                    c1 = aPoint;
                    c2 = bPoint;
                } else {
                    c1 = bPoint;
                    c2 = aPoint;
                }

                // Two contributions are the bigger-sided point with each 1 replaced with 2.
                if ((c1 & 0x01) != 0) {
                    xsv_ext0 = xsb + 2;
                    xsv_ext1 = xsb + 1;
                    dx_ext0 = dx0 - 2 - 3 * SQUISH_CONSTANT_4D;
                    dx_ext1 = dx0 - 1 - 3 * SQUISH_CONSTANT_4D;
                } else {
                    xsv_ext0 = xsv_ext1 = xsb;
                    dx_ext0 = dx_ext1 = dx0 - 3 * SQUISH_CONSTANT_4D;
                }

                if ((c1 & 0x02) != 0) {
                    ysv_ext0 = ysv_ext1 = ysb + 1;
                    dy_ext0 = dy_ext1 = dy0 - 1 - 3 * SQUISH_CONSTANT_4D;
                    if ((c1 & 0x01) == 0) {
                        ysv_ext0 += 1;
                        dy_ext0 -= 1;
                    } else {
                        ysv_ext1 += 1;
                        dy_ext1 -= 1;
                    }
                } else {
                    ysv_ext0 = ysv_ext1 = ysb;
                    dy_ext0 = dy_ext1 = dy0 - 3 * SQUISH_CONSTANT_4D;
                }

                if ((c1 & 0x04) != 0) {
                    zsv_ext0 = zsv_ext1 = zsb + 1;
                    dz_ext0 = dz_ext1 = dz0 - 1 - 3 * SQUISH_CONSTANT_4D;
                    if ((c1 & 0x03) == 0) {
                        zsv_ext0 += 1;
                        dz_ext0 -= 1;
                    } else {
                        zsv_ext1 += 1;
                        dz_ext1 -= 1;
                    }
                } else {
                    zsv_ext0 = zsv_ext1 = zsb;
                    dz_ext0 = dz_ext1 = dz0 - 3 * SQUISH_CONSTANT_4D;
                }

                if ((c1 & 0x08) != 0) {
                    wsv_ext0 = wsb + 1;
                    wsv_ext1 = wsb + 2;
                    dw_ext0 = dw0 - 1 - 3 * SQUISH_CONSTANT_4D;
                    dw_ext1 = dw0 - 2 - 3 * SQUISH_CONSTANT_4D;
                } else {
                    wsv_ext0 = wsv_ext1 = wsb;
                    dw_ext0 = dw_ext1 = dw0 - 3 * SQUISH_CONSTANT_4D;
                }

                // One contribution is a permutation of (1,1,1,-1) based on the smaller-sided point
                xsv_ext2 = xsb + 1;
                ysv_ext2 = ysb + 1;
                zsv_ext2 = zsb + 1;
                wsv_ext2 = wsb + 1;
                dx_ext2 = dx0 - 1 - 2 * SQUISH_CONSTANT_4D;
                dy_ext2 = dy0 - 1 - 2 * SQUISH_CONSTANT_4D;
                dz_ext2 = dz0 - 1 - 2 * SQUISH_CONSTANT_4D;
                dw_ext2 = dw0 - 1 - 2 * SQUISH_CONSTANT_4D;
                if ((c2 & 0x01) == 0) {
                    xsv_ext2 -= 2;
                    dx_ext2 += 2;
                } else if ((c2 & 0x02) == 0) {
                    ysv_ext2 -= 2;
                    dy_ext2 += 2;
                } else if ((c2 & 0x04) == 0) {
                    zsv_ext2 -= 2;
                    dz_ext2 += 2;
                } else {
                    wsv_ext2 -= 2;
                    dw_ext2 += 2;
                }
            }

            // Contribution (1,1,1,0)
            double dx4 = dx0 - 1 - 3 * SQUISH_CONSTANT_4D;
            double dy4 = dy0 - 1 - 3 * SQUISH_CONSTANT_4D;
            double dz4 = dz0 - 1 - 3 * SQUISH_CONSTANT_4D;
            double dw4 = dw0 - 3 * SQUISH_CONSTANT_4D;
            double attn4 = 2 - dx4 * dx4 - dy4 * dy4 - dz4 * dz4 - dw4 * dw4;
            if (attn4 > 0) {
                attn4 *= attn4;
                value += attn4 * attn4 * extrapolate(xsb + 1, ysb + 1, zsb + 1, wsb + 0, dx4, dy4, dz4, dw4);
            }

            // Contribution (1,1,0,1)
            double dx3 = dx4;
            double dy3 = dy4;
            double dz3 = dz0 - 3 * SQUISH_CONSTANT_4D;
            double dw3 = dw0 - 1 - 3 * SQUISH_CONSTANT_4D;
            double attn3 = 2 - dx3 * dx3 - dy3 * dy3 - dz3 * dz3 - dw3 * dw3;
            if (attn3 > 0) {
                attn3 *= attn3;
                value += attn3 * attn3 * extrapolate(xsb + 1, ysb + 1, zsb + 0, wsb + 1, dx3, dy3, dz3, dw3);
            }

            // Contribution (1,0,1,1)
            double dx2 = dx4;
            double dy2 = dy0 - 3 * SQUISH_CONSTANT_4D;
            double dz2 = dz4;
            double dw2 = dw3;
            double attn2 = 2 - dx2 * dx2 - dy2 * dy2 - dz2 * dz2 - dw2 * dw2;
            if (attn2 > 0) {
                attn2 *= attn2;
                value += attn2 * attn2 * extrapolate(xsb + 1, ysb + 0, zsb + 1, wsb + 1, dx2, dy2, dz2, dw2);
            }

            // Contribution (0,1,1,1)
            double dx1 = dx0 - 3 * SQUISH_CONSTANT_4D;
            double dz1 = dz4;
            double dy1 = dy4;
            double dw1 = dw3;
            double attn1 = 2 - dx1 * dx1 - dy1 * dy1 - dz1 * dz1 - dw1 * dw1;
            if (attn1 > 0) {
                attn1 *= attn1;
                value += attn1 * attn1 * extrapolate(xsb + 0, ysb + 1, zsb + 1, wsb + 1, dx1, dy1, dz1, dw1);
            }

            // Contribution (1,1,0,0)
            double dx5 = dx0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dy5 = dy0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dz5 = dz0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dw5 = dw0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double attn5 = 2 - dx5 * dx5 - dy5 * dy5 - dz5 * dz5 - dw5 * dw5;
            if (attn5 > 0) {
                attn5 *= attn5;
                value += attn5 * attn5 * extrapolate(xsb + 1, ysb + 1, zsb + 0, wsb + 0, dx5, dy5, dz5, dw5);
            }

            // Contribution (1,0,1,0)
            double dx6 = dx0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dy6 = dy0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dz6 = dz0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dw6 = dw0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double attn6 = 2 - dx6 * dx6 - dy6 * dy6 - dz6 * dz6 - dw6 * dw6;
            if (attn6 > 0) {
                attn6 *= attn6;
                value += attn6 * attn6 * extrapolate(xsb + 1, ysb + 0, zsb + 1, wsb + 0, dx6, dy6, dz6, dw6);
            }

            // Contribution (1,0,0,1)
            double dx7 = dx0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dy7 = dy0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dz7 = dz0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dw7 = dw0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double attn7 = 2 - dx7 * dx7 - dy7 * dy7 - dz7 * dz7 - dw7 * dw7;
            if (attn7 > 0) {
                attn7 *= attn7;
                value += attn7 * attn7 * extrapolate(xsb + 1, ysb + 0, zsb + 0, wsb + 1, dx7, dy7, dz7, dw7);
            }

            // Contribution (0,1,1,0)
            double dx8 = dx0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dy8 = dy0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dz8 = dz0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dw8 = dw0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double attn8 = 2 - dx8 * dx8 - dy8 * dy8 - dz8 * dz8 - dw8 * dw8;
            if (attn8 > 0) {
                attn8 *= attn8;
                value += attn8 * attn8 * extrapolate(xsb + 0, ysb + 1, zsb + 1, wsb + 0, dx8, dy8, dz8, dw8);
            }

            // Contribution (0,1,0,1)
            double dx9 = dx0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dy9 = dy0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dz9 = dz0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dw9 = dw0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double attn9 = 2 - dx9 * dx9 - dy9 * dy9 - dz9 * dz9 - dw9 * dw9;
            if (attn9 > 0) {
                attn9 *= attn9;
                value += attn9 * attn9 * extrapolate(xsb + 0, ysb + 1, zsb + 0, wsb + 1, dx9, dy9, dz9, dw9);
            }

            // Contribution (0,0,1,1)
            double dx10 = dx0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dy10 = dy0 - 0 - 2 * SQUISH_CONSTANT_4D;
            double dz10 = dz0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double dw10 = dw0 - 1 - 2 * SQUISH_CONSTANT_4D;
            double attn10 = 2 - dx10 * dx10 - dy10 * dy10 - dz10 * dz10 - dw10 * dw10;
            if (attn10 > 0) {
                attn10 *= attn10;
                value += attn10 * attn10 * extrapolate(xsb + 0, ysb + 0, zsb + 1, wsb + 1, dx10, dy10, dz10, dw10);
            }
        }

        // First extra vertex
        double attn_ext0 = 2 - dx_ext0 * dx_ext0 - dy_ext0 * dy_ext0 - dz_ext0 * dz_ext0 - dw_ext0 * dw_ext0;
        if (attn_ext0 > 0) {
            attn_ext0 *= attn_ext0;
            value += attn_ext0 * attn_ext0 * extrapolate(xsv_ext0, ysv_ext0, zsv_ext0, wsv_ext0, dx_ext0, dy_ext0, dz_ext0, dw_ext0);
        }

        // Second extra vertex
        double attn_ext1 = 2 - dx_ext1 * dx_ext1 - dy_ext1 * dy_ext1 - dz_ext1 * dz_ext1 - dw_ext1 * dw_ext1;
        if (attn_ext1 > 0) {
            attn_ext1 *= attn_ext1;
            value += attn_ext1 * attn_ext1 * extrapolate(xsv_ext1, ysv_ext1, zsv_ext1, wsv_ext1, dx_ext1, dy_ext1, dz_ext1, dw_ext1);
        }

        // Third extra vertex
        double attn_ext2 = 2 - dx_ext2 * dx_ext2 - dy_ext2 * dy_ext2 - dz_ext2 * dz_ext2 - dw_ext2 * dw_ext2;
        if (attn_ext2 > 0) {
            attn_ext2 *= attn_ext2;
            value += attn_ext2 * attn_ext2 * extrapolate(xsv_ext2, ysv_ext2, zsv_ext2, wsv_ext2, dx_ext2, dy_ext2, dz_ext2, dw_ext2);
        }

        return value / NORM_CONSTANT_4D;
    }

private double extrapolate(int xsb, int ysb, double dx, double dy) {
        int index = perm[(perm[xsb & 0xFF] + ysb) & 0xFF] & 0x0E;
        return gradients2D[index] * dx + gradients2D[index + 1] * dy;
    }

private double extrapolate(int xsb, int ysb, int zsb, double dx, double dy, double dz) {
        int index = permGradIndex3D[(perm[(perm[xsb & 0xFF] + ysb) & 0xFF] + zsb) & 0xFF];
        return gradients3D[index] * dx + gradients3D[index + 1] * dy + gradients3D[index + 2] * dz;
    }

private double extrapolate(int xsb, int ysb, int zsb, int wsb, double dx, double dy, double dz, double dw) {
        int index = perm[(perm[(perm[(perm[xsb & 0xFF] + ysb) & 0xFF] + zsb) & 0xFF] + wsb) & 0xFF] & 0xFC;
        return gradients4D[index] * dx + gradients4D[index + 1] * dy + gradients4D[index + 2] * dz + gradients4D[index + 3] * dw;
    }

private static int fastFloor(double x) {
        int xi = (int) x;
        return x < xi ? xi - 1 : xi;
    }

public static void resetFloating(Entity player) {
		if(player instanceof EntityPlayerMP) {
			NetHandlerPlayServer handler = ((EntityPlayerMP) player).connection;
			try {
				f_NetHandlerPlayServer_floating.set(handler, false);
				f_NetHandlerPlayServer_floatingTickCount.set(handler, 0);
			} catch (IllegalArgumentException | IllegalAccessException e) {
				throw new RuntimeException(e);
			}
		}
	}

public static void resetVehicleFloating(Entity player) {
		if(player instanceof EntityPlayerMP) {
			NetHandlerPlayServer handler = ((EntityPlayerMP) player).connection;
			try {
				f_NetHandlerPlayServer_vehicleFloating.set(handler, false);
				f_NetHandlerPlayServer_vehicleFloatingTickCount.set(handler, 0);
			} catch (IllegalArgumentException | IllegalAccessException e) {
