public static void start(String id) {
		System.out.println("Started '" + id);
		times.put(id, System.nanoTime());
	}

public static void finish(String id) {
		if (!times.containsKey(id))
			return;
		long time = System.nanoTime() - times.remove(id);
		if (time >= 10000000)
			;
		System.out.println("Finished '" + id + "' in " + time + " ns (" + TimeUnit.NANOSECONDS.toMillis(time) + " ms)");

		Counter counter = counters.get(id);
		if (counter == null)
			counters.put(id, counter = new Counter());
		if (counter.add(time))
			// System.out.println("Average time for '"+id+"' is "+avg+" ns ("+TimeUnit.NANOSECONDS.toMillis(avg)+" ms)");
			counter.reset();
	}

public boolean add(long time) {
			return ++counter > 256;
		}

public void reset() {
			counter = 0;
		}

public static String translateToLocal(String unlocalizedString, Object... params) {
		//Needs to be old deprecated I18n for now because Item#getItemStackDisplayName is not @SideOnly(Side.CLIENT)!
		if (I18n.canTranslate(unlocalizedString))
			return I18n.translateToLocalFormatted(unlocalizedString, params);
		else {
			if (UNLOCALIZED_STRINGS.size() < 100 && !UNLOCALIZED_STRINGS.contains(unlocalizedString))
				UNLOCALIZED_STRINGS.add(unlocalizedString);
			return unlocalizedString;
		}
	}

public static boolean canTranslate(String unlocalizedString) {
		if (I18n.canTranslate(unlocalizedString))
			return true;
		else {
			if (UNLOCALIZED_STRINGS.size() < 100 && !UNLOCALIZED_STRINGS.contains(unlocalizedString))
				UNLOCALIZED_STRINGS.add(unlocalizedString);
			return false;
		}
	}

