public Vec3UV cross(Vec3UV vec) {
		Vec3UV crossProduct = new Vec3UV(0, 0, 0);
		crossProduct.x = this.y * vec.z - vec.y * this.z;
		crossProduct.y = this.z * vec.x - vec.z * this.x;
		crossProduct.z = this.x * vec.y - vec.x * this.y;
		return crossProduct;
	}

public Vec3UV sub(Vec3UV vec) {
		return new Vec3UV(this.x - vec.x, this.y - vec.y, this.z - vec.z);
	}

public double dot(Vec3UV vec) {
		return this.x * vec.x + this.y * vec.y + this.z * vec.z;
	}

public Vec3UV neg() {
		return new Vec3UV(-this.x, -this.y, -this.z);
	}

public Vec3UV div(double d) {
		return new Vec3UV(this.x / d, this.y / d, this.z / d);
	}

public double len() {
		return Math.sqrt(this.x*this.x+this.y*this.y+this.z*this.z);
	}

public Vec3UV normalized() {
		return this.div(this.len());
	}

public float getU(float umax, int width) {
		if(this.packedQuad != null) {
			return (float) (this.maxU ? this.packedQuad.getPackedMaxU() : this.packedQuad.getPackedU()) * umax;
		}
		double umin = 0;
		return (float) (umin + (umax - umin) * this.uw / (double)width * this.u);
	}

public float getV(float vmax, int height) {
		if(this.packedQuad != null) {
			return (float) (this.maxV ? this.packedQuad.getPackedMaxV() : this.packedQuad.getPackedV()) * vmax;
		}
		double vmin = 0;
		return (float) (vmin + (vmax - vmin) * this.vw / (double)height * this.v);
	}

@Override
    public boolean add(T obj) {
        boolean b = super.add(obj);
        recalculateWeight();
        return b;
    }

@Override
    public T remove(int index) {
        T is = super.remove(index);
        recalculateWeight();
        return is;
    }

@Override
    public boolean remove(Object o) {
        boolean b = super.remove(o);
        recalculateWeight();
        return b;
    }

public void recalculateWeight() {
        totalWeight = 0;
        for (T obj : this)
            totalWeight += obj.getWeight();
    }

public int getTotalWeight() {
        return totalWeight;
    }

public T getRandomItem(Random rand) {
        if (isEmpty())
            return null;

        if(totalWeight == 0)
        	return this.get(0);

        int i = rand.nextInt(totalWeight);

        for (T obj : this) {
            i -= obj.getWeight();
            if (i < 0)
                return obj;
        }
        return null;
    }

public T getRandomItem(int weight) {
        if (isEmpty())
            return null;

        if(totalWeight == 0)
        	return this.get(0);

        for (T obj : this) {
            weight -= obj.getWeight();
            if (weight < 0)
                return obj;
        }
        return null;
    }

public EulersSolver(final Simulation sim) {
		this.sim = sim;
	}

@Override
	public void step(final float stepSize) {
		final float[] vars = this.sim.getState();
		final int N = vars.length;
		if (this.inp.length < N) {
			this.inp = new float[N];
			this.k1 = new float[N];
		}
		final float[] inp = this.inp;
		final float[] k1 = this.k1;
		System.arraycopy(vars, 0, inp, 0, N);
		Arrays.fill(k1, 0.0F);
		this.sim.evaluate(inp, k1);
		for (int i = 0; i < N; i++) {
			vars[i] += k1[i] * stepSize;
		}
	}

public PendulumSimulation(final float length, final float friction) {
		this.state = new float[3];
		this.length = length;
		this.friction = friction;
		this.moveForce = 0.0F;
		this.moveAngle = 0.0F;
	}

public float getAngle() {
		return this.state[0];
	}

public void move(final float x, final float y) {
		if (x != 0.0F || y != 0.0F) {
			this.moveAngle = -(float) MathHelper.atan2(x, -y);
			this.moveForce = MathHelper.sqrt(x * x + y * y);
		} else {
			this.moveAngle = 0.0F;
			this.moveForce = 0.0F;
		}
	}

@Override
	public float[] getState() {
		return this.state;
	}

@Override
	public void evaluate(final float[] state, final float[] rate) {
		final float theta = state[0];
		final float omega = state[1];
		final float alpha = -(this.moveForce / this.length) * MathHelper.sin(theta + this.moveAngle) -
			(G / this.length) * MathHelper.sin(theta) -
			this.friction * this.length * omega;
		rate[0] = omega;
		rate[1] = alpha;
		rate[2] = 1.0F;
	}

public RungeKuttaSolver(final Simulation sim) {
		this.sim = sim;
	}

@Override
	public void step(final float stepSize) {
		final float[] vars = sim.getState();
		final int N = vars.length;
		if (this.inp.length < N) {
			this.inp = new float[N];
			this.k1 = new float[N];
			this.k2 = new float[N];
			this.k3 = new float[N];
			this.k4 = new float[N];
		}
		final float[] inp = this.inp;
		final float[] k1 = this.k1;
		final float[] k2 = this.k2;
		final float[] k3 = this.k3;
		final float[] k4 = this.k4;
		System.arraycopy(vars, 0, inp, 0, N);
		Arrays.fill(k1, 0.0F);
		this.sim.evaluate(inp, k1);
		for (int i = 0; i < N; i++) {
			inp[i] = vars[i] + k1[i] * stepSize / 2.0F;
		}
		Arrays.fill(k2, 0.0F);
		this.sim.evaluate(inp, k2);
		for (int i = 0; i < N; i++) {
			inp[i] = vars[i] + k2[i] * stepSize / 2.0F;
		}
		Arrays.fill(k3, 0.0F);
		this.sim.evaluate(inp, k3);
		for (int i = 0; i < N; i++) {
			inp[i] = vars[i] + k3[i] * stepSize;
		}
		Arrays.fill(k4, 0.0F);
		this.sim.evaluate(inp, k4);
		for (int i = 0; i < N; i++) {
			vars[i] += (k1[i] + 2.0F * k2[i] + 2.0F * k3[i] + k4[i]) * stepSize / 6.0F;
		}
	}
